package com.hcimguide;

/**
 * Conservative policy for completing a checklist step from player arrival.
 *
 * <p>Location guidance is broader than proof of completion: an NPC marker,
 * inherited area, or destination attached to a compound instruction can help
 * the player navigate without proving the instruction is finished. This class
 * keeps those concerns separate and permits completion only for an explicit,
 * movement-only leaf step with a trustworthy destination.</p>
 */
final class ArrivalCompletionPolicy
{
	/**
	 * Why arrival may or may not complete a step. One value per refusal so a
	 * "why didn't it check off?" report is answerable from a debug log
	 * instead of re-deriving the whole predicate chain by hand.
	 */
	enum Decision
	{
		ELIGIBLE,
		NO_RESOLVED_PLAN,
		HAS_SEPARATE_CONDITION,
		ENTITY_INTERACTION,
		STRUCTURAL_PARENT,
		NOT_PURE_TRAVEL,
		INFERRED_LOCATION,
		UNTRUSTED_CONFIDENCE,
		UNTRUSTED_SOURCE
	}

	private ArrivalCompletionPolicy()
	{
	}

	static boolean isPureTravelText(String text)
	{
		return StepPhaseParser.parse(text).getMode() == StepPhaseParser.Mode.PURE_TRAVEL;
	}

	static boolean canComplete(GuideStep step, StepLocationPlan plan,
		boolean hasCondition, boolean hasEntityTarget, boolean structuralParent)
	{
		return step != null && canCompleteText(step.getText(), plan,
			hasCondition, hasEntityTarget, structuralParent);
	}

	static boolean canCompleteText(String text, StepLocationPlan plan,
		boolean hasCondition, boolean hasEntityTarget, boolean structuralParent)
	{
		return decide(text, plan, hasCondition, hasEntityTarget, structuralParent)
			== Decision.ELIGIBLE;
	}

	static Decision decide(String text, StepLocationPlan plan,
		boolean hasCondition, boolean hasEntityTarget, boolean structuralParent)
	{
		if (plan == null || !plan.hasWaypoints()
			|| (plan.getReason() != LocationResolutionReason.RESOLVED
				&& plan.getReason() != LocationResolutionReason.MULTIPLE_DESTINATIONS))
		{
			return Decision.NO_RESOLVED_PLAN;
		}
		if (hasCondition)
		{
			return Decision.HAS_SEPARATE_CONDITION;
		}
		if (hasEntityTarget)
		{
			return Decision.ENTITY_INTERACTION;
		}
		if (structuralParent)
		{
			return Decision.STRUCTURAL_PARENT;
		}
		if (!isPureTravelText(text))
		{
			return Decision.NOT_PURE_TRAVEL;
		}
		StepLocationHint finalHint = plan.get(plan.size() - 1);
		if (finalHint == null || finalHint.isInferred())
		{
			return Decision.INFERRED_LOCATION;
		}
		LocationConfidence confidence = finalHint.getConfidence();
		if (confidence != LocationConfidence.EXACT
			&& confidence != LocationConfidence.HIGH
			&& confidence != LocationConfidence.MANUAL)
		{
			return Decision.UNTRUSTED_CONFIDENCE;
		}
		LocationSource source = finalHint.getSource();
		// TransportResolver itself requires travel context, so exact shorthand
		// such as "Dueling ring to Castle Wars" is safe. Manual/authored points
		// still require the parser to prove travel text; a pin alone is not proof.
		boolean trustedSource = source == LocationSource.TRANSPORT
			|| source == LocationSource.NAMED_PLACE
			|| source == LocationSource.AUTHORED_WAYPOINT
			|| source == LocationSource.USER_PIN;
		if (!trustedSource)
		{
			return Decision.UNTRUSTED_SOURCE;
		}
		return Decision.ELIGIBLE;
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Tracks how many of each teleport-relevant item (runes, jewelry, tablets)
 * the player has - in the inventory, equipped, and in the bank - so the
 * route suggester can offer only teleports the player can actually use.
 *
 * Updates arrive on the client thread from container-change events; the
 * bank column is also persisted to config so suggestions can say "in bank"
 * across sessions (it refreshes the next time the bank opens - a stale
 * count between sessions only affects a suggestion's wording, nothing
 * game-state-critical). Only the ~15 name prefixes from the teleport
 * directory are ever tracked - a bank pass is one name comparison per
 * item per prefix, and nothing about the rest of the bank is recorded.
 */
@Singleton
public class BankStockTracker
{
	private static final Logger log = LoggerFactory.getLogger(BankStockTracker.class);
	private static final String STOCK_KEY = "teleportBankStock";

	static final int SRC_INVENTORY = 0;
	static final int SRC_EQUIPMENT = 1;
	static final int SRC_BANK = 2;
	private static final int SOURCES = 3;

	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final Gson gson;

	/**
	 * prefix -> counts[source * 2 + (0=any variant, 1=charged "(n)" variant)].
	 * Guarded by {@code this}; updates are client-thread, reads are cheap.
	 */
	private final Map<String, int[]> counts = new HashMap<>();
	private final Set<String> parts = TeleportDirectory.allNeedParts();

	/** Bumped on every change so cached route suggestions know to recompute. */
	private volatile long revision;

	@Inject
	public BankStockTracker(ItemManager itemManager, ConfigManager configManager, Gson gson)
	{
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.gson = gson;
	}

	/** True once live bank contents have been seen this session. */
	private volatile boolean bankSeenLive;

	/** Recount one container's column. Client thread (item compositions). */
	public synchronized void update(int source, Item[] items)
	{
		if (source < 0 || source >= SOURCES)
		{
			return;
		}
		if (source == SRC_BANK)
		{
			bankSeenLive = true;
		}
		// zero this source's column
		for (int[] row : counts.values())
		{
			row[source * 2] = 0;
			row[source * 2 + 1] = 0;
		}
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				String name;
				try
				{
					ItemComposition comp = itemManager.getItemComposition(item.getId());
					name = comp == null ? null : comp.getName();
				}
				catch (Exception e)
				{
					continue; // composition unavailable - skip the item, never throw
				}
				if (name == null || "null".equals(name))
				{
					continue;
				}
				String low = name.toLowerCase(Locale.ROOT);
				for (String part : parts)
				{
					if (low.startsWith(part))
					{
						int[] row = counts.computeIfAbsent(part, k -> new int[SOURCES * 2]);
						row[source * 2] = addSaturated(row[source * 2], item.getQuantity());
						if (hasChargeSuffix(low))
						{
							row[source * 2 + 1] = addSaturated(row[source * 2 + 1], item.getQuantity());
						}
					}
				}
			}
		}
		revision++;
	}

	/** Inventory + equipped count for a requirement. */
	public synchronized int carried(TeleportOption.ItemNeed need)
	{
		return countFor(need, SRC_INVENTORY) + countFor(need, SRC_EQUIPMENT);
	}

	/** Banked count for a requirement. */
	public synchronized int banked(TeleportOption.ItemNeed need)
	{
		return countFor(need, SRC_BANK);
	}

	/**
	 * True only for a NUMERIC charge suffix like "(4)" - cosmetic suffixes
	 * such as "Amulet of glory (t)" (an UNCHARGED trimmed glory) must not
	 * count as charged.
	 */
	static boolean hasChargeSuffix(String lowerName)
	{
		int i = lowerName.lastIndexOf('(');
		return i >= 0 && i + 1 < lowerName.length() && Character.isDigit(lowerName.charAt(i + 1));
	}

	private int countFor(TeleportOption.ItemNeed need, int source)
	{
		int[] row = counts.get(need.getNamePart());
		if (row == null)
		{
			return 0;
		}
		return row[source * 2 + (need.isChargedOnly() ? 1 : 0)];
	}

	public long revision()
	{
		return revision;
	}

	// ---------------------------------------------------------- persistence

	/** Persist the bank column (call off the client thread). */
	public void saveBankColumn()
	{
		Map<String, int[]> bank = new HashMap<>();
		synchronized (this)
		{
			for (Map.Entry<String, int[]> e : counts.entrySet())
			{
				int any = e.getValue()[SRC_BANK * 2];
				int charged = e.getValue()[SRC_BANK * 2 + 1];
				if (any > 0 || charged > 0)
				{
					bank.put(e.getKey(), new int[]{any, charged});
				}
			}
		}
		try
		{
			configManager.setConfiguration(HcimGuideConfig.GROUP, STOCK_KEY, gson.toJson(bank));
		}
		catch (Exception e)
		{
			log.warn("Could not persist teleport bank stock", e);
		}
	}

	/** Load the persisted bank column (any thread; validated and bounded). */
	public void loadBankColumn()
	{
		if (bankSeenLive)
		{
			// live bank contents (e.g. replayed on plugin enable mid-session)
			// beat last session's persisted counts - never overwrite them
			return;
		}
		String json = configManager.getConfiguration(HcimGuideConfig.GROUP, STOCK_KEY);
		if (json == null || json.isEmpty() || json.length() > 8192)
		{
			return; // absent, or implausibly large for ~15 tracked prefixes
		}
		Map<String, int[]> bank = new HashMap<>();
		try
		{
			com.google.gson.JsonElement parsed = new com.google.gson.JsonParser().parse(json);
			if (!parsed.isJsonObject())
			{
				return;
			}
			for (Map.Entry<String, com.google.gson.JsonElement> entry
				: parsed.getAsJsonObject().entrySet())
			{
				if (!parts.contains(entry.getKey()) || !entry.getValue().isJsonArray())
				{
					continue;
				}
				com.google.gson.JsonArray values = entry.getValue().getAsJsonArray();
				if (values.size() == 2)
				{
					bank.put(entry.getKey(), new int[]{values.get(0).getAsInt(), values.get(1).getAsInt()});
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Could not parse persisted teleport bank stock", e);
			return;
		}
		synchronized (this)
		{
			if (bankSeenLive)
			{
				return; // a live update won the race while we were parsing
			}
			for (Map.Entry<String, int[]> e : bank.entrySet())
			{
				int[] v = e.getValue();
				// only known prefixes, only sane non-negative counts
				if (e.getKey() != null && parts.contains(e.getKey())
					&& v != null && v.length == 2 && v[0] >= 0 && v[1] >= 0
					&& v[0] <= 1_000_000_000 && v[1] <= 1_000_000_000)
				{
					int[] row = counts.computeIfAbsent(e.getKey(), k -> new int[SOURCES * 2]);
					row[SRC_BANK * 2] = v[0];
					row[SRC_BANK * 2 + 1] = v[1];
				}
			}
			// inside the lock: an unsynchronized ++ racing update()'s locked
			// one can lose an increment, and a lost revision leaves the route
			// suggestion cache convinced nothing changed
			revision++;
		}
	}

	/** Forget everything (plugin shutdown; the persisted bank column remains). */
	public synchronized void reset()
	{
		counts.clear();
		bankSeenLive = false;
		revision++;
	}

	/**
	 * Prefix-matched variants can pool into one counter, so the live sum can
	 * theoretically exceed int range - clamp instead of wrapping negative
	 * (a negative count would corrupt route decisions).
	 */
	private static int addSaturated(int a, int b)
	{
		long sum = (long) a + b;
		return sum > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) sum;
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Integration with RuneLite's built-in Bank Tags plugin: the active bank
 * section's withdraw items are kept under a managed tag, and opening the bank
 * automatically opens that tag's tab - so the trip's items are in front of
 * you instead of scattered through your bank. When the section completes,
 * the tag is rebuilt for the next section automatically.
 *
 * Boundaries, deliberately: the plugin only FILTERS the bank view - you still
 * click and withdraw items yourself (automating withdrawals would break
 * Jagex's rules). Items whose names don't resolve to a real item id
 * ("2x Food") can't be tagged and stay manual, and the built-in Bank Tags
 * plugin must be enabled for the tab to appear. The managed tag is fully
 * removed when the feature is toggled off or the plugin shuts down.
 */
@Singleton
public class BankTagIntegration
{
	private static final Logger log = LoggerFactory.getLogger(BankTagIntegration.class);

	/** Namespaced so it can never collide with the user's own tags. */
	static final String TAG = "guide-overlay";

	private final TagManager tagManager;
	private final BankTagsService bankTagsService;
	private final LayoutManager layoutManager;
	private final ItemIconResolver iconResolver;
	private final ScheduledExecutorService executor;
	private final ClientThread clientThread;
	private final HcimGuideConfig config;

	/**
	 * Signature the tag currently reflects; null = cleared. Initialized to the
	 * sentinel so the very first sync request always runs - this scrubs a tag
	 * orphaned by a crashed session even when no active bank exists yet.
	 */
	private volatile String syncedBankId = "!invalidated!";
	/**
	 * What the last successful apply actually wrote: the resolved id list
	 * plus the layout flags in effect. A signature change (e.g. a global
	 * resolver-revision bump from an UNRELATED section's items resolving)
	 * often re-resolves to exactly this - then the whole client-thread
	 * mutation is skipped, most importantly the visible openBankTag re-open
	 * that would reset the user's bank scroll mid-banking. Null = must
	 * apply (never applied, invalidated, or the previous apply failed).
	 */
	private volatile String lastAppliedState;
	private volatile boolean tagHasItems;
	/**
	 * Advances on {@link #cleanup()} - the activation boundary (shutdown,
	 * startup scrub, feature toggled off). A bankId compare alone cannot tell
	 * an in-flight request from a PREVIOUS activation apart from current work
	 * when the new activation re-requests the same bank; the epoch can. Work
	 * stamped with an older epoch declines at every hop.
	 */
	private final java.util.concurrent.atomic.AtomicLong epoch = new java.util.concurrent.atomic.AtomicLong();

	@Inject
	public BankTagIntegration(TagManager tagManager, BankTagsService bankTagsService,
		LayoutManager layoutManager, ItemIconResolver iconResolver,
		ScheduledExecutorService executor, ClientThread clientThread,
		HcimGuideConfig config)
	{
		this.tagManager = tagManager;
		this.bankTagsService = bankTagsService;
		this.layoutManager = layoutManager;
		this.iconResolver = iconResolver;
		this.executor = executor;
		this.clientThread = clientThread;
		this.config = config;
	}

	/**
	 * Rebuild the managed tag for the given bank section if it changed.
	 * Cheap when nothing changed (one string compare); actual tagging runs
	 * on the executor.
	 */
	public void requestSync(String bankId, List<ItemReq> items)
	{
		if (Objects.equals(bankId, syncedBankId))
		{
			return;
		}
		syncedBankId = bankId;
		final long requestEpoch = epoch.get();
		final List<ItemReq> itemsCopy = items == null ? new ArrayList<>() : new ArrayList<>(items);
		executor.execute(() -> sync(requestEpoch, bankId, itemsCopy));
	}

	private void sync(long requestEpoch, String bankId, List<ItemReq> items)
	{
		// somebody re-requested meanwhile, or a cleanup ended the activation
		// this request belongs to; let the newest request win
		if (requestEpoch != epoch.get() || !Objects.equals(bankId, syncedBankId))
		{
			return;
		}
		// name -> id resolution can run here on the executor...
		// Capped: a bank trip is 28 slots, so a tag beyond ~2 trips of
		// DISTINCT items means the section parsed wrong - don't flood the tab.
		final int maxTagItems = 56;
		final Set<Integer> distinct = new LinkedHashSet<>();
		if (bankId != null && !items.isEmpty())
		{
			for (ItemReq req : items)
			{
				for (int id : iconResolver.resolveAll(req))
				{
					distinct.add(id);
					if (distinct.size() >= maxTagItems)
					{
						break;
					}
				}
				if (distinct.size() >= maxTagItems)
				{
					break;
				}
			}
		}
		// ...but TagManager mutations canonicalize item ids through the client
		// (getItemComposition), which is client-thread-bound
		clientThread.invokeLater(() ->
		{
			try
			{
				if (requestEpoch != epoch.get() || !Objects.equals(bankId, syncedBankId))
				{
					return;
				}
				String stateKey = distinct + "|" + config.bankTagUseLayout()
					+ "|" + config.bankTagStepOrder();
				if (stateKey.equals(lastAppliedState))
				{
					return; // content-identical - nothing to rewrite or re-open
				}
				tagManager.removeTag(TAG);
				for (int id : distinct)
				{
					tagManager.addTag(id, TAG, false);
				}
				tagHasItems = !distinct.isEmpty();
				// arrange the tab in GUIDE ORDER: `distinct` is a LinkedHashSet
				// filled in step order, so the layout mirrors the withdrawal
				// sequence top-left to bottom-right. Only when the user wants
				// the managed arrangement - otherwise their own layout stands.
				if (config.bankTagUseLayout() && config.bankTagStepOrder())
				{
					if (distinct.isEmpty())
					{
						layoutManager.removeLayout(TAG);
					}
					else
					{
						Layout layout = new Layout(TAG);
						for (int id : distinct)
						{
							layout.addItem(id);
						}
						layoutManager.saveLayout(layout);
						// the applied layout is a snapshot from when the tab
						// opened - if OUR tab is showing right now, re-open it
						// so the new arrangement takes effect immediately
						if (TAG.equals(bankTagsService.getActiveTag()))
						{
							bankTagsService.openBankTag(TAG, 0);
						}
					}
				}
				lastAppliedState = stateKey;
			}
			catch (Exception e)
			{
				// Bank Tags internals unavailable/changed - never break the guide
				// over it. Mark the signature un-synced so the next sync cycle
				// retries instead of believing the (possibly half-applied) tag
				// is correct until the bank changes.
				if (Objects.equals(bankId, syncedBankId))
				{
					syncedBankId = "!invalidated!";
					tagHasItems = false;
				}
				lastAppliedState = null;
				log.warn("Bank tag sync failed", e);
			}
		});
	}

	/**
	 * Called when the bank interface opens (client thread). Opens the managed
	 * tag's tab if it has items. Only fires on bank OPEN - if the user
	 * switches to another tab afterwards, we don't fight them.
	 */
	public void onBankOpened()
	{
		if (!tagHasItems || !config.bankTagAutoOpen())
		{
			return;
		}
		// let the built-in Bank Tag Layouts arrange the tab unless the user
		// disabled it (then force a plain grid via OPTION_NO_LAYOUT)
		final int options = config.bankTagUseLayout() ? 0 : BankTagsService.OPTION_NO_LAYOUT;
		final long requestEpoch = epoch.get();
		clientThread.invokeLater(() ->
		{
			try
			{
				if (requestEpoch != epoch.get())
				{
					return; // a cleanup removed the tag while this was queued
				}
				bankTagsService.openBankTag(TAG, options);
			}
			catch (Exception e)
			{
				log.warn("Could not open bank tag tab", e);
			}
		});
	}

	/**
	 * Remove the managed tag everywhere and close its tab if it's showing.
	 * All TagManager/BankTagsService work happens on the client thread.
	 * Safe to call unconditionally (e.g. at startup with the feature off, to
	 * scrub a tag left behind by a crashed session).
	 */
	public void cleanup()
	{
		epoch.incrementAndGet(); // everything queued before this is now stale
		syncedBankId = null;
		tagHasItems = false;
		lastAppliedState = null;
		clientThread.invokeLater(() ->
		{
			try
			{
				tagManager.removeTag(TAG);
				layoutManager.removeLayout(TAG);
				if (TAG.equals(bankTagsService.getActiveTag()))
				{
					bankTagsService.closeBankTag();
				}
			}
			catch (Exception e)
			{
				log.warn("Bank tag cleanup failed", e);
			}
		});
	}

	/** Force the next requestSync to retag even for an unchanged signature. */
	public void invalidate()
	{
		syncedBankId = "!invalidated!"; // can never equal a real signature
		lastAppliedState = null;        // and re-APPLY even identical content
	}

	/** Remove the generated step-order layout (the tag itself is untouched). */
	public void clearManagedLayout()
	{
		clientThread.invokeLater(() ->
		{
			try
			{
				layoutManager.removeLayout(TAG);
			}
			catch (Exception e)
			{
				log.warn("Could not remove managed bank tab layout", e);
			}
		});
	}
}

package com.hcimguide;

import java.io.ByteArrayInputStream;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Short confirmation chimes played through RuneLite's own
 * {@link AudioPlayer} rather than the game's sound engine.
 *
 * <p>{@code Client.playSoundEffect} hands the sound to the game engine, so it
 * follows the in-game sound sliders. Players who mute the game lose the
 * plugin's confirmations with it. Going through the client's audio player
 * keeps them audible with the game silent, and gives them a volume of their
 * own.</p>
 *
 * <p>The tones are generated as raw samples and wrapped in an in-memory WAV
 * header rather than shipped as audio files: nothing to license, nothing
 * binary in the repository, and the pitch and length can be tuned by editing
 * numbers.</p>
 *
 * <p>Playback is best effort. A machine with no audio device, or a mixer that
 * refuses the format, simply produces no sound and never an error the player
 * has to care about.</p>
 */
@Singleton
public class ChimePlayer
{
	private static final Logger log = LoggerFactory.getLogger(ChimePlayer.class);

	private static final float SAMPLE_RATE = 44100f;

	/**
	 * Rising major arpeggio: C6, E6, G6. A perfect fifth resolving upward is
	 * what reads as "success" rather than "notification"; the earlier two-note
	 * pair was a bare fourth and sounded like an alert.
	 */
	private static final double[] SUCCESS_HZ = {1046.50, 1318.51, 1567.98};

	/** Same arpeggio carried to the octave, so trip-ready is clearly bigger. */
	private static final double[] READY_HZ = {1046.50, 1318.51, 1567.98, 2093.00};

	private static final int NOTE_MS = 60;

	/** Notes overlap slightly so the run sounds like one gesture, not three beeps. */
	private static final double OVERLAP = 0.35;

	/** Release the one-at-a-time gate this long after the clip's own duration. */
	private static final long CLOSE_MARGIN_MS = 150;

	/**
	 * One chime at a time. Rapid step completions previously spawned a thread
	 * and an audio line each, which overlapped audibly and left plugin-owned
	 * threads for a reviewer to account for.
	 */
	private final java.util.concurrent.atomic.AtomicBoolean playing =
		new java.util.concurrent.atomic.AtomicBoolean();
	private final AudioPlayer audioPlayer;
	private final java.util.concurrent.ScheduledExecutorService executor;

	@Inject
	ChimePlayer(AudioPlayer audioPlayer, java.util.concurrent.ScheduledExecutorService executor)
	{
		this.audioPlayer = audioPlayer;
		this.executor = executor;
	}

	/** @param volumePercent 0 to 100, from the plugin's own setting */
	void playSuccess(int volumePercent)
	{
		play(SUCCESS_HZ, volumePercent);
	}

	void playTripReady(int volumePercent)
	{
		play(READY_HZ, volumePercent);
	}

	private void play(double[] notes, int volumePercent)
	{
		if (volumePercent <= 0 || !playing.compareAndSet(false, true))
		{
			return;
		}
		// Off the caller's thread: opening a clip can block briefly. Use
		// RuneLite's managed executor rather than creating a plugin-owned thread
		// for every accepted chime.
		try
		{
			executor.execute(() -> startTone(notes, volumePercent));
		}
		catch (RuntimeException e)
		{
			// A shutdown-time executor rejection must not leave playback locked.
			playing.set(false);
			log.debug("Chime scheduling unavailable", e);
		}
	}

	private void startTone(double[] notes, int volumePercent)
	{
		byte[] pcm = render(notes, Math.min(100, volumePercent) / 100.0);
		try
		{
			// AudioPlayer buffers the whole in-memory clip into a self-closing
			// line and returns as soon as playback starts, so this task never
			// parks the SHARED executor for the clip's audible duration.
			audioPlayer.play(new ByteArrayInputStream(toWav(pcm)), gainDb(volumePercent));
			// keep the one-at-a-time gate up until the clip has audibly
			// finished, then release it via a scheduled task
			long clipMillis = (long) Math.ceil(pcm.length * 1000.0 / (SAMPLE_RATE * 2));
			executor.schedule(() -> playing.set(false),
				clipMillis + CLOSE_MARGIN_MS, java.util.concurrent.TimeUnit.MILLISECONDS);
		}
		catch (Exception e)
		{
			// no audio device, or the mixer refused the format. Silence is an
			// acceptable outcome for a confirmation chime.
			log.debug("Chime playback unavailable", e);
			playing.set(false);
		}
	}

	/**
	 * The samples are already scaled by the volume fraction; some mixers
	 * ignore per-sample amplitude, so also ask for the equivalent line gain.
	 * Clamped well inside every common mixer's control range so the client's
	 * gain helper never has to reject the value.
	 */
	private static float gainDb(int volumePercent)
	{
		float fraction = Math.max(0.0001f, Math.min(1f, volumePercent / 100f));
		// decibels, not a linear scale; 100% keeps the line's natural level
		return Math.max(-40f, (float) (20.0 * Math.log10(fraction)));
	}

	/**
	 * Wrap 16-bit little-endian mono PCM in a canonical 44-byte RIFF/WAVE
	 * header, entirely in memory, so the client's audio player can parse it
	 * like any WAV resource - without this plugin touching {@code javax.sound}.
	 */
	private static byte[] toWav(byte[] pcm)
	{
		ByteBuffer buffer = ByteBuffer.allocate(44 + pcm.length).order(ByteOrder.LITTLE_ENDIAN);
		int sampleRate = (int) SAMPLE_RATE;
		buffer.put("RIFF".getBytes(StandardCharsets.US_ASCII));
		buffer.putInt(36 + pcm.length);
		buffer.put("WAVE".getBytes(StandardCharsets.US_ASCII));
		buffer.put("fmt ".getBytes(StandardCharsets.US_ASCII));
		buffer.putInt(16);                 // PCM format chunk size
		buffer.putShort((short) 1);        // uncompressed PCM
		buffer.putShort((short) 1);        // mono
		buffer.putInt(sampleRate);
		buffer.putInt(sampleRate * 2);     // byte rate: 16-bit mono
		buffer.putShort((short) 2);        // block align
		buffer.putShort((short) 16);       // bits per sample
		buffer.put("data".getBytes(StandardCharsets.US_ASCII));
		buffer.putInt(pcm.length);
		buffer.put(pcm);
		return buffer.array();
	}

	/**
	 * Overlapping tones with a struck-note envelope.
	 *
	 * <p>Each note fades in fast and decays slowly, like something plucked, and
	 * the notes overlap so the arpeggio rings as one chord rather than three
	 * separate beeps. A quiet octave above each note adds brightness without
	 * changing the pitch that is heard.</p>
	 */
	private byte[] render(double[] notes, double amplitude)
	{
		int perNote = (int) (SAMPLE_RATE * NOTE_MS / 1000.0);
		int step = (int) (perNote * (1.0 - OVERLAP));
		// the last note rings on after the others have finished
		int total = step * (notes.length - 1) + perNote * 3;
		double[] mix = new double[total];
		for (int n = 0; n < notes.length; n++)
		{
			double hz = notes[n];
			int start = n * step;
			// later notes ring longer, so the run settles instead of stopping
			int length = Math.min(total - start, perNote * (n == notes.length - 1 ? 3 : 2));
			for (int i = 0; i < length; i++)
			{
				double progress = (double) i / length;
				// 4 ms attack, then exponential decay: a struck note, not a beep
				double attack = Math.min(1.0, i / (SAMPLE_RATE * 0.004));
				double decay = Math.exp(-3.2 * progress);
				double t = i / SAMPLE_RATE;
				double fundamental = Math.sin(2.0 * Math.PI * hz * t);
				double octave = Math.sin(2.0 * Math.PI * hz * 2.0 * t) * 0.18;
				mix[start + i] += (fundamental + octave) * attack * decay;
			}
		}
		// the decay does not quite reach silence, so fade the last 8 ms to zero
		// rather than cutting mid-wave, which clicks
		int fade = Math.min(total, (int) (SAMPLE_RATE * 0.008));
		for (int i = 0; i < fade; i++)
		{
			mix[total - fade + i] *= 1.0 - (double) i / fade;
		}
		double peak = 0.0;
		for (double v : mix)
		{
			peak = Math.max(peak, Math.abs(v));
		}
		double scale = peak > 0 ? amplitude * 0.5 / peak : 0.0;
		byte[] out = new byte[total * 2];
		for (int i = 0; i < total; i++)
		{
			short value = (short) (mix[i] * scale * Short.MAX_VALUE);
			out[i * 2] = (byte) (value & 0xff);
			out[i * 2 + 1] = (byte) ((value >> 8) & 0xff);
		}
		return out;
	}
}

package com.hcimguide;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/**
 * Guide phrases that name a CONCEPT rather than a specific item: "Combat Gear",
 * "Range Gear", "Melee". No item id can represent these, so they behave
 * differently from a normal requirement everywhere it matters:
 *
 * <ul>
 *   <li>they draw a client sprite instead of an item icon,</li>
 *   <li>they are never inventory-checked, so they cannot show a red "missing"
 *       border,</li>
 *   <li>they never block trip readiness, which previously stalled forever
 *       because the name could not resolve to an item id.</li>
 * </ul>
 *
 * <p>This class deliberately has no RuneLite dependency so the parser and the
 * offline harness can both consult it. {@code ItemIconResolver} maps these same
 * phrases to a sprite.</p>
 */
final class ConceptItems
{
	/** Normalized concept phrases. */
	private static final Set<String> PHRASES = new HashSet<>();

	static
	{
		for (String s : Arrays.asList(
			// Only phrases with NO possible item list remain concepts. Anything
			// naming a family (pickaxe, axe, boots, food) is now an ItemCategory,
			// and anything naming one item is an alias or a step override.
			"combat gear",
			"combat gear melee",
			"combat gear for slagilith",
			"magic gear",
			"mage gear",
			"range gear",
			"ranged gear",
			"range combat gear",
			"bone crossbow gear",
			"melee gear",
			"gear",
			"your gear",
			"best gear",
			"combat equipment",
			"armour",
			"armor",
			"melee",
			"ranged",
			"magic",
			"air spells runes",
			"crumble undead runes",
			"death combat runes",
			"blast spells",
			"magic; wizard mind bomb",
			"combat runes",
			"bomb",
			// no single item exists for these
			"noted rune from corrupted gauntlet", "rune from corrupted gauntlet"))
		{
			PHRASES.add(Names.normalize(s));
		}
	}

	/** True when {@code name} names a concept rather than a concrete item. */
	static boolean isConcept(String name)
	{
		return name != null && PHRASES.contains(Names.normalize(name));
	}

	private ConceptItems()
	{
	}
}

package com.hcimguide;

import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * Derives an auto-completion condition from a step's text where one can be
 * verified against game state. Steps with no recognizable condition remain
 * manual-only.
 */
public final class ConditionParser
{
	private static final Pattern START_QUEST = Pattern.compile(
		"(?i)\\bstart(?:s|ed|ing)?\\s+([A-Za-z][A-Za-z'’ &-]{2,45})");
	private static final Pattern COMPLETE_QUEST = Pattern.compile(
		"(?i)\\bcomplete\\s+([A-Za-z][A-Za-z'’ &-]{2,45})");
	private static final Pattern SKILL_TARGET = Pattern.compile(
		"(?i)\\bto\\s+(\\d{1,2})\\s+([A-Za-z]+)\\b");

	private ConditionParser()
	{
	}

	public static StepCondition parse(String text)
	{
		if (text == null)
		{
			return null;
		}

		List<ItemReq> items = ItemListParser.parse(text);
		if (items != null)
		{
			return StepCondition.itemsInInventory(items);
		}

		Matcher complete = COMPLETE_QUEST.matcher(text);
		if (complete.find())
		{
			Quest q = matchQuest(complete.group(1));
			if (q != null)
			{
				return StepCondition.questFinished(q);
			}
		}

		Matcher start = START_QUEST.matcher(text);
		if (start.find())
		{
			Quest q = matchQuest(start.group(1));
			if (q != null)
			{
				return StepCondition.questStarted(q);
			}
		}

		Matcher skill = SKILL_TARGET.matcher(text);
		if (skill.find())
		{
			Skill s = matchSkill(skill.group(2));
			if (s != null)
			{
				int level = Integer.parseInt(skill.group(1));
				if (level >= 1 && level <= 99)
				{
					return StepCondition.skillLevel(s, level);
				}
			}
		}

		return null;
	}

	private static Quest matchQuest(String candidate)
	{
		String cand = normalize(candidate);
		if (cand.length() < 3)
		{
			return null;
		}
		for (Quest q : Quest.values())
		{
			String name = normalize(q.getName());
			if (name.equals(cand) || name.equals("the" + cand) || cand.equals("the" + name))
			{
				return q;
			}
		}
		// allow the candidate to carry trailing words, e.g. "Vampyre Slayer here"
		for (Quest q : Quest.values())
		{
			String name = normalize(q.getName());
			if (cand.startsWith(name) || cand.startsWith("the" + name)
				|| ("the" + cand).startsWith(name))
			{
				return q;
			}
		}
		return null;
	}

	private static Skill matchSkill(String candidate)
	{
		for (Skill s : Skill.values())
		{
			if (s.getName().equalsIgnoreCase(candidate))
			{
				return s;
			}
		}
		return null;
	}

	private static String normalize(String s)
	{
		return Names.normalize(s);
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** Profile-scoped user location overrides and active waypoint indexes. */
@Singleton
final class CustomLocationStore
{
	private static final Logger log = LoggerFactory.getLogger(CustomLocationStore.class);
	private static final String GROUP = HcimGuideConfig.GROUP;
	private static final String LOCATION_KEY = "customLocationsV1";
	private static final String INDEX_KEY = "waypointIndexesV1";
	/**
	 * Health of the stored blob as of the last read. Anything other than
	 * {@link StoreState#VALID} or {@link StoreState#EMPTY} means the stored data
	 * could not be understood, and writing would destroy whatever is there. In
	 * that case writes are refused until the user explicitly resets the store.
	 */
	enum StoreState
	{
		/** Parsed cleanly. */
		VALID,
		/** Nothing stored yet - writing is safe. */
		EMPTY,
		/** Primary data failed, but a valid backup was loaded. */
		RECOVERED,
		/** Stored text is not valid JSON, or is not the shape we expect. */
		CORRUPTED,
		/** Stored text is larger than the cap, so it cannot be parsed safely. */
		OVERSIZED
	}

	/** Result of the last {@link #readRoot()}; guards {@link #writeRoot}. */
	private StoreState state = StoreState.EMPTY;

	/**
	 * Custom pins live in a RuneLite CONFIG VALUE, not a file, and config values
	 * sync to the cloud. The old 1 MB ceiling was this plugin's own invention and
	 * well above what a config value reliably round-trips: an oversized blob can
	 * come back truncated, and truncated JSON does not parse. That is the main
	 * way this data got corrupted. 128 KB is comfortably inside what the config
	 * service handles while still holding thousands of pins.
	 */
	private static final int MAX_JSON_CHARS = 128 * 1024;
	/**
	 * Reads tolerate up to the 1.5.x write limit: a store that was VALID
	 * under the old 1MB cap must stay readable and exportable after the
	 * cap was lowered, instead of landing in the OVERSIZED dead end on
	 * upgrade. New writes are still bounded by MAX_JSON_CHARS (shrinking
	 * an oversized legacy store is always allowed).
	 */
	private static final int MAX_READ_CHARS = 1024 * 1024;

	/**
	 * Previous good value, written before every overwrite so a failed or
	 * truncated write can be recovered instead of losing the pins outright.
	 */
	private static final String BACKUP_KEY = LOCATION_KEY + "Backup";

	/**
	 * Schema version stored alongside the data. Without it, data written by an
	 * older plugin version reads as "corrupt" when it is really just an older
	 * shape, and the user is told their pins are unreadable for no reason.
	 */
	private static final int SCHEMA_VERSION = 1;
	private static final int MAX_GUIDES = 64;
	private static final int MAX_STEPS = 20_000;
	private static final int MAX_WAYPOINTS = 16;
	private static final Pattern STEP_KEY = Pattern.compile("[A-Za-z0-9._:#-]{3,256}");

	private final Gson gson;
	private final ConfigManager configManager;
	private long revision;

	@Inject
	CustomLocationStore(Gson gson, ConfigManager configManager)
	{
		this.gson = gson;
		this.configManager = configManager;
	}

	synchronized StepLocationPlan getPlan(String guideId, String stepKey)
	{
		Map<String, StoredStep> guide = readRoot().guides.get(guideId);
		return toPlan(guideId, stepKey, guide == null ? null : guide.get(stepKey));
	}

	/**
	 * Every stored plan for one guide, parsed from config in ONE pass. The
	 * plan-rebuild path iterates a whole guide (thousands of steps); calling
	 * {@link #getPlan} per step would deserialize the full stored blob once
	 * per step, which a large import turns into minutes of client work.
	 */
	synchronized Map<String, StepLocationPlan> getPlansForGuide(String guideId)
	{
		Map<String, StepLocationPlan> out = new HashMap<>();
		Map<String, StoredStep> guide = readRoot().guides.get(guideId);
		if (guide == null)
		{
			return out;
		}
		for (Map.Entry<String, StoredStep> entry : guide.entrySet())
		{
			StepLocationPlan plan = toPlan(guideId, entry.getKey(), entry.getValue());
			if (plan != null)
			{
				out.put(entry.getKey(), plan);
			}
		}
		return out;
	}

	/** All persisted waypoint indexes for one guide, keyed by step key - one parse. */
	synchronized Map<String, Integer> getActiveIndexesForGuide(String guideId)
	{
		Map<String, Integer> out = new HashMap<>();
		String prefix = indexKey(guideId, "");
		for (Map.Entry<String, Integer> entry : readIndexes().entrySet())
		{
			if (entry.getKey().startsWith(prefix))
			{
				out.put(entry.getKey().substring(prefix.length()), Math.max(0, entry.getValue()));
			}
		}
		return out;
	}

	private StepLocationPlan toPlan(String guideId, String stepKey, StoredStep stored)
	{
		if (stored == null || stored.waypoints == null || stored.waypoints.isEmpty())
		{
			return null;
		}
		List<StepLocationHint> hints = new ArrayList<>();
		int index = 0;
		for (StoredWaypoint waypoint : stored.waypoints)
		{
			if (!waypoint.valid() || hints.size() >= MAX_WAYPOINTS)
			{
				continue;
			}
			String id = waypoint.id == null || waypoint.id.trim().isEmpty()
				? "manual:" + guideId + ":" + stepKey + ":" + index : waypoint.id;
			hints.add(StepLocationHint.manual(id,
				waypoint.label == null ? "Custom waypoint " + (index + 1) : waypoint.label,
				new WorldPoint(waypoint.x, waypoint.y, waypoint.plane), waypoint.radius));
			index++;
		}
		return hints.isEmpty() ? null : new StepLocationPlan(stepKey, hints);
	}

	synchronized boolean hasPlan(String guideId, String stepKey)
	{
		Root root = readRoot();
		Map<String, StoredStep> guide = root.guides.get(guideId);
		StoredStep step = guide == null ? null : guide.get(stepKey);
		return step != null && step.waypoints != null && !step.waypoints.isEmpty();
	}

	synchronized void rename(String guideId, String stepKey, int index, String label)
	{
		Root root = readRoot();
		StoredStep step = storedStep(root, guideId, stepKey);
		if (step == null || index < 0 || index >= step.waypoints.size())
		{
			throw new IllegalStateException("The active waypoint is not a custom waypoint");
		}
		String clean = label == null ? "" : label.trim();
		if (clean.isEmpty() || clean.length() > 120)
		{
			throw new IllegalArgumentException("Waypoint label must contain 1-120 characters");
		}
		step.waypoints.get(index).label = clean;
		writeRoot(root);
	}

	synchronized int move(String guideId, String stepKey, int index, int direction)
	{
		Root root = readRoot();
		StoredStep step = storedStep(root, guideId, stepKey);
		if (step == null || index < 0 || index >= step.waypoints.size() || direction == 0)
		{
			throw new IllegalStateException("The active waypoint is not a custom waypoint");
		}
		int target = Math.max(0, Math.min(step.waypoints.size() - 1,
			index + (direction > 0 ? 1 : -1)));
		if (target != index)
		{
			StoredWaypoint waypoint = step.waypoints.remove(index);
			step.waypoints.add(target, waypoint);
			rewriteWaypointIds(guideId, stepKey, step);
			writeRoot(root);
			setActiveIndex(guideId, stepKey, target);
		}
		return target;
	}

	synchronized int removeWaypoint(String guideId, String stepKey, int index)
	{
		Root root = readRoot();
		Map<String, StoredStep> guide = root.guides.get(guideId);
		StoredStep step = guide == null ? null : guide.get(stepKey);
		if (step == null || step.waypoints == null || index < 0 || index >= step.waypoints.size())
		{
			throw new IllegalStateException("The active waypoint is not a custom waypoint");
		}
		step.waypoints.remove(index);
		if (step.waypoints.isEmpty())
		{
			guide.remove(stepKey);
			if (guide.isEmpty())
			{
				root.guides.remove(guideId);
			}
			writeRoot(root);
			removeActiveIndex(guideId, stepKey);
			return 0;
		}
		rewriteWaypointIds(guideId, stepKey, step);
		writeRoot(root);
		int next = Math.min(index, step.waypoints.size() - 1);
		setActiveIndex(guideId, stepKey, next);
		return next;
	}

	private static StoredStep storedStep(Root root, String guideId, String stepKey)
	{
		Map<String, StoredStep> guide = root.guides.get(guideId);
		StoredStep step = guide == null ? null : guide.get(stepKey);
		return step == null || step.waypoints == null ? null : step;
	}

	private static void rewriteWaypointIds(String guideId, String stepKey, StoredStep step)
	{
		for (int i = 0; i < step.waypoints.size(); i++)
		{
			step.waypoints.get(i).id = "manual:" + guideId + ":" + stepKey + ":" + i;
		}
	}

	synchronized void replace(String guideId, String stepKey, String label, WorldPoint point)
	{
		Root root = readRoot();
		StoredStep step = new StoredStep();
		step.waypoints = new ArrayList<>();
		step.waypoints.add(StoredWaypoint.of("manual:" + guideId + ":" + stepKey + ":0",
			label, point, 5));
		root.guides.computeIfAbsent(guideId, k -> new HashMap<>()).put(stepKey, step);
		writeRoot(root);
		setActiveIndex(guideId, stepKey, 0);
	}

	/**
	 * Appends a manual waypoint. When no custom override exists yet, the current
	 * automatic plan is copied first so "Add waypoint" extends the route instead
	 * of silently replacing every automatically resolved stop.
	 */
	synchronized void append(String guideId, String stepKey, StepLocationPlan basePlan,
		String label, WorldPoint point)
	{
		Root root = readRoot();
		Map<String, StoredStep> guide = root.guides.computeIfAbsent(guideId, k -> new HashMap<>());
		StoredStep step = guide.get(stepKey);
		if (step == null)
		{
			if (basePlan != null && basePlan.size() >= MAX_WAYPOINTS)
			{
				throw new IllegalStateException(
					"The automatic route already contains the maximum of " + MAX_WAYPOINTS + " waypoints");
			}
			step = new StoredStep();
			step.waypoints = new ArrayList<>();
			if (basePlan != null)
			{
				for (StepLocationHint waypoint : basePlan.getWaypoints())
				{
					if (waypoint == null || waypoint.getPoint() == null)
					{
						break;
					}
					int index = step.waypoints.size();
					step.waypoints.add(StoredWaypoint.of(
						"manual:" + guideId + ":" + stepKey + ":" + index,
						waypoint.getLabel(), waypoint.getPoint(), waypoint.getArrivalRadius()));
				}
			}
			guide.put(stepKey, step);
		}
		if (step.waypoints == null)
		{
			step.waypoints = new ArrayList<>();
		}
		if (step.waypoints.size() >= MAX_WAYPOINTS)
		{
			throw new IllegalStateException("A step can contain at most " + MAX_WAYPOINTS + " custom waypoints");
		}
		int index = step.waypoints.size();
		step.waypoints.add(StoredWaypoint.of("manual:" + guideId + ":" + stepKey + ":" + index,
			label, point, 5));
		writeRoot(root);
	}

	synchronized void clear(String guideId, String stepKey)
	{
		Root root = readRoot();
		Map<String, StoredStep> guide = root.guides.get(guideId);
		if (guide != null)
		{
			guide.remove(stepKey);
			if (guide.isEmpty())
			{
				root.guides.remove(guideId);
			}
			writeRoot(root);
		}
		removeActiveIndex(guideId, stepKey);
	}

	synchronized String exportGuide(String guideId)
	{
		Root root = readRoot();
		Root export = new Root();
		Map<String, StoredStep> guide = root.guides.get(guideId);
		if (guide != null)
		{
			export.guides.put(guideId, guide);
		}
		return gson.toJson(export);
	}

	synchronized int importJson(String json, String expectedGuideId, Set<String> validStepKeys)
	{
		if (json == null || json.length() > MAX_JSON_CHARS)
		{
			throw new IllegalArgumentException("Custom location data is empty or too large");
		}
		// instance API, not JsonParser.parseString: the client bundles an
		// older gson where the static method does not exist (NoSuchMethodError)
		JsonElement parsed = new JsonParser().parse(json);
		if (!parsed.isJsonObject())
		{
			throw new IllegalArgumentException("Custom location data must be a JSON object");
		}
		Root incoming = gson.fromJson(parsed, Root.class);
		if (incoming == null || incoming.guides == null || incoming.guides.size() > MAX_GUIDES
			|| incoming.schemaVersion < 1 || incoming.schemaVersion > 1)
		{
			throw new IllegalArgumentException("Invalid or unsupported custom location data");
		}
		Root current = readRoot();
		int imported = 0;
		for (Map.Entry<String, Map<String, StoredStep>> guideEntry : incoming.guides.entrySet())
		{
			String guideId = guideEntry.getKey();
			if (guideId == null || !guideId.equals(expectedGuideId) || guideEntry.getValue() == null)
			{
				continue;
			}
			Map<String, StoredStep> destination = current.guides.computeIfAbsent(guideId, k -> new HashMap<>());
			for (Map.Entry<String, StoredStep> stepEntry : guideEntry.getValue().entrySet())
			{
				if (imported >= MAX_STEPS || !validStepKey(stepEntry.getKey())
					|| validStepKeys == null || !validStepKeys.contains(stepEntry.getKey()))
				{
					continue;
				}
				StoredStep sanitized = sanitize(guideId, stepEntry.getKey(), stepEntry.getValue());
				if (sanitized != null)
				{
					destination.put(stepEntry.getKey(), sanitized);
					imported++;
				}
			}
		}
		writeRoot(current);
		return imported;
	}

	synchronized int getActiveIndex(String guideId, String stepKey)
	{
		Map<String, Integer> indexes = readIndexes();
		Integer value = indexes.get(indexKey(guideId, stepKey));
		return value == null ? 0 : Math.max(0, value);
	}

	synchronized void setActiveIndex(String guideId, String stepKey, int index)
	{
		Map<String, Integer> indexes = readIndexes();
		String key = indexKey(guideId, stepKey);
		// Index 0 is what an ABSENT entry already means (getActiveIndex
		// defaults to 0), so store it as a removal instead of a zero. This
		// keeps the blob self-pruning - only steps currently mid-route hold
		// an entry - where appending a 0 per phase advance/rewind grew the
		// JSON toward MAX_JSON_CHARS, past which readIndexes drops the whole
		// map and every saved position was silently lost.
		Integer previous = index <= 0 ? indexes.remove(key)
			: indexes.put(key, index);
		if (index <= 0 && previous == null)
		{
			return; // nothing was stored and nothing needs storing
		}
		writeConfig(INDEX_KEY, gson.toJson(indexes));
	}

	private synchronized void removeActiveIndex(String guideId, String stepKey)
	{
		Map<String, Integer> indexes = readIndexes();
		if (indexes.remove(indexKey(guideId, stepKey)) != null)
		{
			writeConfig(INDEX_KEY, gson.toJson(indexes));
		}
	}

	private Root readRoot()
	{
		String json = readConfig(LOCATION_KEY);
		if (json == null || json.isEmpty())
		{
			state = StoreState.EMPTY;
			return new Root();
		}
		if (json.length() > MAX_READ_CHARS)
		{
			// Reads degrade to empty because the data is unusable, but the
			// state is recorded so the next write CANNOT overwrite it.
			state = StoreState.OVERSIZED;
			log.warn("Stored custom locations exceed the size cap ({} chars) - "
				+ "they will be left untouched and no pins can be saved until "
				+ "the store is reset", json.length());
			return new Root();
		}
		try
		{
			Root root = gson.fromJson(json, Root.class);
			if (root != null && root.guides != null)
			{
				// an older schema is not corruption: read it as-is and let the
				// next write stamp the current version
				state = StoreState.VALID;
				return root;
			}
			Root recovered = readBackup();
			if (recovered != null)
			{
				log.warn("Stored custom locations were unreadable; recovered the previous copy");
				state = StoreState.RECOVERED;
				return recovered;
			}
			if (root == null || root.guides == null)
			{
				state = StoreState.CORRUPTED;
				log.warn("Stored custom locations are not in the expected shape - "
					+ "they will be left untouched and no pins can be saved until "
					+ "the store is reset");
				return new Root();
			}
			state = StoreState.VALID;
			return root;
		}
		catch (RuntimeException ex)
		{
			Root recovered = readBackup();
			if (recovered != null)
			{
				log.warn("Stored custom locations could not be read; "
					+ "recovered the previous copy", ex);
				state = StoreState.RECOVERED;
				return recovered;
			}
			state = StoreState.CORRUPTED;
			log.warn("Stored custom locations could not be read - they will be "
				+ "left untouched and no pins can be saved until the store is reset", ex);
			return new Root();
		}
	}

	/** Previous good copy, or null when there is not a usable one. */
	private Root readBackup()
	{
		String json = readConfig(BACKUP_KEY);
		if (json == null || json.isEmpty() || json.length() > MAX_READ_CHARS)
		{
			return null;
		}
		try
		{
			Root root = gson.fromJson(json, Root.class);
			return root != null && root.guides != null ? root : null;
		}
		catch (RuntimeException ignored)
		{
			return null;
		}
	}

	synchronized long getRevision()
	{
		return revision;
	}

	/** Force cached plans to reload after a RuneLite/profile store switch. */
	synchronized void invalidate()
	{
		revision++;
	}

	private void writeRoot(Root root)
	{
		// The stored blob could not be read, so this write would replace real
		// user pins with whatever we managed to parse (nothing). Refuse until
		// the user resets the store deliberately.
		if (state == StoreState.CORRUPTED || state == StoreState.OVERSIZED)
		{
			throw new IllegalStateException(
				"Custom location data could not be read, so it will not be overwritten. "
					+ "Use Location tools -> 'Reset damaged custom pins' to discard it.");
		}
		root.schemaVersion = SCHEMA_VERSION;
		String json = gson.toJson(root);
		String previous = readConfig(LOCATION_KEY);
		int previousLength = previous == null ? 0 : previous.length();
		// over the cap is only acceptable while SHRINKING a legacy store
		// that predates the cap - pruning must never be refused
		if (json.length() > MAX_JSON_CHARS && json.length() >= previousLength)
		{
			throw new IllegalStateException("Custom location data exceeds the storage limit");
		}
		// keep the previous good value so a truncated or failed write is
		// recoverable rather than terminal
		if (state != StoreState.RECOVERED && previous != null && !previous.isEmpty()
			&& previous.length() <= MAX_READ_CHARS)
		{
			writeConfig(BACKUP_KEY, previous);
		}
		writeConfig(LOCATION_KEY, json);
		state = StoreState.VALID;
		revision++;
	}

	/** State of the stored blob as of the last read. */
	synchronized StoreState getState()
	{
		return state;
	}

	/**
	 * Deliberately discard unreadable stored data so pins can be saved again.
	 * Only call from an explicit user action - this is the one path allowed to
	 * destroy data that could not be parsed.
	 */
	/** True when the stored blob is unreadable and writes are refused. */
	synchronized boolean isDamaged()
	{
		readRoot(); // refresh the state from the stored blob
		return state == StoreState.CORRUPTED || state == StoreState.OVERSIZED;
	}

	synchronized void resetDamagedStore()
	{
		if (state != StoreState.CORRUPTED && state != StoreState.OVERSIZED)
		{
			return;
		}
		log.warn("Discarding unreadable custom location data at the user's request");
		writeConfig(LOCATION_KEY, "");
		state = StoreState.EMPTY;
		revision++;
	}

	@SuppressWarnings("unchecked")
	private Map<String, Integer> readIndexes()
	{
		String json = readConfig(INDEX_KEY);
		if (json == null || json.length() > MAX_JSON_CHARS)
		{
			return new HashMap<>();
		}
		try
		{
			Map<String, Double> raw = gson.fromJson(json, Map.class);
			Map<String, Integer> out = new HashMap<>();
			if (raw != null)
			{
				for (Map.Entry<String, Double> entry : raw.entrySet())
				{
					if (entry.getKey() != null && entry.getValue() != null)
					{
						out.put(entry.getKey(), entry.getValue().intValue());
					}
				}
			}
			return out;
		}
		catch (RuntimeException ex)
		{
			return new HashMap<>();
		}
	}

	private String readConfig(String key)
	{
		// An empty profile value must not shadow real data stored globally:
		// reads fall back to global, but writes go to the profile, so treating
		// "" as present orphaned the global copy and looked like data loss.
		String profile = configManager.getRSProfileConfiguration(GROUP, key);
		return profile != null && !profile.isEmpty()
			? profile
			: configManager.getConfiguration(GROUP, key);
	}

	private void writeConfig(String key, String value)
	{
		if (configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(GROUP, key, value);
		}
		else
		{
			// no character profile yet (login screen): refuse rather than
			// write into the GLOBAL config, where the pins would bleed into
			// every character that has no profile-scoped blob of its own
			throw new IllegalStateException(
				"Log into a character before editing custom locations");
		}
	}

	private static String indexKey(String guideId, String stepKey)
	{
		return guideId + "|" + stepKey;
	}

	private static boolean validStepKey(String key)
	{
		return key != null && STEP_KEY.matcher(key).matches();
	}

	private static StoredStep sanitize(String guideId, String stepKey, StoredStep input)
	{
		if (input == null || input.waypoints == null)
		{
			return null;
		}
		StoredStep out = new StoredStep();
		out.waypoints = new ArrayList<>();
		for (StoredWaypoint waypoint : input.waypoints)
		{
			if (waypoint == null || !waypoint.valid() || out.waypoints.size() >= MAX_WAYPOINTS)
			{
				continue;
			}
			String label = waypoint.label == null ? "Custom waypoint" : waypoint.label.trim();
			if (label.isEmpty())
			{
				label = "Custom waypoint";
			}
			if (label.length() > 120)
			{
				label = label.substring(0, 120);
			}
			int index = out.waypoints.size();
			StoredWaypoint clean = StoredWaypoint.of(
				"manual:" + guideId + ":" + stepKey + ":" + index,
				label, new WorldPoint(waypoint.x, waypoint.y, waypoint.plane), waypoint.radius);
			out.waypoints.add(clean);
		}
		return out.waypoints.isEmpty() ? null : out;
	}

	private static final class Root
	{
		private int schemaVersion = 1;
		private Map<String, Map<String, StoredStep>> guides = new HashMap<>();
	}

	private static final class StoredStep
	{
		private List<StoredWaypoint> waypoints = new ArrayList<>();
	}

	private static final class StoredWaypoint
	{
		private String id;
		private String label;
		private int x;
		private int y;
		private int plane;
		private int radius = 5;

		private static StoredWaypoint of(String id, String label, WorldPoint point, int radius)
		{
			StoredWaypoint out = new StoredWaypoint();
			out.id = id;
			out.label = label;
			out.x = point.getX();
			out.y = point.getY();
			out.plane = point.getPlane();
			out.radius = radius;
			return out;
		}

		private boolean valid()
		{
			return x > 0 && x <= 16383 && y > 0 && y <= 16383
				&& plane >= 0 && plane <= 3 && radius >= 1 && radius <= 20;
		}
	}
}

package com.hcimguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines the chat dialogue option the guide says to click, Quest
 * Helper-style. The guide's "(2,1)" notation is parsed per step; the plugin
 * tracks which menu of the conversation is showing - and that the
 * conversation is with the NPC or object the step actually names, so chatting
 * with bystanders never draws a box - and this overlay outlines that option's
 * text. Display only - the player still clicks.
 */
public class DialogOptionOverlay extends Overlay
{
	private final Client client;
	private final HcimGuidePlugin plugin;
	private final HcimGuideConfig config;

	@Inject
	public DialogOptionOverlay(Client client, HcimGuidePlugin plugin, HcimGuideConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.highlightDialogOptions())
		{
			return null;
		}
		int option = plugin.getDialogHighlightOption();
		if (option < 1)
		{
			return null;
		}
		Widget menu = client.getWidget(InterfaceID.CHATMENU, 1);
		if (menu == null || menu.isHidden())
		{
			return null;
		}
		Widget[] children = menu.getDynamicChildren();
		// children[0] is the "Select an Option" title; options start at 1
		if (children == null || option >= children.length)
		{
			return null;
		}
		Widget target = children[option];
		if (target == null || target.isHidden())
		{
			return null;
		}
		Rectangle b = target.getBounds();
		if (b == null || b.width <= 0)
		{
			return null;
		}
		Color color = config.dialogOptionColor();
		g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 40));
		g.fillRoundRect(b.x - 3, b.y - 2, b.width + 6, b.height + 4, 6, 6);
		g.setColor(color);
		g.drawRoundRect(b.x - 3, b.y - 2, b.width + 6, b.height + 4, 6, 6);
		return null;
	}
}

package com.hcimguide;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Extracts a dialogue-choice sequence from a step's text. Guides notate the
 * chat options to pick as "(2,1)" or "(3,1,2,2,1,1)": each number is the
 * option to click in the Nth option menu of the conversation.
 *
 * Deliberately strict to avoid false positives: two to twelve single digits
 * (1-9), commas only. Dose suffixes ("Prayer potion(4)") have one number,
 * coordinates ("(3212, 3428)") have multi-digit numbers, inventory notes
 * ("(14 Inventory Slots)") have words - none match.
 */
final class DialogSequenceParser
{
	private static final Pattern SEQ = Pattern.compile(
		"\\(\\s*([1-9]\\s*(?:,\\s*[1-9]\\s*){1,11})\\)");

	/**
	 * Trailing run of capitalized words (with optional of/the connectors
	 * between them) - guides write the choice notation directly after the
	 * NPC's name: "Talk to Father Aereck (3,1)", "on Veos (2,1)".
	 * Only ever run on a NAME_WINDOW-bounded suffix: on an unbounded
	 * capitalized run java.util.regex recurses per word and a hostile wiki
	 * edit of a few KB would StackOverflowError the guide import.
	 */
	private static final Pattern NAME_BEFORE = Pattern.compile(
		"([A-Z][A-Za-z'’-]*(?:\\s+(?:(?:of|the)\\s+)?[A-Z][A-Za-z'’-]*)*)\\s*$");

	/** The SEQ regex admits at most twelve entries, so this stays tiny. */
	private static final Pattern COMMA = Pattern.compile(",");

	/** Names max out at 32 chars; 48 leaves room for connectors. */
	private static final int NAME_WINDOW = 48;

	private DialogSequenceParser()
	{
	}

	/** First dialogue sequence in the text, or null when the step has none. */
	static int[] extract(String stepText)
	{
		if (stepText == null || stepText.isEmpty())
		{
			return null;
		}
		Matcher m = SEQ.matcher(stepText);
		if (!m.find())
		{
			return null;
		}
		String[] parts = COMMA.split(m.group(1));
		int[] seq = new int[parts.length];
		for (int i = 0; i < parts.length; i++)
		{
			seq[i] = Integer.parseInt(parts[i].trim());
		}
		return seq;
	}

	/**
	 * The name written directly before the first dialogue sequence, e.g.
	 * "Head East & start X Marks the Spot on Veos (2,1)" -&gt; "Veos". Guides
	 * put the notation right after whoever the conversation is with, which
	 * catches steps whose phrasing has no "Talk to" verb for
	 * {@link TargetExtractor#extract}. Underscores count as spaces
	 * ("Jennifer_(Shayzien)"). Null when nothing name-like precedes it.
	 */
	static String npcBefore(String stepText)
	{
		if (stepText == null || stepText.isEmpty())
		{
			return null;
		}
		Matcher m = SEQ.matcher(stepText);
		if (!m.find())
		{
			return null;
		}
		String before = stepText.substring(0, m.start()).replace('_', ' ').trim();
		if (before.length() > NAME_WINDOW)
		{
			// keep the regex input tiny; cut on a word boundary when one
			// exists so the window never starts mid-word
			int cut = before.length() - NAME_WINDOW;
			int ws = before.indexOf(' ', cut);
			before = ws >= 0 && ws < before.length() - 1
				? before.substring(ws + 1) : before.substring(cut);
		}
		Matcher n = NAME_BEFORE.matcher(before);
		if (!n.find())
		{
			return null;
		}
		String name = n.group(1).trim();
		if (name.length() < 2 || name.length() > 32)
		{
			return null;
		}
		return name;
	}
}

package com.hcimguide;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Compass widget pointing toward the exact destination currently handed to
 * Shortest Path (relative to the current camera rotation), with an optional
 * tile distance underneath. This keeps the compass present for every located
 * step using Shortest Path, even when its destination is inside the loaded
 * scene. Without an active Shortest Path hand-off it falls back to the tracked
 * far target, then to the next unchecked step's known location when configured.
 * Dial and needle style are configurable (full dial or bare arrow; triangle
 * or tailed).
 *
 * Deliberately unobtrusive: small by default, semi-transparent (opacity
 * configurable), and movable anywhere on screen with Alt+drag like any
 * RuneLite overlay. Cheap: a handful of trig ops and one polygon per frame.
 */
public class DirectionArrowOverlay extends Overlay
{
	private static final int TEXT_HEIGHT = 14;

	private final Client client;
	private final HcimGuidePlugin plugin;
	private final HcimGuideConfig config;

	@Inject
	public DirectionArrowOverlay(Client client, HcimGuidePlugin plugin, HcimGuideConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showDirectionArrow())
		{
			return null;
		}
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null; // checked FIRST: the fallback below must not run without a player
		}
		// Prefer the exact tile already accepted by the Shortest Path hand-off.
		// In particular, do not recompute from a live NPC here: the pathfinder
		// deliberately applies a movement deadband, and the compass must agree
		// with the path it actually drew rather than point a tile or two away.
		WorldPoint target = selectPrimaryTarget(
			plugin.getShortestPathTarget(), plugin.getFarTarget());
		// No active path/far target: fall back to the NEXT unchecked step's
		// known target (config-gated). The fallback remains limited to a target
		// outside the loaded scene or on another floor so nearby locations are
		// handled by the scene arrow unless Shortest Path is actively guiding
		// them.
		if (target == null && config.compassNextStep() && !plugin.hasPinnedTarget())
		{
			WorldPoint next = plugin.getNextStepPoint();
			if (next != null
				&& (next.getPlane() != player.getWorldLocation().getPlane()
					|| net.runelite.api.coords.LocalPoint.fromWorld(client.getTopLevelWorldView(), next) == null))
			{
				target = next;
			}
		}
		if (target == null || !plugin.allowCompassGuidance(target))
		{
			return null;
		}
		WorldPoint me = player.getWorldLocation();
		int dx = target.getX() - me.getX();
		int dy = target.getY() - me.getY();
		int distance = (int) Math.round(Math.hypot(dx, dy));
		// a target on another floor gets an explicit floor cue instead of a
		// misleading flat bearing to a spot the player may be standing on
		int planeDelta = target.getPlane() - me.getPlane();
		// standing ON the destination tile, same floor: there is no bearing to
		// draw (atan2(0,0) would render an arbitrary north needle over
		// "0 tiles"), and nothing useful to say - hide until there is one.
		// Reachable since the compass follows in-scene path targets.
		if (distance == 0 && planeDelta == 0)
		{
			return null;
		}

		// world bearing (0 = north, clockwise), then rotate into screen space
		// using the camera yaw. Current clients report yaw in 16384 JAU per
		// revolution (0 = north) - same convention Perspective.localToMinimap
		// uses, which is also where the "+" rotation sign comes from.
		double worldAngle = Math.atan2(dx, dy);
		double cameraRad = (client.getCameraYaw() & 0x3fff) * (Math.PI * 2 / 16384.0);
		double screenAngle = worldAngle + cameraRad;

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		OverlayFonts.apply(g, config);

		final int size = config.compassSize();
		final double opacity = config.compassOpacity() / 100.0;
		final boolean showDistance = config.compassShowDistance();

		int cx = size / 2;
		int cy = size / 2;
		int r = size / 2 - 3;
		// the compass has its own colour so it can be told apart from the NPC
		// outline, which is what highlightColor drives
		Color accent = withOpacity(config.compassColor(), opacity);

		if (config.compassShowRing())
		{
			g.setColor(withOpacity(new Color(0, 0, 0, 140), opacity));
			g.fillOval(cx - r, cy - r, r * 2, r * 2);
			g.setColor(accent);
			g.setStroke(new BasicStroke(1.5f));
			g.drawOval(cx - r, cy - r, r * 2, r * 2);
		}

		g.setColor(accent);
		int tipX = cx + (int) Math.round(Math.sin(screenAngle) * (r - 4));
		int tipY = cy - (int) Math.round(Math.cos(screenAngle) * (r - 4));
		if (config.compassArrowStyle() == HcimGuideConfig.CompassArrowStyle.TAILED)
		{
			// arrow with a tail: shaft from the back of the dial to the tip,
			// capped by a smaller head so it reads as a drawn arrow
			int tailX = cx - (int) Math.round(Math.sin(screenAngle) * (r - 5));
			int tailY = cy + (int) Math.round(Math.cos(screenAngle) * (r - 5));
			g.setStroke(new BasicStroke(Math.max(2f, size / 22f),
				BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(tailX, tailY, tipX, tipY);
			drawHead(g, tipX, tipY, screenAngle, Math.max(6, size / 5));
		}
		else
		{
			// solid triangle: tip at the dial edge, base corners rotated +-150 degrees
			drawHead(g, tipX, tipY, screenAngle, Math.max(8, size / 4));
		}

		if (showDistance)
		{
			String label;
			if (planeDelta != 0 && distance == 0)
			{
				// standing on the target's tile with the target on another
				// floor: a "0 tiles" bearing is meaningless - show only the
				// floor cue
				label = planeDelta > 0 ? "above" : "below";
			}
			else if (planeDelta != 0)
			{
				label = distance + " tiles " + (planeDelta > 0 ? "(above)" : "(below)");
			}
			else
			{
				label = distance + " tiles";
			}
			int w = g.getFontMetrics().stringWidth(label);
			int tx = Math.max(0, (size - w) / 2);
			g.setColor(withOpacity(Color.BLACK, opacity));
			g.drawString(label, tx + 1, size + TEXT_HEIGHT - 3 + 1);
			g.setColor(withOpacity(Color.WHITE, opacity));
			g.drawString(label, tx, size + TEXT_HEIGHT - 3);
		}

		return new Dimension(size, size + (showDistance ? TEXT_HEIGHT : 0));
	}

	/** Prefer the destination actually represented by Shortest Path. */
	static WorldPoint selectPrimaryTarget(WorldPoint shortestPathTarget, WorldPoint farTarget)
	{
		return shortestPathTarget != null ? shortestPathTarget : farTarget;
	}

	/** Filled triangular arrowhead with its tip at (tipX, tipY). */
	private static void drawHead(Graphics2D g, int tipX, int tipY, double angle, int arm)
	{
		double left = angle + Math.toRadians(150);
		double right = angle - Math.toRadians(150);
		Polygon tri = new Polygon();
		tri.addPoint(tipX, tipY);
		tri.addPoint(tipX + (int) Math.round(Math.sin(left) * arm), tipY - (int) Math.round(Math.cos(left) * arm));
		tri.addPoint(tipX + (int) Math.round(Math.sin(right) * arm), tipY - (int) Math.round(Math.cos(right) * arm));
		g.fillPolygon(tri);
	}

	private static Color withOpacity(Color c, double opacity)
	{
		int alpha = (int) Math.max(0, Math.min(255, Math.round(c.getAlpha() * opacity)));
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.hcimguide;

import net.runelite.api.Tile;

/**
 * A ground item tile that a current-bank step needs the player to pick up.
 */
public class GroundHighlight
{
	private final Tile tile;
	private final String name;
	private final String normalized;
	private final String singularized;

	public GroundHighlight(Tile tile, String name)
	{
		this.tile = tile;
		this.name = name;
		// precomputed once at spawn so per-tick matching is plain string equality
		this.normalized = Names.normalize(name);
		this.singularized = Names.singularize(name);
	}

	public Tile getTile()
	{
		return tile;
	}

	public String getName()
	{
		return name;
	}

	/** True when this ground item satisfies the given requirement's name. */
	public boolean matches(ItemReq req)
	{
		return normalized.equals(req.getNormalized())
			|| singularized.equals(req.getSingularized());
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.List;

public class Guide
{
	private final List<GuideEpisode> episodes = new ArrayList<>();

	/**
	 * Old step key -&gt; current step key, for steps whose TEXT was produced
	 * differently by an earlier parser version (e.g. the JSON parser once
	 * joined formatting runs with spaces, splitting words). Lets progress
	 * recorded under the old keys be replayed onto the fixed keys. Empty for
	 * parsers that never changed a step's text.
	 */
	private final java.util.Map<String, String> legacyStepKeys = new java.util.HashMap<>();

	/**
	 * Old step key -&gt; ALL current step keys it was split into, for steps a
	 * parser now divides into several smaller steps (e.g. the JSON parser
	 * splitting paragraph steps into one step per sentence). Progress recorded
	 * under the old key replays onto every child, so a paragraph the user had
	 * completed stays fully completed after the split. Empty for parsers that
	 * never split a step.
	 */
	private final java.util.Map<String, java.util.List<String>> legacySplitKeys = new java.util.HashMap<>();

	public List<GuideEpisode> getEpisodes()
	{
		return episodes;
	}

	public java.util.Map<String, String> getLegacyStepKeys()
	{
		return legacyStepKeys;
	}

	public java.util.Map<String, java.util.List<String>> getLegacySplitKeys()
	{
		return legacySplitKeys;
	}

	public int totalSteps()
	{
		int n = 0;
		for (GuideEpisode e : episodes)
		{
			n += e.totalSteps();
		}
		return n;
	}

	public int totalSections()
	{
		int n = 0;
		for (GuideEpisode e : episodes)
		{
			n += e.getBanks().size();
		}
		return n;
	}

	private static final java.util.regex.Pattern NUMBERED_BANK_ID =
		java.util.regex.Pattern.compile("E[0-9]+\\.B[0-9]+[A-Z]?");

	/** Number of sections positively identified as numbered Bank markers. */
	public int numberedBanks()
	{
		int n = 0;
		for (GuideEpisode e : episodes)
		{
			for (GuideBank b : e.getBanks())
			{
				if (NUMBERED_BANK_ID.matcher(b.getId()).matches())
				{
					n++;
				}
			}
		}
		return n;
	}

	public boolean isEmpty()
	{
		return totalSteps() == 0;
	}

	/**
	 * Set when a safety cap (step count, episode count, sections per
	 * episode) discarded part of the source during parsing, so the UI can
	 * say "this import is incomplete" instead of presenting a truncated
	 * guide as the whole thing. Never persisted - recomputed on every parse.
	 */
	private boolean truncated;

	public void markTruncated()
	{
		truncated = true;
	}

	public boolean isTruncated()
	{
		return truncated;
	}
}

