package com.hcimguide;

import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.LinkBrowser;

/**
 * Every clipboard read or write, and every external browser launch, in one
 * place.
 *
 * <p>This is deliberately the ONLY class in the plugin that reads or writes the
 * system clipboard, or asks the operating system to open a URL. No other file
 * imports {@link Toolkit}, {@link java.awt.datatransfer.Clipboard},
 * {@link StringSelection} or {@link LinkBrowser}.</p>
 *
 * <p>The boundary is deliberately narrow. It does NOT cover every desktop-facing
 * thing the plugin does: Swing rendering and the file chooser used for guide
 * import and export are still in the panel. The verifiable claim is about the
 * clipboard and the browser only.</p>
 *
 * <p>The clipboard is only ever read when the user explicitly asks to import
 * something, and only ever written when the user explicitly asks to export. The
 * plugin never polls it.</p>
 *
 * <p>URL opening is validated here rather than at the call sites. Guide content
 * is remote data, so a video link arrives from the same untrusted source as the
 * rest of a guide. {@link VideoLinks#isVideoUrl} already rejects anything that
 * is not an http(s) URL on an exact host allowlist, but before this class that
 * check ran when the guide was parsed while the browser call happened much
 * later, in a different file. Re-checking at the moment of opening turns a
 * property that depended on an upstream invariant into one that can be verified
 * by reading this method.</p>
 */
@Singleton
public class GuideExternalActions
{
	/**
	 * Indirection over the browser so a test can assert exactly which URL would
	 * be opened, and assert that nothing is opened for a rejected URL, without
	 * launching a real browser.
	 */
	public interface BrowserLauncher
	{
		void browse(String url);
	}

	private final BrowserLauncher launcher;

	@Inject
	GuideExternalActions()
	{
		this(LinkBrowser::browse);
	}

	GuideExternalActions(BrowserLauncher launcher)
	{
		this.launcher = launcher;
	}

	/**
	 * Put {@code text} on the system clipboard.
	 *
	 * @throws RuntimeException if the clipboard is unavailable, which AWT does
	 *     when another application holds it. Callers surface the message.
	 */
	public void copyText(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new StringSelection(text == null ? "" : text), null);
	}

	/**
	 * Current clipboard contents as text, or null when the clipboard holds
	 * something else or cannot be read. Never throws.
	 */
	public String readText()
	{
		try
		{
			return (String) Toolkit.getDefaultToolkit().getSystemClipboard()
				.getData(DataFlavor.stringFlavor);
		}
		catch (Exception ex)
		{
			return null;
		}
	}

	/**
	 * Open a guide video link in the user's browser, but only the canonical
	 * form of a URL that passes every check.
	 *
	 * <p>Uses {@link VideoLinks#accepted} rather than the boolean test, because
	 * {@code accepted} also upgrades an {@code http://} link to {@code https://}.
	 * Validating with the boolean form and then opening the ORIGINAL string
	 * would hand the browser a downgraded connection for a guide that contains a
	 * plain http link, which is exactly what that normalization exists to
	 * prevent. Opening the returned value keeps every URL property at this
	 * boundary: allowlist, scheme, https upgrade, and null rejection.</p>
	 *
	 * @return true if the URL was accepted and handed to the browser. A false
	 *     return means nothing was opened.
	 */
	public boolean openVideoUrl(String url)
	{
		String accepted = VideoLinks.accepted(url);
		if (accepted == null)
		{
			return false;
		}
		launcher.browse(accepted);
		return true;
	}
}

package com.hcimguide;

import java.awt.Point;
import java.util.Objects;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.util.HotkeyListener;

/**
 * All keyboard and mouse handling for the guide's step navigation.
 *
 * <p>This is deliberately the ONLY class in the plugin that touches RuneLite's
 * input API. Keeping it separate means the rest of the plugin can be seen, at a
 * glance, to have no way of producing input at all: no other file imports
 * {@link KeyManager} or {@link MouseManager}.</p>
 *
 * <p>Nothing here generates input. Both listeners are read-only observers that
 * consume an event when the click landed on one of the guide's own on-screen
 * arrows, so the click does not also reach the game. No event is ever
 * synthesised, injected or replayed.</p>
 */
@Singleton
public class GuideInputHandler
{
	/**
	 * What the handler is allowed to ask the plugin to do. Deliberately narrow:
	 * two navigation actions and two hit tests, nothing else.
	 */
	public interface Actions
	{
		/** Move to the next ({@code true}) or previous step. */
		void navigateStep(boolean forward);

		/** Show or hide location guidance for the current step. */
		void toggleLocationGuide();

		/** Direction of the on-screen step arrow at {@code p}, or 0 for none. */
		int hitNavArrow(Point p);

		/** True when {@code p} is on the location-guidance toggle. */
		boolean hitLocationToggle(Point p);
	}

	private final HcimGuideConfig config;
	private final KeyManager keyManager;
	private final MouseManager mouseManager;

	/*
	 * Threading: register and unregister run on the client thread, while the
	 * listeners below run on the AWT event thread. The gesture fields are
	 * therefore written from both, so they are volatile for visibility. The
	 * synchronized keyword on register/unregister guards the registration
	 * sequence itself and the `registered` flag; it does NOT publish these
	 * fields to the listener thread, which is why volatile is needed as well.
	 * Every read-modify-write of the gesture state happens on the event thread
	 * alone, so visibility is sufficient and no atomicity is required.
	 */

	/** Set while a consumed press is awaiting its matching left-button release. */
	private volatile boolean navPressConsumed;

	/**
	 * Set after a guide control consumed the press. MouseClicked is delivered
	 * after mouseReleased; by then the action may have hidden or moved the
	 * control, so re-running hit tests is not sufficient to keep the same
	 * gesture from reaching the game.
	 */
	private volatile boolean navClickPending;
	private volatile long navReleaseWhen;

	/** Only touched inside the synchronized lifecycle methods. */
	private boolean registered;

	private volatile Actions actions;

	@Inject
	GuideInputHandler(HcimGuideConfig config, KeyManager keyManager, MouseManager mouseManager)
	{
		this.config = config;
		this.keyManager = keyManager;
		this.mouseManager = mouseManager;
		this.nextStepHotkey = new HotkeyListener(() -> this.config.nextStepKeybind())
		{
			@Override
			public void hotkeyPressed()
			{
				if (GuideInputHandler.this.actions != null && GuideInputHandler.this.config.navKeybindsEnabled())
				{
					GuideInputHandler.this.actions.navigateStep(true);
				}
			}
		};
		this.prevStepHotkey = new HotkeyListener(() -> this.config.prevStepKeybind())
		{
			@Override
			public void hotkeyPressed()
			{
				if (GuideInputHandler.this.actions != null && GuideInputHandler.this.config.navKeybindsEnabled())
				{
					GuideInputHandler.this.actions.navigateStep(false);
				}
			}
		};
	}

	private final HotkeyListener nextStepHotkey;
	private final HotkeyListener prevStepHotkey;

	private void markConsumedPress(MouseEvent e)
	{
		navPressConsumed = true;
		navClickPending = true;
		navReleaseWhen = 0L;
	}

	private boolean isMatchingPendingClick(MouseEvent e)
	{
		if (!navClickPending || e.getButton() != MouseEvent.BUTTON1)
		{
			return false;
		}

		// A normal AWT click follows its release immediately, so a short time
		// bound is enough to stop a drag with no click event from causing an
		// unrelated later click to be consumed. Deliberately NO spatial bound:
		// AWT still synthesizes a click after well over six pixels of movement
		// on the same canvas, and the control action taken on press may have
		// moved or cleared the hitboxes - the captured gesture must be
		// consumed wherever its click lands, or it falls through to the game.
		return navReleaseWhen == 0L
			|| (e.getWhen() >= navReleaseWhen && e.getWhen() - navReleaseWhen <= 1500L);
	}

	private void clearPendingClick()
	{
		navClickPending = false;
		navReleaseWhen = 0L;
	}

	private final MouseAdapter navMouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			// Alt+drag is overlay repositioning - never intercept it. It still
			// STARTS a new gesture, so a stale click-suppression from a
			// previous capture must not survive to eat the Alt gesture's click.
			if (actions == null || e.getButton() != MouseEvent.BUTTON1 || e.isAltDown())
			{
				clearPendingClick();
				return e;
			}
			// A NEW press starts a NEW gesture: a captured gesture whose click
			// event never fired (AWT suppresses clicks after large drags) must
			// not survive to eat this unrelated gesture's click.
			clearPendingClick();
			if (actions.hitLocationToggle(e.getPoint()))
			{
				markConsumedPress(e);
				e.consume();
				actions.toggleLocationGuide();
				return e;
			}
			int dir = actions.hitNavArrow(e.getPoint());
			if (dir != 0)
			{
				markConsumedPress(e);
				e.consume();
				actions.navigateStep(dir > 0);
			}
			else
			{
				// stuck-capture heal: if a captured gesture's release was never
				// delivered (focus loss mid-press), this non-control gesture
				// must not have its drags and release consumed by it
				navPressConsumed = false;
			}
			return e;
		}

		@Override
		public MouseEvent mouseDragged(MouseEvent e)
		{
			// the captured gesture owns its drag events too - without this a
			// press-move-release on a control leaks the drags to the game
			if (navPressConsumed)
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			// consume the captured gesture's release REGARDLESS of where the
			// cursor is now - no re-hit-testing against moved hitboxes
			if (navPressConsumed && e.getButton() == MouseEvent.BUTTON1)
			{
				navPressConsumed = false;
				navReleaseWhen = e.getWhen();
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			// Consume the click belonging to a press we already handled, even if
			// that action changed the overlay so the control no longer hit-tests.
			if (isMatchingPendingClick(e))
			{
				clearPendingClick();
				e.consume();
				return e;
			}

			// Any non-matching click ends the stale gesture. Keep the old hit-test
			// fallback for environments that deliver clicked without pressed.
			clearPendingClick();
			if (actions != null
				&& e.getButton() == MouseEvent.BUTTON1 && !e.isAltDown()
				&& (actions.hitLocationToggle(e.getPoint())
					|| actions.hitNavArrow(e.getPoint()) != 0))
			{
				e.consume();
			}
			return e;
		}
	};

	/** Start listening. Called from the plugin's startUp. */
	public synchronized void register(Actions actions)
	{
		this.actions = Objects.requireNonNull(actions, "actions");
		if (registered)
		{
			return;
		}

		boolean nextRegistered = false;
		boolean prevRegistered = false;
		try
		{
			keyManager.registerKeyListener(nextStepHotkey);
			nextRegistered = true;
			keyManager.registerKeyListener(prevStepHotkey);
			prevRegistered = true;
			mouseManager.registerMouseListener(navMouse);
			registered = true;
		}
		catch (RuntimeException ex)
		{
			if (prevRegistered)
			{
				keyManager.unregisterKeyListener(prevStepHotkey);
			}
			if (nextRegistered)
			{
				keyManager.unregisterKeyListener(nextStepHotkey);
			}
			this.actions = null;
			throw ex;
		}
	}

	/** Stop listening and drop the callback. Called from the plugin's shutDown. */
	public synchronized void unregister()
	{
		if (registered)
		{
			// Remove the mouse listener first so no new gesture can begin while the
			// key listeners and callback are being torn down.
			mouseManager.unregisterMouseListener(navMouse);
			keyManager.unregisterKeyListener(prevStepHotkey);
			keyManager.unregisterKeyListener(nextStepHotkey);
			registered = false;
		}
		actions = null;
		navPressConsumed = false;
		clearPendingClick();
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The catalog of guides the dropdown offers: one built-in entry plus any the
 * user added from a wiki link. Stored as JSON in RuneLite config; guide text
 * snapshots themselves live on disk (see {@link GuideService}).
 */
@Singleton
public class GuideRegistry
{
	static final String BUILTIN_ID = "b0aty-hcim-v3";
	static final String BRUHSAILER_ID = "bruhsailer";
	private static final String REGISTRY_KEY = "guides";
	private static final int MAX_REGISTRY_CHARS = 64 * 1024;
	private static final int MAX_USER_GUIDES = 64;
	private static final Logger log = LoggerFactory.getLogger(GuideRegistry.class);

	/**
	 * Built-in, one-click-downloadable guides. sourceUrl guides fetch a raw
	 * file directly; wikiPage guides fetch via the wiki API. Only built-ins
	 * may carry a sourceUrl (a hardcoded, trusted host) - user-added guides
	 * are wiki-link or file only, so no arbitrary URL fetch is ever possible.
	 */
	private static final List<Entry> BUILTINS = new ArrayList<>();

	static
	{
		BUILTINS.add(new Entry(BUILTIN_ID, "B0aty HCIM Guide V3", "Guide:B0aty_HCIM_Guide_V3", null));
		// PINNED to a commit SHA for reproducible downloads. A future release
		// must update the reviewed commit explicitly; moving branch names are not
		// accepted here.
		BUILTINS.add(new Entry(BRUHSAILER_ID, "BRUHsailer Ironman Guide", null,
			"https://raw.githubusercontent.com/umkyzn/BRUHsailer/ec20b7e843da2cca69bf2343734dd2c25fef913f/data/guide_data.json"));
	}

	/** One selectable guide. wikiPage/sourceUrl are null for file-only guides. */
	public static class Entry
	{
		String id;
		String title;
		String wikiPage;
		String sourceUrl;

		Entry()
		{
		}

		Entry(String id, String title, String wikiPage)
		{
			this(id, title, wikiPage, null);
		}

		Entry(String id, String title, String wikiPage, String sourceUrl)
		{
			this.id = id;
			this.title = title;
			this.wikiPage = wikiPage;
			this.sourceUrl = sourceUrl;
		}

		public String getId()
		{
			return id;
		}

		public String getTitle()
		{
			return title;
		}

		public String getWikiPage()
		{
			return wikiPage;
		}

		/** Direct download URL for built-in non-wiki guides, else null. */
		public String getSourceUrl()
		{
			return isBuiltin() ? sourceUrlForBuiltin(id) : null;
		}

		/** True when this guide can be downloaded (wiki page or built-in source URL). */
		public boolean isDownloadable()
		{
			return wikiPage != null || getSourceUrl() != null;
		}

		public boolean isBuiltin()
		{
			return builtinById(id) != null;
		}
	}

	private static Entry builtinById(String id)
	{
		for (Entry e : BUILTINS)
		{
			if (e.id.equals(id))
			{
				return e;
			}
		}
		return null;
	}

	private static String sourceUrlForBuiltin(String id)
	{
		Entry b = builtinById(id);
		return b == null ? null : b.sourceUrl;
	}

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	public GuideRegistry(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/** All guides, built-in first. Always returns at least the built-in entry. */
	public synchronized List<Entry> list()
	{
		List<Entry> entries = new ArrayList<>();
		String json = configManager.getConfiguration(HcimGuideConfig.GROUP, REGISTRY_KEY);
		if (json != null && !json.isEmpty() && json.length() <= MAX_REGISTRY_CHARS)
		{
			try
			{
				Entry[] saved = gson.fromJson(json, Entry[].class);
				if (saved != null)
				{
					// keyed by id, FIRST valid entry wins: a tampered registry
					// with duplicate ids must yield one stable dropdown entry,
					// not several that byId()/remove can disagree about
					java.util.Map<String, Entry> byId = new java.util.LinkedHashMap<>();
					for (Entry e : saved)
					{
						if (byId.size() >= MAX_USER_GUIDES)
						{
							break;
						}
						// re-validate ids on READ, not just on creation: ids become
						// file names (guides/<id>.txt) and config-key fragments, so
						// a tampered/corrupted registry must never yield a path like
						// "../../x"
						if (e != null && e.id != null && e.title != null && !e.isBuiltin()
							&& GUIDE_ID.matcher(e.id).matches() && validWikiPage(e.wikiPage))
						{
							e.title = sanitizeTitle(e.title); // defense on read too
							e.sourceUrl = null; // user entries can never carry a raw URL
							byId.putIfAbsent(e.id, e);
						}
					}
					entries.addAll(byId.values());
				}
			}
			catch (Exception e)
			{
				log.warn("Could not parse guide registry", e);
			}
		}
		else if (json != null && json.length() > MAX_REGISTRY_CHARS)
		{
			log.warn("Guide registry exceeds the safety cap and was ignored");
		}
		// built-ins first, in declared order
		for (int i = BUILTINS.size() - 1; i >= 0; i--)
		{
			Entry b = BUILTINS.get(i);
			entries.add(0, new Entry(b.id, b.title, b.wikiPage, b.sourceUrl));
		}
		return entries;
	}

	public synchronized Entry byId(String id)
	{
		for (Entry e : list())
		{
			if (e.id.equals(id))
			{
				return e;
			}
		}
		return null;
	}

	/**
	 * Titles render in Swing labels, where text starting with "&lt;html&gt;"
	 * becomes live HTML - never let angle brackets through, at creation OR read.
	 */
	private static boolean validWikiPage(String wikiPage)
	{
		if (wikiPage == null)
		{
			return true; // file-only guide
		}
		try
		{
			return WikiUrl.pageTitle(wikiPage).equals(wikiPage);
		}
		catch (IllegalArgumentException ex)
		{
			return false;
		}
	}

	private static String sanitizeTitle(String title)
	{
		String t = title == null ? "" : title.replace("<", "").replace(">", "").trim();
		if (t.length() > 80)
		{
			t = t.substring(0, 80);
		}
		return t.isEmpty() ? "Unnamed guide" : t;
	}

	/** Adds a guide (or returns the existing entry for the same wiki page). */
	public synchronized Entry add(String title, String wikiPage)
	{
		title = sanitizeTitle(title);
		List<Entry> entries = list();
		int userCount = 0;
		for (Entry e : entries)
		{
			if (!e.isBuiltin())
			{
				userCount++;
			}
			if (wikiPage != null && wikiPage.equals(e.wikiPage))
			{
				return e;
			}
		}
		if (userCount >= MAX_USER_GUIDES)
		{
			throw new IllegalStateException("At most " + MAX_USER_GUIDES + " user guides can be registered");
		}
		String base = slug(title);
		String id = base;
		int n = 2;
		while (byIdIn(entries, id) != null)
		{
			id = base + "-" + n++;
		}
		Entry entry = new Entry(id, title, wikiPage);
		entries.add(entry);
		persist(entries);
		return entry;
	}

	/** Removes a user-added guide. Built-in guides cannot be removed. */
	public synchronized boolean remove(String id)
	{
		if (builtinById(id) != null)
		{
			return false;
		}
		List<Entry> entries = list();
		boolean removed = entries.removeIf(e -> e.id.equals(id));
		if (removed)
		{
			persist(entries);
		}
		return removed;
	}

	private void persist(List<Entry> entries)
	{
		// the built-in entry is re-synthesized on read; don't store it
		List<Entry> userEntries = new ArrayList<>();
		for (Entry e : entries)
		{
			if (!e.isBuiltin() && userEntries.size() < MAX_USER_GUIDES)
			{
				userEntries.add(e);
			}
		}
		configManager.setConfiguration(HcimGuideConfig.GROUP, REGISTRY_KEY, gson.toJson(userEntries));
	}

	private static Entry byIdIn(List<Entry> entries, String id)
	{
		for (Entry e : entries)
		{
			if (e.id.equals(id))
			{
				return e;
			}
		}
		return null;
	}

	/** Same shape GuideService enforces: ids become file names and config keys. */
	private static final java.util.regex.Pattern GUIDE_ID =
		java.util.regex.Pattern.compile("[a-z0-9-]{1,64}");
	private static final java.util.regex.Pattern NON_SLUG =
		java.util.regex.Pattern.compile("[^a-z0-9]+");
	private static final java.util.regex.Pattern SLUG_EDGE_DASH =
		java.util.regex.Pattern.compile("(^-|-$)");

	private static String slug(String s)
	{
		String slug = NON_SLUG.matcher(s.toLowerCase(Locale.ROOT)).replaceAll("-");
		slug = SLUG_EDGE_DASH.matcher(slug).replaceAll("");
		return slug.isEmpty() ? "guide" : (slug.length() > 60 ? slug.substring(0, 60) : slug);
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.function.Consumer;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.RuneLite;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Manages locally stored guide snapshots, one per guide id.
 *
 * Every guide is imported ONCE (explicitly, by the user - from the wiki or
 * from a file) and stored on disk. The plugin never contacts the network on
 * its own, so wiki edits or vandalism can never silently change a guide or
 * reset progress. Each guide's previous snapshot is kept as a backup and can
 * be restored.
 */
@Singleton
public class GuideService
{
	/**
	 * Calls that have been handed to OkHttp and have not settled yet. Tracked so
	 * shutdown can cancel them: a guarded callback stops stale state from being
	 * applied, but the request itself would otherwise keep running, holding its
	 * callback and buffers alive past disable.
	 */
	private final java.util.Set<Call> activeCalls =
		java.util.concurrent.ConcurrentHashMap.newKeySet();

	/**
	 * Submit a call and keep track of it until it settles, so
	 * {@link #cancelInFlight()} can stop it.
	 */
	private void enqueueTracked(Request request, Callback callback)
	{
		Call tracked = okHttpClient.newCall(request);
		activeCalls.add(tracked);
		tracked.enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				try
				{
					callback.onFailure(call, e);
				}
				finally
				{
					activeCalls.remove(call);
				}
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				// removed only after the callback has finished reading the body
				// and parsing: removing on headers meant a shutdown midway
				// through parsing could not cancel the call
				try
				{
					callback.onResponse(call, response);
				}
				finally
				{
					activeCalls.remove(call);
				}
			}
		});
	}

	/** Cancel everything still in flight. Called from the plugin's shutDown. */
	void cancelInFlight()
	{
		for (Call call : activeCalls)
		{
			call.cancel();
		}
		activeCalls.clear();
	}

	private static final Logger log = LoggerFactory.getLogger(GuideService.class);

	private static final File DATA_DIR = new File(RuneLite.RUNELITE_DIR, "hcim-guide");
	private static final File GUIDES_DIR = new File(DATA_DIR, "guides");
	/** Pre-multi-guide store location, migrated to the built-in guide's slot. */
	private static final File LEGACY_FILE = new File(DATA_DIR, "guide-wikitext.txt");
	private static final Pattern GUIDE_ID = Pattern.compile("[a-z0-9-]{1,64}");
	/** Body/on-disk cap for guide content (real guides are well under 1MB). */
	private static final long MAX_GUIDE_BYTES = 16L * 1024 * 1024;

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final WikitextParser parser = new WikitextParser();
	private final JsonGuideParser jsonParser = new JsonGuideParser();

	/**
	 * Parse dispatch: structured-JSON guides (BRUHsailer) vs wikitext (wiki
	 * guides). Content-sniffed, so a snapshot needs no format tag - the stored
	 * text speaks for itself.
	 */
	private Guide parseGuide(String text)
	{
		// single-pass: tryParse both sniffs AND parses, so a multi-MB JSON
		// import isn't parsed twice (once to identify, once to build)
		Guide json = jsonParser.tryParse(text);
		return json != null ? json : parser.parse(text);
	}

	/**
	 * The page wikitext out of a MediaWiki parse-API response, or null when
	 * the response has any other shape. Every level is type-checked: the API
	 * (or a proxy in between) can legally return "parse" as a non-object,
	 * omit "wikitext", or make it a non-string - none of which may throw.
	 */
	static String extractWikiText(JsonObject root)
	{
		if (root == null)
		{
			return null;
		}
		JsonElement parse = root.get("parse");
		if (parse == null || !parse.isJsonObject())
		{
			return null;
		}
		JsonElement text = parse.getAsJsonObject().get("wikitext");
		if (text == null || !text.isJsonPrimitive() || !text.getAsJsonPrimitive().isString())
		{
			return null;
		}
		return text.getAsString();
	}

	@Inject
	public GuideService(OkHttpClient okHttpClient, Gson gson)
	{
		// hard wall-clock ceiling per call: the body caps bound BYTES, but a
		// server trickling bytes under the shared client's read timeout could
		// otherwise hold a worker for as long as it liked. Shares the client's
		// pools; only the timeout differs.
		this.okHttpClient = okHttpClient.newBuilder()
			.callTimeout(java.time.Duration.ofSeconds(60))
			.build();
		this.gson = gson;
	}

	private static File snapshotFile(String guideId)
	{
		return new File(GUIDES_DIR, requireGuideId(guideId) + ".txt");
	}

	private static File backupFile(String guideId)
	{
		return new File(GUIDES_DIR, requireGuideId(guideId) + ".bak");
	}

	private static String requireGuideId(String guideId)
	{
		if (guideId == null || !GUIDE_ID.matcher(guideId).matches())
		{
			throw new IllegalArgumentException("Invalid guide id");
		}
		return guideId;
	}

	/** One-time move of the pre-multi-guide snapshot into the built-in guide's slot. */
	public void migrateLegacyStore()
	{
		try
		{
			File target = snapshotFile(GuideRegistry.BUILTIN_ID);
			if (LEGACY_FILE.isFile() && !target.isFile())
			{
				//noinspection ResultOfMethodCallIgnored
				GUIDES_DIR.mkdirs();
				Files.move(LEGACY_FILE.toPath(), target.toPath());
			}
		}
		catch (IOException e)
		{
			log.warn("Legacy guide store migration failed", e);
		}
	}

	public boolean hasSnapshot(String guideId)
	{
		return snapshotFile(guideId).isFile();
	}

	/** Parses the stored snapshot for a guide, or returns null when none exists. */
	public Guide loadStored(String guideId)
	{
		try
		{
			File f = snapshotFile(guideId);
			if (f.isFile())
			{
				String wikitext = readStoredText(f);
				Guide g = parseGuide(wikitext);
				if (!g.isEmpty())
				{
					return g;
				}
			}
		}
		catch (Exception e)
		{
			log.warn("Failed to read or parse stored guide", e);
		}
		return null;
	}

	/**
	 * Imports guide wikitext supplied directly (e.g. read from a user-chosen
	 * file), stores it as the guide's new snapshot, and returns the parsed guide.
	 *
	 * @throws IllegalArgumentException when the text is not parseable as a guide
	 */
	public Guide importText(String guideId, String wikitext) throws IOException
	{
		validateGuideText(wikitext);
		Guide guide = parseGuide(wikitext);
		if (guide.isEmpty())
		{
			throw new IllegalArgumentException("Text could not be parsed as a guide (no sections with steps found)");
		}
		// a failed disk write propagates: the source file still exists, so
		// failing loudly beats pretending the guide was stored
		saveSnapshot(guideId, wikitext);
		return guide;
	}

	/** Outcome of {@link #restorePrevious}: what happened, precisely. */
	public static final class RestoreResult
	{
		/** The restored guide; never null in a returned result. */
		final Guide guide;
		/** Non-null when the restore itself landed but the swap-back didn't. */
		final String warning;

		private RestoreResult(Guide guide, String warning)
		{
			this.guide = guide;
			this.warning = warning;
		}
	}

	/**
	 * Swaps a guide's stored snapshot with its previous one, if a backup
	 * exists. Returns null only when nothing was restored (no backup, or it
	 * no longer parses) - the on-disk state is untouched in that case. Both
	 * replacement files are fully staged as temps BEFORE the first move, and
	 * the SNAPSHOT is moved first: once it lands the restore has genuinely
	 * happened, so a failure writing the old text back into the backup slot
	 * is reported as a warning on a successful restore, never as "nothing
	 * was restored" while the disk actually changed.
	 */
	public RestoreResult restorePrevious(String guideId)
	{
		File snapshot = snapshotFile(guideId);
		File backup = backupFile(guideId);
		String backupText;
		Guide guide;
		String currentText;
		try
		{
			if (!backup.isFile())
			{
				return null;
			}
			backupText = readStoredText(backup);
			guide = parseGuide(backupText);
			if (guide.isEmpty())
			{
				return null;
			}
			currentText = snapshot.isFile() ? readStoredText(snapshot) : null;
			atomicWrite(snapshot, backupText.getBytes(StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			// nothing moved yet (atomicWrite stages a temp and moves once):
			// the stored state is intact and reporting "not restored" is true
			log.warn("Failed to restore previous snapshot", e);
			return null;
		}
		if (currentText == null)
		{
			return new RestoreResult(guide, null);
		}
		try
		{
			atomicWrite(backup, currentText.getBytes(StandardCharsets.UTF_8));
			return new RestoreResult(guide, null);
		}
		catch (Exception e)
		{
			// the restore DID land; only the swap-back failed. Say exactly that.
			log.warn("Restored guide but could not write the swap-back backup", e);
			return new RestoreResult(guide,
				"Previous snapshot restored, but the replaced import could not be "
					+ "kept as the new backup (" + e.getMessage() + ") - restoring "
					+ "forward again may not be possible");
		}
	}

	/**
	 * Fetches a wiki page's wikitext asynchronously and stores it as the
	 * guide's snapshot. Only ever called from an explicit, user-confirmed
	 * action. Exactly one of onSuccess/onError is invoked, on an OkHttp
	 * worker thread. onSuccess's second argument is a nullable STORAGE
	 * WARNING: non-null means the guide parsed fine but could not be written
	 * to disk (it will need re-importing after a restart) - the user must be
	 * told rather than shown a false "stored locally".
	 */
	public void fetch(String guideId, String pageTitle,
		java.util.function.BooleanSupplier requestCurrent,
		java.util.function.BiConsumer<Guide, String> onSuccess, Consumer<String> onError)
	{
		HttpUrl url = HttpUrl.get("https://oldschool.runescape.wiki/api.php").newBuilder()
			.addQueryParameter("action", "parse")
			.addQueryParameter("page", pageTitle)
			.addQueryParameter("prop", "wikitext")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.build();

		Request request = new Request.Builder()
			.url(url)
			.header("User-Agent", "guide-overlay RuneLite plugin")
			.build();

		// Enforces the exactly-one-callback contract documented above.
		final java.util.concurrent.atomic.AtomicBoolean settled =
			new java.util.concurrent.atomic.AtomicBoolean();

		enqueueTracked(request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				if (requestStopped(call, requestCurrent))
				{
					return;
				}
				log.warn("Guide download failed", e);
				safeError(settled, onError, "Download failed: " + e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (requestStopped(call, requestCurrent))
				{
					response.close();
					return;
				}
				// A pinned https URL only bounds where the request STARTS.
				// OkHttp follows redirects by default, so verify the response
				// actually came back from the host we asked for.
				okhttp3.HttpUrl finalUrl = response.request().url();
				if (!finalUrl.isHttps()
					|| !finalUrl.host().equals(call.request().url().host()))
				{
					response.close();
					safeError(settled, onError,
						"Response came from an unexpected host: " + finalUrl.host());
					return;
				}
				// separate phases so a failure is reported as what it actually
				// is - a read error must never surface as "Parse failed"
				Guide guide = null;
				String error = null;
				String storageWarning = null;
				String bodyText = null;
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						error = "Wiki returned HTTP " + response.code();
					}
					else
					{
						bodyText = readBounded(body);
					}
				}
				catch (Exception e)
				{
					log.warn("Reading wiki response failed", e);
					error = "Could not read the wiki response: " + e.getMessage();
				}

				String wikitext = null;
				if (error == null && requestStopped(call, requestCurrent))
				{
					return;
				}
				if (error == null)
				{
					try
					{
						JsonObject root = gson.fromJson(bodyText, JsonObject.class);
						wikitext = extractWikiText(root);
						if (wikitext == null)
						{
							error = root != null && root.has("error")
								? "Wiki page not found"
								: "Unexpected wiki API response";
						}
					}
					catch (Exception e)
					{
						log.warn("Wiki response was not valid JSON", e);
						error = "Wiki response was not valid JSON";
					}
				}

				if (error == null && requestStopped(call, requestCurrent))
				{
					return;
				}
				if (error == null)
				{
					try
					{
						guide = parseGuide(wikitext);
						if (guide.isEmpty())
						{
							guide = null;
							error = "That page has no parseable guide steps";
						}
					}
					catch (Exception e)
					{
						log.warn("Guide parse failed", e);
						error = "Guide could not be parsed: " + e.getMessage();
					}
				}

				if (guide != null)
				{
					try
					{
						if (!saveSnapshot(guideId, wikitext,
							() -> !requestStopped(call, requestCurrent)))
						{
							return;
						}
					}
					catch (Exception e)
					{
						log.warn("Snapshot write failed", e);
						storageWarning = "Guide imported but could NOT be saved to disk ("
							+ e.getMessage() + ") - check free space/permissions on ~/.runelite; "
							+ "it will need re-importing after a restart";
					}
				}

				// exactly one callback fires, and a throwing consumer can't trigger the
				// other or propagate into the OkHttp dispatcher thread
				if (requestStopped(call, requestCurrent))
				{
					return;
				}
				if (guide != null)
				{
					if (settled.compareAndSet(false, true))
					{
						try
						{
							onSuccess.accept(guide, storageWarning);
						}
						catch (Exception e)
						{
							log.warn("Guide success handler failed", e);
						}
					}
				}
				else
				{
					safeError(settled, onError, error != null ? error : "Unknown error");
				}
			}
		});
	}

	/**
	 * Reads a response body while COUNTING BYTES, aborting past the cap.
	 * Content-Length can't be trusted for this: transparent gzip decoding
	 * makes OkHttp report -1, and a hostile server can lie - so the only
	 * reliable bound is counting what actually comes off the wire.
	 */
	private static String readBounded(ResponseBody body) throws IOException
	{
		java.io.InputStream in = body.byteStream();
		java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
		byte[] buf = new byte[8192];
		int n;
		while ((n = in.read(buf)) > 0)
		{
			out.write(buf, 0, n);
			if (out.size() > MAX_GUIDE_BYTES)
			{
				throw new IOException("guide download exceeds " + (MAX_GUIDE_BYTES / (1024 * 1024)) + "MB - aborted");
			}
		}
		return new String(out.toByteArray(), StandardCharsets.UTF_8);
	}

	/**
	 * Fetches a built-in guide directly from a trusted raw URL (e.g. the
	 * BRUHsailer JSON) and stores it as the snapshot. The URL is only ever a
	 * hardcoded built-in source, never user-supplied. Same one-of/exactly-one
	 * callback contract as {@link #fetch}, with one deliberate exception: a
	 * URL that fails validation reports onError SYNCHRONOUSLY on the calling
	 * thread, before any network work starts.
	 */
	public void fetchUrl(String guideId, String sourceUrl,
		java.util.function.BooleanSupplier requestCurrent,
		java.util.function.BiConsumer<Guide, String> onSuccess, Consumer<String> onError)
	{
		HttpUrl parsedUrl;
		try
		{
			parsedUrl = HttpUrl.get(sourceUrl);
			if (!"https".equals(parsedUrl.scheme()) || !"raw.githubusercontent.com".equals(parsedUrl.host()))
			{
				throw new IllegalArgumentException("unsupported built-in guide source");
			}
		}
		catch (Exception e)
		{
			safeError(new java.util.concurrent.atomic.AtomicBoolean(), onError,
				"Built-in guide source is invalid");
			return;
		}
		Request request = new Request.Builder()
			.url(parsedUrl)
			.header("User-Agent", "guide-overlay RuneLite plugin")
			.build();

		// Enforces the exactly-one-callback contract documented above.
		final java.util.concurrent.atomic.AtomicBoolean settled =
			new java.util.concurrent.atomic.AtomicBoolean();

		enqueueTracked(request, new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				if (requestStopped(call, requestCurrent))
				{
					return;
				}
				log.warn("Guide download failed", e);
				safeError(settled, onError, "Download failed: " + e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				if (requestStopped(call, requestCurrent))
				{
					response.close();
					return;
				}
				// A pinned https URL only bounds where the request STARTS.
				// OkHttp follows redirects by default, so verify the response
				// actually came back from the host we asked for.
				okhttp3.HttpUrl finalUrl = response.request().url();
				if (!finalUrl.isHttps()
					|| !finalUrl.host().equals(call.request().url().host()))
				{
					response.close();
					safeError(settled, onError,
						"Response came from an unexpected host: " + finalUrl.host());
					return;
				}
				// same phase separation as fetch(): read, parse, persist
				Guide guide = null;
				String error = null;
				String storageWarning = null;
				String text = null;
				try (ResponseBody body = response.body())
				{
					if (!response.isSuccessful() || body == null)
					{
						error = "Source returned HTTP " + response.code();
					}
					else
					{
						text = readBounded(body);
					}
				}
				catch (Exception e)
				{
					log.warn("Reading guide response failed", e);
					error = "Could not read the download: " + e.getMessage();
				}

				if (error == null && requestStopped(call, requestCurrent))
				{
					return;
				}
				if (error == null)
				{
					try
					{
						guide = parseGuide(text);
						if (guide.isEmpty())
						{
							guide = null;
							error = "The downloaded guide has no parseable steps";
						}
					}
					catch (Exception e)
					{
						log.warn("Guide parse failed", e);
						error = "Guide could not be parsed: " + e.getMessage();
					}
				}

				if (guide != null)
				{
					try
					{
						if (!saveSnapshot(guideId, text,
							() -> !requestStopped(call, requestCurrent)))
						{
							return;
						}
					}
					catch (Exception e)
					{
						log.warn("Snapshot write failed", e);
						storageWarning = "Guide imported but could NOT be saved to disk ("
							+ e.getMessage() + ") - check free space/permissions on ~/.runelite; "
							+ "it will need re-importing after a restart";
					}
				}

				if (requestStopped(call, requestCurrent))
				{
					return;
				}
				if (guide != null)
				{
					if (settled.compareAndSet(false, true))
					{
						try
						{
							onSuccess.accept(guide, storageWarning);
						}
						catch (Exception e)
						{
							log.warn("Guide success handler failed", e);
						}
					}
				}
				else
				{
					safeError(settled, onError, error != null ? error : "Unknown error");
				}
			}
		});
	}

	/** True when shutdown/cycling invalidated the request before its commit. */
	private static boolean requestStopped(Call call,
		java.util.function.BooleanSupplier requestCurrent)
	{
		return call.isCanceled() || requestCurrent == null || !requestCurrent.getAsBoolean();
	}


	/** Fires onError at most once per fetch, per the exactly-one contract. */
	private static void safeError(java.util.concurrent.atomic.AtomicBoolean settled,
		Consumer<String> onError, String message)
	{
		if (!settled.compareAndSet(false, true))
		{
			return;
		}
		try
		{
			onError.accept(message);
		}
		catch (Exception e)
		{
			log.warn("Guide error handler failed", e);
		}
	}

	/**
	 * Stores the new snapshot, rotating the old one into the backup slot.
	 * Both files are fully staged as temps BEFORE either move, so a failure
	 * while preparing leaves the stored pair untouched. The backup rotates
	 * first: if the snapshot move then fails, the pair is still consistent
	 * (backup == the snapshot the user still has) and the thrown message
	 * says precisely that - the old backup is gone but nothing is corrupt.
	 */
	private static void saveSnapshot(String guideId, String wikitext) throws IOException
	{
		saveSnapshot(guideId, wikitext, () -> true);
	}

	/**
	 * Stage a snapshot fully, then cross one lifecycle commit gate before any
	 * stored file is replaced. Once that gate passes, both moves complete as
	 * one logical commit even if shutdown begins between them.
	 *
	 * @return false when the originating request became stale before commit
	 */
	private static boolean saveSnapshot(String guideId, String wikitext,
		java.util.function.BooleanSupplier mayCommit) throws IOException
	{
		validateGuideText(wikitext);
		Files.createDirectories(GUIDES_DIR.toPath());
		File snapshot = snapshotFile(guideId);
		File backup = backupFile(guideId);
		Path dir = GUIDES_DIR.toPath();
		Path newSnapshot = Files.createTempFile(dir, snapshot.getName(), ".tmp");
		Path newBackup = null;
		try
		{
			Files.write(newSnapshot, wikitext.getBytes(StandardCharsets.UTF_8));
			if (snapshot.isFile())
			{
				// keep the previous snapshot so a bad import can be undone
				newBackup = Files.createTempFile(dir, backup.getName(), ".tmp");
				Files.copy(snapshot.toPath(), newBackup, StandardCopyOption.REPLACE_EXISTING);
			}
			// No persistent path has changed yet. A request from an activation
			// that ended while reading/parsing is discarded at this commit gate.
			if (!mayCommit.getAsBoolean())
			{
				return false;
			}
			if (newBackup != null)
			{
				moveReplacing(newBackup, backup.toPath());
			}
			try
			{
				moveReplacing(newSnapshot, snapshot.toPath());
			}
			catch (IOException e)
			{
				throw new IOException("guide not saved (" + e.getMessage()
					+ "); the backup slot now holds the still-current snapshot", e);
			}
			return true;
		}
		finally
		{
			Files.deleteIfExists(newSnapshot);
			if (newBackup != null)
			{
				Files.deleteIfExists(newBackup);
			}
		}
	}

	private static String readStoredText(File file) throws IOException
	{
		try (java.io.InputStream in = Files.newInputStream(file.toPath()))
		{
			java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
			byte[] buffer = new byte[8192];
			int n;
			while ((n = in.read(buffer)) > 0)
			{
				out.write(buffer, 0, n);
				if (out.size() > MAX_GUIDE_BYTES)
				{
					throw new IOException("stored guide exceeds 16MB");
				}
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8);
		}
	}

	private static void validateGuideText(String text) throws IOException
	{
		if (text == null)
		{
			throw new IOException("guide text is missing");
		}
		if (text.getBytes(StandardCharsets.UTF_8).length > MAX_GUIDE_BYTES)
		{
			throw new IOException("guide exceeds 16MB");
		}
	}

	private static void atomicWrite(File target, byte[] bytes) throws IOException
	{
		Path directory = target.getParentFile().toPath();
		Files.createDirectories(directory);
		Path temp = Files.createTempFile(directory, target.getName(), ".tmp");
		try
		{
			Files.write(temp, bytes);
			moveReplacing(temp, target.toPath());
		}
		finally
		{
			// after a successful move the temp path no longer exists and this
			// is a no-op; it only ever deletes a leftover from a FAILED write
			Files.deleteIfExists(temp);
		}
	}

	private static void moveReplacing(Path source, Path target) throws IOException
	{
		try
		{
			Files.move(source, target, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
		}
		catch (AtomicMoveNotSupportedException e)
		{
			Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
		}
	}
}

package com.hcimguide;

/**
 * A single actionable line of the guide (one bullet point).
 */
public class GuideStep
{
	private final String key;
	private final String text;
	private final int depth;
	private final String bankId;
	/**
	 * First whitelisted video link (YouTube/Streamable) this step references,
	 * or null. Display metadata only - NEVER part of the step text, so keys
	 * (users' saved progress) are unaffected by link changes.
	 */
	private String videoUrl;

	public GuideStep(String key, String text, int depth, String bankId)
	{
		this.key = key;
		this.text = text;
		this.depth = depth;
		this.bankId = bankId;
	}

	/**
	 * Stable identifier used to persist checkbox state. Built from the bank id,
	 * a hash of the step text and the occurrence index of identical text within
	 * the bank, so it survives unrelated edits to the guide.
	 */
	public String getKey()
	{
		return key;
	}

	public String getText()
	{
		return text;
	}

	/** Nesting depth; 0 = top-level bullet, 1 = sub-bullet, ... */
	public int getDepth()
	{
		return depth;
	}

	public String getBankId()
	{
		return bankId;
	}

	public String getVideoUrl()
	{
		return videoUrl;
	}

	void setVideoUrl(String videoUrl)
	{
		this.videoUrl = videoUrl;
	}
}

