		HcimGuideConfig.GuidanceDisplayMode mode = config.guidanceDisplayMode();
		if (mode == HcimGuideConfig.GuidanceDisplayMode.SHORTEST_PATH_ONLY
			|| mode == HcimGuideConfig.GuidanceDisplayMode.NEARBY_ONLY)
