package com.hcimguide;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Walks every step of the loaded guide, resolves every item requirement against
 * the live client, and reports the ones that produce no item icon.
 *
 * <p>This exists because the offline item lists a developer can check against go
 * stale: they cannot contain items added after the list was captured. Only a
 * running client knows the full item set, so the authoritative answer to "which
 * requirements show as plain text" has to come from inside the game.</p>
 *
 * <p>The whole guide is walked in one pass, so nothing has to be scrolled
 * through by hand.</p>
 */
final class ItemAudit
{
	/** Bounds the report the same way the location audit bounds its own. */
	private static final int MAX_TABLE_CHARS = 512 * 1024;

	private ItemAudit()
	{
	}

	/**
	 * @param resolver live resolver, used only to ask whether a name has an icon
	 * @return a Markdown report listing every requirement with no item icon
	 */
	static String toMarkdown(String guideId, Guide guide, ItemIconResolver resolver,
		Map<String, List<ItemReq>> requirementsByStep)
	{
		if (guide == null)
		{
			return "# Item audit\n\nNo guide is loaded.\n";
		}

		// name -> where it was first seen, preserving guide order
		Map<String, String> unresolved = new LinkedHashMap<>();
		Map<String, String> concepts = new LinkedHashMap<>();
		Map<String, String> pending = new LinkedHashMap<>();
		int stepsWithItems = 0;
		int requirements = 0;
		int resolved = 0;
		// occurrence counters, so the summary adds up. The tables below list
		// DISTINCT names, which is a smaller number and a different unit -
		// mixing the two made 104 requirements look unaccounted for.
		int unresolvedHits = 0;
		int conceptHits = 0;
		int pendingHits = 0;

		for (GuideEpisode episode : guide.getEpisodes())
		{
			for (GuideBank bank : episode.getBanks())
			{
				for (GuideStep step : bank.getSteps())
				{
					List<ItemReq> reqs = requirementsByStep == null
						? StepItemRequirements.displayFor(step)
						: requirementsByStep.get(step.getKey());
					if (reqs == null || reqs.isEmpty())
					{
						continue;
					}
					stepsWithItems++;
					for (ItemReq req : reqs)
					{
						requirements++;
						String name = req.getName();
						String where = bank.getId() + " | " + step.getText();
						if (ConceptItems.isConcept(name))
						{
							conceptHits++;
							concepts.putIfAbsent(name, where);
							continue;
						}
						// stateOf(ItemReq) understands category and alternative
						// requirements; stateOf(String) flattens them to a
						// display name that may not be a real item at all
						ItemIconResolver.ResolutionState state = resolver.stateOf(req);
						if (state == ItemIconResolver.ResolutionState.RESOLVED)
						{
							resolved++;
						}
						else if (state == ItemIconResolver.ResolutionState.UNRESOLVABLE)
						{
							unresolvedHits++;
							unresolved.putIfAbsent(name, where);
						}
						else
						{
							// PENDING: the full-database scan had not reached this
							// name yet. Reported so the totals always add up -
							// silently skipping these hid 104 names on an earlier
							// run and made the guide look cleaner than it was.
							pendingHits++;
							pending.putIfAbsent(name, where);
						}
					}
				}
			}
		}

		StringBuilder out = new StringBuilder();
		out.append("# Item audit\n\n");
		out.append("Guide: ").append(guideId == null ? "(unknown)" : guideId).append("\n\n");
		out.append("Every requirement in the guide, checked against the live client.\n\n");
		out.append("Counts below are OCCURRENCES, so one item used in twenty steps counts\n");
		out.append("twenty times. The preload action reports UNIQUE names instead, which is\n");
		out.append("why its number is much smaller. Both are correct.\n\n");
		out.append("| | |\n|---|---:|\n");
		out.append("| Steps with items | ").append(stepsWithItems).append(" |\n");
		out.append("| Requirement occurrences | ").append(requirements).append(" |\n");
		out.append("| Resolved to an item | ").append(resolved).append(" |\n");
		out.append("| No item icon | ").append(unresolvedHits)
			.append(" (").append(unresolved.size()).append(" distinct) |\n");
		out.append("| Concept slots | ").append(conceptHits)
			.append(" (").append(concepts.size()).append(" distinct) |\n");
		out.append("| Still scanning | ").append(pendingHits)
			.append(" (").append(pending.size()).append(" distinct) |\n");
		out.append("| **Total** | **")
			.append(resolved + unresolvedHits + conceptHits + pendingHits)
			.append("** |\n\n");
		if (!pending.isEmpty())
		{
			out.append("## THIS REPORT IS INCOMPLETE\n\n");
			out.append(pendingHits).append(" of ").append(requirements);
			out.append(" requirements had not finished scanning when this ran, so the\n");
			out.append("\"No item icon\" count below is NOT the full picture. Wait a few\n");
			out.append("seconds and export again. Only trust a report where this section\n");
			out.append("is absent.\n\n");
		}

		out.append("Anything listed under \"No item icon\" showed as plain text rather\n");
		out.append("than an item picture. Each one needs either an alias to the real item\n");
		out.append("name, or removing if it is not an item at all.\n\n");

		appendTable(out, "No item icon", unresolved);
		appendTable(out, "Concept slots (expected, shown as an icon not an item)", concepts);
		appendTable(out, "Still scanning when the report ran", pending);

		if (out.length() > MAX_TABLE_CHARS)
		{
			out.setLength(MAX_TABLE_CHARS);
			out.append("\n\n(report truncated)\n");
		}
		return out.toString();
	}

	private static void appendTable(StringBuilder out, String title, Map<String, String> rows)
	{
		out.append("## ").append(title).append(" (").append(rows.size()).append(")\n\n");
		if (rows.isEmpty())
		{
			out.append("None.\n\n");
			return;
		}
		out.append("| Parsed name | First seen in |\n|---|---|\n");
		List<Map.Entry<String, String>> sorted = new ArrayList<>(rows.entrySet());
		sorted.sort(Comparator.comparing(Map.Entry::getKey, String.CASE_INSENSITIVE_ORDER));
		for (Map.Entry<String, String> e : sorted)
		{
			out.append("| `").append(escape(e.getKey())).append("` | ")
				.append(escape(trim(e.getValue()))).append(" |\n");
		}
		out.append('\n');
	}

	private static String trim(String value)
	{
		return value.length() <= 110 ? value : value.substring(0, 110) + "...";
	}

	private static String escape(String value)
	{
		return value == null ? "" : value.replace("|", "\\|").replace("\n", " ");
	}
}

package com.hcimguide;

import java.util.Locale;

/** Runtime item categories evaluated from RuneLite's live item definitions. */
public enum ItemCategory
{
	/** Any edible, prepared food. Raw, uncooked and burnt items are excluded. */
	COOKED_FOOD("Any cooked food", "Shrimps", new String[]
	{
		"Shark", "Cooked karambwan", "Manta ray", "Sea turtle", "Anglerfish",
		"Dark crab", "Monkfish", "Swordfish", "Lobster", "Tuna", "Salmon", "Trout",
		"Shrimps"
	}),

	/** Any pickaxe, bronze through dragon and beyond. */
	PICKAXE("Any pickaxe", "Bronze pickaxe", new String[]
	{
		"Bronze pickaxe", "Iron pickaxe", "Steel pickaxe", "Black pickaxe",
		"Mithril pickaxe", "Adamant pickaxe", "Rune pickaxe", "Dragon pickaxe",
		"Crystal pickaxe", "Infernal pickaxe"
	}),

	/** Any woodcutting axe. */
	AXE("Any axe", "Bronze axe", new String[]
	{
		"Bronze axe", "Iron axe", "Steel axe", "Black axe", "Mithril axe",
		"Adamant axe", "Rune axe", "Dragon axe", "Crystal axe", "Infernal axe"
	}),

	/** Any worn boots. */
	BOOTS("Any boots", "Leather boots", new String[]
	{
		"Leather boots", "Boots of lightness", "Climbing boots", "Rune boots",
		"Dragon boots", "Graceful boots"
	}),

	/** Any ring. */
	RING("Any ring", "Gold ring", new String[]
	{
		"Gold ring", "Sapphire ring", "Emerald ring", "Ruby ring",
		"Diamond ring", "Ring of recoil", "Ring of dueling(8)"
	}),

	/** Any grimy herb. */
	GRIMY_HERB("Any grimy herb", "Grimy guam leaf", new String[]
	{
		"Grimy guam leaf", "Grimy marrentill", "Grimy tarromin", "Grimy harralander",
		"Grimy ranarr weed", "Grimy irit leaf", "Grimy avantoe", "Grimy kwuarm",
		"Grimy cadantine", "Grimy lantadyme", "Grimy dwarf weed", "Grimy torstol"
	});

	private final String displayName;
	/**
	 * Item shown for the slot. The LOWEST tier is used deliberately: it is the
	 * least capable thing that satisfies the requirement, so the picture never
	 * implies gear the step does not actually need.
	 */
	private final String iconName;
	private final String[] bankTagExamples;

	ItemCategory(String displayName, String iconName, String[] bankTagExamples)
	{
		this.displayName = displayName;
		this.iconName = iconName;
		this.bankTagExamples = bankTagExamples;
	}

	/** Lowest-tier member, used for the slot icon. */
	public String getIconName()
	{
		return iconName;
	}

	public String getDisplayName()
	{
		return displayName;
	}

	/** Representative, useful choices for bank-tag expansion; not the membership definition. */
	public String[] getBankTagExamples()
	{
		return bankTagExamples.clone();
	}

	/**
	 * Membership test taken on the item's live name and inventory actions.
	 *
	 * <p>Deliberately takes plain values rather than a RuneLite
	 * {@code ItemComposition}: {@link ItemReq} holds a category, and the offline
	 * test harness compiles {@code ItemReq} without the RuneLite API. Coupling
	 * this enum to the client library made the entire harness uncompilable.
	 * The single caller passes {@code comp.getName()} and
	 * {@code comp.getInventoryActions()}.</p>
	 */
	public boolean matches(String itemName, String[] inventoryActions)
	{
		if (itemName == null)
		{
			return false;
		}
		String name = itemName.toLowerCase(Locale.ROOT);
		if (name.equals("null"))
		{
			return false;
		}
		switch (this)
		{
			case PICKAXE:
				return name.endsWith(" pickaxe") || name.equals("pickaxe");
			case AXE:
				// " axe" only, so "pickaxe" and "battleaxe" do not qualify
				return name.endsWith(" axe") || name.equals("axe");
			case BOOTS:
				return name.endsWith(" boots") || name.equals("boots");
			case RING:
				// excludes "ring of charos" style quest rings? no: any ring counts,
				// but not items that merely contain the word, like "ring mould"
				return name.endsWith(" ring") || name.startsWith("ring of ")
					|| name.equals("ring");
			case GRIMY_HERB:
				return name.startsWith("grimy ");
			case COOKED_FOOD:
			default:
				if (name.startsWith("raw ") || name.startsWith("burnt ")
					|| name.startsWith("uncooked ") || name.contains(" burnt"))
				{
					return false;
				}
				if (inventoryActions == null)
				{
					return false;
				}
				for (String action : inventoryActions)
				{
					if (action != null && action.equalsIgnoreCase("Eat"))
					{
						return true;
					}
				}
				return false;
		}
	}
}

package com.hcimguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.TexturePaint;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Item icons for a step's requirements, drawn on an OSRS-inventory-style
 * panel: the classic stone-brown background with a beveled edge, four
 * columns wide like the real inventory. The background is PAINTED (plain
 * gradients and lines in the game's palette), not a bundled game texture,
 * so no copyrighted asset ships with the plugin. Slots get a green border
 * when the item is currently carried, red when missing.
 */
public class ItemGridPanel extends JPanel
{
	/**
	 * Four columns, like the in-game inventory. 4 x 36px slots + gaps +
	 * border = ~158px, well inside the side panel's ~200px usable row width
	 * even on indented steps. Item sprites are 36x32 natively, so they fit
	 * without scaling; anything wider is scaled down on load.
	 */
	private static final int COLUMNS = 4;
	private static final int SLOT = 36;
	private static final int SLOT_H = 32;
	/** Stack-count yellow, matching the client's own quantity text. */
	private static final Color QTY_LABEL = new Color(255, 255, 0);
	private static final Color PRESENT = new Color(0, 200, 120, 170);
	private static final Color MISSING = new Color(190, 60, 60, 170);

	// fallback palette while the real sprite loads (painted, not a game asset)
	private static final Color INV_BG = new Color(62, 53, 41);
	private static final Color INV_BG_LIGHT = new Color(73, 64, 52);
	private static final Color INV_EDGE_DARK = new Color(43, 36, 27);
	private static final Color INV_EDGE_LIGHT = new Color(94, 84, 66);

	/**
	 * The ACTUAL in-game inventory stone background, pulled from the player's
	 * own game files via SpriteManager at runtime (never bundled). While it
	 * loads - or if the cache read ever fails - the painted fallback shows.
	 */
	private static volatile BufferedImage inventoryBackground;

	static void setInventoryBackground(BufferedImage img)
	{
		inventoryBackground = img;
	}

	/** Release the one shared background image when the plugin is disabled. */
	static void clearInventoryBackground()
	{
		inventoryBackground = null;
	}

	private final List<Slot> slots = new ArrayList<>();

	/**
	 * Set when the panel generation is discarded (episode switch / re-import),
	 * so late-arriving async icon loads can't resurrect a dead component tree.
	 */
	private volatile boolean disposed;

	private static class Slot
	{
		final ItemReq req;
		final JLabel label;
		boolean present;
		/** Last resolved item id for this slot (-1 = no matching item). */
		int itemId = -1;

		Slot(ItemReq req, JLabel label)
		{
			this.req = req;
			this.label = label;
		}
	}

	/** When false, no colored have-it borders - a clean wiki-style inventory. */
	private final boolean presenceBorders;

	ItemGridPanel(List<ItemReq> items, boolean presenceBorders)
	{
		this.presenceBorders = presenceBorders;
		int rows = (items.size() + COLUMNS - 1) / COLUMNS;
		setLayout(new GridLayout(rows, COLUMNS, 2, 2));
		setOpaque(false); // background painted in paintComponent
		setBorder(BorderFactory.createEmptyBorder(4, 4, 5, 4));
		// the step row wraps this panel in a left-aligned FlowLayout, which
		// respects preferred size - so the grid keeps its natural width

		for (ItemReq req : items)
		{
			JLabel label = new JLabel();
			label.setHorizontalAlignment(SwingConstants.CENTER);
			label.setVerticalAlignment(SwingConstants.CENTER);
			label.setPreferredSize(new Dimension(SLOT, SLOT_H));
			label.setOpaque(false); // items sit directly on the inventory brown
			String tooltip = req.toString();
			if (req.getCompletionQuantity() < req.getQuantity())
			{
				tooltip += " (ready at " + req.getCompletionQuantity() + ")";
			}
			label.setToolTipText(tooltip);
			label.setFont(FontManager.getRunescapeSmallFont());
			// text fallback until (or unless) an icon resolves
			label.setText(abbreviate(req.getName()));
			label.setForeground(new Color(214, 195, 152)); // parchment on brown

			Slot slot = new Slot(req, label);
			slots.add(slot);
			setSlotBorder(slot, false);
			add(label);
		}

		// pad the last row so slots keep their size
		int pad = rows * COLUMNS - items.size();
		for (int i = 0; i < pad; i++)
		{
			JLabel filler = new JLabel();
			filler.setPreferredSize(new Dimension(SLOT, SLOT_H));
			add(filler);
		}
	}

	/**
	 * Resolve icons via the item manager. Call from any thread; icon updates
	 * hop to the EDT when each image loads. Slots are also REORDERED so
	 * anything with a picture - real items AND sprite-backed concepts like
	 * "Combat Gear" - comes first, and only textual chips ("2 Food") sink to
	 * the end of the grid; stable order within each group, idempotent across
	 * re-resolution passes.
	 *
	 * @param ids one resolved item id per slot, -1 for unresolved
	 */
	void applyIcons(ItemManager itemManager, List<ItemReq> reqs, int[] ids)
	{
		applyIcons(itemManager, null, reqs, ids);
	}

	/**
	 * @param spriteManager supplies icons for sprite-backed slots ("Combat
	 *     Gear"), which have no item id. May be null, in which case those
	 *     slots stay empty.
	 */
	void applyIcons(ItemManager itemManager, net.runelite.client.game.SpriteManager spriteManager,
		List<ItemReq> reqs, int[] ids)
	{
		// pair ids to slots by REQUIREMENT IDENTITY, not position: a reorder
		// scheduled by an earlier pass may land between the caller's resolve()
		// and this call, and positional pairing would then swap icons. The
		// same ItemReq objects live in both the slots and the caller's list,
		// so identity mapping is exact.
		final java.util.IdentityHashMap<ItemReq, Integer> byReq = new java.util.IdentityHashMap<>();
		for (int i = 0; i < reqs.size() && i < ids.length; i++)
		{
			byReq.put(reqs.get(i), ids[i]);
		}
		final List<Slot> snapshot;
		List<Slot> reordered = null;
		synchronized (slots)
		{
			snapshot = new ArrayList<>(slots);
			for (Slot s : snapshot)
			{
				Integer id = byReq.get(s.req);
				if (id != null)
				{
					s.itemId = id;
				}
			}
			List<Slot> resolved = new ArrayList<>();
			List<Slot> unresolved = new ArrayList<>();
			for (Slot s : snapshot)
			{
				(s.itemId > 0 || ItemIconResolver.isSpriteId(s.itemId) ? resolved : unresolved).add(s);
			}
			if (!resolved.isEmpty() && !unresolved.isEmpty())
			{
				List<Slot> candidate = new ArrayList<>(resolved);
				candidate.addAll(unresolved);
				// skip the EDT rebuild when already partitioned (idempotent)
				if (!candidate.equals(snapshot))
				{
					reordered = candidate;
				}
			}
		}
		if (reordered != null)
		{
			final List<Slot> ordered = reordered;
			SwingUtilities.invokeLater(() ->
			{
				if (disposed)
				{
					return;
				}
				synchronized (slots)
				{
					if (ordered.size() != slots.size())
					{
						return; // a newer generation replaced the slots
					}
					slots.clear();
					slots.addAll(ordered);
				}
				removeAll();
				for (Slot s : ordered)
				{
					add(s.label);
				}
				// pad the last row so slots keep their size
				int rows = (ordered.size() + COLUMNS - 1) / COLUMNS;
				int pad = rows * COLUMNS - ordered.size();
				for (int i = 0; i < pad; i++)
				{
					JLabel filler = new JLabel();
					filler.setPreferredSize(new Dimension(SLOT, SLOT_H));
					add(filler);
				}
				revalidate();
				repaint();
			});
		}

		for (Slot slot : snapshot)
		{
			if (slot.itemId <= 0 && !ItemIconResolver.isSpriteId(slot.itemId))
			{
				continue;
			}
			int qty = slot.req.getQuantity();
			// open quantities ("all", "100+") get a drawn label instead of the
			// sprite's baked-in stack number, which can only render digits
			boolean openQty = slot.req.hasQuantityLabel();
			if (ItemIconResolver.isSpriteId(slot.itemId))
			{
				setConceptBorder(slot);
				applySpriteSlot(spriteManager, slot);
				continue;
			}
			AsyncBufferedImage img = itemManager.getImage(slot.itemId, qty, !openQty && qty > 1);
			final Slot finalSlot = slot;
			Runnable apply = () ->
			{
				if (disposed)
				{
					return;
				}
				if (openQty)
				{
					finalSlot.label.setText(finalSlot.req.getQuantityLabel());
					finalSlot.label.setForeground(QTY_LABEL);
					finalSlot.label.setFont(finalSlot.label.getFont().deriveFont(10f));
					finalSlot.label.setHorizontalTextPosition(SwingConstants.LEFT);
					finalSlot.label.setVerticalTextPosition(SwingConstants.TOP);
				}
				else
				{
					finalSlot.label.setText(null);
				}
				// item sprites are 36x32 natively - exactly the slot size, so
				// they render crisp and unscaled; only oversized images shrink
				if (img.getWidth() > SLOT)
				{
					finalSlot.label.setIcon(new ImageIcon(img.getScaledInstance(
						SLOT, -1, java.awt.Image.SCALE_SMOOTH)));
				}
				else
				{
					finalSlot.label.setIcon(new ImageIcon(img));
				}
				finalSlot.label.revalidate();
				finalSlot.label.repaint();
			};
			img.onLoaded(() -> SwingUtilities.invokeLater(apply));
			SwingUtilities.invokeLater(apply);
		}
	}


	/** Fills a sprite-backed slot once the client sprite loads. */
	private void applySpriteSlot(net.runelite.client.game.SpriteManager spriteManager, Slot slot)
	{
		if (spriteManager == null)
		{
			return;
		}
		final Slot target = slot;
		spriteManager.getSpriteAsync(ItemIconResolver.spriteIdOf(slot.itemId), 0, img ->
			SwingUtilities.invokeLater(() ->
			{
				if (disposed || img == null)
				{
					return;
				}
				target.label.setText(null);
				target.label.setIcon(new ImageIcon(img));
				target.label.revalidate();
				target.label.repaint();
			}));
	}

	/** Update presence borders from the current inventory snapshot (O(1) per slot). */
	void updatePresence(InventorySnapshot snapshot)
	{
		final List<Slot> copy;
		synchronized (slots)
		{
			copy = new ArrayList<>(slots);
		}
		for (Slot slot : copy)
		{
			// a concept slot ("Combat Gear") names no concrete item, so a
			// presence check would always fail and paint a permanent red border
			if (ConceptItems.isConcept(slot.req.getName()))
			{
				continue;
			}
			boolean present = snapshot.countOf(slot.req) >= slot.req.getCompletionQuantity();
			if (present != slot.present)
			{
				slot.present = present;
				setSlotBorder(slot, present);
			}
		}
	}

	/**
	 * Background: the REAL inventory stone texture from the game's own files
	 * (tiled at native pixel density, like the wiki's inventory images).
	 * Falls back to a painted approximation until the sprite loads.
	 */
	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		try
		{
			int w = getWidth();
			int h = getHeight();
			BufferedImage bg = inventoryBackground;
			if (bg != null && bg.getWidth() > 0 && bg.getHeight() > 0)
			{
				g2.setPaint(new TexturePaint(bg,
					new Rectangle2D.Float(0, 0, bg.getWidth(), bg.getHeight())));
				g2.fillRect(0, 0, w, h);
				g2.setColor(INV_EDGE_DARK);
				g2.drawRect(0, 0, w - 1, h - 1);
			}
			else
			{
				g2.setPaint(new GradientPaint(0, 0, INV_BG_LIGHT, 0, h, INV_BG));
				g2.fillRect(0, 0, w, h);
				g2.setColor(INV_EDGE_DARK);
				g2.drawRect(0, 0, w - 1, h - 1);
				g2.setColor(INV_EDGE_LIGHT);
				g2.drawLine(1, 1, w - 2, 1);
				g2.drawLine(1, 1, 1, h - 2);
			}
		}
		finally
		{
			g2.dispose();
		}
		super.paintComponent(g);
	}

	/** Detach this grid from future async icon callbacks. */
	void dispose()
	{
		disposed = true;
	}

	private void setConceptBorder(Slot slot)
	{
		slot.present = true;
		slot.label.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
	}

	private void setSlotBorder(Slot slot, boolean present)
	{
		if (!presenceBorders)
		{
			slot.label.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
			return;
		}
		slot.label.setBorder(BorderFactory.createLineBorder(present ? PRESENT : MISSING, 1));
	}

	private static String abbreviate(String name)
	{
		String s = name.trim();
		return s.length() <= 6 ? s : s.substring(0, 5) + "…";
	}

	List<ItemReq> getItems()
	{
		synchronized (slots)
		{
			List<ItemReq> out = new ArrayList<>();
			for (Slot s : slots)
			{
				out.add(s.req);
			}
			return out;
		}
	}
}

