	/**
	 * "16k feathers", "5k cannonballs", "1250k": a number with a 'k' thousands
	 * suffix. Expanded to the full count so the requirement is right (16000),
	 * not read as an item named "16k". Applied before the item name is cut.
	 */
	private static final Pattern K_SUFFIX = Pattern.compile("(?i)^(\\d+)k\\b\\s*(.*)$");

	/**
	 * Phrases naming a whole armour set or spell rune cost. These occur across
	 * many steps, so they expand here rather than as per-step overrides.
	 * Each entry is name then count, repeated.
	 */

	/**
	 * Spell name and phrase to rune cost, loaded from the bundled
	 * spell-runes.json. Guides write "Curse Runes" or "Vile Vigour" where an
	 * item belongs, so the runes a spell actually consumes are the useful
	 * requirement.
	 *
	 * <p>Loaded once, statically. If the resource is missing the maps stay
	 * empty and the parser falls back to its hardcoded phrases, so a packaging
	 * mistake degrades rather than breaks.</p>
	 */
	private static final Map<String, Map<String, Integer>> SPELL_RUNES = new HashMap<>();

	/** Guide phrasing to spell name, e.g. "curse runes" -> "Curse". */
	private static final Map<String, String> SPELL_PHRASES = new HashMap<>();

	static
	{
		try (java.io.InputStream in =
			ItemListParser.class.getResourceAsStream("spell-runes.json"))
		{
			if (in != null)
			{
				// instance API, not the static parseReader: the client bundles an
				// older Gson without it. CustomLocationStore documents the same
				// constraint.
				com.google.gson.JsonObject root = new com.google.gson.JsonParser()
					.parse(new java.io.InputStreamReader(
						in, java.nio.charset.StandardCharsets.UTF_8))
					.getAsJsonObject();
				com.google.gson.JsonObject spells = root.getAsJsonObject("spells");
				for (String spell : spells.keySet())
				{
					Map<String, Integer> runes = new java.util.LinkedHashMap<>();
					com.google.gson.JsonObject cost = spells.getAsJsonObject(spell);
					for (String rune : cost.keySet())
					{
						runes.put(rune, cost.get(rune).getAsInt());
					}
					SPELL_RUNES.put(Names.normalize(spell), runes);
					// the spell's own name is also a valid phrase
					SPELL_PHRASES.put(Names.normalize(spell), Names.normalize(spell));
				}
				com.google.gson.JsonObject aliases = root.getAsJsonObject("aliases");
				for (String phrase : aliases.keySet())
				{
					SPELL_PHRASES.put(Names.normalize(phrase),
						Names.normalize(aliases.get(phrase).getAsString()));
				}
			}
		}
		catch (Exception ignored)
		{
			// bundled data missing or malformed: fall back to hardcoded phrases
		}
	}

	/** Runes for a spell phrase, or null when the phrase names no spell. */
	private static String[][] spellRunes(String phrase)
	{
		String spell = SPELL_PHRASES.get(Names.normalize(phrase));
		if (spell == null)
		{
			return null;
		}
		Map<String, Integer> runes = SPELL_RUNES.get(spell);
		if (runes == null || runes.isEmpty())
		{
			return null;
		}
		String[][] out = new String[runes.size()][2];
		int i = 0;
		for (Map.Entry<String, Integer> e : runes.entrySet())
		{
			out[i][0] = e.getKey();
			out[i][1] = String.valueOf(e.getValue());
			i++;
		}
		return out;
	}

	private static String[][] setExpansion(String phrase)
	{
		switch (phrase.toLowerCase(java.util.Locale.ROOT).trim())
		{
			case "crystal armour":
			case "full crystal":
				return new String[][]{{"Crystal helm", "1"}, {"Crystal body", "1"},
					{"Crystal legs", "1"}};
			case "full initiate":
			case "initiate armour":
				return new String[][]{{"Initiate sallet", "1"}, {"Initiate hauberk", "1"},
					{"Initiate cuisse", "1"}};
			case "shayzien armour 5":
			case "t5 shayzien outfit":
			case "shayzien outfit":
				return new String[][]{{"Shayzien helm (5)", "1"}, {"Shayzien body (5)", "1"},
					{"Shayzien greaves (5)", "1"}, {"Shayzien gloves (5)", "1"},
					{"Shayzien boots (5)", "1"}};
			case "rogues outfit":
			case "rogue outfit":
				return new String[][]{{"Rogue mask", "1"}, {"Rogue top", "1"},
					{"Rogue trousers", "1"}, {"Rogue gloves", "1"}, {"Rogue boots", "1"}};
			// spell phrasings the guides use in an item position
			case "air spells runes":
			case "air spell runes":
				return new String[][]{{"Air rune", "1"}, {"Chaos rune", "1"}};
			case "death combat runes":
				return new String[][]{{"Death rune", "1"}, {"Air rune", "1"}};
			case "crumble undead runes":
			case "crumble undead":
				return new String[][]{{"Air rune", "2"}, {"Earth rune", "2"}, {"Chaos rune", "1"}};
			case "vile vigour":
				return new String[][]{{"Air rune", "3"}, {"Soul rune", "1"}};
			case "curse runes":
				return new String[][]{{"Earth rune", "3"}, {"Water rune", "2"}, {"Body rune", "1"}};
			case "humidify runes":
				return new String[][]{{"Fire rune", "1"}, {"Water rune", "3"}, {"Astral rune", "1"}};
			case "superglass make runes":
				return new String[][]{{"Air rune", "10"}, {"Fire rune", "6"}, {"Astral rune", "2"}};
			case "plank make runes":
				return new String[][]{{"Earth rune", "15"}, {"Astral rune", "2"}, {"Nature rune", "1"}};
			default:
				// everything else: consult the bundled spell table
				return spellRunes(phrase);
		}
	}

	/**
	 * Named teleport "runes" phrase ("trollheim teleport runes"), expanded to
	 * the actual runes for that teleport via {@link #teleportRuneSet}.
	 */
	private static final Pattern TELEPORT_RUNE_PHRASE = Pattern.compile(
		"(?i)^(.*?)\\s+teleport\\s+runes?$");

	/**
	 * Leading spelled-out quantity: returns {quantity, charsConsumed} or null.
	 * "a"/"an" count as 1 only when a noun follows, so "a spade" is quantity 1
	 * but a lone "a" is left alone.
	 */
	private static int[] leadingWordQuantity(String p)
	{
		int sp = p.indexOf(' ');
		if (sp <= 0)
		{
			return null;
		}
		String first = p.substring(0, sp).toLowerCase(java.util.Locale.ROOT);
		Integer n = WORD_NUMBERS.get(first);
		if (n == null)
		{
			return null;
		}
		return new int[]{n, sp + 1};
	}

	/**
	 * Normalized forms of the prose drop-list, so smart quotes and punctuation
	 * ("it's possible" with a curly apostrophe) still match.
	 */
	private static final Set<String> NOT_ITEMS_NORM = new HashSet<>();

	static
	{
		for (String s : NOT_ITEMS_PROSE)
		{
			NOT_ITEMS_NORM.add(Names.normalize(s));
		}
	}

	// stop the item name at travel/location phrasing
	private static final Pattern GATHER_CUTOFF = Pattern.compile(
		"(?i)\\s+(?:off|from|inside|outside|at|on|next to|near|beneath|below|above|under|behind|"
		+ "in|to|south|north|east|west|whenever|if|while|then|when|during|after|before|"
		+ "and wield|and equip|by|for)\\b.*$");

	// every expression below runs once per step during import - precompiled
	// so a large guide doesn't compile thousands of throwaway Patterns
	private static final Pattern SLOTS_PAREN = Pattern.compile("(?i)\\s*\\([^)]*slots?[^)]*\\)");
	private static final Pattern SLOTS_BRACKET = Pattern.compile("(?i)\\s*\\[[^\\]]*slots?[^\\]]*]");
	private static final Pattern SLOTS_UNCLOSED = Pattern.compile("(?i)\\s*\\([^)]*slots?.*$");
	private static final Pattern TRAILING_DOTS = Pattern.compile("[.\\s]+$");
	/**
	 * List separators. The '+' is a separator between items ("Spade + Range
	 * Gear") EXCEPT when it directly follows a digit, where it means "at least
	 * this many" ("10+ Nails", "50+ Earth Runes"). Without the lookbehind the
	 * split produced an item named "10" and another named "Nails".
	 */
	/**
	 * List separators: comma, ampersand, "+" (except after a digit, where it
	 * means "at least"), and the word "and". BRUHsailer-style guides write
	 * "two cheese, eight redberries and one banana", so "and" must split or the
	 * trailing items merge into one and their quantities are lost. Bounded by
	 * spaces so it never splits inside a word like "Grand" or "Wand".
	 */
	private static final Pattern LIST_SPLIT = Pattern.compile(
		",|&|(?<!\\d)\\+|\\s+and\\s+");
	private static final Pattern INSTRUCTION_FRAGMENT = Pattern.compile(
		"(?i)^(?:wear|wield|equip|use|then|and|if|climb|go|run|walk|talk|return|"
			+ "bank|deposit|bury|teleport|travel|head|enter|leave|cross|open|close)\\b.*");
	/**
	 * A requirement phrase, not an instruction. It must survive the instruction
	 * filter so {@link #emit} can turn a destination-free phrase into the honest
	 * minimum requirement (one law rune).
	 */
	private static final Pattern TELEPORT_RUNES_REQUIREMENT = Pattern.compile(
		"(?i)^teleport\\s+runes?(?:\\s+.*)?$");
	private static final Pattern GATHER_BOUNDARY = Pattern.compile("[.\\[(,&+]");
	private static final Pattern LEADING_ARTICLE = Pattern.compile("^(?:the|a|an)\\s+");

	private static final Set<String> NOT_ITEMS = new HashSet<>(Arrays.asList(
		"everything", "all", "it", "them", "both", "one", "this", "these"));

	private ItemListParser()
	{
	}

	/**
	 * Drops ONE trailing "(advice here)" parenthetical - but NEVER a short
	 * dose/charge suffix like "Prayer potion(4)", "Ring of dueling(8)" or
	 * "(t)", whose parenthetical is part of the real item name. Advice
	 * contains whitespace or is 8+ characters; suffixes are short and solid.
	 *
	 * A single left-to-right scan replacing the old
	 * {@code \s*\((?:[^)]*\s[^)]*|[^)]{8,})\)\s*$} regex, whose overlapping
	 * unbounded quantifiers backtracked quadratically on malformed
	 * whitespace-heavy text with an unclosed parenthesis (measured ~0.5s at
	 * 10k chars - enough to stall a guide import). Same semantics: the
	 * stripped region must end the string, its content can't contain a
	 * closing parenthesis, and like the regex's leftmost match it starts at
	 * the EARLIEST open parenthesis after the second-to-last close - so an
	 * unbalanced "(see (note)" strips whole, never leaving a dangling "(see".
	 */
	static String stripTrailingAdvice(String value)
	{
		int end = value.length();
		while (end > 0 && Character.isWhitespace(value.charAt(end - 1)))
		{
			end--;
		}
		if (end == 0 || value.charAt(end - 1) != ')')
		{
			return value;
		}
		int lastClose = value.lastIndexOf(')', end - 2);
		int open = value.indexOf('(', lastClose + 1);
		if (open < 0 || open >= end - 1)
		{
			return value;
		}
		String inner = value.substring(open + 1, end - 1);
		boolean advice = inner.length() >= 8;
		for (int i = 0; !advice && i < inner.length(); i++)
		{
			advice = Character.isWhitespace(inner.charAt(i));
		}
		if (!advice)
		{
			return value;
		}
		// also consume the whitespace that preceded the parenthetical
		while (open > 0 && Character.isWhitespace(value.charAt(open - 1)))
		{
			open--;
		}
		return value.substring(0, open);
	}

	/**
	 * Full multi-item list from a "Withdraw:" step, or null when this isn't one.
	 */
	public static List<ItemReq> parseWithdraw(String text)
	{
		if (text == null || text.length() > MAX_ITEM_PARSE_CHARS)
		{
			return null;
		}
		Matcher m = WITHDRAW.matcher(stripWikiLinks(text).trim());
		if (!m.matches())
		{
			return null;
		}
		// drop "(8 Inventory slots)" style notes ANYWHERE in the list -
		// the live guide often continues after them ("... (14 Inventory
		// Slots) + Food"), so trailing-only stripping isn't enough; the third
		// covers a writer who forgot the closing parenthesis
		String list = DIALOGUE_OPTIONS.matcher(m.group(1)).replaceAll("");
		list = GROUPED_THOUSANDS.matcher(list).replaceAll("");
		list = protectAndNames(list);
		list = SLOTS_PAREN.matcher(list).replaceAll("");
		list = SLOTS_BRACKET.matcher(list).replaceAll("");
		list = SLOTS_UNCLOSED.matcher(list).replaceAll("");
		list = stripTrailingAdvice(list);
		list = TRAILING_DOTS.matcher(list).replaceAll("");

		return parseList(list);
	}

	/**
	 * Items list from a JSON guide's " (Items: 100 gp, knife, logs)" step
	 * suffix (appended from its items_needed metadata), or null when the step
	 * has none. Display/bank-tag/icon use ONLY - unlike a Withdraw step this
	 * never becomes an auto-completion condition, because holding the items is
	 * not what completes such a step.
	 */
	public static List<ItemReq> parseItemsSuffix(String text)
	{
		if (text == null)
		{
			return null;
		}
		int idx = text.lastIndexOf("(Items: ");
		if (idx < 0)
		{
			return null;
		}
		String inner = text.substring(idx + "(Items: ".length()).trim();
		// the step may have been length-capped mid-suffix ("...…"): parse the
		// items that survived instead of dropping the whole list
		boolean truncated = false;
		if (inner.endsWith("…"))
		{
			inner = inner.substring(0, inner.length() - 1);
			truncated = true;
		}
		if (inner.endsWith(")"))
		{
			inner = inner.substring(0, inner.length() - 1);
			truncated = false; // the list closed before the cap hit
		}
		List<ItemReq> out = parseList(inner);
		if (truncated && out != null && !out.isEmpty())
		{
			// the cap cut mid-list: the final fragment ("kni…") is not a real
			// item name - drop it rather than show a bogus grid entry
			out.remove(out.size() - 1);
			if (out.isEmpty())
			{
				return null;
			}
		}
		return out;
	}

	/** Split a comma/&amp;/+-separated item list into requirements. */
	private static List<ItemReq> parseList(String list)
	{
		List<ItemReq> out = new ArrayList<>();
		// the guide separates items with commas, ampersands, and plus signs
		for (String part : LIST_SPLIT.split(list))
		{
			// a curated override can also name a single LIST SEGMENT
			// ("Cure Me Spells", "Curse Runes"): those phrases only ever
			// occur inside longer withdraw lines, so the whole-step lookup
			// in parse() never sees them - expand them here instead
			List<ItemReq> segmentOverride = StepItemOverrides.forStep(part.trim());
			if (segmentOverride != null)
			{
				out.addAll(segmentOverride);
				continue;
			}
			String p = stripTrailingAdvice(part.trim());
			// trailing sentences ("Ball of Wool. If 85 Crafting...")
			int sentence = p.indexOf(". ");
			if (sentence > 0)
			{
				p = p.substring(0, sentence);
			}
			p = p.trim();
			if (p.isEmpty())
			{
				continue;
			}
			// instruction fragments after '&' splits ("wear them", "equip it").
			// "Teleport Runes" is an item requirement despite beginning with an
			// instruction verb; it must reach emit() instead of being discarded.
			if (INSTRUCTION_FRAGMENT.matcher(p).matches()
				&& !TELEPORT_RUNES_REQUIREMENT.matcher(p).matches())
			{
				continue;
			}
			// strip a trailing "(...)" qualifier whose insides would otherwise be
			// mistaken for list separators ("Potion (3)/(4)")
			String stripped = TRAILING_QUALIFIER.matcher(p).replaceAll("");
			if (!stripped.equals(p) && !stripped.trim().isEmpty())
			{
				p = stripped.trim();
			}
			// "Research Notes / Bronze pickaxe not needed": the slash separates
			// a real item from an explicit negation, so keep only what's needed
			if (p.indexOf('/') >= 0)
			{
				expandSlashGroup(out, p);
				continue;
			}
			if (NEGATED.matcher(p).find())
			{
				continue;
			}
			// "2x Inventory of X" must be read whole: letting the generic
			// quantity prefix consume the "2x" first loses the multiplier
			if (INVENTORY_OF.matcher(p).matches())
			{
				emit(out, p, 1, null);
				continue;
			}
			int qty = 1;
			String qtyLabel = null;
			Matcher q = QTY_PREFIX.matcher(p);
			if (q.matches())
			{
				try
				{
					qty = Math.max(1, Integer.parseInt(q.group(1)));
				}
				catch (NumberFormatException ignored)
				{
				}
				if (!q.group(2).isEmpty())
				{
					// "100+ Cosmic Runes": 100 satisfies the step, the label
					// carries the guide's real open-ended intent
					qtyLabel = q.group(1) + "+";
				}
				p = q.group(3).trim();
			}
			else
			{
				Matcher ks = K_SUFFIX.matcher(p);
				if (ks.matches() && !ks.group(2).trim().isEmpty())
				{
					try
					{
						qty = Math.max(1, Integer.parseInt(ks.group(1)) * 1000);
					}
					catch (NumberFormatException ignored)
					{
					}
					p = ks.group(2).trim();
				}
				else
				{
					// spelled-out quantity ("two cheese", "three raw beef")
					int[] wq = leadingWordQuantity(p);
					if (wq != null)
					{
						qty = Math.max(1, wq[0]);
						p = p.substring(wq[1]).trim();
					}
				}
			}
			emit(out, p, qty, qtyLabel);
		}
		if (out.isEmpty())
		{
			return null;
		}
		applyInventoryFillThresholds(out);
		return out;
	}

	/**
	 * "Inventory of X" still displays the guide's literal 28-slot request.
	 * When the same step also requests another item, half an inventory is the
	 * practical readiness/completion threshold: 14 for one inventory, 28 for
	 * two inventories. This is deliberately narrow and never changes the
	 * displayed stack count.
	 */
	private static void applyInventoryFillThresholds(List<ItemReq> items)
	{
		boolean hasOtherRequirement = false;
		for (ItemReq req : items)
		{
			if (!req.isInventoryFill() && !ConceptItems.isConcept(req.getName()))
			{
				hasOtherRequirement = true;
				break;
			}
		}
		if (!hasOtherRequirement)
		{
			return;
		}
		for (int i = 0; i < items.size(); i++)
		{
			ItemReq req = items.get(i);
			if (req.isInventoryFill())
			{
				items.set(i, req.withCompletionQuantity(Math.max(1, req.getQuantity() / 2)));
			}
		}
	}


	/**
	 * Expands a slash-joined fragment. Two shapes occur in the guide:
	 *
	 * <p>A LEADING qualifier shared by every part - "Raw Rat/Chicken/Beef"
	 * means raw rat, raw chicken and raw beef. A TRAILING noun shared by every
	 * part - "Mind/6xAir/6xEarth/All Water Runes" means mind rune, 6 air runes,
	 * 6 earth runes and all water runes. Parts that already carry the shared
	 * word keep their own copy rather than doubling it.</p>
	 *
	 * <p>Explicit negations ("Bronze pickaxe not needed") are dropped, which is
	 * what makes a slash also usable as an alternatives separator.</p>
	 */
	private static void expandSlashGroup(List<ItemReq> out, String fragment)
	{
		String[] parts = fragment.split("/");
		if (parts.length < 2)
		{
			expand(out, fragment);
			return;
		}
		String first = parts[0].trim();
		String last = parts[parts.length - 1].trim();

		// trailing shared noun: last part's final word, when the earlier parts
		// are bare enough to need it ("Mind" -> "Mind Runes")
		String tailNoun = null;
		int lastSpace = last.lastIndexOf(' ');
		if (lastSpace > 0)
		{
			tailNoun = last.substring(lastSpace + 1).trim();
		}

		// leading shared qualifier: first part's first word, when the later
		// parts are single bare words ("Raw Rat" -> "Raw Chicken")
		String headWord = null;
		int firstSpace = first.indexOf(' ');
		if (firstSpace > 0)
		{
			headWord = first.substring(0, firstSpace).trim();
		}
		boolean tailShared = tailNoun != null && !tailNoun.isEmpty()
			&& parts.length > 1 && !containsWord(first, tailNoun);
		boolean headShared = headWord != null && !headWord.isEmpty()
			&& !containsWord(last, headWord) && !tailShared;

		for (String raw : parts)
		{
			String a = raw.trim();
			if (a.isEmpty() || NEGATED.matcher(a).find())
			{
				continue;
			}
			if (headShared && a != first && !containsWord(a, headWord))
			{
				a = headWord + " " + a;
			}
			else if (tailShared && !containsWord(a, tailNoun))
			{
				a = a + " " + tailNoun;
			}
			expand(out, a);
		}
	}

	/**
	 * Runes for a named teleport, or null if not one we expand. Counts verified
	 * against the Teleportation_spells wiki table.
	 */
	private static String[][] teleportRuneSet(String place)
	{
		switch (place)
		{
			case "trollheim":
				return new String[][]{{"2", "Fire rune"}, {"2", "Law rune"}};
			case "varrock":
				return new String[][]{{"3", "Air rune"}, {"1", "Fire rune"}, {"1", "Law rune"}};
			case "falador":
				return new String[][]{{"3", "Air rune"}, {"1", "Water rune"}, {"1", "Law rune"}};
			case "lumbridge":
				return new String[][]{{"3", "Air rune"}, {"1", "Earth rune"}, {"1", "Law rune"}};
			case "camelot":
				return new String[][]{{"5", "Air rune"}, {"1", "Law rune"}};
			case "ardougne":
				return new String[][]{{"2", "Water rune"}, {"2", "Law rune"}};
			case "watchtower":
				return new String[][]{{"2", "Earth rune"}, {"2", "Law rune"}};
			case "house":
			case "teleport to house":
				return new String[][]{{"1", "Air rune"}, {"1", "Earth rune"}, {"1", "Law rune"}};
			default:
				return null;
		}
	}

	private static boolean lowerStarts(String s, String prefix)
	{
		return s.length() >= prefix.length()
			&& s.substring(0, prefix.length()).equalsIgnoreCase(prefix);
	}

	private static boolean containsWord(String haystack, String word)
	{
		String h = " " + haystack.toLowerCase(java.util.Locale.ROOT) + " ";
		return h.contains(" " + word.toLowerCase(java.util.Locale.ROOT) + " ");
	}

	/**
	 * Adds one parsed fragment, applying the guide's open-ended and derived
	 * quantity conventions. Fragments that survive to here are already
	 * de-negated and slash-split.
	 */
	private static void emit(List<ItemReq> out, String p, int qty, String qtyLabel)
	{
		emit(out, p, qty, qtyLabel, 0);
	}

	/**
	 * The rewrite rules ("All X", "Inventory of X", "Best X Spell") re-emit
	 * their stripped noun, so degenerate input ("all all all ...") recurses
	 * once per token. Real steps never nest past two; the depth cap turns a
	 * hostile 4k-char chain from a StackOverflowError into a dropped item.
	 */
	private static final int MAX_EMIT_DEPTH = 8;

	private static void emit(List<ItemReq> out, String p, int qty, String qtyLabel, int depth)
	{
		if (p == null || depth > MAX_EMIT_DEPTH)
		{
			return;
		}
		p = p.trim();
		if (p.isEmpty())
		{
			return;
		}

		// "All Water Runes": any amount satisfies the step, so the numeric
		// requirement is 1 and the label carries the guide's real intent
		Matcher all = ALL_QTY.matcher(p);
		if (all.matches())
		{
			emit(out, all.group(1).trim(), 1, "all", depth + 1);
			return;
		}

		// "2x Inventory of Waterskins(4)" -> 2 * 28
		Matcher inv = INVENTORY_OF.matcher(p);
		if (inv.matches())
		{
			int multiples = 1;
			if (inv.group(1) != null)
			{
				try
				{
					multiples = Math.max(1, Integer.parseInt(inv.group(1)));
				}
				catch (NumberFormatException ignored)
				{
				}
			}
			int before = out.size();
			emit(out, inv.group(2).trim(), multiples * INVENTORY_SLOTS, null, depth + 1);
			for (int i = before; i < out.size(); i++)
			{
				out.set(i, out.get(i).asInventoryFill());
			}
			return;
		}

		// "1 extra Rotten Apple" - one MORE than the one the step already needs
		Matcher extra = EXTRA_QTY.matcher(p);
		if (extra.matches())
		{
			int n = 1;
			try
			{
				n = Math.max(1, Integer.parseInt(extra.group(1)));
			}
			catch (NumberFormatException ignored)
			{
			}
			emit(out, extra.group(2).trim(), n + 1, null, depth + 1);
			return;
		}

		// restore any " and " that was masked to survive the list split
		if (p.indexOf('\u0001') >= 0)
		{
			p = p.replace(AND_GUARD, " and ");
		}

		// A bare charged/dosed phrase accepts ANY dose. An explicitly written
		// "(4)" in the guide is left exact. Previously a bare phrase was pinned
		// to one dose, so holding a 3-dose potion counted as nothing.
		String[] anyDose = DOSE_GROUPS.get(Names.normalize(p));
		if (anyDose != null)
		{
			out.add(ItemReq.anyOf(anyDose[0], Math.max(1, qty), qtyLabel, anyDose));
			return;
		}

		// "Kitten or Cat" and "Food for Elvarg" name a choice and a category,
		// not one exact item
		String bare = Names.normalize(p);
		if (bare.equals("kittenorcat") || bare.equals("catorkitten"))
		{
			out.add(ItemReq.anyOf("Pet kitten", Math.max(1, qty), qtyLabel,
				"Pet kitten", "Pet cat", "Cat", "Kitten"));
			return;
		}
		if (bare.equals("teleportrunes") || bare.equals("teleportrune"))
		{
			// A bare "Teleport Runes" begins with the verb "teleport", so the
			// instruction-fragment filter used to discard it before emit() ran.
			// Every standard teleport needs a law rune; use that honest minimum
			// as an exact requirement and a real icon.
			out.add(new ItemReq("Law rune", Math.max(1, qty), qtyLabel));
			return;
		}
		if (bare.equals("batteredkeyorknife"))
		{
			// two real items, either satisfies the step
			out.add(ItemReq.anyOf("Battered key", Math.max(1, qty), qtyLabel,
				"Battered key", "Knife"));
			return;
		}
		// phrases that name an item FAMILY: any tier counts, and the slot shows
		// the lowest tier
		ItemCategory family = FAMILY_PHRASES.get(bare);
		if (family != null)
		{
			out.add(ItemReq.category(family, Math.max(1, qty), qtyLabel));
			return;
		}

		// FIXED-size phrases carry their own count and must never be multiplied
		// by a quantity the parser already pulled off the front: "5 Coloured
		// Balls" was becoming 25 because both fives were applied.
		String fixedKey = Names.normalize(p);
		if (fixedKey.equals("colouredballs") || fixedKey.equals("5colouredballs")
			|| fixedKey.equals("all5colouredballs") || fixedKey.equals("coloredballs"))
		{
			emit(out, "Stone ball", 5, null);
			return;
		}

		// whole-set and spell phrases expand into their real components
		String[][] expansion = setExpansion(p);
		if (expansion != null)
		{
			for (String[] piece : expansion)
			{
				emit(out, piece[0], Integer.parseInt(piece[1]) * Math.max(1, qty), null);
			}
			return;
		}

		// "Trollheim teleport runes" -> the runes that teleport actually uses
		Matcher teleRunes = TELEPORT_RUNE_PHRASE.matcher(p);
		if (teleRunes.matches())
		{
			String place = teleRunes.group(1).toLowerCase(java.util.Locale.ROOT).trim();
			String[][] set = teleportRuneSet(place);
			if (set != null)
			{
				for (String[] rune : set)
				{
					emit(out, rune[1], Integer.parseInt(rune[0]), null, depth + 1);
				}
				return;
			}
			// A bare "Teleport Runes" with no destination used to fall through
			// here and get dropped entirely, so banks 102 and 105 showed no
			// teleport requirement at all. Every teleport spell needs a law
			// rune, so that is the honest minimum and gives the slot a real icon.
			if (place.isEmpty())
			{
				emit(out, "Law rune", Math.max(1, qty), qtyLabel, depth + 1);
				return;
			}
			// named but unknown destination: leave as a generic runes label
			// rather than guess at the elemental runes
		}

		// "Best Air Spell" -> the elemental rune it needs
		Matcher bestSpell = BEST_SPELL.matcher(p);
		if (bestSpell.matches())
		{
			emit(out, bestSpell.group(1) + " rune", 1, null, depth + 1);
			return;
		}
		// "best food" / "best X" where X is a plain noun: drop the qualifier
		if (lowerStarts(p, "best "))
		{
			emit(out, p.substring(5).trim(), qty, qtyLabel, depth + 1);
			return;
		}

		// "Few food", "as many bones as possible": keep the guide's own word as
		// the label; the numeric requirement stays 1 so any amount satisfies it
		Matcher vague = VAGUE_QTY.matcher(p);
		if (vague.matches())
		{
			String word = vague.group(1).toLowerCase(java.util.Locale.ROOT);
			String rest = RANDOM_FILLER.matcher(vague.group(2)).replaceAll("").trim();
			emit(out, rest, 1, "as many".equals(word) ? "all" : word, depth + 1);
			return;
		}

		// "60 Noted Empty Buckets" - the noted form of the same item
		Matcher noted = NOTED.matcher(p);
		if (noted.matches())
		{
			emit(out, noted.group(1).trim(), qty, qtyLabel, depth + 1);
			return;
		}

		// length cap: real item names are short; oversized "names" are
		// malformed wiki text and would only bloat tooltips/grids
		// "Goblin Diplomacy]" - the opening bracket went to another fragment,
		// so what is left is quest-tag text, not an item
		if (ORPHAN_BRACKET.matcher(p).matches())
		{
			return;
		}
		String lower = p.toLowerCase(java.util.Locale.ROOT);
		String norm = Names.normalize(p);
		if (p.length() > 60 || NOT_ITEMS.contains(lower) || NOT_ITEMS_TRANSPORT.contains(lower)
			|| NOT_ITEMS_PROSE.contains(lower) || NOT_ITEMS_NORM.contains(norm))
		{
			return;
		}
		out.add(qtyLabel != null ? new ItemReq(p, qty, qtyLabel) : new ItemReq(p, qty));
	}


	/** Replaces [[Target|Label]] and [[Target]] with their display text. */
	static String stripWikiLinks(String text)
	{
		if (text == null || text.indexOf("[[") < 0)
		{
			return text == null ? "" : text;
		}
		StringBuilder sb = new StringBuilder(text.length());
		int i = 0;
		while (i < text.length())
		{
			int open = text.indexOf("[[", i);
			if (open < 0)
			{
				sb.append(text, i, text.length());
				break;
			}
			int close = text.indexOf("]]", open);
			if (close < 0)
			{
				sb.append(text, i, text.length());
				break;
			}
			sb.append(text, i, open);
			String inner = text.substring(open + 2, close);
			int pipe = inner.lastIndexOf('|');
			sb.append(pipe >= 0 ? inner.substring(pipe + 1) : inner);
			i = close + 2;
		}
		return sb.toString();
	}

	/**
	 * Splits a slash-joined fragment whose parts share a trailing noun
	 * ("Raw Rat/Chicken/Beef" -> three raw meats, "Desert Robes/boots" -> two
	 * desert pieces) and emits each. Falls back to emitting the fragment
	 * unchanged when no shared noun is detectable.
	 */
	private static void expand(List<ItemReq> out, String fragment)
	{
		int qty = 1;
		String qtyLabel = null;
		Matcher q = QTY_PREFIX.matcher(fragment);
		if (q.matches())
		{
			try
			{
				qty = Math.max(1, Integer.parseInt(q.group(1)));
			}
			catch (NumberFormatException ignored)
			{
			}
			if (!q.group(2).isEmpty())
			{
				qtyLabel = q.group(1) + "+";
			}
			fragment = q.group(3).trim();
		}
		emit(out, fragment, qty, qtyLabel);
	}

	/**
	 * Single item from a gathering step ("Collect 3x Logs ..."), or null.
	 * Only applies when the step STARTS with the verb, to avoid false positives
	 * in longer sentences.
	 */
	public static List<ItemReq> parseGather(String text)
	{
		if (text == null || text.length() > MAX_ITEM_PARSE_CHARS)
		{
			return null;
		}
		Matcher m = GATHER_VERB.matcher(protectAndNames(
			DIALOGUE_OPTIONS.matcher(stripWikiLinks(text)).replaceAll("").trim()));
		if (!m.matches())
		{
			return null;
		}
		String rest = m.group(1).trim();

		// "1 extra Rotten Apple" must be seen BEFORE the quantity prefix is
		// consumed, otherwise "extra" survives as the item name
		Matcher extraFirst = EXTRA_QTY.matcher(rest);
		if (extraFirst.matches())
		{
			int n = 1;
			try
			{
				n = Math.max(1, Integer.parseInt(extraFirst.group(1)));
			}
			catch (NumberFormatException ignored)
			{
			}
			String name = extraFirst.group(2).trim();
			String[] cut = GATHER_BOUNDARY.split(name);
			name = cut.length > 0 ? cut[0].trim() : "";
			name = GATHER_CUTOFF.matcher(name).replaceAll("").trim();
			List<ItemReq> extraOut = new ArrayList<>();
			emit(extraOut, name, n + 1, null);
			return extraOut.isEmpty() ? null : extraOut;
		}

		int qty = 1;
		String qtyLabel = null;
		Matcher q = QTY_PREFIX.matcher(rest);
		if (q.matches())
		{
			try
			{
				qty = Math.max(1, Integer.parseInt(q.group(1)));
			}
			catch (NumberFormatException ignored)
			{
			}
			if (!q.group(2).isEmpty())
			{
				// "Buy 100+ Cosmic Runes": the open-quantity label was dropped
				// here while the withdraw path kept it, so the same phrase
				// rendered differently depending on the verb
				qtyLabel = q.group(1) + "+";
			}
			String remainder = q.group(3).trim();
			// "Buy 2x Inventory of Waterskins(4)": the leading count multiplies
			// INVENTORIES, not items, so hand the whole phrase to emit() intact
			// rather than letting it be read as a plain item quantity
			if (INVENTORY_OF.matcher(remainder).matches())
			{
				List<ItemReq> invOut = new ArrayList<>();
				emit(invOut, qty + "x " + remainder, 1, null);
				if (invOut.isEmpty())
				{
					return null;
				}
				applyInventoryFillThresholds(invOut);
				return invOut;
			}
			rest = remainder;
		}

		// A gather step can name several items ("Buy 3x Buckets & Shears"), so
		// split on the same separators a withdraw list uses BEFORE cutting at
		// sentence/location boundaries - the old code kept only the first
		// fragment and silently dropped everything after the ampersand.
		List<ItemReq> out = new ArrayList<>();
		String[] segments = LIST_SPLIT.split(GROUPED_THOUSANDS.matcher(rest).replaceAll(""));
		String[] distributed = distributeTrailingNoun(segments);
		if (distributed != null)
		{
			segments = distributed;
		}
		for (int i = 0; i < segments.length; i++)
		{
			String seg = segments[i].trim();
			if (seg.isEmpty())
			{
				continue;
			}
			// possessives and hedges the guide puts before a count
			seg = LEADING_HEDGE.matcher(seg).replaceFirst("").trim();

			// This segment's OWN quantity prefix must be taken before the
			// boundary split: GATHER_BOUNDARY treats '+' as a boundary, so
			// "100+ Cosmic Runes" was cut down to "100" and the item was lost.
			int segPrefixQty = 0;
			String segPrefixLabel = null;
			Matcher segQ = QTY_PREFIX.matcher(seg);
			if (segQ.matches())
			{
				try
				{
					segPrefixQty = Math.max(1, Integer.parseInt(segQ.group(1)));
				}
				catch (NumberFormatException ignored)
				{
				}
				if (!segQ.group(2).isEmpty())
				{
					segPrefixLabel = segQ.group(1) + "+";
				}
				seg = segQ.group(3).trim();
			}

			// bracket/parenthesis boundaries end the item name
			String[] bits = GATHER_BOUNDARY.split(seg);
			String name = bits.length > 0 ? bits[0].trim() : "";
			name = GATHER_CUTOFF.matcher(name).replaceAll("").trim();
			// k-suffix ("16k feathers") and spelled-out quantity ("three raw
			// beef") on THIS segment before the article strip, so each item in
			// a multi-item gather keeps its own count instead of defaulting to 1
			int segWordQty = 0;
			Matcher segK = K_SUFFIX.matcher(name);
			if (segK.matches() && !segK.group(2).trim().isEmpty())
			{
				try
				{
					segWordQty = Integer.parseInt(segK.group(1)) * 1000;
				}
				catch (NumberFormatException ignored)
				{
				}
				name = segK.group(2).trim();
			}
			else
			{
				int[] wq = leadingWordQuantity(name);
				if (wq != null)
				{
					segWordQty = wq[0];
					name = name.substring(wq[1]).trim();
				}
			}
			name = LEADING_ARTICLE.matcher(name).replaceFirst("").trim();
			// the 30-char cap targets runaway prose, but "Full Inventory of
			// Balls of wool" is a legitimate long form that emit() rewrites
			// into a short item name - so let those through
			if (name.isEmpty()
				|| (name.length() > 30 && !INVENTORY_OF.matcher(name).matches()))
			{
				continue;
			}
			if (INSTRUCTION_FRAGMENT.matcher(name).matches())
			{
				continue;
			}
			// precedence: this segment's own prefix, then a spelled-out number,
			// then the verb's leading count on segment 0, else 1
			int segQty = segPrefixQty > 0 ? segPrefixQty
				: (segWordQty > 0 ? segWordQty : (i == 0 ? qty : 1));
			// the verb-level open-quantity label ("Buy 100+ Cosmic Runes")
			// belongs to segment 0, the same way its count does
			String segLabel = segPrefixLabel != null ? segPrefixLabel
				: (i == 0 && segPrefixQty == 0 && segWordQty == 0 ? qtyLabel : null);
			if (name.indexOf('/') >= 0)
			{
				// "100 Soda Ash/Sand": every branch of the group inherits the
				// shared leading count instead of silently becoming 1
				List<ItemReq> group = new ArrayList<>();
				expandSlashGroup(group, name);
				for (ItemReq r : group)
				{
					emit(out, r.getName(),
						segQty > 1 ? segQty : r.getQuantity(), segLabel);
				}
			}
			else if (segLabel != null)
			{
				emit(out, name, segQty, segLabel);
			}
			else
			{
				expand(out, segQty > 1 ? segQty + "x " + name : name);
			}
		}
		if (out.isEmpty())
		{
			return null;
		}
		applyInventoryFillThresholds(out);
		return out;
	}

	/**
	 * Withdraw list if present, otherwise gather item, otherwise null.
	 *
	 * <p>A step-specific override wins over both, for the handful of guide
	 * sentences whose wording no general rule resolves correctly. An override
	 * that no longer matches falls through to normal parsing.</p>
	 */
	/**
	 * Hostile-input bound for the regex pipeline. Several cleanup patterns
	 * ({@code SLOTS_*}, {@code TRAILING_QUALIFIER}) scan quadratically on
	 * pathological "((((("-flooded text; real guide item lines top out around
	 * 230 characters, so anything past this cap is malformed or hostile and
	 * produces no items at all rather than minutes of executor time.
	 * (Measured: 350ms per 4k-char flooded step without the cap.)
	 */
	private static final int MAX_ITEM_PARSE_CHARS = 512;

	public static List<ItemReq> parse(String text)
	{
		List<ItemReq> override = StepItemOverrides.forStep(text);
		if (override != null)
		{
			return override;
		}
		List<ItemReq> w = parseWithdraw(text);
		return w != null ? w : parseGather(text);
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * An item requirement parsed from a step. A requirement may name one exact
 * item or an interchangeable group such as "any cooked food".
 *
 * <p>For alternative groups, {@link #getQuantity()} is the minimum TOTAL
 * quantity across every eligible item. This lets a guide express requirements
 * such as "21 food of any cooked type" without inventing three exact foods.
 * The ordered alternatives are also used by bank tags so the player can see
 * the valid choices they actually own.</p>
 */
public class ItemReq
{
	private final String name;
	private final int quantity;
	/** Minimum held quantity used for borders/readiness/auto-completion. */
	private final int completionQuantity;
	/** True when the source wording was "inventory of X". */
	private final boolean inventoryFill;
	private final String normalized;
	private final String singularized;
	private final String quantityLabel;
	private final List<String> alternatives;
	private final ItemCategory category;

	public ItemReq(String name, int quantity)
	{
		this(name, quantity, null);
	}

	public ItemReq(String name, int quantity, String quantityLabel)
	{
		this(name, quantity, quantity, false, quantityLabel, Collections.emptyList(), null);
	}

	private ItemReq(String name, int quantity, int completionQuantity, boolean inventoryFill,
		String quantityLabel, List<String> alternatives, ItemCategory category)
	{
		this.name = name;
		this.quantity = Math.max(1, quantity);
		this.completionQuantity = Math.max(1, Math.min(this.quantity, completionQuantity));
		this.inventoryFill = inventoryFill;
		this.normalized = Names.normalize(name);
		this.singularized = Names.singularize(name);
		this.quantityLabel = quantityLabel;
		this.alternatives = alternatives;
		this.category = category;
	}

	/**
	 * Build a requirement satisfied by the combined quantity of any listed
	 * alternatives. Duplicate/blank names are removed while input order is
	 * preserved.
	 */
	public static ItemReq anyOf(String displayName, int minimumTotal, String quantityLabel, String... options)
	{
		Set<String> unique = new LinkedHashSet<>();
		if (options != null)
		{
			for (String option : options)
			{
				if (option != null && !Names.normalize(option).isEmpty())
				{
					unique.add(option.trim());
				}
			}
		}
		if (unique.isEmpty())
		{
			throw new IllegalArgumentException("Alternative requirement needs at least one option");
		}
		return new ItemReq(displayName, minimumTotal, minimumTotal, false, quantityLabel,
			Collections.unmodifiableList(new ArrayList<>(unique)), null);
	}

	/** Build a requirement satisfied by any live item in a runtime category. */
	public static ItemReq category(ItemCategory category, int minimumTotal, String quantityLabel)
	{
		if (category == null)
		{
			throw new IllegalArgumentException("Category is required");
		}
		return new ItemReq(category.getDisplayName(), minimumTotal, minimumTotal, false, quantityLabel,
			Collections.emptyList(), category);
	}

	public String getName()
	{
		return name;
	}

	public int getQuantity()
	{
		return quantity;
	}

	/** Quantity that actually satisfies this requirement. */
	public int getCompletionQuantity()
	{
		return completionQuantity;
	}

	public boolean isInventoryFill()
	{
		return inventoryFill;
	}

	/** Preserve display quantity while changing the held-item threshold. */
	ItemReq withCompletionQuantity(int minimumHeld)
	{
		return new ItemReq(name, quantity, minimumHeld, inventoryFill, quantityLabel, alternatives, category);
	}

	/** Mark a parser result as originating from "inventory of X" wording. */
	ItemReq asInventoryFill()
	{
		return new ItemReq(name, quantity, completionQuantity, true, quantityLabel, alternatives, category);
	}

	public String getQuantityLabel()
	{
		return quantityLabel;
	}

	public boolean hasQuantityLabel()
	{
		return quantityLabel != null;
	}

	public String getNormalized()
	{
		return normalized;
	}

	public String getSingularized()
	{
		return singularized;
	}

	/** True when any eligible option may satisfy this requirement. */
	public boolean isAlternativeGroup()
	{
		return !alternatives.isEmpty();
	}

	public boolean isCategoryRequirement()
	{
		return category != null;
	}

	public ItemCategory getCategory()
	{
		return category;
	}

	/** Ordered eligible item names. Empty for an exact requirement. */
	public List<String> getAlternatives()
	{
		return alternatives;
	}

	/** Name used for the single representative icon in compact displays. */
	public String getIconName()
	{
		if (isCategoryRequirement())
		{
			// lowest tier stands in for the family: the least capable item that
			// satisfies the requirement, so the picture never implies gear the
			// step does not actually need
			return category.getIconName();
		}
		return isCategoryRequirement() ? category.getBankTagExamples()[0]
			: isAlternativeGroup() ? alternatives.get(0) : name;
	}

	/**
	 * Every name that can satisfy this requirement. Used for inventory and
	 * bank-tag matching.
	 *
	 * <p>Aliases used to affect only the icon, so a step asking for "Ardy Cloak"
	 * showed the right picture while still reporting the item missing. The
	 * canonical name is now a match candidate too. Callers must dedupe by
	 * resolved item, since several candidates can point at one held stack.</p>
	 */
	public List<String> getMatchNames()
	{
		if (isCategoryRequirement())
		{
			return java.util.Arrays.asList(category.getBankTagExamples());
		}
		List<String> base = isAlternativeGroup()
			? alternatives : Collections.singletonList(name);
		java.util.LinkedHashSet<String> out = new java.util.LinkedHashSet<>(base);
		for (String option : base)
		{
			String canonical = ItemAliases.canonical(Names.normalize(option));
			if (canonical != null)
			{
				out.add(canonical);
			}
		}
		return new java.util.ArrayList<>(out);
	}

	public static String normalize(String s)
	{
		return Names.normalize(s);
	}

	public static boolean namesEquivalent(String a, String b)
	{
		String na = Names.normalize(a);
		String nb = Names.normalize(b);
		if (na.isEmpty() || nb.isEmpty())
		{
			return false;
		}
		return na.equals(nb) || Names.singularMatch(a, b);
	}

	@Override
	public String toString()
	{
		String prefix = quantityLabel != null ? quantityLabel
			: quantity > 1 ? quantity + "x" : "";
		String base = prefix.isEmpty() ? name : prefix + " " + name;
		if (!isAlternativeGroup() || isCategoryRequirement())
		{
			return base;
		}
		return base + " (any of: " + String.join(", ", alternatives) + ")";
	}
}

package com.hcimguide;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

/**
 * Parses structured-JSON guides (chapters -&gt; sections -&gt; steps) into the
 * same Guide/Episode/Bank/Step model as the wikitext parser, so every
 * downstream feature (checkboxes, highlighting, auto-completion, bank tags)
 * works identically regardless of the guide's original source.
 *
 * Supported shape (BRUHsailer's data/guide_data.json and anything matching):
 * <pre>
 * { "title": "...", "chapters": [
 *     { "title": "Chapter 1: ...", "sections": [
 *         { "title": "1.1: ...", "steps": [
 *             { "content": [{"text": "..."}], "nestedContent": [...],
 *               "metadata": {"items_needed": "...", "total_time": "..."} } ] } ] } ] }
 * </pre>
 *
 * Everything is defensive: missing keys, wrong types, and empty text degrade
 * to a smaller guide rather than throwing, and the same MAX_STEPS cap as the
 * wikitext parser bounds a hostile file.
 */
public class JsonGuideParser
{
	private static final int MAX_STEPS = 25_000;
	/**
	 * Structural caps, mirroring WikitextParser: the step cap alone doesn't
	 * bound the MODEL - a 16 MB file of empty chapters/sections would still
	 * allocate thousands of episodes and banks. Hitting one marks the guide
	 * truncated. Real BRUHsailer data: 4 chapters, ~30 sections.
	 */
	private static final int MAX_EPISODES = 500;
	private static final int MAX_SECTIONS_PER_CHAPTER = 500;
	private static final int MAX_TEXT = 400;
	/** Fragments shorter than this fold into their neighbor instead of standing alone. */
	private static final int MIN_FRAGMENT = 12;
	/** Sentences longer than this get a secondary split at comma boundaries. */
	private static final int LONG_FRAGMENT = 300;
	/** Target length for comma-split chunks of an over-long sentence. */
	private static final int CHUNK_TARGET = 150;
	/** A parenthetical protects against splitting only if it closes within this many chars. */
	private static final int PAREN_WINDOW = 160;
	/**
	 * Hard cap on the paragraph length fed to the splitter, against quadratic
	 * CPU on hostile imports (the short-fragment merge fold and the chunk
	 * fallback both re-copy within one paragraph; unbounded input made them
	 * O(n^2) - same class of guard as WikitextParser's MAX_LABEL caps, keep
	 * it). Real paragraphs top out ~2,200 chars; old-generation keys only
	 * ever read the first MAX_TEXT chars, so migration is unaffected.
	 */
	private static final int MAX_PARAGRAPH = 10_000;
	/** Dot-terminated tokens that do NOT end a sentence ("see e.g. Getting Rats"). */
	private static final java.util.Set<String> ABBREVIATIONS = new java.util.HashSet<>(java.util.Arrays.asList(
		"e.g", "i.e", "vs", "approx", "etc", "mr", "mrs", "st", "no"));

	/**
	 * First non-whitespace character is '{' - the cheap sniff shared by
	 * every JSON entry point, deliberately NOT trim(): trimming a 16 MB
	 * import allocates a second 16 MB string just to look at one char.
	 */
	private static boolean sniffJson(String text)
	{
		if (text == null)
		{
			return false;
		}
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (!Character.isWhitespace(c))
			{
				return c == '{';
			}
		}
		return false;
	}

	/** True when the text is a JSON guide this parser understands. */
	public static boolean looksLikeJsonGuide(String text)
	{
		if (!sniffJson(text))
		{
			return false;
		}
		try
		{
			// instance API, not JsonParser.parseString: the client bundles an
			// older gson where the static method does not exist
			JsonElement root = new JsonParser().parse(text);
			return root.isJsonObject() && root.getAsJsonObject().has("chapters");
		}
		catch (Exception e)
		{
			return false;
		}
	}

	/**
	 * Parses the text as a JSON guide in ONE pass, or returns null when it
	 * isn't one (not JSON, not an object, or no "chapters") so the caller
	 * can fall back to the wikitext parser - without the parse-twice cost of
	 * calling {@link #looksLikeJsonGuide} first on a multi-MB import.
	 */
	public Guide tryParse(String text)
	{
		if (!sniffJson(text))
		{
			return null;
		}
		JsonObject root;
		try
		{
			JsonElement parsed = new JsonParser().parse(text);
			if (!parsed.isJsonObject() || !parsed.getAsJsonObject().has("chapters"))
			{
				return null;
			}
			root = parsed.getAsJsonObject();
		}
		catch (Exception e)
		{
			return null;
		}
		return build(root);
	}

	public Guide parse(String text)
	{
		if (text == null)
		{
			return new Guide();
		}
		JsonObject root;
		try
		{
			JsonElement parsed = new JsonParser().parse(text);
			if (!parsed.isJsonObject())
			{
				return new Guide();
			}
			root = parsed.getAsJsonObject();
		}
		catch (Exception e)
		{
			return new Guide();
		}
		return build(root);
	}

	private Guide build(JsonObject root)
	{
		Guide guide = new Guide();

		JsonArray chapters = optArray(root, "chapters");
		if (chapters == null)
		{
			return guide;
		}

		int stepCount = 0;
		int chapterNo = 0;
		for (JsonElement chapterEl : chapters)
		{
			if (!chapterEl.isJsonObject())
			{
				continue;
			}
			JsonObject chapter = chapterEl.getAsJsonObject();
			chapterNo++;
			if (guide.getEpisodes().size() >= MAX_EPISODES)
			{
				guide.markTruncated();
				continue;
			}
			GuideEpisode episode = new GuideEpisode(chapterNo, WikitextParser.sanitizeDisplay(optString(chapter, "title", "Chapter " + chapterNo)));

			// a chapter may hold sections, or steps directly. Banks and the
			// episode itself attach to the model only once populated, so a
			// malformed/hostile file of empty structures allocates nothing -
			// while chapterNo/sectionNo still count EVERY source structure, so
			// the C<n>.S<n> ids in persisted step keys never renumber when an
			// empty chapter sits between populated ones.
			JsonArray sections = optArray(chapter, "sections");
			if (sections == null)
			{
				JsonArray directSteps = optArray(chapter, "steps");
				if (directSteps != null)
				{
					GuideBank bank = new GuideBank("C" + chapterNo + ".S0", "Steps", chapterNo);
					stepCount = addSteps(guide, bank, directSteps, stepCount);
					if (!bank.getSteps().isEmpty())
					{
						episode.getBanks().add(bank);
					}
				}
			}
			else
			{
				int sectionNo = 0;
				for (JsonElement sectionEl : sections)
				{
					if (!sectionEl.isJsonObject())
					{
						continue;
					}
					JsonObject section = sectionEl.getAsJsonObject();
					sectionNo++;
					if (sectionNo > MAX_SECTIONS_PER_CHAPTER)
					{
						guide.markTruncated();
						continue;
					}
					String title = WikitextParser.sanitizeDisplay(optString(section, "title", "Section " + sectionNo));
					GuideBank bank = new GuideBank("C" + chapterNo + ".S" + sectionNo, title, chapterNo);
					stepCount = addSteps(guide, bank, optArray(section, "steps"), stepCount);
					if (!bank.getSteps().isEmpty())
					{
						episode.getBanks().add(bank);
					}
				}
			}
			if (!episode.getBanks().isEmpty())
			{
				guide.getEpisodes().add(episode);
			}
		}
		return guide;
	}

	private int addSteps(Guide guide, GuideBank bank, JsonArray steps, int stepCount)
	{
		if (steps == null)
		{
			return stepCount;
		}
		// occurrence indexes count IDENTICAL texts only (same contract as
		// WikitextParser): keys stay stable when unrelated steps are inserted
		// or removed upstream, so a re-import never resets unrelated progress.
		// Three key spaces are tracked separately so each generation of old
		// keys is reproduced exactly as its parser built them:
		//   occByText   - the CURRENT (sentence-split) step texts
		//   occByOld    - the pre-split verbatim paragraph texts
		//   occByLegacy - the space-joined paragraph texts (oldest parser)
		java.util.Map<String, Integer> occByText = new java.util.HashMap<>();
		java.util.Map<String, Integer> occByOld = new java.util.HashMap<>();
		java.util.Map<String, Integer> occByLegacy = new java.util.HashMap<>();
		for (JsonElement stepEl : steps)
		{
			if (stepCount >= MAX_STEPS)
			{
				guide.markTruncated();
				continue;
			}
			if (!stepEl.isJsonObject())
			{
				continue;
			}
			JsonObject step = stepEl.getAsJsonObject();

			String raw = joinContent(optArray(step, "content"), false);
			String legacyRaw = joinContent(optArray(step, "content"), true);
			String itemsSuffix = itemsSuffix(step);
			// KNOWN BOUNDED EDGE: a step is added (and all occurrence counters
			// advanced) only when the NEW verbatim text is non-empty. If runs
			// concatenate into a fully-strippable tag while the old space-joined
			// form did not (pathological input), later duplicate-text legacy
			// keys shift and miss migration - the user re-ticks those steps.
			if (!raw.isEmpty())
			{
				stepCount = addParagraph(guide, bank, raw, legacyRaw, itemsSuffix, 0,
					videoLinks(optArray(step, "content")),
					occByText, occByOld, occByLegacy, stepCount);
			}

			JsonArray nested = optArray(step, "nestedContent");
			if (nested != null)
			{
				for (JsonElement nEl : nested)
				{
					if (stepCount >= MAX_STEPS)
					{
						guide.markTruncated();
						continue;
					}
					if (!nEl.isJsonObject())
					{
						continue;
					}
					JsonObject n = nEl.getAsJsonObject();
					String nRaw = joinContent(optArray(n, "content"), false);
					String nLegacy = joinContent(optArray(n, "content"), true);
					if (!nRaw.isEmpty())
					{
						int depth = Math.max(1, Math.min(4, optInt(n, "level", 1)));
						stepCount = addParagraph(guide, bank, nRaw, nLegacy, "", depth,
							videoLinks(optArray(n, "content")),
							occByText, occByOld, occByLegacy, stepCount);
					}
				}
			}
		}
		return stepCount;
	}

	/**
	 * Add one source paragraph as one step PER SENTENCE (the guide's paragraphs
	 * are strings of short actions; one checkbox per action reads like the
	 * wikitext guides and stops the MAX_TEXT cap from truncating the tail).
	 * Sentences still longer than LONG_FRAGMENT split again at comma
	 * boundaries, the continuation chunks indented one level.
	 *
	 * Both generations of the paragraph's OLD key are recorded for progress
	 * migration: the pre-split verbatim key maps to all split children via
	 * {@link Guide#getLegacySplitKeys()}, and the oldest space-joined key
	 * chains onto it via {@link Guide#getLegacyStepKeys()} (replayed first, so
	 * either generation of saved progress lands on the split steps).
	 */
	private static int addParagraph(Guide guide, GuideBank bank, String raw, String legacyRaw,
		String itemsSuffix, int depth, java.util.List<String[]> videoLinks,
		java.util.Map<String, Integer> occByText,
		java.util.Map<String, Integer> occByOld, java.util.Map<String, Integer> occByLegacy, int stepCount)
	{
		if (raw.length() > MAX_PARAGRAPH)
		{
			raw = raw.substring(0, MAX_PARAGRAPH - 1) + "…";
		}
		java.util.List<String> newKeys = new java.util.ArrayList<>();
		java.util.List<GuideStep> added = new java.util.ArrayList<>();
		boolean first = true;
		for (String fragment : splitDigestible(raw))
		{
			boolean fragmentHead = true;
			// the first fragment carries the items suffix: reserve room for it
			// so the combined text can never reach the MAX_TEXT cap
			for (String chunk : chunkAtCommas(fragment, first ? itemsSuffix.length() : 0))
			{
				if (stepCount >= MAX_STEPS)
				{
					// mid-paragraph cap: later chunks are dropped - admit it,
					// this can be the LAST element with no outer check left
					guide.markTruncated();
					break;
				}
				// the items suffix stays on the paragraph's first step only
				String text = first ? chunk + itemsSuffix : chunk;
				int d = fragmentHead ? depth : Math.min(4, depth + 1);
				GuideStep guideStep = addStep(bank, text, d, occByText);
				// bare video URLs in the text itself (some runs carry the URL
				// as their visible text)
				guideStep.setVideoUrl(VideoLinks.firstVideoUrl(guideStep.getText()));
				newKeys.add(guideStep.getKey());
				added.add(guideStep);
				stepCount++;
				first = false;
				fragmentHead = false;
			}
		}

		// linked runs ("Getting Rats for 2t Oaks" -> youtube): attach each
		// video to the split step whose text contains the anchor, falling back
		// to the paragraph's first step when the anchor got chunked apart
		for (String[] link : videoLinks)
		{
			String anchor = link[0];
			String needle = anchor.length() > 24 ? anchor.substring(0, 24) : anchor;
			GuideStep dest = null;
			if (!needle.isEmpty())
			{
				for (GuideStep s : added)
				{
					if (s.getText().contains(needle))
					{
						dest = s;
						break;
					}
				}
			}
			if (dest == null && !added.isEmpty())
			{
				dest = added.get(0);
			}
			if (dest != null && dest.getVideoUrl() == null)
			{
				dest.setVideoUrl(link[1]);
			}
		}

		// the key the PREVIOUS parser gave this paragraph (verbatim join,
		// suffix appended, both capped exactly as it did)
		//
		// KNOWN BOUNDED EDGE: a paragraph whose whole text equals another
		// paragraph's leading sentence gets an old key that a real split
		// child now owns. migrateSplitKeys resolves it when the store also
		// holds the other paragraph's old key; an old store holding ONLY the
		// duplicate is indistinguishable from new-format progress on the
		// child, so the identical-text child shows ticked in its place - the
		// user re-ticks at most one step per duplicated sentence.
		String oldText = cap(cap(raw) + itemsSuffix);
		int oldOcc = occByOld.merge(oldText, 1, Integer::sum) - 1;
		String oldKey = bank.getId() + "#" + Integer.toHexString(oldText.hashCode()) + "#" + oldOcc;
		if (!newKeys.isEmpty() && !(newKeys.size() == 1 && newKeys.get(0).equals(oldKey)))
		{
			guide.getLegacySplitKeys().put(oldKey, newKeys);
		}

		// the OLDEST parser joined formatting runs with spaces; its key chains
		// onto the previous parser's key (migrateLegacyKeys runs before
		// migrateSplitKeys, so gen1 -> gen2 -> split children resolves fully)
		String legacyText = cap(cap(legacyRaw) + itemsSuffix);
		int legacyOcc = occByLegacy.merge(legacyText, 1, Integer::sum) - 1;
		if (!legacyText.equals(oldText) || legacyOcc != oldOcc)
		{
			String legacyKey = bank.getId() + "#" + Integer.toHexString(legacyText.hashCode()) + "#" + legacyOcc;
			if (!legacyKey.equals(oldKey))
			{
				guide.getLegacyStepKeys().put(legacyKey, oldKey);
			}
		}
		return stepCount;
	}

	private static GuideStep addStep(GuideBank bank, String text, int depth, java.util.Map<String, Integer> occByText)
	{
		// enforce the documented cap on the COMBINED text (items suffix included)
		text = cap(text);
		int occ = occByText.merge(text, 1, Integer::sum) - 1;
		String key = bank.getId() + "#" + Integer.toHexString(text.hashCode()) + "#" + occ;
		GuideStep step = new GuideStep(key, text, depth, bank.getId());
		bank.getSteps().add(step);
		return step;
	}

	/**
	 * (anchor text, url) pairs for content runs that carry a whitelisted video
	 * link - the url lives either on the run itself or in its formatting
	 * object, depending on the exporter version.
	 */
	private static java.util.List<String[]> videoLinks(JsonArray content)
	{
		java.util.List<String[]> out = new java.util.ArrayList<>();
		if (content == null)
		{
			return out;
		}
		for (JsonElement el : content)
		{
			if (!el.isJsonObject())
			{
				continue;
			}
			JsonObject run = el.getAsJsonObject();
			String url = optString(run, "url", "");
			if (url.isEmpty())
			{
				JsonElement f = run.get("formatting");
				if (f != null && f.isJsonObject())
				{
					url = optString(f.getAsJsonObject(), "url", "");
				}
			}
			// store the ACCEPTED form: trimmed (an untrimmed original would
			// pass validation yet break LinkBrowser later) and https-normalized
			String ok = VideoLinks.accepted(url);
			if (ok != null)
			{
				out.add(new String[]{WikitextParser.sanitizeDisplay(optString(run, "text", "")), ok});
			}
		}
		return out;
	}

	/**
	 * Split a sanitized paragraph into sentences. A sentence ends at '.', '!'
	 * or '?' followed by a space, EXCEPT inside a SHORT parenthetical (see
	 * {@link #protectedSpans}) or after a known abbreviation. Fragments shorter
	 * than MIN_FRAGMENT fold into their neighbor so stray "Ok." pieces never
	 * become their own checkbox.
	 */
	static java.util.List<String> splitDigestible(String text)
	{
		boolean[] prot = protectedSpans(text);
		java.util.List<String> parts = new java.util.ArrayList<>();
		int start = 0;
		int n = text.length();
		for (int i = 0; i < n; i++)
		{
			char c = text.charAt(i);
			if ((c == '.' || c == '!' || c == '?') && !prot[i] && i + 1 < n
				&& text.charAt(i + 1) == ' ' && !abbreviationBefore(text, i))
			{
				String frag = text.substring(start, i + 1).trim();
				if (!frag.isEmpty())
				{
					parts.add(frag);
				}
				start = i + 1;
			}
		}
		String tail = text.substring(start).trim();
		if (!tail.isEmpty())
		{
			parts.add(tail);
		}
		java.util.List<String> merged = new java.util.ArrayList<>();
		for (String p : parts)
		{
			int last = merged.size() - 1;
			if (last >= 0 && (p.length() < MIN_FRAGMENT || merged.get(last).length() < MIN_FRAGMENT))
			{
				merged.set(last, merged.get(last) + " " + p);
			}
			else
			{
				merged.add(p);
			}
		}
		return merged;
	}

	/**
	 * Marks characters inside a SHORT parenthetical/bracket - one whose closer
	 * arrives within PAREN_WINDOW chars - as protected from splitting, so
	 * asides like "(hop worlds. Really)" stay on one step. An unclosed or
	 * page-long parenthetical is treated as ordinary prose: the real guide has
	 * paragraph-sized "(this involves...)" asides that would otherwise lock
	 * splitting off for the rest of the paragraph. Bounded work: each opener
	 * scans at most PAREN_WINDOW chars ahead.
	 */
	private static boolean[] protectedSpans(String text)
	{
		int n = text.length();
		boolean[] prot = new boolean[n];
		for (int i = 0; i < n; i++)
		{
			char c = text.charAt(i);
			if (c != '(' && c != '[')
			{
				continue;
			}
			char closer = c == '(' ? ')' : ']';
			int end = Math.min(n, i + 1 + PAREN_WINDOW);
			for (int j = i + 1; j < end; j++)
			{
				if (text.charAt(j) == closer)
				{
					for (int k = i; k <= j; k++)
					{
						prot[k] = true;
					}
					break;
				}
			}
		}
		return prot;
	}

	/** True when the token ending at the '.' at dotIdx is a known abbreviation. */
	private static boolean abbreviationBefore(String text, int dotIdx)
	{
		int j = dotIdx - 1;
		while (j >= 0 && text.charAt(j) != ' ')
		{
			j--;
		}
		return ABBREVIATIONS.contains(text.substring(j + 1, dotIdx).toLowerCase(java.util.Locale.ROOT));
	}

	/**
	 * Secondary split for a sentence still longer than LONG_FRAGMENT: cut at
	 * the first unprotected ", " once CHUNK_TARGET is reached, greedily. A
	 * chunk that STILL exceeds LONG_FRAGMENT (commas all inside parens, or no
	 * commas at all) falls back to cutting at any ", ", then at a plain space,
	 * so ordinary prose never survives long enough for the MAX_TEXT cap to
	 * truncate visible text. (A single space-less token longer than the cap
	 * has no cut point at all and still gets truncated - hostile input only.)
	 * A trailing chunk too short to stand alone folds into the previous one.
	 */
	static java.util.List<String> chunkAtCommas(String fragment)
	{
		return chunkAtCommas(fragment, 0);
	}

	/**
	 * @param reserve chars to keep free on the FIRST chunk (the items suffix
	 *                appended to a paragraph's first step), so suffix-carrying
	 *                steps can never reach the MAX_TEXT cap either
	 */
	static java.util.List<String> chunkAtCommas(String fragment, int reserve)
	{
		java.util.List<String> out = new java.util.ArrayList<>();
		if (fragment.length() + reserve <= LONG_FRAGMENT)
		{
			out.add(fragment);
			return out;
		}
		boolean[] prot = protectedSpans(fragment);
		int start = 0;
		for (int i = 0; i < fragment.length(); i++)
		{
			if (fragment.charAt(i) == ',' && !prot[i] && i + 1 < fragment.length()
				&& fragment.charAt(i + 1) == ' ' && i + 1 - start >= CHUNK_TARGET)
			{
				out.add(fragment.substring(start, i + 1).trim());
				start = i + 1;
			}
		}
		String tail = fragment.substring(start).trim();
		if (!tail.isEmpty())
		{
			int last = out.size() - 1;
			if (tail.length() < MIN_FRAGMENT && last >= 0)
			{
				out.set(last, out.get(last) + " " + tail);
			}
			else
			{
				out.add(tail);
			}
		}
		// fallback tiers for chunks the protected commas couldn't shorten
		java.util.List<String> bounded = new java.util.ArrayList<>();
		for (String chunk : out)
		{
			while (true)
			{
				int limit = bounded.isEmpty() ? LONG_FRAGMENT - reserve : LONG_FRAGMENT;
				if (chunk.length() <= limit)
				{
					break;
				}
				int cut = chunk.lastIndexOf(", ", limit);
				if (cut < MIN_FRAGMENT)
				{
					cut = chunk.lastIndexOf(' ', limit);
				}
				if (cut < MIN_FRAGMENT)
				{
					break; // one giant unbreakable token: let the cap handle it
				}
				bounded.add(chunk.substring(0, cut + 1).trim());
				chunk = chunk.substring(cut + 1).trim();
			}
			if (!chunk.isEmpty())
			{
				int last = bounded.size() - 1;
				if (chunk.length() < MIN_FRAGMENT && last >= 0)
				{
					bounded.set(last, bounded.get(last) + " " + chunk);
				}
				else
				{
					bounded.add(chunk);
				}
			}
		}
		return bounded;
	}

	private static String cap(String s)
	{
		return s.length() > MAX_TEXT ? s.substring(0, MAX_TEXT - 1) + "…" : s;
	}

	/**
	 * Concatenate a content array's text fields into one clean, sanitized step
	 * line. Runs are FORMATTING runs and are frequently split mid-word
	 * ("Gr" + "ab coins"), so they concatenate verbatim - each run carries its
	 * own spacing. legacySpacing reproduces the old space-inserting behavior
	 * solely so progress keys recorded under it can be migrated.
	 */
	private static String joinContent(JsonArray content, boolean legacySpacing)
	{
		if (content == null)
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (JsonElement el : content)
		{
			if (el.isJsonObject())
			{
				String t = optString(el.getAsJsonObject(), "text", "");
				if (!t.isEmpty())
				{
					if (legacySpacing && sb.length() > 0)
					{
						sb.append(' ');
					}
					sb.append(t);
				}
			}
			else if (el.isJsonPrimitive())
			{
				sb.append(el.getAsString());
			}
		}
		// NOT capped here: the sentence splitter needs the full paragraph.
		// Old-parser keys re-apply the cap via cap() where they are rebuilt.
		return WikitextParser.sanitizeDisplay(sb.toString());
	}

	/** " (Items: ...)" from metadata.items_needed when it's a real list. */
	private static String itemsSuffix(JsonObject step)
	{
		JsonElement m = step.get("metadata");
		if (m == null || !m.isJsonObject())
		{
			return "";
		}
		String items = optString(m.getAsJsonObject(), "items_needed", "");
		if (items.isEmpty() || items.equalsIgnoreCase("none") || items.equalsIgnoreCase("n/a"))
		{
			return "";
		}
		String clean = WikitextParser.sanitizeDisplay(items);
		if (clean.length() > 120)
		{
			clean = clean.substring(0, 119) + "…";
		}
		return " (Items: " + clean + ")";
	}

	private static JsonArray optArray(JsonObject o, String key)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonArray() ? e.getAsJsonArray() : null;
	}

	private static String optString(JsonObject o, String key, String fallback)
	{
		JsonElement e = o.get(key);
		return e != null && e.isJsonPrimitive() ? e.getAsString() : fallback;
	}

	private static int optInt(JsonObject o, String key, int fallback)
	{
		try
		{
			JsonElement e = o.get(key);
			return e != null && e.isJsonPrimitive() ? e.getAsInt() : fallback;
		}
		catch (Exception ex)
		{
			return fallback;
		}
	}
}

package com.hcimguide;

import java.util.concurrent.atomic.AtomicLong;

/**
 * Tracks which activation of the plugin is current.
 *
 * <p>RuneLite reuses the same plugin instance when a plugin is disabled and
 * enabled again, so a plain "am I active" flag is not enough to protect
 * asynchronous work. Consider:</p>
 *
 * <pre>
 * work starts -> plugin disabled -> plugin enabled -> old callback finishes
 * </pre>
 *
 * <p>By the time the old callback runs the flag is true again, so it passes the
 * check and mutates the NEW session with results belonging to the old one. A
 * generation number that increments on both start and stop closes that hole: the
 * callback captured generation N, the current generation is N+2, so it declines
 * to run.</p>
 *
 * <p>This class is deliberately free of RuneLite and Swing dependencies so it can
 * be unit tested directly.</p>
 */
final class LifecycleGeneration
{
	private final AtomicLong generation = new AtomicLong();
	private volatile boolean active;

	/** Mark a new activation and return its generation token. */
	long begin()
	{
		long g = generation.incrementAndGet();
		active = true;
		return g;
	}

	/**
	 * End the current activation. The generation advances here too, so work
	 * captured during the activation that just ended can never match again,
	 * even if the plugin is immediately re-enabled.
	 */
	void end()
	{
		active = false;
		generation.incrementAndGet();
	}

	/** Token for the activation running right now. */
	long current()
	{
		return generation.get();
	}

	/** True only while {@code token} still refers to the live activation. */
	boolean isCurrent(long token)
	{
		return active && generation.get() == token;
	}

	/** True while any activation is live. Equivalent to the old active flag. */
	boolean isActive()
	{
		return active;
	}
}

package com.hcimguide;

import java.util.Collections;
import java.util.Map;

/** Builds a deterministic Markdown report for unresolved and low-confidence steps. */
final class LocationAudit
{
	/**
	 * Character budget per table. The summary counters above each table stay
	 * exact; only the rendered rows are capped, so a poorly-resolving
	 * 25,000-step guide cannot push a multi-megabyte document onto the
	 * clipboard. Checked by length rather than by counting rows so the guard is
	 * O(1) per append rather than rescanning the builder each time. Sized at
	 * roughly a thousand rows of typical width.
	 */
	private static final int MAX_TABLE_CHARS = 512 * 1024;

	private LocationAudit()
	{
	}

	static String toMarkdown(String guideId, Guide guide, Map<String, StepLocationPlan> plans)
	{
		Map<String, StepLocationPlan> safe = plans == null ? Collections.emptyMap() : plans;
		int total = 0;
		int resolved = 0;
		int inherited = 0;
		int manual = 0;
		int transport = 0;
		int entity = 0;
		int lowConfidence = 0;
		int unresolved = 0;
		StringBuilder unresolvedRows = new StringBuilder();
		StringBuilder lowRows = new StringBuilder();
		for (GuideEpisode episode : guide.getEpisodes())
		{
			for (GuideBank bank : episode.getBanks())
			{
				for (GuideStep step : bank.getSteps())
				{
					total++;
					StepLocationPlan plan = safe.get(step.getKey());
					if (plan != null && plan.hasWaypoints())
					{
						resolved++;
						for (StepLocationHint waypoint : plan.getWaypoints())
						{
							if (waypoint.getSource() == LocationSource.INHERITED_CONTEXT)
							{
								inherited++;
							}
							else if (waypoint.getSource() == LocationSource.USER_PIN)
							{
								manual++;
							}
							else if (waypoint.getSource() == LocationSource.TRANSPORT)
							{
								transport++;
							}
							else if (waypoint.getSource() == LocationSource.LIVE_NPC
								|| waypoint.getSource() == LocationSource.LIVE_OBJECT
								|| waypoint.getSource() == LocationSource.STORED_ENTITY)
							{
								entity++;
							}
							if (waypoint.getConfidence() == LocationConfidence.LOW)
							{
								lowConfidence++;
								appendResolvedRow(lowRows, episode, bank, step, waypoint);
							}
						}
						if (isPartiallyUnresolved(plan))
						{
							unresolved++;
							appendUnresolvedRow(unresolvedRows, episode, bank, step, plan);
						}
						continue;
					}
					LocationResolutionReason reason = plan == null
						? LocationResolutionReason.NO_LOCATION_NEEDED : plan.getReason();
					if (reason == LocationResolutionReason.NO_LOCATION_NEEDED)
					{
						continue;
					}
					unresolved++;
					appendUnresolvedRow(unresolvedRows, episode, bank, step, plan);
				}
			}
		}
		StringBuilder out = new StringBuilder();
		out.append("# Guide Overlay location-resolution audit\n\n")
			.append("- Guide: `").append(escape(guideId)).append("`\n")
			.append("- Resolver version: ").append(StepLocationPlanner.RESOLVER_VERSION).append("\n")
			.append("- Total steps: ").append(total).append("\n")
			.append("- Resolved steps: ").append(resolved).append("\n")
			.append("- Manual waypoints: ").append(manual).append("\n")
			.append("- Transport waypoints: ").append(transport).append("\n")
			.append("- Entity waypoints: ").append(entity).append("\n")
			.append("- Inherited waypoints: ").append(inherited).append("\n")
			.append("- Low-confidence waypoints: ").append(lowConfidence).append("\n")
			.append("- Unresolved actionable steps: ").append(unresolved).append("\n\n")
			.append("## Unresolved actionable steps\n\n")
			.append("| Episode | Episode title | Bank ID | Bank | Step key | Reason | Extracted candidate | Step text |\n")
			.append("|---:|---|---|---|---|---|---|---|\n")
			.append(unresolvedRows);
		if (unresolved == 0)
		{
			out.append("| — | — | — | — | — | — | — | No unresolved actionable locations |\n");
		}
		else if (unresolvedRows.length() >= MAX_TABLE_CHARS)
		{
			out.append("\n_Table truncated at the ").append(MAX_TABLE_CHARS / 1024)
				.append("KB safety cap; ").append(unresolved)
				.append(" unresolved steps were found in total._\n");
		}
		out.append("\n## Low-confidence resolved waypoints\n\n")
			.append("| Episode | Bank | Step key | Destination | Source | Confidence | Step text |\n")
			.append("|---:|---|---|---|---|---|---|\n")
			.append(lowRows);
		if (lowConfidence == 0)
		{
			out.append("| — | — | — | — | — | — | No low-confidence waypoints |\n");
		}
		else if (lowRows.length() >= MAX_TABLE_CHARS)
		{
			out.append("\n_Table truncated at the ").append(MAX_TABLE_CHARS / 1024)
				.append("KB safety cap; ").append(lowConfidence)
				.append(" low-confidence waypoints were found in total._\n");
		}
		return out.toString();
	}

	private static boolean isPartiallyUnresolved(StepLocationPlan plan)
	{
		if (plan == null || plan.getUnresolvedCandidates().isEmpty())
		{
			return false;
		}
		LocationResolutionReason reason = plan.getReason();
		return reason != LocationResolutionReason.RESOLVED
			&& reason != LocationResolutionReason.MULTIPLE_DESTINATIONS
			&& reason != LocationResolutionReason.NO_LOCATION_NEEDED;
	}

	private static void appendUnresolvedRow(StringBuilder rows, GuideEpisode episode, GuideBank bank,
		GuideStep step, StepLocationPlan plan)
	{
		if (rows.length() >= MAX_TABLE_CHARS)
		{
			return;
		}
		LocationResolutionReason reason = plan == null
			? LocationResolutionReason.NO_LOCATION_NEEDED : plan.getReason();
		rows.append("| ").append(episode.getNumber()).append(" | ")
			.append(escape(episode.getTitle())).append(" | ")
			.append(escape(bank.getId())).append(" | ")
			.append(escape(bank.getTitle())).append(" | `")
			.append(escape(step.getKey())).append("` | ")
			.append(reason.displayName()).append(" | ")
			.append(escape(plan == null ? "" : String.join("; ", plan.getUnresolvedCandidates())))
			.append(" | ").append(escape(step.getText())).append(" |\n");
	}

	private static void appendResolvedRow(StringBuilder rows, GuideEpisode episode, GuideBank bank,
		GuideStep step, StepLocationHint waypoint)
	{
		if (rows.length() >= MAX_TABLE_CHARS)
		{
			return;
		}
		rows.append("| ").append(episode.getNumber()).append(" | ")
			.append(escape(bank.getTitle())).append(" | `")
			.append(escape(step.getKey())).append("` | ")
			.append(escape(waypoint.getLabel())).append(" | ")
			.append(waypoint.getSource().displayName()).append(" | ")
			.append(waypoint.getConfidence().displayName()).append(" | ")
			.append(escape(step.getText())).append(" |\n");
	}

	private static String escape(String value)
	{
		return value == null ? "" : value.replace("|", "\\|").replace("\n", " ").replace("\r", " ");
	}
}

