package com.hcimguide;

/**
 * Step-scoped location-guide suppression.
 *
 * A hide applies to exactly the step it was made on. When the guided step
 * moves on, the suppression clears - the next step gets its arrow even when
 * its destination is the same building. (An earlier design carried
 * suppression into "equivalent" follow-up destinations while the player
 * stayed put; in practice that read as arrows going randomly missing, so
 * suppression is now strictly per-step.)
 */
final class LocationSuppressionState
{
	private String originStepKey;

	synchronized void hide(String stepKey)
	{
		if (stepKey != null)
		{
			originStepKey = stepKey;
		}
	}

	synchronized void clear()
	{
		originStepKey = null;
	}

	synchronized boolean isActive()
	{
		return originStepKey != null;
	}

	synchronized boolean hides(String stepKey)
	{
		return originStepKey != null && originStepKey.equals(stepKey);
	}

	/**
	 * Clears the suppression once the guided step is no longer the origin.
	 * Returns true when state changed (so callers can mark routes dirty).
	 */
	synchronized boolean clearWhenGuidedStepChanged(String guidedStepKey)
	{
		if (originStepKey != null && !originStepKey.equals(guidedStepKey))
		{
			originStepKey = null;
			return true;
		}
		return false;
	}
}

package com.hcimguide;

import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Single home for the name-normalization rules used to compare guide text
 * against NPC names, inventory item names and quest names.
 *
 * All patterns are precompiled: these methods run in per-tick code paths,
 * and {@code String.replaceAll} would compile a fresh Pattern on every call.
 * {@link Locale#ROOT} is used throughout so matching behaves identically on
 * every system locale.
 */
public final class Names
{
	private static final Pattern NON_ALNUM = Pattern.compile("[^a-z0-9]");
	private static final Pattern WORD_SPLIT = Pattern.compile("[^a-z0-9]+");

	private Names()
	{
	}

	/** Lowercase (root locale) with everything but letters/digits removed. */
	public static String normalize(String s)
	{
		if (s == null)
		{
			return "";
		}
		return NON_ALNUM.matcher(s.toLowerCase(Locale.ROOT)).replaceAll("");
	}

	/**
	 * Word-by-word plural stripping so "Jugs of wine" matches "Jug of wine".
	 * Both sides of any comparison get the same transformation, so
	 * over-stripping (e.g. "glass" -&gt; "glas") is harmless for equality.
	 */
	public static String singularize(String s)
	{
		if (s == null)
		{
			return "";
		}
		StringBuilder sb = new StringBuilder();
		for (String word : WORD_SPLIT.split(s.toLowerCase(Locale.ROOT)))
		{
			if (word.length() > 4 && word.endsWith("ies"))
			{
				// "berries" -> "berry"
				sb.append(word, 0, word.length() - 3).append('y');
			}
			else if (word.length() > 4 && word.endsWith("es")
				&& (word.endsWith("ches") || word.endsWith("shes")
					|| word.endsWith("sses") || word.endsWith("xes")
					|| word.endsWith("zzes")))
			{
				// "branches" -> "branch", "glasses" -> "glass", "boxes" -> "box".
				// Deliberately narrow: a blanket "-es" rule turned "pickaxes"
				// into "pickax", "roses" into "ros" and "shoes" into "sho",
				// because those stems already end in e.
				sb.append(word, 0, word.length() - 2);
			}
			else if (word.length() > 3 && word.endsWith("s") && !word.endsWith("ss"))
			{
				sb.append(word, 0, word.length() - 1);
			}
			else
			{
				sb.append(word);
			}
		}
		return sb.toString();
	}

	/**
	 * Loose match for NPC names that tolerates prefixes in either direction
	 * ("Veos" vs "Veos the sailor"). Both arguments must already be
	 * {@link #normalize(String) normalized}.
	 */
	public static boolean matchNormalized(String a, String b)
	{
		return !a.isEmpty() && !b.isEmpty()
			&& (a.equals(b) || b.startsWith(a) || a.startsWith(b));
	}

	/**
	 * Every plausible singular form of a name.
	 *
	 * <p>No single rule works: "boxes" needs two characters removed to reach
	 * "box", while "pickaxes" needs one to reach "pickaxe". Reducing to one
	 * guess corrupted "pickaxes" to "pickax", "roses" to "ros" and "shoes" to
	 * "sho". Producing candidates and matching if any of them agree avoids
	 * having to choose.</p>
	 *
	 * <p>Results are normalized, so they compare directly against
	 * {@link #normalize}d names.</p>
	 */
	public static java.util.Set<String> singularCandidates(String s)
	{
		java.util.LinkedHashSet<String> out = new java.util.LinkedHashSet<>();
		if (s == null || s.isEmpty())
		{
			return out;
		}
		out.add(normalize(s));
		out.add(singularize(s));

		String[] words = WORD_SPLIT.split(s.toLowerCase(java.util.Locale.ROOT));
		// each word contributes its own variants; combine positionally so a
		// multi-word name like "buckets of sand" still lines up with the item
		java.util.List<java.util.List<String>> perWord = new java.util.ArrayList<>();
		for (String w : words)
		{
			java.util.LinkedHashSet<String> forms = new java.util.LinkedHashSet<>();
			forms.add(w);
			if (w.length() > 3 && w.endsWith("s") && !w.endsWith("ss"))
			{
				forms.add(w.substring(0, w.length() - 1));
			}
			if (w.length() > 4 && w.endsWith("es"))
			{
				forms.add(w.substring(0, w.length() - 2));
			}
			if (w.length() > 4 && w.endsWith("ies"))
			{
				forms.add(w.substring(0, w.length() - 3) + "y");
			}
			perWord.add(new java.util.ArrayList<>(forms));
		}
		// bounded expansion: only the FIRST and LAST word are varied together,
		// which covers "buckets of sand" and "steel chainbodies" without a
		// combinatorial blowup on long names
		if (!perWord.isEmpty())
		{
			int last = perWord.size() - 1;
			for (String first : perWord.get(0))
			{
				for (String tail : perWord.get(last))
				{
					StringBuilder sb = new StringBuilder();
					for (int i = 0; i < perWord.size(); i++)
					{
						if (i == 0)
						{
							sb.append(first);
						}
						else if (i == last)
						{
							sb.append(tail);
						}
						else
						{
							sb.append(perWord.get(i).get(0));
						}
					}
					out.add(sb.toString());
				}
			}
		}
		out.remove("");
		return out;
	}

	/** True when two names share any singular form. */
	public static boolean singularMatch(String a, String b)
	{
		java.util.Set<String> ca = singularCandidates(a);
		for (String candidate : singularCandidates(b))
		{
			if (ca.contains(candidate))
			{
				return true;
			}
		}
		return false;
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.RuneLite;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * NPC name -&gt; world location database used to point at far-away targets.
 *
 * Two sources, no guesswork at runtime:
 * - a small bundled seed of well-known early-game NPCs (approximate is fine -
 *   the arrow only needs to point the right way);
 * - LEARNING: whenever a guide-target NPC is actually seen in the scene, its
 *   exact position is recorded, overriding the seed. The database therefore
 *   self-corrects and grows as you play, and is bounded by the set of names
 *   the guide references.
 *
 * Persisted to ~/.runelite/hcim-guide/npc-locations.json.
 */
@Singleton
public class NpcLocationStore
{
	private static final Logger log = LoggerFactory.getLogger(NpcLocationStore.class);
	private static final File STORE_FILE =
		new File(new File(RuneLite.RUNELITE_DIR, "hcim-guide"), "npc-locations.json");
	/** Import size guard: covers full-game spawn dumps with generous headroom. */
	private static final int MAX_IMPORT_ENTRIES = 50_000;
	private static final int MAX_IMPORT_CHARS = 16 * 1024 * 1024;
	private static final long MAX_STORE_BYTES = 32L * 1024 * 1024;

	private final Gson gson;
	/** normalized NPC name -> {x, y, plane}. */
	private final Map<String, int[]> locations = new ConcurrentHashMap<>();
	private volatile boolean dirty;
	private volatile boolean loaded;

	/**
	 * lookup() runs every game tick while a pinned target is out of scene, and
	 * its loose-match fallback scans the whole map on a miss - trivial for the
	 * seed, but a bundled full-game database makes that tens of thousands of
	 * comparisons per tick. Memoize recent queries INCLUDING misses (an empty
	 * Optional), so alternating between two unknown targets never rescans, and
	 * invalidate whenever the map changes. Access-order LRU, synchronized;
	 * clear() replaces the old two-field cache whose separate writes could
	 * briefly pair a query with the wrong result.
	 */
	private static final int LOOKUP_CACHE_SIZE = 16;
	private final Map<String, Optional<WorldPoint>> lookupCache =
		Collections.synchronizedMap(new LinkedHashMap<String, Optional<WorldPoint>>(32, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, Optional<WorldPoint>> eldest)
			{
				return size() > LOOKUP_CACHE_SIZE;
			}
		});
	/**
	 * Guards against a lookup that STRADDLES an invalidation: it read the old
	 * map, the importer put new data and cleared the cache, and only then
	 * would the lookup cache its stale result - which nothing would ever
	 * invalidate again. Snapshot before reading, only cache when unchanged.
	 */
	private final java.util.concurrent.atomic.AtomicInteger cacheGen =
		new java.util.concurrent.atomic.AtomicInteger();

	@Inject
	public NpcLocationStore(Gson gson)
	{
		this.gson = gson;
	}

	/** Loads the on-disk store (seeded from the bundled resources on first run). Call off the EDT. */
	public synchronized void load()
	{
		if (loaded)
		{
			return;
		}
		// precedence: anything already learned this session (newest) > the
		// saved store > the bundled FULL database (if present) > the seed -
		// so neither file load nor bundled data can overwrite a position
		// observed moments ago
		if (STORE_FILE.isFile())
		{
			try
			{
				String json = readStoreText();
				mergeIfAbsent(readLocationMap(new StringReader(json), MAX_IMPORT_ENTRIES));
			}
			catch (Exception e)
			{
				log.warn("Could not read npc location store", e);
			}
		}
		// optional full-game database: generate with tools/convert_spawns.py
		// from a community spawn dump and drop it into resources before
		// building - the plugin bundles and loads it automatically
		readInto(resourceStream("npc-locations-full.json"), "bundled full database");
		readInto(resourceStream("npc-locations-seed.json"), "bundled seed");
		invalidateLookupCache();
		loaded = true;
	}

	private InputStream resourceStream(String name)
	{
		return NpcLocationStore.class.getResourceAsStream(name);
	}

	private void readInto(InputStream in, String label)
	{
		if (in == null)
		{
			return;
		}
		try (InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			mergeIfAbsent(readLocationMap(reader, MAX_IMPORT_ENTRIES));
		}
		catch (Exception e)
		{
			log.warn("Could not read npc locations ({})", label, e);
		}
	}

	/** Bounded streaming parser avoids reflective generic metadata and whole-tree allocation. */
	private static Map<String, int[]> readLocationMap(Reader input, int maxEntries)
		throws IOException
	{
		Map<String, int[]> out = new HashMap<>();
		try (com.google.gson.stream.JsonReader reader = new com.google.gson.stream.JsonReader(input))
		{
			reader.beginObject();
			while (reader.hasNext())
			{
				String name = reader.nextName();
				if (out.size() >= maxEntries)
				{
					reader.skipValue();
					continue;
				}
				if (reader.peek() != com.google.gson.stream.JsonToken.BEGIN_ARRAY)
				{
					reader.skipValue();
					continue;
				}
				reader.beginArray();
				int[] values = new int[3];
				int count = 0;
				boolean valid = true;
				while (reader.hasNext())
				{
					if (count < values.length && reader.peek() == com.google.gson.stream.JsonToken.NUMBER)
					{
						values[count++] = reader.nextInt();
					}
					else
					{
						valid = false;
						reader.skipValue();
					}
				}
				reader.endArray();
				if (valid && count == values.length)
				{
					out.put(name, values);
				}
			}
			reader.endObject();
		}
		return out;
	}

	private void mergeIfAbsent(Map<String, int[]> raw)
	{
		if (raw == null)
		{
			return;
		}
		for (Map.Entry<String, int[]> e : raw.entrySet())
		{
			int[] v = e.getValue();
			// same range check as importJson: a corrupted on-disk store must
			// not feed nonsense coordinates to the compass/world map
			if (e.getKey() != null && v != null && v.length == 3
				&& v[0] >= 0 && v[0] < 20000 && v[1] >= 0 && v[1] < 20000 && v[2] >= 0 && v[2] <= 3)
			{
				String key = Names.normalize(e.getKey());
				if (!key.isEmpty())
				{
					locations.putIfAbsent(key, v);
				}
			}
		}
	}

	/** Records an observed NPC position (exact data always overrides the seed). */
	public void learn(String npcName, WorldPoint point)
	{
		if (npcName == null || point == null)
		{
			return;
		}
		String key = Names.normalize(npcName);
		if (key.isEmpty())
		{
			return;
		}
		int[] existing = locations.get(key);
		if (existing != null && existing[0] == point.getX() && existing[1] == point.getY()
			&& existing[2] == point.getPlane())
		{
			return;
		}
		locations.put(key, new int[]{point.getX(), point.getY(), point.getPlane()});
		invalidateLookupCache();
		dirty = true;
	}

	/** Best-known location for a target name, or null. Memoized per query. */
	public WorldPoint lookup(String targetName)
	{
		String norm = Names.normalize(targetName);
		if (norm.isEmpty())
		{
			return null;
		}
		Optional<WorldPoint> cached = lookupCache.get(norm);
		if (cached != null)
		{
			return cached.orElse(null);
		}
		int gen = cacheGen.get();
		int[] v = locations.get(norm);
		if (v == null)
		{
			v = looseMatch(norm);
		}
		WorldPoint result = v == null ? null : new WorldPoint(v[0], v[1], v[2]);
		if (cacheGen.get() == gen)
		{
			lookupCache.put(norm, Optional.ofNullable(result));
		}
		return result;
	}

	/**
	 * Deterministic loose fallback for prefix-style matches ("Veos" vs "Veos
	 * the captain"), used only after an exact miss. Prefix matching is only
	 * attempted when both names have at least four normalized characters -
	 * a two-letter query would loose-match half of a full-game database.
	 * Among the candidates the closest length wins, ties broken
	 * lexicographically, so the same query resolves to the same entry
	 * regardless of map iteration order or capacity.
	 */
	private int[] looseMatch(String norm)
	{
		if (norm.length() < 4)
		{
			return null;
		}
		String bestKey = null;
		int[] best = null;
		for (Map.Entry<String, int[]> e : locations.entrySet())
		{
			String key = e.getKey();
			if (key.length() < 4 || !Names.matchNormalized(norm, key))
			{
				continue;
			}
			if (bestKey == null || closerTo(norm, key, bestKey))
			{
				bestKey = key;
				best = e.getValue();
			}
		}
		return best;
	}

	/** True when candidate is a strictly better match for query than incumbent. */
	private static boolean closerTo(String query, String candidate, String incumbent)
	{
		int c = Math.abs(candidate.length() - query.length());
		int i = Math.abs(incumbent.length() - query.length());
		return c != i ? c < i : candidate.compareTo(incumbent) < 0;
	}

	private void invalidateLookupCache()
	{
		cacheGen.incrementAndGet();
		lookupCache.clear();
	}

	/** Revision used by cached guide-location plans. Changes whenever location data changes. */
	int getRevision()
	{
		return cacheGen.get();
	}

	/** All known locations as shareable JSON (name -&gt; [x, y, plane]). */
	public String exportJson()
	{
		return gson.toJson(new java.util.TreeMap<>(locations));
	}

	/**
	 * Merges locations from shared JSON (an {@link #exportJson()} payload or a
	 * converted community spawn dump). Explicit user action, so imported
	 * entries overwrite existing ones.
	 *
	 * @return number of entries imported
	 * @throws IllegalArgumentException when the text isn't a valid location map
	 */
	public int importJson(String json)
	{
		if (json == null)
		{
			throw new IllegalArgumentException("No locations found in the text");
		}
		if (json.length() > MAX_IMPORT_CHARS)
		{
			throw new IllegalArgumentException("Location JSON is too large (over 16MB)");
		}
		if (json.trim().isEmpty())
		{
			throw new IllegalArgumentException("No locations found in the text");
		}
		Map<String, int[]> raw;
		try
		{
			raw = readLocationMap(new StringReader(json), MAX_IMPORT_ENTRIES + 1);
		}
		catch (Exception e)
		{
			throw new IllegalArgumentException("Not a valid location JSON: " + e.getMessage(), e);
		}
		if (raw == null || raw.isEmpty())
		{
			throw new IllegalArgumentException("No locations found in the text");
		}
		if (raw.size() > MAX_IMPORT_ENTRIES)
		{
			throw new IllegalArgumentException(
				"Too many entries (" + raw.size() + "); the limit is " + MAX_IMPORT_ENTRIES);
		}
		int count = 0;
		for (Map.Entry<String, int[]> e : raw.entrySet())
		{
			int[] v = e.getValue();
			if (e.getKey() != null && v != null && v.length == 3
				&& v[0] >= 0 && v[0] < 20000 && v[1] >= 0 && v[1] < 20000 && v[2] >= 0 && v[2] <= 3)
			{
				String key = Names.normalize(e.getKey());
				if (!key.isEmpty())
				{
					locations.put(key, v);
					count++;
				}
			}
		}
		if (count == 0)
		{
			throw new IllegalArgumentException("No valid location entries in the text");
		}
		invalidateLookupCache();
		dirty = true;
		return count;
	}

	/**
	 * Bulk-adds entries whose keys are ALREADY normalized, without overwriting
	 * anything present (learned/saved/seed positions win). Used by the full
	 * database download so observed data is never clobbered.
	 *
	 * @return number of new entries added
	 */
	public int addNormalizedIfAbsent(Map<String, int[]> normalized)
	{
		int added = 0;
		for (Map.Entry<String, int[]> e : normalized.entrySet())
		{
			int[] v = e.getValue();
			if (e.getKey() != null && !e.getKey().isEmpty() && v != null && v.length == 3
				&& v[0] >= 0 && v[0] < 20000 && v[1] >= 0 && v[1] < 20000 && v[2] >= 0 && v[2] <= 3
				&& locations.putIfAbsent(e.getKey(), v) == null)
			{
				added++;
			}
		}
		if (added > 0)
		{
			invalidateLookupCache();
			dirty = true;
		}
		return added;
	}

	/** Writes the store if anything changed. Call off the EDT/client thread. */
	public synchronized void saveIfDirty()
	{
		if (!dirty)
		{
			return;
		}
		// clear BEFORE snapshotting: a learn() landing mid-save re-marks dirty
		// and gets picked up by the next save instead of being lost. (Its
		// entry may ALSO already be in this save's snapshot - the cost is one
		// harmless redundant save, never a lost write.)
		dirty = false;
		try
		{
			//noinspection ResultOfMethodCallIgnored
			STORE_FILE.getParentFile().mkdirs();
			atomicWrite(STORE_FILE,
				gson.toJson(new HashMap<>(locations)).getBytes(StandardCharsets.UTF_8));
		}
		catch (Exception e)
		{
			dirty = true;
			log.warn("Could not save npc location store", e);
		}
	}

	private static void atomicWrite(File target, byte[] bytes) throws IOException
	{
		Path directory = target.getParentFile().toPath();
		Files.createDirectories(directory);
		Path temp = Files.createTempFile(directory, target.getName(), ".tmp");
		try
		{
			Files.write(temp, bytes);
			try
			{
				Files.move(temp, target.toPath(), StandardCopyOption.ATOMIC_MOVE,
					StandardCopyOption.REPLACE_EXISTING);
			}
			catch (AtomicMoveNotSupportedException e)
			{
				Files.move(temp, target.toPath(), StandardCopyOption.REPLACE_EXISTING);
			}
		}
		finally
		{
			Files.deleteIfExists(temp);
		}
	}

	private static String readStoreText() throws IOException
	{
		try (InputStream in = Files.newInputStream(STORE_FILE.toPath()))
		{
			java.io.ByteArrayOutputStream out = new java.io.ByteArrayOutputStream();
			byte[] buffer = new byte[8192];
			int n;
			while ((n = in.read(buffer)) > 0)
			{
				out.write(buffer, 0, n);
				if (out.size() > MAX_STORE_BYTES)
				{
					throw new IOException("location store exceeds 32MB");
				}
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8);
		}
	}
}

package com.hcimguide;

import java.awt.Font;
import java.awt.Graphics2D;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.client.ui.FontManager;

/** Resolves bounded, configurable fonts for every text-bearing plugin overlay. */
final class OverlayFonts
{
	private static final int MAX_CACHED_FONTS = 128;
	private static final int MAX_CUSTOM_FAMILY_LENGTH = 80;

	/**
	 * Access-order LRU: users can explore installed fonts and sizes without
	 * retaining every combination for the lifetime of the RuneLite client.
	 */
	private static final Map<String, Font> CACHE = new LinkedHashMap<String, Font>(32, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Font> eldest)
		{
			return size() > MAX_CACHED_FONTS;
		}
	};

	private OverlayFonts()
	{
	}

	static void apply(Graphics2D graphics, HcimGuideConfig config)
	{
		graphics.setFont(resolve(graphics.getFont(), config.overlayFontFamily(),
			config.customOverlayFontFamily(), config.overlayFontWeight(), config.overlayFontSize()));
	}

	static Font resolve(Font fallback, HcimGuideConfig.OverlayFontFamily family,
		String customFamily, HcimGuideConfig.OverlayFontWeight weight, int requestedSize)
	{
		HcimGuideConfig.OverlayFontFamily safeFamily = family == null
			? HcimGuideConfig.OverlayFontFamily.SANS_SERIF : family;
		HcimGuideConfig.OverlayFontWeight safeWeight = weight == null
			? HcimGuideConfig.OverlayFontWeight.FAMILY_DEFAULT : weight;
		int size = Math.max(8, Math.min(40, requestedSize));
		String custom = sanitizeCustomFamily(customFamily);
		String fallbackKey = fallback == null ? "null"
			: fallback.getName() + ':' + fallback.getStyle();
		String key = safeFamily.name() + ':' + custom.toLowerCase(Locale.ROOT)
			+ ':' + safeWeight.name() + ':' + size + ':' + fallbackKey;
		synchronized (CACHE)
		{
			Font cached = CACHE.get(key);
			if (cached != null)
			{
				return cached;
			}
			Font created = create(fallback, safeFamily, custom, safeWeight, size);
			CACHE.put(key, created);
			return created;
		}
	}

	private static Font create(Font fallback, HcimGuideConfig.OverlayFontFamily family,
		String customFamily, HcimGuideConfig.OverlayFontWeight weight, int size)
	{
		Font base;
		if (family == HcimGuideConfig.OverlayFontFamily.CLIENT_DEFAULT)
		{
			base = fallback != null ? fallback : FontManager.getRunescapeFont();
		}
		else if (family.isRuneScape())
		{
			switch (family)
			{
				case SMALL:
					base = FontManager.getRunescapeSmallFont();
					break;
				case BOLD:
					base = FontManager.getRunescapeBoldFont();
					break;
				case RUNESCAPE:
				case REGULAR:
				default:
					base = FontManager.getRunescapeFont();
					break;
			}
		}
		else
		{
			int physicalStyle = weight == HcimGuideConfig.OverlayFontWeight.FAMILY_DEFAULT
				? family.getDefaultStyle() : weight.resolveStyle(family);
			String requestedName = family == HcimGuideConfig.OverlayFontFamily.CUSTOM
				? customFamily : family.getAwtName();
			if (requestedName == null || requestedName.isEmpty())
			{
				requestedName = Font.SANS_SERIF;
			}
			base = installedOrFallback(requestedName, physicalStyle, size);
		}
		int style = weight == HcimGuideConfig.OverlayFontWeight.FAMILY_DEFAULT
			? base.getStyle() : weight.resolveStyle(family);
		return base.deriveFont(style, (float) size);
	}

	/** Java silently maps unknown physical names to Dialog; make the fallback explicit. */
	private static Font installedOrFallback(String requestedName, int style, int size)
	{
		Font candidate = new Font(requestedName, style, size);
		String resolved = candidate.getFamily(Locale.ROOT);
		if (!Font.DIALOG.equalsIgnoreCase(requestedName)
			&& Font.DIALOG.equalsIgnoreCase(resolved)
			&& !requestedName.equalsIgnoreCase(resolved))
		{
			return new Font(Font.SANS_SERIF, style, size);
		}
		return candidate;
	}

	private static String sanitizeCustomFamily(String family)
	{
		if (family == null)
		{
			return "";
		}
		String trimmed = family.trim();
		return trimmed.length() <= MAX_CUSTOM_FAMILY_LENGTH
			? trimmed : trimmed.substring(0, MAX_CUSTOM_FAMILY_LENGTH);
	}

	/** Drop cached native font objects when the plugin is disabled. */
	static void clear()
	{
		synchronized (CACHE)
		{
			CACHE.clear();
		}
	}

	static int cacheSizeForTesting()
	{
		synchronized (CACHE)
		{
			return CACHE.size();
		}
	}
}

