package com.hcimguide;

/** Pure layout arithmetic kept separate from Swing so it can be regression tested. */
final class PanelLayout
{
	private PanelLayout()
	{
	}

	/**
	 * RuneLite's own settings-panel content margins (ConfigPanel uses
	 * {@code new EmptyBorder(8, 10, 10, 10)} around its scrollable content).
	 * The checklist adopts them verbatim so the plugin's sidebar and the
	 * client's settings sidebar keep identical edge geometry.
	 */
	static final int CONTENT_MARGIN_TOP = 8;
	static final int CONTENT_MARGIN_LEFT = 10;
	static final int CONTENT_MARGIN_BOTTOM = 10;
	static final int CONTENT_MARGIN_RIGHT = 10;

	/**
	 * Small internal gap inside the step-text component, on top of the 10px
	 * content margin, producing a 12px visible clearance between the wrap
	 * boundary and the divider/scrollbar.
	 */
	static final int TEXT_RIGHT_SAFETY = 2;

	/** RuneLite's fixed plugin-panel content width (PluginPanel.PANEL_WIDTH). */
	static final int PANEL_CONTENT_WIDTH = 225;

	/**
	 * Conservative step-text width for the very first preferred-size pass,
	 * before the layout has allocated the text component a real width: the
	 * fixed content width minus both content margins, the deepest row border
	 * (capped indent plus right edge), a checkbox column and an east-control
	 * column. Deliberately NARROW - narrower than ANY real row, so the first
	 * guess only overestimates height for one pass; a too-wide guess would
	 * underestimate it and clip the last line until the resize settles.
	 */
	static int preLayoutTextWidth()
	{
		return PANEL_CONTENT_WIDTH - CONTENT_MARGIN_LEFT - CONTENT_MARGIN_RIGHT
			- 24 /* deepest capped row border: 6+2*8 indent + 2 right */
			- 22 /* checkbox column */ - 28 /* east controls */;
	}

	/**
	 * Vertical view position that centers a row in the viewport.
	 *
	 * @param rowY row top in view coordinates
	 * @param rowHeight row height
	 * @param viewportHeight the viewport's visible extent height
	 * @param viewHeight total scrollable view height
	 * @return clamped y for {@code JViewport.setViewPosition}; a row taller
	 *     than the viewport aligns its top so its start is always visible
	 */
	static int centeredViewPosition(int rowY, int rowHeight, int viewportHeight, int viewHeight)
	{
		int desired = rowHeight >= viewportHeight
			? rowY
			: rowY - (viewportHeight - rowHeight) / 2;
		int max = Math.max(0, viewHeight - viewportHeight);
		return Math.max(0, Math.min(desired, max));
	}
}

package com.hcimguide;

import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Optional hand-off to the community "Shortest Path" Plugin Hub plugin:
 * when enabled, the current objective is sent over RuneLite's PluginMessage
 * bus so that plugin draws its real, collision-aware tile path (with all
 * the transport/teleport options the USER configured over there).
 *
 * Deliberately loose coupling: this is a broadcast, not an API call. If
 * Shortest Path isn't installed, nobody is listening and the message
 * vanishes at zero cost - no dependency, no reflection, no error. That's
 * also why this plugin doesn't reimplement pathfinding itself: a real
 * pathfinder needs the game's full collision map (megabytes of data kept
 * current by that plugin already).
 *
 * Dedup: a target is only re-sent when it CHANGES, and "clear" is only
 * sent when something was sent before - the bus never sees per-tick spam.
 */
@Singleton
public class PathfinderIntegration
{
	private static final Logger log = LoggerFactory.getLogger(PathfinderIntegration.class);

	/** Namespace/payload contract published by the Shortest Path plugin. */
	static final String NAMESPACE = "shortestpath";

	@FunctionalInterface
	interface MessageSink
	{
		void post(PluginMessage message);
	}

	private final MessageSink messageSink;

	private WorldPoint lastSent; // client thread only
	private long lastSentAtNanos;
	/**
	 * Exact destination represented by the last successful Shortest Path
	 * hand-off. Overlay rendering is not guaranteed to run on the client
	 * thread, so publish this separately from the client-thread dedup state.
	 */
	private volatile WorldPoint activeTarget;

	@Inject
	public PathfinderIntegration(EventBus eventBus)
	{
		this(eventBus::post);
	}

	/** Package-private seam for deterministic lifecycle/failure tests. */
	PathfinderIntegration(MessageSink messageSink)
	{
		this.messageSink = messageSink;
	}

	/**
	 * Ignore target drift below this many tiles: a pinned NPC wandering its
	 * patrol must not make the pathfinder replan every tick. Kept small so
	 * the drawn path still tracks a moving target near-realtime.
	 */
	private static final int RESEND_DEADBAND_TILES = 2;
	/**
	 * PluginMessage is a one-way broadcast with no acknowledgement. Re-send a
	 * stable target occasionally so the integration recovers when Shortest Path
	 * starts after this plugin, reloads, or clears its path internally.
	 */
	private static final long KEEPALIVE_NANOS = 15_000_000_000L;

	/**
	 * Force the next {@link #setTarget} to resend even if the destination has
	 * not changed.
	 *
	 * <p>Shortest Path only trims the walked tail when it receives a target and
	 * recomputes from the player's CURRENT position. Without a resend the drawn
	 * path keeps its stale head all the way to the destination.</p>
	 */
	public void forceResend()
	{
		lastSentAtNanos = 0L;
		lastSent = null;
	}

	/**
	 * Destination currently represented by Shortest Path, or {@code null}
	 * after a clear. The compass consumes this snapshot so both displays point
	 * at the same tile, including while that tile is inside the loaded scene.
	 */
	WorldPoint getActiveTarget()
	{
		return activeTarget;
	}

	/** Send a path target (client thread). Null clears. */
	public void setTarget(WorldPoint target)
	{
		setTarget(target, false);
	}

	/**
	 * @param movingTarget true only for a live NPC whose patrol movement should
	 *                     not trigger a full path recalculation every tick
	 */
	public void setTarget(WorldPoint target, boolean movingTarget)
	{
		if (target == null)
		{
			clear();
			return;
		}
		long now = System.nanoTime();
		boolean keepaliveDue = lastSent == null || now - lastSentAtNanos >= KEEPALIVE_NANOS;
		if (!keepaliveDue && lastSent != null && target.getPlane() == lastSent.getPlane())
		{
			int drift = Math.max(Math.abs(target.getX() - lastSent.getX()),
				Math.abs(target.getY() - lastSent.getY()));
			// Static objectives update on ANY tile change. Only a live NPC gets
			// the patrol deadband; otherwise two adjacent guide objectives could
			// incorrectly share a stale path forever.
			if (target.equals(lastSent) || (movingTarget && drift <= RESEND_DEADBAND_TILES))
			{
				return;
			}
		}
		try
		{
			Map<String, Object> data = new HashMap<>();
			data.put("target", target);
			messageSink.post(new PluginMessage(NAMESPACE, "path", data));
			// Commit dedup state only after the message was posted successfully.
			lastSent = target;
			lastSentAtNanos = now;
			activeTarget = target;
		}
		catch (Exception e)
		{
			// never let an integration hiccup touch the guide itself
			log.debug("Shortest Path hand-off failed", e);
		}
	}

	/** Remove the drawn path, if any was requested (client thread). */
	public void clear()
	{
		if (lastSent == null && activeTarget == null)
		{
			return;
		}
		try
		{
			messageSink.post(new PluginMessage(NAMESPACE, "clear"));
			lastSent = null;
			lastSentAtNanos = 0L;
			activeTarget = null;
		}
		catch (Exception e)
		{
			log.debug("Shortest Path clear failed", e);
		}
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

/**
 * Curated named destinations used when a guide step names a place rather than
 * an NPC. Entries live in a data file so new aliases or destinations can be
 * added without changing parser logic.
 */
@Singleton
final class PlaceDirectory
{
	private static final String RESOURCE = "place-locations-seed.json";
	private static final Pattern NON_WORD = Pattern.compile("[^a-z0-9']+");
	private static final Pattern SPACES = Pattern.compile("\\s+");
	private static final Pattern MOVEMENT_INTENT = Pattern.compile(
		"(?i)\\b(?:go|head|travel|teleport|run|walk|return|sail|enter|leave|"
			+ "climb|descend|make your way|take (?:the )?(?:boat|ship|portal|minecart|quetzal|canoe|charter)|"
			+ "minigame teleport|fairy ring|ardy cloak|ardougne cloak)\\b");
	private static final Pattern NON_MOVEMENT_LOCATION_CONTEXT = Pattern.compile(
		"(?i)\\b(?:do|visit|reach|bank|rebank|start|finish|complete|train|mine|fish|hunt|kill|"
			+ "buy|talk|at|in|inside|outside|near|from|to)(?:\\s+the)?\\s+$");
	/** A location mentioned only as an optional/future fallback is not the active destination. */
	private static final Pattern OPTIONAL_LOCATION_SUFFIX = Pattern.compile(
		"(?i)^\\s*(?:if\\s+(?:(?:you\\s+)?(?:need|want|wish)(?:\\s+to)?|needed|necessary|required)|"
			+ "when\\s+needed|later|eventually|at\\s+(?:your|a)\\s+convenience|"
			+ "optionally|optional)\\b");
	/** Same idea when the qualifier precedes the place: "optionally stop at Varrock". */
	private static final Pattern OPTIONAL_LOCATION_PREFIX = Pattern.compile(
		"(?i)(?:^|\\b)(?:optionally|optional|later|eventually|when\\s+needed|"
			+ "if\\s+(?:needed|necessary|required)|at\\s+(?:your|a)\\s+convenience)"
			+ "[\\s,:;()\\-]*(?:(?:stop|rebank|bank|visit|go|head|travel|teleport|return|"
			+ "use|take)(?:\\s+(?:at|in|to|the|a|an))?\\s*)?$");

	private final List<Place> places;

	@Inject
	PlaceDirectory(Gson gson)
	{
		List<Place> loaded = new ArrayList<>();
		try (InputStream in = PlaceDirectory.class.getResourceAsStream(RESOURCE))
		{
			if (in != null)
			{
				Entry[] entries = gson.fromJson(
					new InputStreamReader(in, StandardCharsets.UTF_8), Entry[].class);
				if (entries != null)
				{
					for (Entry entry : entries)
					{
						Place place = Place.from(entry);
						if (place != null)
						{
							loaded.add(place);
						}
					}
				}
			}
		}
		catch (Exception ignored)
		{
			// A missing or malformed optional seed must not prevent plugin startup.
		}
		places = Collections.unmodifiableList(loaded);
	}

	/**
	 * Returns the last explicitly named destination in a step. Choosing the
	 * final mention matches common guide wording such as "go to X, then Y";
	 * ties prefer the longer alias ("Varrock East Bank" over "Varrock").
	 */
	StepLocationHint find(String stepText)
	{
		String normalized = normalizeWords(stepText);
		String haystack = " " + normalized + " ";
		if (normalized.isEmpty())
		{
			return null;
		}
		// If a later travel verb names a destination the directory does not
		// know, an earlier known place is stale. Only accept a place mentioned
		// after the final movement instruction (or anywhere when there is none).
		int lastMovementEnd = lastMovementIntentEnd(normalized);
		List<AliasMatch> matches = new ArrayList<>();
		for (Place place : places)
		{
			for (String alias : place.aliases)
			{
				String needle = " " + alias + " ";
				int from = 0;
				while (from < haystack.length())
				{
					int index = haystack.indexOf(needle, from);
					if (index < 0)
					{
						break;
					}
					from = index + Math.max(1, needle.length() - 1);
					boolean exactWholeFragment = normalized.equals(alias);
					if ((lastMovementEnd >= 0 && index < lastMovementEnd)
						|| (lastMovementEnd < 0 && alias.indexOf(' ') < 0
							&& !exactWholeFragment
							&& !hasNonMovementLocationContext(normalized, index)))
					{
						continue;
					}
					matches.add(new AliasMatch(place, alias, index, index + needle.length()));
				}
			}
		}

		// Mark complete named-location spans whose following words make the
		// mention optional/future. Every overlapping shorter alias is suppressed
		// too: "Lumbridge Castle if needed" must not fall back to "Lumbridge".
		List<AliasMatch> optionalMatches = new ArrayList<>();
		for (AliasMatch match : matches)
		{
			int normalizedStart = Math.max(0, match.start - 1);
			int normalizedEnd = Math.min(normalized.length(), match.end - 1);
			String suffix = normalized.substring(normalizedEnd);
			String prefix = normalized.substring(Math.max(0, normalizedStart - 80), normalizedStart);
			boolean optionalSuffix = OPTIONAL_LOCATION_SUFFIX.matcher(suffix).find();
			if (optionalSuffix || OPTIONAL_LOCATION_PREFIX.matcher(prefix).find())
			{
				optionalMatches.add(match);
			}
		}

		Place bestPlace = null;
		int bestEnd = -1;
		int bestLength = -1;
		for (AliasMatch match : matches)
		{
			boolean optional = false;
			for (AliasMatch optionalMatch : optionalMatches)
			{
				if (match.start < optionalMatch.end && optionalMatch.start < match.end)
				{
					optional = true;
					break;
				}
			}
			if (optional)
			{
				continue;
			}
			if (match.end > bestEnd
				|| (match.end == bestEnd && match.alias.length() > bestLength))
			{
				bestPlace = match.place;
				bestEnd = match.end;
				bestLength = match.alias.length();
			}
		}
		return bestPlace == null ? null
			: new StepLocationHint(bestPlace.name, bestPlace.point, false, false, false,
				"place:" + normalizeWords(bestPlace.name).replace(' ', '-'),
				LocationSource.NAMED_PLACE, LocationConfidence.EXACT, 5, 2);
	}

	private static boolean hasNonMovementLocationContext(String normalized, int aliasStart)
	{
		int from = Math.max(0, aliasStart - 40);
		return NON_MOVEMENT_LOCATION_CONTEXT.matcher(normalized.substring(from, aliasStart)).find();
	}

	private static int lastMovementIntentEnd(String normalized)
	{
		java.util.regex.Matcher matcher = MOVEMENT_INTENT.matcher(normalized);
		int end = -1;
		while (matcher.find())
		{
			end = matcher.end();
		}
		return end;
	}

	static boolean hasMovementIntent(String stepText)
	{
		return stepText != null && MOVEMENT_INTENT.matcher(stepText).find();
	}

	static String normalizeWords(String value)
	{
		if (value == null)
		{
			return "";
		}
		String lower = value.toLowerCase(Locale.ROOT)
			.replace('\u2019', '\'')
			.replace('\u2018', '\'');
		return SPACES.matcher(NON_WORD.matcher(lower).replaceAll(" ")).replaceAll(" ").trim();
	}

	private static final class AliasMatch
	{
		private final Place place;
		private final String alias;
		private final int start;
		private final int end;

		private AliasMatch(Place place, String alias, int start, int end)
		{
			this.place = place;
			this.alias = alias;
			this.start = start;
			this.end = end;
		}
	}

	private static final class Place
	{
		private final String name;
		private final WorldPoint point;
		private final List<String> aliases;

		private Place(String name, WorldPoint point, List<String> aliases)
		{
			this.name = name;
			this.point = point;
			this.aliases = aliases;
		}

		private static Place from(Entry entry)
		{
			if (entry == null || entry.name == null || entry.name.trim().isEmpty()
				|| entry.x <= 0 || entry.y <= 0 || entry.plane < 0 || entry.plane > 3)
			{
				return null;
			}
			List<String> aliases = new ArrayList<>();
			addAlias(aliases, entry.name);
			if (entry.aliases != null)
			{
				for (String alias : entry.aliases)
				{
					addAlias(aliases, alias);
				}
			}
			return aliases.isEmpty() ? null : new Place(entry.name.trim(),
				new WorldPoint(entry.x, entry.y, entry.plane), Collections.unmodifiableList(aliases));
		}

		private static void addAlias(List<String> aliases, String value)
		{
			String alias = normalizeWords(value);
			// Very short aliases create accidental matches in ordinary prose.
			if (alias.length() >= 4 && !aliases.contains(alias))
			{
				aliases.add(alias);
			}
		}
	}

	private static final class Entry
	{
		private String name;
		private List<String> aliases;
		private int x;
		private int y;
		private int plane;
	}
}

package com.hcimguide;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;
import java.util.zip.GZIPInputStream;
import java.util.zip.GZIPOutputStream;

/**
 * Serializes progress (the set of completed step keys) to a compact,
 * clipboard-friendly text code and back: sorted keys joined by newlines,
 * gzipped, base64-encoded, with a versioned prefix so future formats can
 * be told apart. Pure Java - no plugin dependencies - so it is unit-testable
 * anywhere.
 */
public final class ProgressCodec
{
	static final String PREFIX = "HCIMGUIDE1:";

	/** Decoded payloads larger than this are rejected (a valid one is ~100KB max). */
	private static final int MAX_DECODED_BYTES = 4 * 1024 * 1024;
	/** Bound memory before Base64 decoding; normal progress codes are far smaller. */
	private static final int MAX_ENCODED_CHARS = 8 * 1024 * 1024;

	/** Key-count cap so a hostile shared code can't bloat RuneLite's config store. */
	private static final int MAX_KEYS = 50_000;
	/** Parsed step keys are compact hashes; this leaves ample forward-compatible room. */
	private static final int MAX_KEY_CHARS = 512;
	private static final java.util.regex.Pattern GUIDE_ID_PATTERN =
		java.util.regex.Pattern.compile("[a-z0-9-]{1,64}");

	private ProgressCodec()
	{
	}

	/** Decoded result: the keys plus the guide id the code was exported from (may be null for old codes). */
	public static class Decoded
	{
		public final Set<String> keys;
		public final String guideId;

		Decoded(Set<String> keys, String guideId)
		{
			this.keys = keys;
			this.guideId = guideId;
		}
	}

	public static String encode(Set<String> completedKeys, String guideId) throws IOException
	{
		if (completedKeys == null)
		{
			throw new IllegalArgumentException("Progress set is missing");
		}
		if (completedKeys.size() > MAX_KEYS)
		{
			throw new IllegalArgumentException("Progress has too many entries");
		}
		if (guideId != null && !guideId.isEmpty() && !GUIDE_ID_PATTERN.matcher(guideId).matches())
		{
			throw new IllegalArgumentException("Guide id is invalid");
		}
		StringBuilder sb = new StringBuilder();
		if (guideId != null && !guideId.isEmpty())
		{
			sb.append("#guide:").append(guideId).append('\n');
		}
		// sorted so identical progress always yields an identical code
		TreeSet<String> sorted = new TreeSet<>();
		for (String key : completedKeys)
		{
			validateKey(key);
			sorted.add(key);
		}
		sb.append(String.join("\n", sorted));
		byte[] payload = sb.toString().getBytes(StandardCharsets.UTF_8);
		if (payload.length > MAX_DECODED_BYTES)
		{
			throw new IllegalArgumentException("Progress is implausibly large");
		}
		ByteArrayOutputStream bos = new ByteArrayOutputStream();
		try (GZIPOutputStream gz = new GZIPOutputStream(bos))
		{
			gz.write(payload);
		}
		return PREFIX + Base64.getEncoder().encodeToString(bos.toByteArray());
	}

	/**
	 * @throws IllegalArgumentException when the text is not a valid progress code
	 */
	public static Decoded decode(String text)
	{
		if (text == null)
		{
			throw new IllegalArgumentException("Clipboard is empty");
		}
		if (text.length() > MAX_ENCODED_CHARS)
		{
			throw new IllegalArgumentException("Progress code is implausibly large");
		}
		String trimmed = text.trim();
		if (!trimmed.startsWith(PREFIX))
		{
			throw new IllegalArgumentException("Not a progress code (missing " + PREFIX + " prefix)");
		}
		try
		{
			byte[] compressed = Base64.getDecoder().decode(trimmed.substring(PREFIX.length()));
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			try (InputStream gz = new GZIPInputStream(new ByteArrayInputStream(compressed)))
			{
				byte[] buf = new byte[8192];
				int n;
				while ((n = gz.read(buf)) > 0)
				{
					out.write(buf, 0, n);
					if (out.size() > MAX_DECODED_BYTES)
					{
						throw new IllegalArgumentException("Progress code is implausibly large");
					}
				}
			}
			Set<String> keys = new HashSet<>();
			String guideId = null;
			for (String line : out.toString(StandardCharsets.UTF_8.name()).split("\n"))
			{
				if (line.isEmpty())
				{
					continue;
				}
				if (line.startsWith("#"))
				{
					// metadata lines; unknown ones are ignored for forward compatibility
					if (line.startsWith("#guide:"))
					{
						String candidate = line.substring("#guide:".length()).trim();
						if (!GUIDE_ID_PATTERN.matcher(candidate).matches())
						{
							throw new IllegalArgumentException("Progress code contains an invalid guide id");
						}
						guideId = candidate;
					}
					continue;
				}
				validateKey(line);
				keys.add(line);
				if (keys.size() > MAX_KEYS)
				{
					throw new IllegalArgumentException("Progress code has too many entries");
				}
			}
			return new Decoded(keys, guideId);
		}
		catch (IllegalArgumentException e)
		{
			throw e;
		}
		catch (Exception e)
		{
			throw new IllegalArgumentException("Progress code is corrupted: " + e.getMessage(), e);
		}
	}

	private static void validateKey(String key)
	{
		if (key == null || key.isEmpty() || key.length() > MAX_KEY_CHARS || key.charAt(0) == '#')
		{
			throw new IllegalArgumentException("Progress contains an invalid step key");
		}
		for (int i = 0; i < key.length(); i++)
		{
			if (Character.isISOControl(key.charAt(i)))
			{
				throw new IllegalArgumentException("Progress contains an invalid step key");
			}
		}
	}
}

package com.hcimguide;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/** Compatibility migrations for progress keys produced by older parsers. */
final class ProgressKeyMigration
{
	private ProgressKeyMigration()
	{
	}

	/**
	 * Earlier parser versions placed every step in an episode-wide "Notes"
	 * section when the wiki's visual Bank labels were not recognized. Once the
	 * labels parse correctly, section IDs become E#.B# and therefore stable step
	 * keys change. Replace matching legacy Notes keys in guide order.
	 *
	 * KNOWN BOUNDED EDGE: legacy occurrence indices were assigned in document
	 * order; this replay iterates bank-grouped order. They differ only when a
	 * repeated bank marker CONTINUES an earlier section AND the identical step
	 * text also appears in an intervening bank - in that narrow case one
	 * duplicate-text checkbox can land on the wrong twin. Every other key
	 * migrates exactly; the user re-ticks at most one step.
	 *
	 * @return true when the supplied set was changed
	 */
	static boolean migrateLegacyNotes(Guide guide, Set<String> completedSteps)
	{
		if (guide == null || completedSteps == null || guide.numberedBanks() == 0)
		{
			return false;
		}

		boolean migrated = false;
		Map<String, Integer> occurrence = new HashMap<>();
		for (GuideEpisode episode : guide.getEpisodes())
		{
			String notesId = "E" + episode.getNumber() + "-notes";
			for (GuideBank bank : episode.getBanks())
			{
				for (GuideStep step : bank.getSteps())
				{
					String occKey = notesId + " " + step.getText();
					int occ = occurrence.merge(occKey, 1, Integer::sum) - 1;
					String legacyKey = notesId + "#"
						+ Integer.toHexString(step.getText().hashCode()) + "#" + occ;
					if (!legacyKey.equals(step.getKey()) && completedSteps.remove(legacyKey))
					{
						completedSteps.add(step.getKey());
						migrated = true;
					}
				}
			}
		}
		return migrated;
	}

	/**
	 * Replays progress recorded under keys a parser used to produce (the guide
	 * carries an explicit old-key -&gt; new-key map, e.g. after the JSON parser's
	 * run-joining fix changed step texts). Old keys are consumed so the store
	 * stays clean.
	 *
	 * Two safety properties: (1) a legacy key that COLLIDES with some real
	 * step's current key is never touched - genuine new-format progress always
	 * wins over a migration guess; (2) the replay is two-phase against a
	 * snapshot, so chained same-hash mappings (#2-&gt;#1, #1-&gt;#0) can't consume
	 * each other's freshly-migrated keys regardless of map iteration order.
	 *
	 * @return true when the supplied set was changed
	 */
	static boolean migrateLegacyKeys(Guide guide, Set<String> completedSteps)
	{
		if (guide == null || completedSteps == null || guide.getLegacyStepKeys().isEmpty())
		{
			return false;
		}
		Set<String> currentKeys = new java.util.HashSet<>();
		for (GuideEpisode ep : guide.getEpisodes())
		{
			for (GuideBank bank : ep.getBanks())
			{
				for (GuideStep step : bank.getSteps())
				{
					currentKeys.add(step.getKey());
				}
			}
		}
		Set<String> snapshot = new java.util.HashSet<>(completedSteps);
		Set<String> toRemove = new java.util.HashSet<>();
		Set<String> toAdd = new java.util.HashSet<>();
		for (Map.Entry<String, String> e : guide.getLegacyStepKeys().entrySet())
		{
			if (currentKeys.contains(e.getKey()))
			{
				continue; // a real step owns this key - never steal it
			}
			if (snapshot.contains(e.getKey()))
			{
				toRemove.add(e.getKey());
				toAdd.add(e.getValue());
			}
		}
		boolean changed = completedSteps.removeAll(toRemove);
		changed |= completedSteps.addAll(toAdd);
		return changed;
	}

	/**
	 * Replays progress recorded under keys of steps a parser now SPLITS into
	 * several smaller steps (the guide carries an explicit
	 * old-key -&gt; all-child-keys map): a completed paragraph marks every
	 * split child complete. Old keys are consumed so the store stays clean.
	 *
	 * Same safety properties as {@link #migrateLegacyKeys}: an old key that
	 * collides with a real step's current key is never touched, and the replay
	 * runs two-phase against a snapshot. Run migrateLegacyKeys FIRST - oldest
	 * generation keys chain through the split map's parent keys.
	 *
	 * @return true when the supplied set was changed
	 */
	static boolean migrateSplitKeys(Guide guide, Set<String> progress)
	{
		if (guide == null || progress == null || guide.getLegacySplitKeys().isEmpty())
		{
			return false;
		}
		Set<String> currentKeys = new java.util.HashSet<>();
		for (GuideEpisode ep : guide.getEpisodes())
		{
			for (GuideBank bank : ep.getBanks())
			{
				for (GuideStep step : bank.getSteps())
				{
					currentKeys.add(step.getKey());
				}
			}
		}
		Set<String> snapshot = new java.util.HashSet<>(progress);
		Set<String> toRemove = new java.util.HashSet<>();
		Set<String> toAdd = new java.util.HashSet<>();
		for (Map.Entry<String, java.util.List<String>> e : guide.getLegacySplitKeys().entrySet())
		{
			if (currentKeys.contains(e.getKey()))
			{
				continue; // a real step owns this key - never steal it
			}
			if (snapshot.contains(e.getKey()))
			{
				toRemove.add(e.getKey());
				toAdd.addAll(e.getValue());
			}
		}
		// COLLISION PASS: a paragraph whose whole text equals another
		// paragraph's leading sentence has an old key that a real split child
		// now owns (the real BRUHsailer guide contains one such duplicate).
		// The live key is never consumed, but when the snapshot ALSO holds a
		// parent paragraph key whose children include the collided key, the
		// tick is provably old-format progress, so the colliding entry's
		// children are added too (the live key stays ticked - it is the other
		// paragraph's first child, which that parent's entry also marks).
		for (Map.Entry<String, java.util.List<String>> e : guide.getLegacySplitKeys().entrySet())
		{
			if (!currentKeys.contains(e.getKey()) || !snapshot.contains(e.getKey()))
			{
				continue;
			}
			for (Map.Entry<String, java.util.List<String>> p : guide.getLegacySplitKeys().entrySet())
			{
				if (!p.getKey().equals(e.getKey()) && !currentKeys.contains(p.getKey())
					&& snapshot.contains(p.getKey()) && p.getValue().contains(e.getKey()))
				{
					toAdd.addAll(e.getValue());
					break;
				}
			}
		}
		boolean changed = progress.removeAll(toRemove);
		changed |= progress.addAll(toAdd);
		return changed;
	}
}

package com.hcimguide;

import java.util.List;

/**
 * Picks the fastest way to the current objective: walk, or one of the
 * teleports the player actually owns the items for. Distances are
 * straight-line (Chebyshev) tile estimates - this is a SUGGESTION engine,
 * not a pathfinder; the optional Shortest Path plugin hand-off draws the
 * real tile path. Pure Java (ints only) so it is unit-testable offline.
 */
final class RouteSuggester
{
	/** Fixed cost (in tile-equivalents) of casting/rubbing a carried teleport. */
	static final int CARRIED_COST = 25;

	/** Extra cost when the items are only in the bank (detour to withdraw). */
	static final int BANKED_COST = 90;

	/**
	 * A teleport must beat plain walking by at least this many tiles before
	 * it's suggested - nobody wants "teleport" spam for a 40-tile stroll.
	 */
	static final int MIN_SAVING = 30;

	/** A teleport option plus where its items currently are. */
	static class Candidate
	{
		final TeleportOption option;
		final boolean banked;

		Candidate(TeleportOption option, boolean banked)
		{
			this.option = option;
			this.banked = banked;
		}
	}

	/** The winning option, or null when walking is (close enough to) fastest. */
	static class Suggestion
	{
		final TeleportOption option;
		final boolean banked;
		final int cost;
		final int walkCost;

		Suggestion(TeleportOption option, boolean banked, int cost, int walkCost)
		{
			this.option = option;
			this.banked = banked;
			this.cost = cost;
			this.walkCost = walkCost;
		}
	}

	/**
	 * @param px,py player position; tx,ty objective position (same plane
	 *              assumed - callers pass surface coordinates)
	 */
	static Suggestion best(int px, int py, int tx, int ty, List<Candidate> candidates)
	{
		final int walk = dist(px, py, tx, ty);
		Suggestion best = null;
		for (Candidate c : candidates)
		{
			if (c == null || c.option == null)
			{
				continue;
			}
			int cost = dist(c.option.getX(), c.option.getY(), tx, ty)
				+ (c.banked ? BANKED_COST : CARRIED_COST);
			if (cost <= walk - MIN_SAVING && (best == null || cost < best.cost))
			{
				best = new Suggestion(c.option, c.banked, cost, walk);
			}
		}
		return best;
	}

	/** Chebyshev distance - OSRS movement is 8-directional. */
	static int dist(int ax, int ay, int bx, int by)
	{
		return Math.max(Math.abs(ax - bx), Math.abs(ay - by));
	}

	private RouteSuggester()
	{
	}
}

package com.hcimguide;

import java.util.List;
import net.runelite.api.Quest;
import net.runelite.api.Skill;

/**
 * A game-state condition that can auto-complete a step.
 */
public class StepCondition
{
	public enum Type
	{
		QUEST_STARTED,
		QUEST_FINISHED,
		SKILL_LEVEL,
		ITEMS_IN_INVENTORY
	}

	private final Type type;
	private final Quest quest;
	private final Skill skill;
	private final int level;
	private final List<ItemReq> items;

	private StepCondition(Type type, Quest quest, Skill skill, int level, List<ItemReq> items)
	{
		this.type = type;
		this.quest = quest;
		this.skill = skill;
		this.level = level;
		this.items = items;
	}

	static StepCondition questStarted(Quest quest)
	{
		return new StepCondition(Type.QUEST_STARTED, quest, null, 0, null);
	}

	static StepCondition questFinished(Quest quest)
	{
		return new StepCondition(Type.QUEST_FINISHED, quest, null, 0, null);
	}

	static StepCondition skillLevel(Skill skill, int level)
	{
		return new StepCondition(Type.SKILL_LEVEL, null, skill, level, null);
	}

	static StepCondition itemsInInventory(List<ItemReq> items)
	{
		return new StepCondition(Type.ITEMS_IN_INVENTORY, null, null, 0, items);
	}

	public Type getType()
	{
		return type;
	}

	public Quest getQuest()
	{
		return quest;
	}

	public Skill getSkill()
	{
		return skill;
	}

	public int getLevel()
	{
		return level;
	}

	public List<ItemReq> getItems()
	{
		return items;
	}

	public String describe()
	{
		switch (type)
		{
			case QUEST_STARTED:
				return "Auto-completes when \"" + quest.getName() + "\" is started";
			case QUEST_FINISHED:
				return "Auto-completes when \"" + quest.getName() + "\" is finished";
			case SKILL_LEVEL:
				return "Auto-completes at " + level + " " + skill.getName();
			case ITEMS_IN_INVENTORY:
				return "Auto-completes when all listed items are in your inventory";
			default:
				return "";
		}
	}
}

package com.hcimguide;

/** One runtime-only phase inside a persisted source guide row. */
final class StepExecutionPhase
{
	private final String id;
	private final String text;
	private final StepPhaseParser.Kind kind;
	private final StepLocationPlan locationPlan;
	private final String entityTarget;
	private final StepCondition condition;

	StepExecutionPhase(String id, String text, StepPhaseParser.Kind kind,
		StepLocationPlan locationPlan, String entityTarget, StepCondition condition)
	{
		this.id = id;
		this.text = text;
		this.kind = kind;
		this.locationPlan = locationPlan;
		this.entityTarget = entityTarget;
		this.condition = condition;
	}

	String getId()
	{
		return id;
	}

	String getText()
	{
		return text;
	}

	StepPhaseParser.Kind getKind()
	{
		return kind;
	}

	StepLocationPlan getLocationPlan()
	{
		return locationPlan;
	}

	String getEntityTarget()
	{
		return entityTarget;
	}

	StepCondition getCondition()
	{
