	{
		return kind == StepPhaseParser.Kind.TRAVEL;
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable runtime execution plan for one original checklist row. */
final class StepExecutionPlan
{
	private final String parentStepKey;
	private final StepPhaseParser.Mode mode;
	private final List<StepExecutionPhase> phases;

	StepExecutionPlan(String parentStepKey, StepPhaseParser.Mode mode,
		List<StepExecutionPhase> phases)
	{
		this.parentStepKey = parentStepKey;
		this.mode = mode;
		this.phases = Collections.unmodifiableList(new ArrayList<>(phases));
	}

	String getParentStepKey()
	{
		return parentStepKey;
	}

	StepPhaseParser.Mode getMode()
	{
		return mode;
	}

	List<StepExecutionPhase> getPhases()
	{
		return phases;
	}

	int size()
	{
		return phases.size();
	}

	StepExecutionPhase get(int index)
	{
		if (phases.isEmpty())
		{
			return null;
		}
		return phases.get(Math.max(0, Math.min(index, phases.size() - 1)));
	}

	int indexOfId(String id)
	{
		if (id == null)
		{
			return -1;
		}
		for (int i = 0; i < phases.size(); i++)
		{
			if (id.equals(phases.get(i).getId()))
			{
				return i;
			}
		}
		return -1;
	}

	boolean isVirtualized()
	{
		return phases.size() > 1;
	}
}

package com.hcimguide;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;

/** Builds phase plans without inserting generated rows into guide banks. */
final class StepExecutionPlanner
{
	private static final Pattern ITEM_SUFFIX = Pattern.compile("(?is)\\(\\s*items?\\s*:\\s*.*?\\)\\s*$");

	private StepExecutionPlanner()
	{
	}

	static Map<String, StepExecutionPlan> buildPlans(Guide guide,
		PlaceDirectory places, TransportResolver transports,
		Function<String, WorldPoint> locationLookup,
		Map<String, StepLocationPlan> parentPlans)
	{
		if (guide == null || places == null || transports == null || locationLookup == null)
		{
			return Collections.emptyMap();
		}
		Map<String, StepExecutionPlan> out = new HashMap<>();
		for (GuideEpisode episode : guide.getEpisodes())
		{
			for (GuideBank bank : episode.getBanks())
			{
				for (GuideStep step : bank.getSteps())
				{
					StepLocationPlan parent = parentPlans == null ? null : parentPlans.get(step.getKey());
					StepExecutionPlan plan = build(step, places, transports, locationLookup, parent);
					if (plan != null)
					{
						out.put(step.getKey(), plan);
					}
				}
			}
		}
		return Collections.unmodifiableMap(out);
	}

	static StepExecutionPlan build(GuideStep step, PlaceDirectory places,
		TransportResolver transports, Function<String, WorldPoint> locationLookup)
	{
		return build(step, places, transports, locationLookup, null);
	}

	static StepExecutionPlan build(GuideStep step, PlaceDirectory places,
		TransportResolver transports, Function<String, WorldPoint> locationLookup,
		StepLocationPlan parentPlan)
	{
		if (step == null)
		{
			return null;
		}
		StepPhaseParser.Parsed parsed = StepPhaseParser.parse(step.getText());
		if (parsed.getMode() == StepPhaseParser.Mode.MANUAL)
		{
			return null;
		}
		// A guidance-only plan exists to TARGET, never to complete. The shape
		// gates below (no compound, travel-first, task-last) exist to make
		// arrival completion safe; they are not needed when completion is
		// impossible by construction. Without this exemption GUIDANCE_ONLY was
		// unreachable - the parser produced it and the planner rejected exactly
		// those shapes, so no plan was ever built.
		final boolean guidanceOnly =
			parsed.getMode() == StepPhaseParser.Mode.GUIDANCE_ONLY;
		int travelClauses = 0;
		for (StepPhaseParser.Clause clause : parsed.getClauses())
		{
			if (clause.getKind() == StepPhaseParser.Kind.TRAVEL)
			{
				travelClauses++;
			}
		}

		List<StepExecutionPhase> phases = new ArrayList<>();
		Map<String, Integer> idOccurrences = new HashMap<>();
		StepCondition parentCondition = ConditionParser.parse(step.getText());
		boolean parentConditionRepresented = parentCondition == null;
		if (parsed.hasItemPreparation())
		{
			StepCondition condition = ConditionParser.parse(step.getText());
			if (condition == null || condition.getType() != StepCondition.Type.ITEMS_IN_INVENTORY)
			{
				return null; // explicit prep text that cannot be proved: fail closed
			}
			phases.add(new StepExecutionPhase(uniqueId(step.getKey(), "prep", "items", idOccurrences),
				"Prepare listed items", StepPhaseParser.Kind.PREPARATION,
				null, null, condition));
			parentConditionRepresented |= conditionsEquivalent(parentCondition, condition);
		}

		for (StepPhaseParser.Clause clause : parsed.getClauses())
		{
			if (clause.getKind() == StepPhaseParser.Kind.NOTE)
			{
				continue;
			}
			if (clause.getKind() == StepPhaseParser.Kind.COMPOUND && !guidanceOnly)
			{
				return null;
			}
			String target = TargetExtractor.extract(clause.getText());
			StepCondition condition = ConditionParser.parse(clause.getText());
			parentConditionRepresented |= conditionsEquivalent(parentCondition, condition);
			StepLocationPlan location = StepLocationPlanner.buildPlanForText(
				step.getKey(), clause.getText(), target, places, transports, locationLookup);
			if (clause.getKind() == StepPhaseParser.Kind.TRAVEL)
			{
				if (!usableLocation(location) && travelClauses == 1
					&& trustedParentLocation(parentPlan))
				{
					// Grammar such as "Teleport & bank at Camelot" puts the
					// destination in the following task clause. The legacy full-row
					// planner can still prove one direct destination; with exactly one
					// travel phase it is safe to lend that plan to the travel phase.
					location = parentPlan;
				}
				if (!usableLocation(location))
				{
					return null; // a travel phase without a proven destination is not executable
				}
			}
			phases.add(new StepExecutionPhase(
				uniqueId(step.getKey(), clause.getKind().name().toLowerCase(),
					clause.getText(), idOccurrences),
				clause.getText(), clause.getKind(), location, target, condition));
		}

		if (phases.isEmpty() || !parentConditionRepresented)
		{
			// The legacy row has a game-state condition that no generated phase owns.
			// Virtualizing it would hide that condition from activeStepCondition(), so
			// leave the parent on the proven legacy path instead.
			return null;
		}
		// Do not create a phase machine that starts on an unverifiable manual task.
		int firstNonPrep = 0;
		while (firstNonPrep < phases.size()
			&& phases.get(firstNonPrep).getKind() == StepPhaseParser.Kind.PREPARATION)
		{
			firstNonPrep++;
		}
		if (!guidanceOnly
			&& (firstNonPrep >= phases.size() || !phases.get(firstNonPrep).isTravel()))
		{
			return null;
		}
		if (guidanceOnly && phases.isEmpty())
		{
			return null;
		}
		// A task may only be the final phase. Otherwise there is no safe automatic
		// signal for moving past it to later travel.
		if (!guidanceOnly)
		{
			for (int i = firstNonPrep; i + 1 < phases.size(); i++)
			{
				if (phases.get(i).getKind() == StepPhaseParser.Kind.TASK)
				{
					return null;
				}
			}
		}
		return new StepExecutionPlan(step.getKey(), parsed.getMode(), phases);
	}

	private static boolean usableLocation(StepLocationPlan plan)
	{
		return plan != null && plan.hasWaypoints()
			&& (plan.getReason() == LocationResolutionReason.RESOLVED
				|| plan.getReason() == LocationResolutionReason.MULTIPLE_DESTINATIONS);
	}

	private static boolean trustedParentLocation(StepLocationPlan plan)
	{
		if (!usableLocation(plan))
		{
			return false;
		}
		StepLocationHint last = plan.get(plan.size() - 1);
		if (last == null || last.isInferred())
		{
			return false;
		}
		LocationConfidence confidence = last.getConfidence();
		return confidence == LocationConfidence.EXACT
			|| confidence == LocationConfidence.HIGH
			|| confidence == LocationConfidence.MANUAL;
	}

	private static boolean conditionsEquivalent(StepCondition left, StepCondition right)
	{
		if (left == right)
		{
			return true;
		}
		if (left == null || right == null || left.getType() != right.getType())
		{
			return false;
		}
		switch (left.getType())
		{
			case QUEST_STARTED:
			case QUEST_FINISHED:
				return left.getQuest() == right.getQuest();
			case SKILL_LEVEL:
				return left.getSkill() == right.getSkill() && left.getLevel() == right.getLevel();
			case ITEMS_IN_INVENTORY:
				return itemRequirementsEquivalent(left.getItems(), right.getItems());
			default:
				return false;
		}
	}

	private static boolean itemRequirementsEquivalent(List<ItemReq> left, List<ItemReq> right)
	{
		if (left == right)
		{
			return true;
		}
		if (left == null || right == null || left.size() != right.size())
		{
			return false;
		}
		for (int i = 0; i < left.size(); i++)
		{
			ItemReq a = left.get(i);
			ItemReq b = right.get(i);
			if (a.getQuantity() != b.getQuantity()
				|| a.getCompletionQuantity() != b.getCompletionQuantity()
				|| a.isInventoryFill() != b.isInventoryFill()
				|| a.isAlternativeGroup() != b.isAlternativeGroup()
				|| a.isCategoryRequirement() != b.isCategoryRequirement()
				|| !Names.normalize(a.getName()).equals(Names.normalize(b.getName()))
				|| !a.getAlternatives().equals(b.getAlternatives())
				|| a.getCategory() != b.getCategory())
			{
				return false;
			}
		}
		return true;
	}

	private static String uniqueId(String parentKey, String kind, String text,
		Map<String, Integer> occurrences)
	{
		String base = id(parentKey, kind, text);
		int occurrence = occurrences.merge(base, 1, Integer::sum);
		return occurrence == 1 ? base : base + ":" + occurrence;
	}

	private static String id(String parentKey, String kind, String text)
	{
		String normalized = Names.normalize(ITEM_SUFFIX.matcher(text == null ? "" : text)
			.replaceAll(""));
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256")
				.digest(normalized.getBytes(StandardCharsets.UTF_8));
			StringBuilder hash = new StringBuilder();
			for (int i = 0; i < 6; i++)
			{
				hash.append(String.format("%02x", digest[i]));
			}
			return parentKey + "@" + kind + ":" + hash;
		}
		catch (Exception ignored)
		{
			return parentKey + "@" + kind + ":" + Integer.toHexString(normalized.hashCode());
		}
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Exact item lists for individual guide steps whose wording the general parser
 * cannot resolve correctly.
 *
 * <p>Keyed on the NORMALIZED step text rather than a bank number, because bank
 * numbers shift whenever a bank is inserted earlier in the guide while the
 * sentence itself stays put. The bank number in each comment is for auditing
 * only. Normalization strips wiki markup, case, and punctuation, so a cosmetic
 * wiki edit does not silently drop the override.</p>
 *
 * <p>An override that stops matching degrades to normal parsing - never to a
 * wrong item - so a stale entry costs accuracy, not correctness. Keep this
 * table small: anything expressible as a general rule belongs in
 * {@link ItemListParser} or {@link ItemAliases} instead.</p>
 */
final class StepItemOverrides
{
	private static final Map<String, List<ItemReq>> OVERRIDES = new HashMap<>();

	private static void o(String stepText, ItemReq... items)
	{
		OVERRIDES.put(key(stepText), Collections.unmodifiableList(Arrays.asList(items)));
	}

	private static ItemReq q(String name, int qty)
	{
		return new ItemReq(name, qty);
	}

	private static ItemReq label(String name, int qty, String display)
	{
		return new ItemReq(name, qty, display);
	}

	private static ItemReq any(String displayName, int minimumTotal, String quantityLabel, String... options)
	{
		return ItemReq.anyOf(displayName, minimumTotal, quantityLabel, options);
	}

	private static ItemReq cookedFood(int minimumTotal, String label)
	{
		return ItemReq.category(ItemCategory.COOKED_FOOD, minimumTotal, label);
	}


	static
	{
		// ---- Bank 36: rune shop purchase. Comma-grouped thousands plus a "100+"
		// open quantity; the general parser now handles both, but the trailing

		// ---- Bank 36: the soul rune purchase is its own step
		o("Buy 1 Soul Rune [Legend' Quest]", q("Soul rune", 1));

		// ---- Bank 30-ish: moulds sold as bare nouns needing the "mould" suffix,
		// followed by two non-mould items after the ampersand
		o("Buy moulds: Ring, Amulet, 2x Necklace, Bracelet, Sickle, Tiara, 3x Needle & 50 Thread (from [[Rommik]] in Rimmington)",
			q("Ring mould", 1),
			q("Amulet mould", 1),
			q("Necklace mould", 2),
			q("Bracelet mould", 1),
			q("Sickle mould", 1),
			q("Tiara mould", 1),
			q("Needle", 3),
			q("Thread", 50));

		// ---- Research notes and the pickaxe are alternatives, not a set: the
		// slash separates a needed item from an explicit negation
		o("Withdraw: Coins, Research Notes (2 inventory Slots) / Bronze pickaxe not needed",
			q("Coins", 1),
			q("Research notes", 1));


		// ---- armour sets named as a single phrase (all names verified against
		// the live item list; "Crystal chestplate"/"Initiate helmet" do NOT exist)
		o("Withdraw: Rogue Outfit, Few food, Seedbox, Garden Pie",
			q("Rogue mask", 1), q("Rogue top", 1), q("Rogue trousers", 1),
			q("Rogue gloves", 1), q("Rogue boots", 1),
			cookedFood(1, "few"),
			q("Seed box", 1), q("Garden pie", 1));

		// ---- spell rune sets, each taken from the spell's own wiki infobox
		o("Crumble undead runes", q("Air rune", 2), q("Earth rune", 2), q("Chaos rune", 1));
		o("Humidify Runes", q("Fire rune", 1), q("Water rune", 3), q("Astral rune", 1));
		o("Cure Me Spells", q("Astral rune", 2), q("Cosmic rune", 2), q("Law rune", 1));
		o("Curse Runes", q("Earth rune", 3), q("Water rune", 2), q("Body rune", 1));
		o("Teleport Runes to House", q("Air rune", 1), q("Earth rune", 1), q("Law rune", 1));
		o("Varrock Teleport Runes", q("Air rune", 3), q("Fire rune", 1), q("Law rune", 1));

		// case 3 (guide line 427)
		o("Loot & Bank 139 [[Plank]]s (1x 27 Inventory & 4x 28)",
			q("Plank", 139));
		// case 56 (guide line 163)
		o("Collect the Logs & fletch 2,100 Arrowshafts (hop between 2 worlds)",
			q("Arrow shaft", 2100));
		// case 57 (guide line 164)
		o("Collect 11 Logs & make 10 into Planks. Make the 3 Waxwood Planks.",
			q("Logs", 11),
			q("Plank", 10));
		// case 58 (guide line 362)
		o("Buy atleast 1x Bronze Bars [Mournings End Pt 2]",
			q("Bronze bar", 1));
		// case 61 (guide line 847)
		o("Buy your 100 Soda Ash/Sand if you haven't yet",
			q("Soda ash", 100),
			q("Bucket of sand", 100));
		// case 65 (guide line 975)
		o("Buy at least 4x Jute seeds, 1x Marigold seeds, 6x Onion seeds, 6x Cabbage seeds for [Kandarin Easy Diary and Garden of Tranquility]",
			q("Jute seed", 4),
			q("Marigold seed", 1),
			q("Onion seed", 6),
			q("Cabbage seed", 6));
		// case 68 (guide line 1224)
		o("Take out your supercompost from the [[Tool Leprechaun]] if you've stored it there",
			q("Supercompost", 1));
		// case 69 (guide line 1327)
		o("Buy Bronze, Iron, and Steel Knives before & after each completion [Temple of Ikov]",
			q("Bronze knife", 1),
			q("Iron knife", 1),
			q("Steel knife", 1));
		// case 70 (guide line 1328)
		o("Buy 25 more Lockpicks after you get the outfit",
			q("Lockpick", 25));
		// case 76 (guide line 2189)
		o("Withdraw: Coins, Dueling Ring, a knife, log or axe, ardy cloak, dramen staff.",
			q("Coins", 1),
			q("Ring of dueling(8)", 1),
			q("Knife", 1),
			any("Log or axe", 1, null,
				"Logs", "Bronze axe", "Iron axe", "Steel axe", "Black axe",
				"Mithril axe", "Adamant axe", "Rune axe", "Dragon axe"),
			q("Ardougne cloak 1", 1),
			q("Dramen staff", 1));
		// case 80 (guide line 3582)
		o("Withdraw a Chisel & Uncut gems from Gauntlet.",
			q("Chisel", 1),
			any("Uncut gems", 1, "all",
				"Uncut sapphire", "Uncut emerald", "Uncut ruby",
				"Uncut diamond", "Uncut dragonstone"));
		// case 81 (guide line 3642)
		o("Withdraw: Bow of Faerdhinen & Crystal Armour, Seal of Passage, 3 lots of 7 random cooked food",
			q("Bow of Faerdhinen", 1),
			q("Crystal helm", 1),
			q("Crystal body", 1),
			q("Crystal legs", 1),
			q("Seal of Passage", 1),
			cookedFood(21, "3×7"));

		// Guide wording, not a parser fault: "Raw" is written once and is meant to
		// carry across the whole list. Nothing in the sentence marks the later
		// items as raw, so only a per-step override can express the intent.
		o("Buy Raw Sea Bass, Swordfish, 3x Cod & 15 Sardines while here for your Kitten",
			q("Raw bass", 1),
			q("Raw swordfish", 1),
			q("Raw cod", 3),
			q("Raw sardine", 15));

		// Guide punctuation, not a parser fault: "6 Clay Hammer" is a missing
		// comma between two separate items.
		o("Withdraw: Teleport Runes, Orange Dye, Blue Dye, Spicy Maggots, Charcoal, Dyed Orange, Soggy Bread, 2 Iron Ore, Blurite Ore, 4x Copper Ore, 6 Clay Hammer & antique Lamp (26 Inventory Slots)",
			q("Law rune", 1), q("Orange dye", 1), q("Blue dye", 1),
			q("Spicy maggots", 1), q("Charcoal", 1), q("Soggy bread", 1),
			q("Iron ore", 2), q("Blurite ore", 1), q("Copper ore", 4),
			q("Clay", 6), q("Hammer", 1), q("Antique lamp", 1));

		// "If 56/57/58 Magic" is a level condition, not an item. The bomb is
		// carried regardless.
		o("Withdraw: Teleport Runes, Coins, Death Runes, Antipoison, Super Antipoison, Scrying Orb If 56/57/58 Magic; Wizard Mind Bomb, (9/10 Inventory Slots) + Food",
			q("Law rune", 1), q("Coins", 1), q("Death rune", 1),
			q("Antipoison(4)", 1), q("Superantipoison(4)", 1),
			q("Scrying orb", 1), q("Wizard\u0027s mind bomb", 1));

        // Trailing noun written once and meant to carry backwards. Handled as
        // overrides rather than a general rule: "Rune Axe, Guam, Pestle &
        // Mortar, 15 Swamp Tar" has the same shape but Guam is a herb, not
        // "Guam Tar", so a blanket rule would corrupt it.
		o("Buy 100 mind, 100 air, 50 water, 50 earth and 20 fire runes (no rune packs).",
			q("Mind rune", 100), q("Air rune", 100), q("Water rune", 50),
			q("Earth rune", 50), q("Fire rune", 20));

		// "Buy Black Full Helmet & Plate legs": the colour is written once and
		// applies to both pieces. Nothing in the sentence marks the second.
		o("Buy Black Full Helmet & Plate legs [Heroes Quest/Kings Ransom]",
			q("Black full helm", 1), q("Black platelegs", 1));

		// Mastering Mixology: "goggles" and "Amulet" name the two Mixology
		// rewards, not generic equipment.
		o("Buy the goggles/Amulet if you haven\u2019t already.",
			q("Prescription goggles", 1), q("Alchemist\u0027s amulet", 1));

		// "Teleport Runes to House, Falador, Varrock, Ardougne" is ONE phrase
		// naming four destinations; the destinations were being read as separate
		// items and "Ardougne" was picked up as a diary flag.
		o("Withdraw: Coins, Teleport Runes to House, Falador, Varrock, Ardougne, Nature Runes, Noted Rune from Corrupted Gauntlet, 4x Steel Bars, Plank Sack, Inventory of Teak Planks",
			q("Coins", 1),
			q("Law rune", 4),
			q("Air rune", 12),
			q("Earth rune", 1),
			q("Fire rune", 1),
			q("Water rune", 1),
			q("Nature rune", 1),
			q("Noted Rune from Corrupted Gauntlet", 1),
			q("Steel bar", 4),
			q("Plank sack", 1),
			q("Teak plank", 26));

		// ---- two distinct pickups in one line; "when getting" hides the second
		o("Take 2x Logs when getting the rat tail",
			q("Logs", 2),
			q("Rat's tail", 1));
	}

	/** Normalized lookup key: wiki markup stripped, lowercase alphanumeric. */
	static String key(String stepText)
	{
		if (stepText == null)
		{
			return "";
		}
		String s = stepText;
		int link;
		while ((link = s.indexOf("[[")) >= 0)
		{
			int close = s.indexOf("]]", link);
			if (close < 0)
			{
				break;
			}
			String inner = s.substring(link + 2, close);
			int pipe = inner.lastIndexOf('|');
			s = s.substring(0, link) + (pipe >= 0 ? inner.substring(pipe + 1) : inner)
				+ s.substring(close + 2);
		}
		return Names.normalize(s);
	}

	/**
	 * @return a defensive copy of the override list, or null when this step has
	 *     none and normal parsing should run
	 */
	static List<ItemReq> forStep(String stepText)
	{
		List<ItemReq> hit = OVERRIDES.get(key(stepText));
		return hit == null ? null : new ArrayList<>(hit);
	}

	private StepItemOverrides()
	{
	}
}

package com.hcimguide;

import java.util.List;

/**
 * One authoritative projection of the item requirements shown for a guide step.
 *
 * <p>Condition-backed withdraw/gather steps use their parsed condition items.
 * Display-only JSON guide suffixes use the explicit {@code (Items: ...)} list.
 * Keeping this rule in one place prevents the panel, preload, and audit paths
 * from silently inspecting different requirements.</p>
 */
final class StepItemRequirements
{
	private StepItemRequirements()
	{
	}

	static List<ItemReq> displayFor(GuideStep step)
	{
		if (step == null)
		{
			return null;
		}
		StepCondition condition = ConditionParser.parse(step.getText());
		return displayFor(step.getText(), condition);
	}

	static List<ItemReq> displayFor(String text, StepCondition condition)
	{
		if (condition != null
			&& condition.getType() == StepCondition.Type.ITEMS_IN_INVENTORY)
		{
			return condition.getItems();
		}
		return ItemListParser.parseItemsSuffix(text);
	}
}

package com.hcimguide;

import java.util.Locale;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;

/** One destination/waypoint for a guide step. */
final class StepLocationHint
{
	// precompiled per the convention documented in Names: identity generation
	// runs once per hint, and every plan rebuild constructs many hints
	private static final Pattern NON_SLUG = Pattern.compile("[^a-z0-9]+");
	private static final Pattern SLUG_EDGE_DASH = Pattern.compile("(?:^-+|-+$)");

	private final String label;
	private final WorldPoint point;
	private final boolean inferred;
	private final boolean preferredOverEntity;
	private final boolean transport;
	private final String identity;
	private final LocationSource source;
	private final LocationConfidence confidence;
	/** Arrival radius for a plain teleport that lands on the objective. */
	private static final int DEFAULT_TRANSPORT_RADIUS = 3;
	/** Wider radius for transports that drop the player at a fixed structure. */
	static final int STRUCTURE_TRANSPORT_RADIUS = 8;

	private final int arrivalRadius;
	private final int confirmationTicks;

	StepLocationHint(String label, WorldPoint point, boolean inferred)
	{
		this(label, point, inferred, false, false);
	}

	StepLocationHint(String label, WorldPoint point, boolean inferred, boolean preferredOverEntity)
	{
		this(label, point, inferred, preferredOverEntity, false);
	}

	StepLocationHint(String label, WorldPoint point, boolean inferred,
		boolean preferredOverEntity, boolean transport)
	{
		this(label, point, inferred, preferredOverEntity, transport,
			defaultIdentity(label, point, transport),
			inferred ? LocationSource.INHERITED_CONTEXT
				: transport ? LocationSource.TRANSPORT : LocationSource.NAMED_PLACE,
			inferred ? LocationConfidence.MEDIUM : LocationConfidence.HIGH,
			transport ? 4 : 5, 2);
	}

	StepLocationHint(String label, WorldPoint point, boolean inferred,
		boolean preferredOverEntity, boolean transport, String identity,
		LocationSource source, LocationConfidence confidence,
		int arrivalRadius, int confirmationTicks)
	{
		this.label = label == null ? "Destination" : label;
		this.point = point;
		this.inferred = inferred;
		this.preferredOverEntity = preferredOverEntity;
		this.transport = transport;
		this.identity = identity == null || identity.isEmpty()
			? defaultIdentity(this.label, point, transport) : identity;
		this.source = source == null ? LocationSource.NAMED_PLACE : source;
		this.confidence = confidence == null ? LocationConfidence.HIGH : confidence;
		this.arrivalRadius = Math.max(1, Math.min(20, arrivalRadius));
		this.confirmationTicks = Math.max(1, Math.min(10, confirmationTicks));
	}

	static StepLocationHint manual(String identity, String label, WorldPoint point, int radius)
	{
		return new StepLocationHint(label, point, false, true, false, identity,
			LocationSource.USER_PIN, LocationConfidence.MANUAL, radius, 2);
	}

	String getLabel()
	{
		return label;
	}

	WorldPoint getPoint()
	{
		return point;
	}

	boolean isInferred()
	{
		return inferred;
	}

	boolean isPreferredOverEntity()
	{
		return preferredOverEntity;
	}

	boolean isTransport()
	{
		return transport;
	}

	String getIdentity()
	{
		return identity;
	}

	LocationSource getSource()
	{
		return source;
	}

	LocationConfidence getConfidence()
	{
		return confidence;
	}

	int getArrivalRadius()
	{
		return arrivalRadius;
	}

	int getConfirmationTicks()
	{
		return confirmationTicks;
	}

	StepLocationHint asTransport(boolean preferOverEntity)
	{
		return asTransport(preferOverEntity, DEFAULT_TRANSPORT_RADIUS);
	}

	/**
	 * Transport waypoint with an explicit arrival radius. Structure-drop
	 * transports (spirit tree, gnome glider, fairy ring, minecart) deposit the
	 * player at a fixed node that can be several tiles from the step's real
	 * objective, so the default tight radius never registers arrival and
	 * auto-advance silently fails. The planner passes a wider radius for those.
	 */
	StepLocationHint asTransport(boolean preferOverEntity, int transportRadius)
	{
		int r = Math.max(transportRadius, arrivalRadius);
		return transport && preferredOverEntity == preferOverEntity && arrivalRadius >= r ? this
			: new StepLocationHint(label, point, inferred, preferOverEntity, true,
				identity.startsWith("transport:") ? identity : "transport:" + identity,
				LocationSource.TRANSPORT, confidence, r, confirmationTicks);
	}

	StepLocationHint inferredCopy()
	{
		return inferred ? this : new StepLocationHint(label, point, true, false, transport,
			identity, LocationSource.INHERITED_CONTEXT, LocationConfidence.MEDIUM,
			arrivalRadius, confirmationTicks);
	}

	StepLocationHint withPreferredOverEntity(boolean preferOverEntity)
	{
		return preferredOverEntity == preferOverEntity ? this
			: new StepLocationHint(label, point, inferred, preferOverEntity, transport,
				identity, source, confidence, arrivalRadius, confirmationTicks);
	}

	StepLocationHint withSource(LocationSource newSource, LocationConfidence newConfidence)
	{
		return new StepLocationHint(label, point, inferred, preferredOverEntity, transport,
			identity, newSource, newConfidence, arrivalRadius, confirmationTicks);
	}

	boolean equivalentTo(StepLocationHint other, int radius)
	{
		if (other == null)
		{
			return false;
		}
		if (identity.equals(other.identity))
		{
			return true;
		}
		return point != null && other.point != null && point.getPlane() == other.point.getPlane()
			&& Math.max(Math.abs(point.getX() - other.point.getX()),
				Math.abs(point.getY() - other.point.getY())) <= Math.max(0, radius);
	}

	private static String defaultIdentity(String label, WorldPoint point, boolean transport)
	{
		String base = label == null ? "destination"
			: SLUG_EDGE_DASH.matcher(
				NON_SLUG.matcher(label.toLowerCase(Locale.ROOT)).replaceAll("-")).replaceAll("");
		String prefix = transport ? "transport:" : "place:";
		if (!base.isEmpty())
		{
			return prefix + base;
		}
		return prefix + (point == null ? "unknown"
			: point.getX() + ":" + point.getY() + ":" + point.getPlane());
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable ordered location plan for a guide step. */
final class StepLocationPlan
{
	private final String stepKey;
	private final List<StepLocationHint> waypoints;
	private final LocationResolutionReason reason;
	private final List<String> unresolvedCandidates;

	StepLocationPlan(String stepKey, List<StepLocationHint> waypoints)
	{
		this(stepKey, waypoints, waypoints == null || waypoints.isEmpty()
			? LocationResolutionReason.NO_LOCATION_NEEDED : LocationResolutionReason.RESOLVED,
			Collections.emptyList());
	}

	StepLocationPlan(String stepKey, List<StepLocationHint> waypoints,
		LocationResolutionReason reason, List<String> unresolvedCandidates)
	{
		this.stepKey = stepKey;
		List<StepLocationHint> safe = waypoints == null ? Collections.emptyList() : waypoints;
		this.waypoints = Collections.unmodifiableList(new ArrayList<>(safe));
		this.reason = reason == null ? LocationResolutionReason.NO_LOCATION_NEEDED : reason;
		List<String> candidates = unresolvedCandidates == null
			? Collections.emptyList() : unresolvedCandidates;
		this.unresolvedCandidates = Collections.unmodifiableList(new ArrayList<>(candidates));
	}

	String getStepKey()
	{
		return stepKey;
	}

	List<StepLocationHint> getWaypoints()
	{
		return waypoints;
	}

	boolean hasWaypoints()
	{
		return !waypoints.isEmpty();
	}

	int size()
	{
		return waypoints.size();
	}

	StepLocationHint get(int index)
	{
		if (waypoints.isEmpty())
		{
			return null;
		}
		return waypoints.get(Math.max(0, Math.min(index, waypoints.size() - 1)));
	}

	LocationResolutionReason getReason()
	{
		return reason;
	}

	List<String> getUnresolvedCandidates()
	{
		return unresolvedCandidates;
	}

	StepLocationPlan withWaypoints(List<StepLocationHint> replacement)
	{
		return new StepLocationPlan(stepKey, replacement,
			replacement == null || replacement.isEmpty() ? reason : LocationResolutionReason.RESOLVED,
			unresolvedCandidates);
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;

/** Builds cached single- or multi-waypoint plans for every guide step. */
final class StepLocationPlanner
{
	/**
	 * Transports that deposit the player at a FIXED structure rather than at the
	 * destination itself, so arrival must be judged with a wider radius. A
	 * spirit tree lands you at the tree, a fairy ring at the ring, a glider at
	 * the glider pad - each can sit several tiles from the step objective.
	 */
	private static final java.util.regex.Pattern STRUCTURE_DROP_TRANSPORT =
		java.util.regex.Pattern.compile(
			"(?i)\\b(?:spirit tree|fairy ring|gnome glider|glider|minecart|"
			+ "quetzal|mushtree|spirit pool)\\b");

	static final int RESOLVER_VERSION = 6;
	/** Inherited-context steps beyond this run length are LOW confidence. */
	private static final int LOW_CONFIDENCE_CHAIN_LENGTH = 5;
	private static final Pattern WAYPOINT_BREAK = Pattern.compile(
		"(?i)\\s*(?:->|→|;|\\bthen\\b|\\bafter(?:wards| that)?\\b|\\bnext\\s+(?:go|head|run|walk|travel|teleport|take)\\b|\\bfollowed by\\b)\\s*");
	private static final Pattern RELATIVE_ONLY = Pattern.compile(
		"(?i)^\\s*(?:go|head|run|walk|climb|go back|return)\\s+(?:north|south|east|west|upstairs|downstairs|back|inside|outside)(?:[- ](?:east|west))?\\b.*");
	private static final Pattern DYNAMIC_NEAREST = Pattern.compile(
		"(?i)\\b(?:bank anywhere|nearest bank|any bank|nearest general store|teleport anywhere to bank)\\b");
	private static final Pattern QUEST_STAGE = Pattern.compile(
		"(?i)\\b(?:continue|complete|finish|start|begin)\\b[^.;]{0,70}"
			+ "\\b(?:quest|part\\s+(?:[ivx]+|[0-9]+))\\b");
	private static final Pattern GENERIC_PLACE = Pattern.compile(
		"(?i)\\b(?:the |a |an )?(?:bank|church|altar|pub|inn|mine|cave|dungeon|house|mansion|library|guild|quarry|portal|boat|minecart)\\b");
	private static final Pattern FAIRY_CODE_LIKE = Pattern.compile("(?i)\\b[a-d][i-l][p-s]\\b");

	private StepLocationPlanner()
	{
	}

	/** Legacy single-hint view retained for callers/tests that do not need waypoints. */
	static Map<String, StepLocationHint> build(Guide guide, Map<String, String> targets,
		PlaceDirectory places, TransportResolver transports,
		Function<String, WorldPoint> locationLookup)
	{
		Map<String, StepLocationPlan> plans = buildPlans(guide, targets, places, transports, locationLookup);
		Map<String, StepLocationHint> out = new HashMap<>();
		for (Map.Entry<String, StepLocationPlan> entry : plans.entrySet())
		{
			StepLocationPlan plan = entry.getValue();
			StepLocationHint hint = plan.get(plan.size() - 1);
			if (hint != null)
			{
				out.put(entry.getKey(), hint);
			}
		}
		return Collections.unmodifiableMap(out);
	}

	static Map<String, StepLocationPlan> buildPlans(Guide guide, Map<String, String> targets,
		PlaceDirectory places, TransportResolver transports,
		Function<String, WorldPoint> locationLookup)
	{
		if (guide == null || targets == null || places == null || transports == null
			|| locationLookup == null)
		{
			return Collections.emptyMap();
		}
		Map<String, StepLocationPlan> out = new HashMap<>();
		for (GuideEpisode episode : guide.getEpisodes())
		{
			for (GuideBank bank : episode.getBanks())
			{
				StepLocationHint context = null;
				int inheritedRun = 0;
				for (GuideStep step : bank.getSteps())
				{
					String text = step.getText() == null ? "" : step.getText();
					String target = targets.get(step.getKey());
					Resolution resolution = resolveDirect(text, target, places, transports, locationLookup);
					if (!resolution.waypoints.isEmpty())
					{
						StepLocationPlan plan = new StepLocationPlan(step.getKey(), resolution.waypoints,
							resolution.reason, resolution.candidates);
						out.put(step.getKey(), plan);
						context = resolution.waypoints.get(resolution.waypoints.size() - 1);
						inheritedRun = 0;
					}
					else if (resolution.breaksContext)
					{
						context = null;
						inheritedRun = 0;
						out.put(step.getKey(), new StepLocationPlan(step.getKey(), Collections.emptyList(),
							resolution.reason, resolution.candidates));
					}
					else if (context != null)
					{
						// the further an inherited destination is carried, the
						// less likely the player is still headed there - long
						// chains are honestly LOW confidence, which is what the
						// hide-low-confidence option and audit table act on
						inheritedRun++;
						StepLocationHint inherited = context.inferredCopy();
						if (inheritedRun > LOW_CONFIDENCE_CHAIN_LENGTH)
						{
							inherited = inherited.withSource(
								LocationSource.INHERITED_CONTEXT, LocationConfidence.LOW);
						}
						out.put(step.getKey(), new StepLocationPlan(step.getKey(),
							Collections.singletonList(inherited)));
					}
					else if (resolution.reason != LocationResolutionReason.NO_LOCATION_NEEDED)
					{
						out.put(step.getKey(), new StepLocationPlan(step.getKey(), Collections.emptyList(),
							resolution.reason, resolution.candidates));
					}
				}
			}
		}
		return Collections.unmodifiableMap(out);
	}


	/** Build one direct plan for a virtual clause without changing the guide model. */
	static StepLocationPlan buildPlanForText(String stepKey, String text, String target,
		PlaceDirectory places, TransportResolver transports,
		Function<String, WorldPoint> locationLookup)
	{
		if (stepKey == null || places == null || transports == null || locationLookup == null)
		{
			return new StepLocationPlan(stepKey, Collections.emptyList(),
				LocationResolutionReason.NO_LOCATION_NEEDED, Collections.emptyList());
		}
		Resolution resolution = resolveDirect(text == null ? "" : text, target,
			places, transports, locationLookup);
		return new StepLocationPlan(stepKey, resolution.waypoints,
			resolution.reason, resolution.candidates);
	}

	static boolean isQuestStageText(String text)
	{
		return text != null && QUEST_STAGE.matcher(text).find();
	}

	private static Resolution resolveDirect(String text, String target, PlaceDirectory places,
		TransportResolver transports, Function<String, WorldPoint> locationLookup)
	{
		List<StepLocationHint> waypoints = new ArrayList<>();
		List<String> unresolved = new ArrayList<>();
		String[] segments = WAYPOINT_BREAK.split(text, 12);
		boolean anyMovement = false;
		boolean unresolvedFinalMovement = false;
		for (int i = 0; i < segments.length; i++)
		{
			String segment = segments[i].trim();
			if (segment.isEmpty())
			{
				continue;
			}
			boolean movement = PlaceDirectory.hasMovementIntent(segment);
			boolean transportIntent = TransportResolver.hasTransportIntent(segment);
			StepLocationHint transport = transports.find(segment);

			// WAYPOINT_BREAK intentionally splits arrows and "then" into ordered
			// stops. Fairy-ring shorthand can place the access method in the prior
			// segment ("Ardy cloak -> CIS"), so retry only code-like segments with
			// their adjacent context. Restricting this fallback to fairy codes avoids
			// carrying an earlier jewelry teleport into a later ordinary waypoint.
			if (transport == null && i > 0 && FAIRY_CODE_LIKE.matcher(segment).find())
			{
				String withPreviousContext = segments[i - 1].trim() + " to " + segment;
				transport = transports.find(withPreviousContext);
				transportIntent |= transport != null
					|| TransportResolver.hasTransportIntent(withPreviousContext);
			}

			boolean structureDrop = STRUCTURE_DROP_TRANSPORT.matcher(segment).find()
				|| (transport != null && transport.getIdentity().startsWith("transport:fairy-ring:"));
			int transportRadius = structureDrop
				? StepLocationHint.STRUCTURE_TRANSPORT_RADIUS : 3;
			anyMovement |= movement || transportIntent;
			StepLocationHint place = places.find(segment);
			StepLocationHint chosen = null;
			// An exact structure beats an approximate place name. A fairy ring
			// has its own coordinates; a named place is a centroid. When a
			// segment carries both ("CKS Fairy Ring to Canifis") the ring is
			// where you actually arrive, so pointing at the middle of the town
			// was simply wrong - and it only showed up when returning to an
			// already-advanced step, because the forward pass had a live target.
			if (transport != null && structureDrop)
			{
				chosen = transport.asTransport(true, transportRadius);
			}
			else if (place != null && (movement || transportIntent))
			{
				chosen = transportIntent ? place.asTransport(true, transportRadius)
					: place.withSource(LocationSource.NAMED_PLACE, LocationConfidence.EXACT)
						.withPreferredOverEntity(true);
			}
			else if (transport != null)
			{
				// a DIRECT transport match ("Fairy Ring -> BKR") drops the player
				// at the structure too, so it needs the same widened arrival
				// radius as the named-place path above. Without this, auto-advance
				// failed here for exactly the reason spirit trees did.
				chosen = structureDrop
					? transport.asTransport(transport.isPreferredOverEntity(), transportRadius)
					: transport;
			}
			else if (place != null)
			{
				chosen = place.withSource(LocationSource.NAMED_PLACE, LocationConfidence.HIGH);
			}
			if (chosen != null)
			{
				addUnique(waypoints, chosen);
			}
			else if ((movement || transportIntent) && i == segments.length - 1)
			{
				unresolvedFinalMovement = true;
				unresolved.add(segment);
			}
		}

		if (target != null)
		{
			WorldPoint known = locationLookup.apply(target);
			if (known != null)
			{
				StepLocationHint entity = new StepLocationHint(target, known, false, false, false,
					"entity:" + Names.normalize(target), LocationSource.STORED_ENTITY,
					LocationConfidence.HIGH, 3, 2);
				if (waypoints.isEmpty() || !anyMovement)
				{
					addUnique(waypoints, entity);
				}
			}
			else if (waypoints.isEmpty())
			{
				return new Resolution(waypoints, LocationResolutionReason.ENTITY_LOCATION_UNKNOWN,
					Collections.singletonList(target), true);
			}
		}

		if (unresolvedFinalMovement)
		{
			// A known intermediate waypoint is still useful, but never inherit it into
			// later steps as though it were the unresolved final destination.
			return new Resolution(waypoints, LocationResolutionReason.UNKNOWN_NAMED_PLACE,
				unresolved, true);
		}
		if (!waypoints.isEmpty())
		{
			return new Resolution(waypoints,
				waypoints.size() > 1 ? LocationResolutionReason.MULTIPLE_DESTINATIONS
					: LocationResolutionReason.RESOLVED,
				unresolved, false);
		}
		if (DYNAMIC_NEAREST.matcher(text).find())
		{
			return new Resolution(waypoints, LocationResolutionReason.DYNAMIC_NEAREST_REQUIRED,
				Collections.singletonList(text), true);
		}
		if (RELATIVE_ONLY.matcher(text).find())
		{
			return new Resolution(waypoints, LocationResolutionReason.RELATIVE_DIRECTION_ONLY,
				Collections.singletonList(text), false);
		}
		if (TransportResolver.hasTransportIntent(text) && FAIRY_CODE_LIKE.matcher(text).find())
		{
			return new Resolution(waypoints, LocationResolutionReason.UNKNOWN_TRANSPORT_CODE,
				Collections.singletonList(text), true);
		}
		if (QUEST_STAGE.matcher(text).find())
		{
			return new Resolution(waypoints, LocationResolutionReason.QUEST_STAGE,
				Collections.singletonList(text), true);
		}
		if (PlaceDirectory.hasMovementIntent(text) && GENERIC_PLACE.matcher(text).find())
		{
			return new Resolution(waypoints, LocationResolutionReason.AMBIGUOUS_GENERIC_PLACE,
				Collections.singletonList(text), true);
		}
		return new Resolution(waypoints, LocationResolutionReason.NO_LOCATION_NEEDED,
			Collections.emptyList(), false);
	}

	private static void addUnique(List<StepLocationHint> waypoints, StepLocationHint candidate)
	{
		if (candidate == null || candidate.getPoint() == null)
		{
			return;
		}
		// Suppress only an immediately repeated resolver result. A route may
		// intentionally revisit the same destination (Wilderness -> Ardougne ->
		// Wilderness -> Ardougne); removing every earlier equivalent waypoint
		// destroys that ordered route.
		if (!waypoints.isEmpty()
			&& waypoints.get(waypoints.size() - 1).equivalentTo(candidate, 2))
		{
			return;
		}
		waypoints.add(candidate);
	}

	private static final class Resolution
	{
		private final List<StepLocationHint> waypoints;
		private final LocationResolutionReason reason;
		private final List<String> candidates;
		private final boolean breaksContext;

		private Resolution(List<StepLocationHint> waypoints, LocationResolutionReason reason,
			List<String> candidates, boolean breaksContext)
		{
			this.waypoints = waypoints;
			this.reason = reason;
			this.candidates = candidates;
			this.breaksContext = breaksContext;
		}
	}
}

package com.hcimguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Floating previous/next step, waypoint, and location controls. */
public class StepNavOverlay extends Overlay
{
	static final int BUTTON_W = 28;
	static final int BUTTON_H = 22;
	static final int BUTTON_GAP = 4;

	private static final Color BACKGROUND = new Color(30, 30, 30, 170);
	private static final Color BORDER = new Color(140, 130, 110, 200);
	private static final Color ARROW = new Color(230, 220, 190);
	private static final Color LOCATION = new Color(110, 200, 255);
	private static final Color LOCATION_HIDDEN = new Color(205, 120, 120);
	/**
	 * Tint for a slot that exists but cannot act on the current step. The slots
	 * are always drawn so the row never changes width: previously the waypoint
	 * and location buttons collapsed when unavailable, which slid the next-step
	 * arrow out from under the pointer between clicks and sent the next click
	 * to the game world.
	 */
	private static final Color DISABLED = new Color(120, 120, 120, 130);

	private final HcimGuidePlugin plugin;
	private final HcimGuideConfig config;

	/**
	 * Immutable per-frame hit regions. Published as ONE volatile write so the
	 * AWT thread can never hit-test against a mixture of old and new
	 * rectangles mid-render.
	 */
	static final class HitRegions
	{
		final Rectangle prev;
		final Rectangle location;
		final Rectangle next;

		HitRegions(Rectangle prev, Rectangle location, Rectangle next)
		{
			this.prev = prev;
			this.location = location;
			this.next = next;
		}
	}

	private volatile HitRegions hitRegions;

	@Inject
	public StepNavOverlay(HcimGuidePlugin plugin, HcimGuideConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Next step",
			"Guide Overlay", e -> plugin.navigateStep(true));
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Previous step",
			"Guide Overlay", e -> plugin.navigateStep(false));
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Toggle location guide",
			"Guide Overlay", e -> plugin.toggleLocationGuideForCurrentStep());
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Snooze location guide (5 min)",
			"Guide Overlay", e -> plugin.snoozeLocationGuide());
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Restore location guide",
			"Guide Overlay", e -> plugin.restoreLocationGuide());
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Set current tile as pin",
			"Guide Overlay", e -> plugin.setCurrentTileAsCustomPin(false));
		addMenuEntry(net.runelite.api.MenuAction.RUNELITE_OVERLAY, "Add current tile as waypoint",
			"Guide Overlay", e -> plugin.setCurrentTileAsCustomPin(true));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (config.navArrows() != HcimGuideConfig.ArrowMode.FLOATING || !plugin.hasGuideLoaded())
		{
			clearRects();
			return null;
		}

		boolean showLocation = plugin.hasLocationForGuidedStep();

		// fixed three-slot layout, always the same width and the same positions
		int x = 0;
		Rectangle prev = buttonAt(x);
		x += BUTTON_W + BUTTON_GAP;
		Rectangle location = buttonAt(x);
		x += BUTTON_W + BUTTON_GAP;
		Rectangle next = buttonAt(x);

		drawArrowButton(graphics, prev, false);
		drawLocationButton(graphics, location,
			plugin.isLocationGuideHiddenForGuidedStep(), showLocation);
		drawArrowButton(graphics, next, true);

		hitRegions = new HitRegions(prev, location, next);
		return new Dimension(totalWidth(true), BUTTON_H);
	}

	private static Rectangle buttonAt(int x)
	{
		return new Rectangle(x, 0, BUTTON_W, BUTTON_H);
	}

	private void clearRects()
	{
		hitRegions = null;
	}

	/**
	 * Drop the published hit regions. Called from the plugin's shutDown so a
	 * re-enable cannot consume a click against the PREVIOUS activation's rects
	 * in the window before this overlay's first render publishes fresh ones.
	 */
	void resetClickState()
	{
		clearRects();
	}

	int hitArrow(Point screen)
	{
		HitRegions r = hitRegions;
		return r == null ? 0 : hitArrow(screen, getBounds(), r.prev, r.next);
	}

	boolean hitLocationToggle(Point screen)
	{
		HitRegions r = hitRegions;
		return r != null && hitButton(screen, getBounds(), r.location);
	}

	static int hitArrow(Point screen, Rectangle bounds, Rectangle prev, Rectangle next)
	{
		if (screen == null || bounds == null || bounds.width <= 0)
		{
			return 0;
		}
		int lx = screen.x - bounds.x;
		int ly = screen.y - bounds.y;
		if (next != null && next.contains(lx, ly))
		{
			return 1;
		}
		if (prev != null && prev.contains(lx, ly))
		{
			return -1;
		}
		return 0;
	}

	static boolean hitButton(Point screen, Rectangle bounds, Rectangle button)
	{
		return screen != null && bounds != null && bounds.width > 0 && button != null
			&& button.contains(screen.x - bounds.x, screen.y - bounds.y);
	}

	static int totalWidth(boolean includeLocation)
	{
		int buttons = 2 + (includeLocation ? 1 : 0);
		return BUTTON_W * buttons + BUTTON_GAP * (buttons - 1);
	}

	static void drawArrowButton(Graphics2D g, Rectangle r, boolean right)
	{
		drawBase(g, r);
		drawTriangle(g, r, right, ARROW);
	}

	private static void drawBase(Graphics2D g, Rectangle r)
	{
		Object oldAa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(BACKGROUND);
		g.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setColor(BORDER);
		g.drawRoundRect(r.x, r.y, r.width - 1, r.height - 1, 6, 6);
		if (oldAa != null)
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, oldAa);
		}
	}

	private static void drawTriangle(Graphics2D g, Rectangle r, boolean right, Color color)
	{
		int cx = r.x + r.width / 2;
		int cy = r.y + r.height / 2;
		int half = Math.min(r.width, r.height) / 4;
		int[] xs = right
			? new int[]{cx - half + 1, cx - half + 1, cx + half - 1}
			: new int[]{cx + half - 1, cx + half - 1, cx - half + 1};
		int[] ys = {cy - half, cy + half, cy};
		g.setColor(color);
		g.fillPolygon(xs, ys, 3);
	}

	static void drawLocationButton(Graphics2D g, Rectangle r, boolean hidden)
	{
		drawLocationButton(g, r, hidden, true);
	}

	/**
	 * @param enabled false when the current step resolves to no location. Drawn
	 *     greyed rather than omitted so the row keeps a constant width and the
	 *     arrows never move between clicks.
	 */
	static void drawLocationButton(Graphics2D g, Rectangle r, boolean hidden, boolean enabled)
	{
		drawBase(g, r);
		int cx = r.x + r.width / 2;
		int cy = r.y + r.height / 2;
		int radius = Math.max(4, Math.min(r.width, r.height) / 4);
		g.setColor(!enabled ? DISABLED : (hidden ? LOCATION_HIDDEN : LOCATION));
		g.drawOval(cx - radius, cy - radius, radius * 2, radius * 2);
		g.drawLine(cx, cy - radius - 3, cx, cy + radius + 3);
		g.drawLine(cx - radius - 3, cy, cx + radius + 3, cy);
		if (hidden)
		{
			g.drawLine(cx - radius - 4, cy + radius + 4, cx + radius + 4, cy - radius - 4);
		}
	}
}

package com.hcimguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Conservative clause splitter and classifier for compound guide rows.
 *
 * <p>This parser never creates persisted checklist rows. It only describes the
 * ordered runtime actions inside one source {@link GuideStep}. Ambiguous text
 * fails closed to MANUAL rather than manufacturing arrival semantics.</p>
 */
final class StepPhaseParser
{
	enum Kind
	{
		TRAVEL,
		TASK,
		NOTE,
		PREPARATION,
		COMPOUND
	}

	enum Mode
	{
		PURE_TRAVEL,
		TRAVEL_THEN_TASK,
		/**
		 * Clauses parsed cleanly and are useful for TARGETING, but arrival can
		 * never complete the parent. A single task clause such as
		 * "Use Star on Experiment Entrance" has no travel at all, yet the phase
		 * carries the object so highlighting works on the clause rather than the
		 * whole row. Completion stays exactly as manual as MANUAL.
		 */
		GUIDANCE_ONLY,
		MANUAL
	}

	static final class Clause
	{
		private final Kind kind;
		private final String text;

		Clause(Kind kind, String text)
		{
			this.kind = kind;
			this.text = text;
		}

		Kind getKind()
		{
			return kind;
		}

		String getText()
		{
			return text;
		}
	}

	static final class Parsed
	{
		private final List<Clause> clauses;
		private final Mode mode;
		private final boolean itemPreparation;
		private final boolean requiredParentheticalAction;

		Parsed(List<Clause> clauses, Mode mode, boolean itemPreparation,
			boolean requiredParentheticalAction)
		{
			this.clauses = Collections.unmodifiableList(new ArrayList<>(clauses));
			this.mode = mode;
			this.itemPreparation = itemPreparation;
			this.requiredParentheticalAction = requiredParentheticalAction;
		}

		List<Clause> getClauses()
		{
			return clauses;
		}

		Mode getMode()
		{
			return mode;
		}

		boolean hasItemPreparation()
		{
			return itemPreparation;
		}

		boolean hasRequiredParentheticalAction()
		{
			return requiredParentheticalAction;
		}
	}

	private static final Pattern WIKI_LINK = Pattern.compile("\\[\\[(?:[^|\\]]*\\|)?([^\\]]+)\\]\\]");
	private static final Pattern BRACKET_TAG = Pattern.compile("\\[[^\\]]+\\]");
	private static final Pattern ITEM_SUFFIX = Pattern.compile("(?is)\\(\\s*items?\\s*:\\s*.*?\\)\\s*$");
	private static final Pattern OPTIONAL = Pattern.compile(
		"(?i)\\b(?:optional(?:ly)?|if\\s+you\\s+(?:want|wish|prefer)|at\\s+(?:your|a)\\s+convenience|"
			+ "when(?:ever)?\\s+needed|as\\s+needed|consider)\\b");
	private static final Pattern ADVISORY_LEAD = Pattern.compile(
		"(?i)^\\s*(?:optional(?:ly)?|note|alternatively|whenever|at\\s+your\\s+convenience|"
			+ "you\\s+(?:can|may|might|should|will|probably|could)|consider|remember|"
			+ "the\\s+fastest\\s+method|it\\s+is\\s+(?:recommended|best)|this\\s+(?:has|means|bottle)|"
			+ "there\\s+(?:is|was)|for\\s+(?:using|an\\s+example)|right\\s+now\\s+that)\\b");

	private static final String TRANSPORT_OBJECT =
		"(?:boat|ship|portal|minecart|glider|quetzal|canoe|charter|ferry|rowboat|raft|"
			+ "spirit\\s+tree|fairy\\s+ring|lever|hole|trapdoor|ladder|stairs?|rope\\s+swing|"
			+ "magic\\s+carpet|travel\\s+cart|lady\\s+of\\s+the\\s+waves)";
	private static final Pattern TAKE_TRANSPORT = Pattern.compile(
		"(?i)\\btake\\s+(?:(?:the|a|an|north)\\s+)?"
			+ "(?:(?:[a-z][a-z'’?-]*|of)\\s+){0,4}"
			+ TRANSPORT_OBJECT + "\\b|\\btake\\s+to\\s+\\S");
	private static final Pattern USE_TRANSPORT = Pattern.compile(
		"(?i)^\\s*use\\s+(?:(?:the|a|an)\\s+|your\\s+(?:freshly\\s+charged\\s+)?|"
			+ "freshly\\s+charged\\s+|\\d+\\s+)?"
			+ "(?:ring|amulet|amulet\\s+of\\s+glory|glory|necklace|bracelet|cloak|ectophial|chronicle|"
			+ "teleport\\s+crystal|digsite\\s+pendant|camulet|fairy\\s+ring|house\\s+teleport|"
			+ "games\\s+necklace|pharaoh.?s\\s+sceptre|rope|ectotokens?)"
			+ "[^.;]{0,100}\\b(?:teleport|return|get\\s+there|go\\s+to|enter|area)\\b");
	private static final Pattern TRANSPORT_SHORTHAND = Pattern.compile(
		"(?i)^\\s*(?:(?:dueling|duelling)\\s+ring|ring\\s+of\\s+dueling|games?\\s+necklace|necklace\\s+of\\s+passage|"
			+ "chronicle|ectophial|camulet|teleport\\s+crystal|pharaoh.?s\\s+sceptre|"
			+ "(?:ardy|ardougne)\\s+cloak|rada.?s\\s+blessing|blessing|house\\s+teleport|"
			+ "home\\s+teleport|minigame\\s+teleport|fairy\\s+ring|spirit\\s+tree)"
			+ "(?:\\s+teleport)?\\s*(?:to|->|→)\\s*\\S");
	private static final Pattern NAMED_TELEPORT_HEAD = Pattern.compile(
		"(?i)^\\s*(?:(?:[a-z][a-z'’?-]*|of|the)\\s+){1,6}teleport"
			+ "(?:\\s+(?:to|towards?|into|outside))?\\b");
	private static final Pattern RETURN_ITEM = Pattern.compile(
		"(?i)^\\s*return\\s+(?:the|a|an|your|this|that)\\s+\\S");
	private static final Pattern BARE_TRANSPORT_HEAD = Pattern.compile(
		"(?i)^\\s*(?:boat|ship|portal|minecart|glider|quetzal|canoe|ferry|rowboat|raft|"
			+ "spirit\\s+tree|fairy\\s+ring)\\s+(?:to|towards?|into|back)\\b");
	private static final Pattern TRANSPORT_ARROW_HEAD = Pattern.compile(
		"(?i)^\\s*(?:boat|ship|portal|minecart|glider|quetzal|canoe|ferry|rowboat|raft|"
			+ "spirit\\s+tree|fairy\\s+ring)\\s*(?:->|→)\\s*\\S");
	private static final Pattern FAIRY_CODE_ONLY = Pattern.compile("(?i)^\\s*[a-d][i-l][p-s]\\s*$");
	private static final Pattern FAIRY_RING_TO_FINAL_DESTINATION = Pattern.compile(
		"(?i)(\\b(?:[a-d][i-l][p-s]\\s+fairy\\s+ring|fairy\\s+ring\\s+[a-d][i-l][p-s])\\b)"
			+ "\\s+to\\s+get\\s+to\\s+(?=\\S)");
	private static final Pattern ACCESS_METHOD_ONLY = Pattern.compile(
		"(?i)^\\s*(?:(?:ardy|ardougne)\\s+(?:cape|cloak)(?:\\s+teleport)?(?:\\s+\\d+)?|"
			+ "ardougne\\s+cape\\s+teleport|fairy\\s+ring|minecart|glider|quetzal|boat|ship|"
			+ "teleport\\s+to\\s+poh|teleport\\s+poh|poh|house\\s+teleport|blessing)\\s*$");
	private static final Pattern CONTEXTUAL_TRANSPORT_HEAD = Pattern.compile(
		"(?i)^\\s*[^:]{1,40}:\\s*(?:(?:ardy|ardougne)\\s+(?:cape|cloak)|teleport|"
