	private static final Pattern INFORMATIONAL = Pattern.compile(
		"(?i)^\\s*(?:do\\s+not|don['’]?t|nothing|this\\s+bottle\\s+will|the\\s+bottle|there\\s+(?:is|was)|"
			+ "all\\s+lamps|one\\s+or\\s+two|ogres\\b|basilisks\\b|follow\\s+this\\s+guide\\b)");
	private static final Pattern LEAVE_LOCATION = Pattern.compile(
		"(?i)^\\s*leave\\s+(?:the\\s+)?(?:(?:[a-z][a-z'’?-]*|of)\\s+){0,5}"
			+ "(?:cave|room|dungeon|building|area|portal|altar|island|ship|boat|bank|guild|"
			+ "house|castle|tower|mine|lair|tunnel|entrance|exit)\\b");
	private static final Pattern LEAVE_ITEM = Pattern.compile(
		"(?i)^\\s*leave\\s+(?:one|two|three|four|five|six|seven|eight|nine|ten|\\d+|your|the|a|an)\\s+"
			+ "(?!(?:cave|room|dungeon|building|area|portal|altar|island|ship|boat|bank|guild|"
			+ "house|castle|tower|mine|lair|tunnel|entrance|exit)\\b)");
	private static final Pattern TAKE_ITEM = Pattern.compile(
		"(?i)\\btake\\s+(?:one|two|three|four|five|six|seven|eight|nine|ten|\\d+|your|the|a|an)\\s+"
			+ "(?!(?:boat|ship|portal|minecart|glider|quetzal|canoe|charter|ferry|rowboat|raft|spirit\\s+tree|fairy\\s+ring)\\b)");

	private StepPhaseParser()
	{
	}

	static Parsed parse(String value)
	{
		String text = normalizeExplicitFinalDestination(clean(value));
		List<String> rawClauses = mergeAccessCodeClauses(splitClauses(text));
		List<Clause> clauses = new ArrayList<>();
		Kind previousAction = null;
		boolean riskyIgnoredText = false;
		boolean sawAction = false;
		for (String raw : rawClauses)
		{
			String clause = raw.trim();
			if (clause.isEmpty())
			{
				continue;
			}
			Kind kind = classify(clause);
			// A leading "Visit Canifis" is satisfied by reaching the named place.
			// After an earlier travel leg, however, "and visit the museum" is a
			// separate objective rather than proof that the first arrival finished it.
			if (previousAction == Kind.TRAVEL && kind == Kind.TRAVEL
				&& stripLeadingContext(BRACKET_TAG.matcher(clause).replaceAll("").trim())
					.matches("(?i)^visit\\b.*"))
			{
				kind = Kind.TASK;
			}
			boolean inheritedTravel = false;
			if (kind == Kind.NOTE && previousAction == Kind.TRAVEL
				&& !isBenignTravelContext(clause) && isRouteFragment(clause))
			{
				kind = Kind.TRAVEL;
				inheritedTravel = true;
			}
			if (kind == Kind.NOTE && ((!sawAction && !isBenignTravelContext(clause))
				|| (sawAction && !isHarmlessIgnoredClause(clause)
					&& !isBenignTravelContext(clause))))
			{
				riskyIgnoredText = true;
			}
			clauses.add(new Clause(kind, inheritedTravel
				? normalizeEllipticalText(clause, previousAction) : trimBoundary(clause)));
			if (kind != Kind.NOTE)
			{
				sawAction = true;
				previousAction = kind;
			}
		}

		ParentheticalScan parenthetical = scanParentheticals(text);
		List<Clause> actionable = new ArrayList<>();
		if (parenthetical.itemPreparation)
		{
			actionable.add(new Clause(Kind.PREPARATION, "Items requirement"));
		}
		for (Clause clause : clauses)
		{
			if (clause.kind != Kind.NOTE)
			{
				actionable.add(clause);
			}
		}

		Mode mode = Mode.MANUAL;
		if (!parenthetical.requiredAction && !riskyIgnoredText && !actionable.isEmpty())
		{
			boolean compound = false;
			List<Clause> nonPreparation = new ArrayList<>();
			for (Clause clause : actionable)
			{
				compound |= clause.kind == Kind.COMPOUND;
				if (clause.kind != Kind.PREPARATION)
				{
					nonPreparation.add(clause);
				}
			}
			if (!compound && !nonPreparation.isEmpty()
				&& nonPreparation.get(0).kind == Kind.TRAVEL)
			{
				boolean taskBeforeLast = false;
				for (int i = 0; i + 1 < nonPreparation.size(); i++)
				{
					if (nonPreparation.get(i).kind == Kind.TASK)
					{
						taskBeforeLast = true;
						break;
					}
				}
				if (!taskBeforeLast)
				{
					mode = nonPreparation.get(nonPreparation.size() - 1).kind == Kind.TASK
						? Mode.TRAVEL_THEN_TASK : Mode.PURE_TRAVEL;
				}
			}

			// ---- guidance-only fallbacks ----------------------------------
			// Reviewed against all 152 manual rows in the two bundled guides.
			// These produce phases for TARGETING only. Arrival completion is
			// decided separately and is unchanged, so no row that should stay
			// manual becomes auto-completable.
			if (mode == Mode.MANUAL)
			{
				boolean anyTravel = false;
				boolean anyResolvableTask = false;
				for (Clause clause : nonPreparation)
				{
					anyTravel |= clause.kind == Kind.TRAVEL;
					anyResolvableTask |= clause.kind == Kind.TASK;
				}
				// Rule 1: a LEADING task must not reject the plan. Travel after a
				//         task still guides ("Break another POH tab, return to Thurgo").
				// Rule 2: a lone task is a valid one-phase guidance plan
				//         ("Use Star on Experiment Entrance").
				// Rule 3: a COMPOUND next to a resolvable TRAVEL keeps the travel
				//         phase instead of discarding the whole row.
				// Rule 4: NOTE clauses between travel legs must not break the chain;
				//         notes are already excluded from nonPreparation.
				if (anyTravel || anyResolvableTask)
				{
					mode = Mode.GUIDANCE_ONLY;
				}
			}
		}
		return new Parsed(clauses, mode, parenthetical.itemPreparation,
			parenthetical.requiredAction);
	}

	private static Kind classify(String clause)
	{
		String text = stripLeadingContext(BRACKET_TAG.matcher(clause).replaceAll("").trim());
		if (text.isEmpty() || INFORMATIONAL.matcher(text).find()
			|| ADVISORY_LEAD.matcher(text).find())
		{
			return Kind.NOTE;
		}
		if (!LEAVE_LOCATION.matcher(text).find() && LEAVE_ITEM.matcher(text).find())
		{
			return Kind.TASK;
		}
		if (RETURN_ITEM.matcher(text).find())
		{
			return Kind.TASK;
		}
		if (SPELLBOOK_ACTION.matcher(text).find())
		{
			return Kind.TASK;
		}
		if (ALTERNATIVE_ROUTE.matcher(text).find() || QUANTIFIED_ROUTE.matcher(text).find()
			|| INLINE_ITEM_LOADOUT.matcher(text).find())
		{
			return Kind.COMPOUND;
		}

		boolean takeTransport = TAKE_TRANSPORT.matcher(text).find();
		boolean useTransport = USE_TRANSPORT.matcher(text).find();
		boolean travel = TRAVEL_HEAD.matcher(text).find() || takeTransport || useTransport
			|| TRANSPORT_SHORTHAND.matcher(text).find()
			|| NAMED_TELEPORT_HEAD.matcher(text).find()
			|| BARE_TRANSPORT_HEAD.matcher(text).find()
			|| TRANSPORT_ARROW_HEAD.matcher(text).find()
			|| NAMED_TRANSPORT_DESTINATION.matcher(text).find()
			|| CONTEXTUAL_TRANSPORT_HEAD.matcher(text).find()
			|| Pattern.compile("(?i)^\\s*(?:[a-d][i-l][p-s]\\s+fairy\\s+ring|"
				+ "(?:ardy|ardougne)\\s+cloak\\s*(?:->|→)|blessing\\s*(?:->|→)|spirit\\s+tree\\b)")
				.matcher(text).find();
		boolean task = TASK_HEAD.matcher(text).find();

		String withoutTransport = stripOptionalParentheticals(text);
		withoutTransport = TAKE_TRANSPORT.matcher(withoutTransport).replaceAll("");
		if (useTransport)
		{
			withoutTransport = USE_TRANSPORT.matcher(withoutTransport).replaceAll("");
		}
		withoutTransport = DESTINATION_BANK.matcher(withoutTransport).replaceAll("");
		boolean requiredTask = TASK_ANY.matcher(withoutTransport).find()
			|| TAKE_ITEM.matcher(withoutTransport).find();
		if (travel)
		{
			return requiredTask ? Kind.COMPOUND : Kind.TRAVEL;
		}
		if (task || requiredTask)
		{
			return Kind.TASK;
		}
		return Kind.NOTE;
	}

	private static boolean isRouteFragment(String clause)
	{
		String text = trimBoundary(clause);
		return text.matches("(?i)^(?:to|back\\s+to|again\\s+to|take\\s+to)\\s+\\S.*")
			|| text.matches("(?i)^(?:directly\\s+)?(?:north|south|east|west|north[- ]?east|"
				+ "north[- ]?west|south[- ]?east|south[- ]?west)\\b.*")
			|| (text.length() <= 80 && !text.isEmpty()
				&& Character.isUpperCase(text.charAt(0))
				&& !TASK_ANY.matcher(text).find() && !TAKE_ITEM.matcher(text).find()
				&& !SPELLBOOK_ACTION.matcher(text).find());
	}

	private static String normalizeEllipticalText(String clause, Kind previousAction)
	{
		String text = trimBoundary(clause);
		if (previousAction == Kind.TRAVEL && isRouteFragment(text))
		{
			if (text.matches("(?i)^take\\s+to\\s+.*"))
			{
				return text.replaceFirst("(?i)^take\\s+to\\s+", "Travel to ");
			}
			if (text.matches("(?i)^to\\s+.*") || text.matches("(?i)^back\\s+to\\s+.*"))
			{
				return "Travel " + text;
			}
			if (text.matches("(?i)^(?:directly\\s+)?(?:north|south|east|west|north[- ]?east|"
				+ "north[- ]?west|south[- ]?east|south[- ]?west)\\b.*"))
			{
				return "Head " + text;
			}
			if (!ACTION_HEAD.matcher(text).find() && !TRAVEL_HEAD.matcher(text).find())
			{
				return "Travel to " + text;
			}
		}
		return text;
	}

	private static boolean isRiskyLeadingText(String clause)
	{
		String text = clause == null ? "" : clause.trim();
		if (text.isEmpty())
		{
			return false;
		}
		// Optional/advisory rows describe choices, not one required execution path.
		if (ADVISORY_LEAD.matcher(text).find() || OPTIONAL.matcher(text).find()
			|| text.matches("(?i)^\\s*(?:if|unless)\\b.*"))
		{
			return true;
		}
		// An unclassified action before travel must not be silently discarded.
		return TASK_ANY.matcher(text).find() || TAKE_ITEM.matcher(text).find()
			|| text.matches("(?i).*\\b(?:right\\s*click|choose|chose|select|send|attack|peek|peak)\\b.*");
	}

	private static boolean isBenignTravelContext(String clause)
	{
		String text = clause == null ? "" : clause.trim();
		return text.matches("(?i)^\\s*(?:once\\b|after\\b|at\\s+the\\s+end\\b|from\\s+here\\b).*" )
			&& !TASK_ANY.matcher(text).find() && !TAKE_ITEM.matcher(text).find();
	}

	/**
	 * A fixed transport node can be only the access leg for a later named
	 * destination. Preserve both phases instead of allowing arrival at the ring
	 * itself to prove that the final destination was reached.
	 */
	private static String normalizeExplicitFinalDestination(String value)
	{
		if (value == null || value.isEmpty())
		{
			return value == null ? "" : value;
		}
		return FAIRY_RING_TO_FINAL_DESTINATION.matcher(value)
			.replaceAll("$1, then travel to ");
	}

	private static boolean isHarmlessIgnoredClause(String clause)
	{
		String text = clause == null ? "" : clause.trim();
		return text.matches("(?is)^\\(\\s*items?\\s*:.*\\)\\s*$")
			|| text.matches("^\\[[^\\]]+\\]$")
			|| text.matches("(?is)^\\((?:optional|option|e\\.g\\.|for example|formerly|right-click).*\\)$");
	}

	private static List<String> mergeAccessCodeClauses(List<String> input)
	{
		if (input.size() < 2)
		{
			return input;
		}
		List<String> out = new ArrayList<>();
		for (int i = 0; i < input.size(); i++)
		{
			String current = input.get(i).trim();
			if (i + 1 < input.size() && ACCESS_METHOD_ONLY.matcher(current).matches()
				&& (FAIRY_CODE_ONLY.matcher(input.get(i + 1)).matches()
					|| isSimpleDestinationFragment(input.get(i + 1))))
			{
				out.add(current + " -> " + input.get(++i).trim());
			}
			else
			{
				out.add(current);
			}
		}
		return out;
	}

	private static boolean isSimpleDestinationFragment(String value)
	{
		String text = value == null ? "" : value.trim();
		return text.length() > 2 && text.length() <= 80
			&& !ACTION_HEAD.matcher(text).find() && !TASK_ANY.matcher(text).find()
			&& !SPELLBOOK_ACTION.matcher(text).find()
			&& !text.matches("(?i).*\\b(?:items?|diary|option|optional)\\s*:.*");
	}

	private static String stripOptionalParentheticals(String value)
	{
		if (value == null || value.indexOf('(') < 0)
		{
			return value == null ? "" : value;
		}
		StringBuilder out = new StringBuilder(value.length());
		int depth = 0;
		int start = -1;
		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);
			if (c == '(')
			{
				if (depth++ == 0)
				{
					start = i;
				}
			}
			else if (c == ')' && depth > 0)
			{
				if (--depth == 0 && start >= 0)
				{
					String body = value.substring(start + 1, i);
					if (!OPTIONAL.matcher(body).find())
					{
						out.append(value, start, i + 1);
					}
					start = -1;
				}
			}
			else if (depth == 0)
			{
				out.append(c);
			}
		}
		if (depth > 0 && start >= 0)
		{
			out.append(value.substring(start));
		}
		return out.toString();
	}

	private static String stripLeadingContext(String value)
	{
		String text = value.trim();
		String[] patterns = {
			"(?i)^at\\s+the\\s+end\\s+of\\b[^,.;]{0,100}[,;:]?\\s*",
			"(?i)^after\\b[^,.;]{0,100}[,;:]\\s*",
			"(?i)^after\\s+[^,.;]{1,100}?\\s+(?=(?:use|take|tele(?:port)?|go|head|run|walk|"
				+ "travel|return|fairy\\s+ring|spirit\\s+tree)\\b)",
			"(?i)^once\\b[^,.;]{0,100}[,;:]\\s*",
			"(?i)^if\\s+you\\s+were\\b[^,.;]{0,100}[,;:]\\s*(?:now\\s+)?",
			"(?i)^from\\s+here[,;:]?\\s*",
			"(?i)^(?:then|next|finally|quickly|immediately|now)\\s+"
		};
		boolean changed;
		do
		{
			changed = false;
			for (String pattern : patterns)
			{
				String replaced = text.replaceFirst(pattern, "").trim();
				if (!replaced.equals(text))
				{
					text = replaced;
					changed = true;
				}
			}
		}
		while (changed);
		return text;
	}

	private static List<String> splitClauses(String text)
	{
		if (text == null || text.trim().isEmpty())
		{
			return Collections.emptyList();
		}
		boolean[] protectedChars = protectedCharacters(text);
		List<Boundary> boundaries = new ArrayList<>();
		for (int i = 0; i < text.length(); i++)
		{
			if (protectedChars[i])
			{
				continue;
			}
			if (text.startsWith("->", i))
			{
				boundaries.add(new Boundary(i, i + 2));
				i++;
			}
			else if (text.charAt(i) == '→' || text.charAt(i) == ';' || text.charAt(i) == '\n')
			{
				boundaries.add(new Boundary(i, i + 1));
			}
			else if (text.charAt(i) == '.'
				&& (i + 1 == text.length() || Character.isWhitespace(text.charAt(i + 1)))
				&& !isAcronymPeriod(text, i))
			{
				boundaries.add(new Boundary(i, i + 1));
			}
		}

		Matcher strong = Pattern.compile("(?i)\\b(?:then|afterwards|after\\s+that|followed\\s+by)\\b")
			.matcher(text);
		while (strong.find())
		{
			if (!isProtected(protectedChars, strong.start(), strong.end()))
			{
				boundaries.add(new Boundary(strong.start(), strong.end()));
			}
		}

		Matcher conditional = Pattern.compile("(?i),|&|\\band\\b|\\bthere\\s+(?=(?:use|open|talk|speak|"
			+ "activate|search|read|pay|give|collect|buy|kill|enter|climb)\\b)").matcher(text);
		while (conditional.find())
		{
			if (!isProtected(protectedChars, conditional.start(), conditional.end())
				&& (conditional.group().toLowerCase(Locale.ROOT).startsWith("there")
					|| startsWithAction(text.substring(conditional.end()))))
			{
				boundaries.add(new Boundary(conditional.start(), conditional.end()));
			}
		}

		Collections.sort(boundaries);
		List<String> out = new ArrayList<>();
		int start = 0;
		for (Boundary boundary : boundaries)
		{
			if (boundary.start < start)
			{
				continue;
			}
			String clause = trimBoundary(text.substring(start, boundary.start));
			if (!clause.isEmpty())
			{
				out.add(clause);
			}
			start = boundary.end;
		}
		String tail = trimBoundary(text.substring(start));
		if (!tail.isEmpty())
		{
			out.add(tail);
		}
		return out;
	}

	private static boolean startsWithAction(String value)
	{
		String text = value == null ? "" : value;
		return ACTION_HEAD.matcher(text).find()
			|| text.matches("(?i)^\\s*(?:boat|ship|portal|minecart|glider|quetzal|canoe|ferry|"
				+ "rowboat|raft|spirit\\s+tree|fairy\\s+ring)\\s+(?:to|towards?|into|back)\\b.*");
	}

	private static boolean isAcronymPeriod(String text, int index)
	{
		if (index <= 0 || !Character.isLetter(text.charAt(index - 1)))
		{
			return false;
		}
		int from = Math.max(0, index - 6);
		String prefix = text.substring(from, index + 1);
		return prefix.matches("(?i).*(?:[a-z]\\.){2,}[a-z]?\\.?$");
	}

	private static String trimBoundary(String value)
	{
		return value == null ? "" : value
			.replaceFirst("(?i)^[\\s,;:\\-]+(?:and\\s+)?", "")
			.replaceFirst("(?i)(?:,?\\s+and)?[\\s,;:\\-]+$", "").trim();
	}

	private static boolean[] protectedCharacters(String text)
	{
		boolean[] out = new boolean[text.length()];
		int depth = 0;
		char quote = 0;
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (quote != 0)
			{
				out[i] = true;
				if (c == quote && (i == 0 || text.charAt(i - 1) != '\\'))
				{
					quote = 0;
				}
				continue;
			}
			if ((c == '"' || c == '`')
				|| (c == '\'' && !(i > 0 && i + 1 < text.length()
					&& Character.isLetterOrDigit(text.charAt(i - 1))
					&& Character.isLetterOrDigit(text.charAt(i + 1)))))
			{
				quote = c;
				out[i] = true;
				continue;
			}
			if (c == '(' || c == '[' || c == '{')
			{
				depth++;
				out[i] = true;
			}
			else if (c == ')' || c == ']' || c == '}')
			{
				out[i] = true;
				depth = Math.max(0, depth - 1);
			}
			else if (depth > 0)
			{
				out[i] = true;
			}
		}
		return out;
	}

	private static boolean isProtected(boolean[] protectedChars, int start, int end)
	{
		for (int i = Math.max(0, start); i < Math.min(protectedChars.length, end); i++)
		{
			if (protectedChars[i])
			{
				return true;
			}
		}
		return false;
	}

	private static ParentheticalScan scanParentheticals(String text)
	{
		boolean itemPreparation = ITEM_SUFFIX.matcher(text).find();
		boolean requiredAction = false;
		int depth = 0;
		int start = -1;
		for (int i = 0; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '(')
			{
				if (depth++ == 0)
				{
					start = i + 1;
				}
			}
			else if (c == ')' && depth > 0 && --depth == 0 && start >= 0)
			{
				String body = text.substring(start, i).trim();
				if (!body.toLowerCase(Locale.ROOT).startsWith("items:")
					&& !OPTIONAL.matcher(body).find()
					&& !body.matches("(?i)^(?:option|e\\.g\\.|for example|formerly|right-click).*"))
				{
					String withoutTransport = TAKE_TRANSPORT.matcher(body).replaceAll("");
					String parentheticalInstruction = stripLeadingContext(withoutTransport);
					requiredAction |= TASK_HEAD.matcher(parentheticalInstruction).find()
						|| RETURN_ITEM.matcher(parentheticalInstruction).find()
						|| TAKE_ITEM.matcher(parentheticalInstruction).find();
				}
				start = -1;
			}
		}
		return new ParentheticalScan(itemPreparation, requiredAction);
	}

	private static String clean(String value)
	{
		if (value == null)
		{
			return "";
		}
		return WIKI_LINK.matcher(value).replaceAll("$1").trim();
	}

	private static final class ParentheticalScan
	{
		private final boolean itemPreparation;
		private final boolean requiredAction;

		private ParentheticalScan(boolean itemPreparation, boolean requiredAction)
		{
			this.itemPreparation = itemPreparation;
			this.requiredAction = requiredAction;
		}
	}

	private static final class Boundary implements Comparable<Boundary>
	{
		private final int start;
		private final int end;

		private Boundary(int start, int end)
		{
			this.start = start;
			this.end = end;
		}

		@Override
		public int compareTo(Boundary other)
		{
			int byStart = Integer.compare(start, other.start);
			return byStart != 0 ? byStart : Integer.compare(end, other.end);
		}
	}
}

package com.hcimguide;

import java.util.regex.Pattern;

/**
 * High-signal semantic categories used only for step text presentation.
 *
 * <p>The matcher is intentionally conservative. It highlights explicit danger,
 * preparation/setup instructions, and transport actions without treating every
 * boss name, item name, level goal, or three-letter token as special.</p>
 */
final class StepTextSemantic
{
	enum Kind
	{
		NORMAL,
		TRANSPORT,
		PREPARATION,
		DANGER
	}

	private static final Pattern DANGER = Pattern.compile(
		"(?i)\\b(?:wilderness|wildy|suicid(?:e|ing)|die|dying|died|kill yourself|"
			+ "intentional(?:ly)? (?:die|death)|(?:safe|unsafe) death|death pile|death storage|"
			+ "lost on death|lose[^.\\n]{0,40} on death|items?[^.\\n]{0,40} lost on death|"
			+ "pk(?:er|ing)?|player killer|danger(?:ous)?|hardcore warning|hcim warning|"
			+ "one[- ]life|risk(?:ing)? (?:your )?(?:items?|gear)|irreversible|cannot be undone)\\b");

	/** Preparation verbs at the start of the actionable instruction. */
	private static final Pattern PREPARATION_LEAD = Pattern.compile(
		"(?i)^\\s*(?:withdraw|bring|equip|wear|wield|bank|deposit|buy|purchase|"
			+ "charge|recharge|fill|stock up|prepare|set up|grab)\\b");

	/** Strong setup/prerequisite language takes priority over a later travel verb. */
	private static final Pattern PREPARATION_REQUIREMENT = Pattern.compile(
		"(?i)\\b(?:make sure(?: you)? have|ensure(?: you)? have|must have|requires?|requirements?|"
			+ "minimum(?: level)?|at least (?:level )?\\d{1,3}|"
			+ "before (?:leaving|starting|entering|teleporting|travelling|traveling)|"
			+ "bring [^.\\n]{1,80} with you)\\b");

	/** Weaker setup details yield to an actual transport action in the same step. */
	private static final Pattern PREPARATION_DETAIL = Pattern.compile(
		"(?i)\\b(?:\\d+ charges?|fully charged|partially charged|"
			+ "in (?:your )?inventory|with [^.\\n]{1,80} equipped)\\b");

	private StepTextSemantic()
	{
	}

	static Kind classify(String stepText)
	{
		if (stepText == null || stepText.trim().isEmpty())
		{
			return Kind.NORMAL;
		}
		if (DANGER.matcher(stepText).find())
		{
			return Kind.DANGER;
		}
		// A setup instruction mentioning a later teleport is still preparation,
		// e.g. "Withdraw food before teleporting" should be amber, not cyan.
		if (PREPARATION_LEAD.matcher(stepText).find()
			|| PREPARATION_REQUIREMENT.matcher(stepText).find())
		{
			return Kind.PREPARATION;
		}
		if (TransportResolver.hasTransportIntent(stepText))
		{
			return Kind.TRANSPORT;
		}
		if (PREPARATION_DETAIL.matcher(stepText).find())
		{
			return Kind.PREPARATION;
		}
		return Kind.NORMAL;
	}
}

package com.hcimguide;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Extracts a likely NPC target name from a step's text, e.g.
 * "Talk to Father Urhney in the lumbridge swamp ..." -&gt; "Father Urhney".
 *
 * Extraction runs once per step when a guide is imported (results are
 * precomputed and cached by the plugin); matching helpers run per tick.
 * All patterns are precompiled.
 */
public final class TargetExtractor
{
	private static final Pattern VERB = Pattern.compile(
		"(?i)\\b(?:talk to|talk with|talking to|talking with|speak to|speak with|speaking to|speaking with|trade with|trade|kill|attack|pickpocket|sell(?:\\s+[a-z0-9',]+){1,4}?\\s+to)\\s+(?:the\\s+)?([A-Z][A-Za-z'’()_-]*(?:\\s+[A-Z][A-Za-z'’()_-]*)*)");

	// words that end a name if the guide continues the sentence in lowercase
	private static final Pattern TRAILING = Pattern.compile(
		"(?i)\\s+(?:and|&|in|at|for|to|then|with|on|near|inside|outside|again|whenever|north|south|east|west)\\b.*$");

	private static final Pattern TRAILING_PAREN = Pattern.compile("\\s*\\([^)]*\\)\\s*$");
	private static final Pattern TRAILING_JUNK = Pattern.compile("[^A-Za-z'’)]+$");

	private TargetExtractor()
	{
	}

	/**
	 * VERB's capitalized-run tail recurses per word in java.util.regex, so
	 * unbounded input (a hostile wiki edit) would StackOverflowError the
	 * import. No real step approaches this; overflow needs several thousand
	 * words. Anything longer is scanned only up to the cap (fails closed).
	 */
	private static final int MAX_SCAN_CHARS = 1000;

	public static String extract(String stepText)
	{
		return extractWith(VERB, stepText);
	}

	/**
	 * Travel-verb phrasings ("Head to King Roald and start ... (1,1,3)")
	 * name who a dialogue sequence is with when no talk verb does. Kept
	 * separate from {@link #extract} on purpose: find() takes the EARLIEST
	 * match, and "Head to the Soul Altar &amp; talk to Aretha" must keep
	 * resolving to Aretha for highlighting - this is only ever an EXTRA
	 * dialogue-partner candidate, never the primary target.
	 */
	private static final Pattern TRAVEL_VERB = Pattern.compile(
		"\\b(?i:head to|head over to|go to|go over to|walk to|run to|return to)\\s+(?i:the\\s+)?([A-Z][A-Za-z'’()_-]*(?:\\s+[A-Z][A-Za-z'’()_-]*)*)");

	public static String extractSecondary(String stepText)
	{
		String name = extractWith(TRAVEL_VERB, stepText);
		if (name == null)
		{
			return null;
		}
		// travel destinations are often scenery ("Head to the Soul Altar"):
		// a candidate that is (or prefixes) a scene-object word would let a
		// click on that object arm the highlight with no conversation at all
		String norm = Names.normalize(name);
		for (String w : OBJECT_WORDS)
		{
			if (norm.contains(w) || w.startsWith(norm))
			{
				return null;
			}
		}
		return name;
	}

	private static String extractWith(Pattern verb, String stepText)
	{
		if (stepText == null)
		{
			return null;
		}
		if (stepText.length() > MAX_SCAN_CHARS)
		{
			stepText = stepText.substring(0, MAX_SCAN_CHARS);
		}
		Matcher m = verb.matcher(stepText);
		if (!m.find())
		{
			return null;
		}
		String name = m.group(1);
		name = TRAILING.matcher(name).replaceAll("");
		// strip dialogue notation / disambiguation leftovers
		name = name.replace('_', ' ');
		name = TRAILING_PAREN.matcher(name).replaceAll("");
		name = TRAILING_JUNK.matcher(name).replaceAll("").trim();
		if (name.length() < 2 || name.length() > 32)
		{
			return null;
		}
		return name;
	}

	/** Case-insensitive comparison tolerant of underscores and extra spaces. */
	public static boolean namesMatch(String guideName, String npcName)
	{
		return Names.matchNormalized(Names.normalize(guideName), Names.normalize(npcName));
	}

	/**
	 * Whether a conversation belongs to the step that is being guided:
	 * true when any name seen in the conversation (the clicked NPC or scene
	 * object, or a dialogue speaker) matches one of the step's extracted NPC
	 * candidates, or is one of the step's scene-object words. Everything is
	 * pre-normalized; empty/null collections simply never match, so a step
	 * that names nobody fails closed.
	 */
	public static boolean conversationMatches(java.util.Set<String> speakersNorm,
		java.util.List<String> npcCandidatesNorm, java.util.Set<String> objectWordsNorm)
	{
		if (speakersNorm == null || speakersNorm.isEmpty())
		{
			return false;
		}
		for (String speaker : speakersNorm)
		{
			if (npcCandidatesNorm != null)
			{
				for (String candidate : npcCandidatesNorm)
				{
					if (Names.matchNormalized(candidate, speaker))
					{
						return true;
					}
				}
			}
			if (objectWordsNorm != null && objectWordsNorm.contains(speaker))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Normalized names of interactable scene objects worth tracking for the
	 * step-object highlighter (ladders, altars, doors, ...). A fixed
	 * whitelist rather than verb-based extraction: object phrasing varies
	 * wildly and a whitelist can't false-positive onto NPC or item names.
	 * The scene tracker only remembers objects whose name is in this set,
	 * which keeps its bookkeeping to a handful of objects per scene.
	 */
	static final java.util.Set<String> OBJECT_WORDS;

	/** Guide-text word -&gt; the scene-object names it should light up. */
	private static final java.util.Map<String, String[]> OBJECT_EXPANSIONS =
		new java.util.HashMap<>();

	/** The raw (spaced, lowercase) forms scanned for in step text. */
	private static final String[] OBJECT_WORD_LIST = {
		"ladder", "staircase", "stairs", "altar", "door", "gate", "trapdoor",
		"tunnel", "cave entrance", "portal", "lever", "chest",
		"furnace", "anvil", "cooking range", "spinning wheel", "loom",
		"fountain", "obelisk", "fairy ring", "spirit tree", "ropeswing",
		"stile", "stepping stone", "log balance", "crevice",
		"bank booth", "bank chest", "deposit box", "sand pit", "hopper",
		"dark hole", "manhole", "pottery wheel", "kiln", "spiderweb"};

	static
	{
		// words whose in-scene object name differs from the guide's wording
		OBJECT_EXPANSIONS.put("stairs", new String[]{"stairs", "staircase"});
		OBJECT_EXPANSIONS.put("staircase", new String[]{"staircase", "stairs"});
		OBJECT_EXPANSIONS.put("cooking range", new String[]{"cooking range", "range"});
		OBJECT_EXPANSIONS.put("spiderweb", new String[]{"spiderweb", "web"});
		OBJECT_EXPANSIONS.put("stepping stone", new String[]{"stepping stone", "stepping stones"});
		OBJECT_EXPANSIONS.put("deposit box", new String[]{"deposit box", "bank deposit box"});
		OBJECT_EXPANSIONS.put("door", new String[]{"door", "large door"});

		java.util.Set<String> w = new java.util.HashSet<>();
		for (String s : OBJECT_WORD_LIST)
		{
			w.add(Names.normalize(s));
		}
		for (String[] scene : OBJECT_EXPANSIONS.values())
		{
			for (String s : scene)
			{
				w.add(Names.normalize(s));
			}
		}
		OBJECT_WORDS = java.util.Collections.unmodifiableSet(w);
	}

	/**
	 * The scene-object names (normalized) a step's text asks for, e.g.
	 * "Climb the stairs" -&gt; {stairs, staircase}. Word-boundary matching on
	 * the lowercase text so "doorman" never matches "door"; a trailing
	 * plural 's' is tolerated ("climb the ladders").
	 */
	public static java.util.Set<String> objectWordsIn(String stepText)
	{
		if (stepText == null || stepText.isEmpty())
		{
			return java.util.Collections.emptySet();
		}
		String lower = stepText.toLowerCase(java.util.Locale.ROOT);
		java.util.Set<String> out = null;
		for (String word : OBJECT_WORD_LIST)
		{
			int idx = lower.indexOf(word);
			while (idx >= 0)
			{
				boolean startOk = idx == 0 || !Character.isLetter(lower.charAt(idx - 1));
				int end = idx + word.length();
				// allow a trailing plural 's' but no other letter continuation
				boolean endOk = end >= lower.length()
					|| !Character.isLetter(lower.charAt(end))
					|| (lower.charAt(end) == 's'
						&& (end + 1 >= lower.length() || !Character.isLetter(lower.charAt(end + 1))));
				if (startOk && endOk)
				{
					if (out == null)
					{
						out = new java.util.HashSet<>();
					}
					String[] scene = OBJECT_EXPANSIONS.get(word);
					if (scene != null)
					{
						for (String s : scene)
						{
							out.add(Names.normalize(s));
						}
					}
					else
					{
						out.add(Names.normalize(word));
					}
					break;
				}
				idx = lower.indexOf(word, idx + 1);
			}
		}
		return out == null ? java.util.Collections.emptySet() : out;
	}
}

package com.hcimguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.Text;

/**
 * Draws the step-related highlights, similar to Quest Helper:
 * - the guided (current or pinned) step's target NPC: thick outline, name and
 *   colored target arrow
 * - every NPC referenced by the active bank's unchecked steps: thinner outline
 * - ground items the active bank needs: tile highlight + item name
 */
public class TargetOverlay extends Overlay
{
	private final Client client;
	private final HcimGuidePlugin plugin;
	private final HcimGuideConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	@Inject
	public TargetOverlay(Client client, HcimGuidePlugin plugin, HcimGuideConfig config, ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		OverlayFonts.apply(graphics, config);
		if (!plugin.allowSceneGuidance())
		{
			return null;
		}
		NPC target = plugin.getTargetNpc();

		// step NPCs (skip the pinned target; it gets its own stronger outline below)
		if (config.highlightStepNpcs())
		{
			Color color = config.stepNpcColor();
			for (NPC npc : plugin.getStepNpcs())
			{
				if (npc == null || npc == target)
				{
					continue;
				}
				outlineRenderer.drawOutline(npc, 1, color, 1);
				drawNameAbove(graphics, npc, color);
			}
		}

		// the current step's applicable scene objects (nearest ladder/altar/
		// door of each type the step mentions - scoped by the plugin)
		if (config.highlightStepObjects())
		{
			Color color = config.stepObjectColor();
			Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), 28);
			int plane = client.getTopLevelWorldView().getPlane();
			for (net.runelite.api.TileObject obj : plugin.getObjectHighlights())
			{
				// spawn events fire for ALL planes at scene load - never draw
				// a floating outline for a ladder on another floor
				if (obj == null || obj.getPlane() != plane)
				{
					continue;
				}
				java.awt.Shape box = obj.getClickbox();
				if (box == null)
				{
					continue;
				}
				graphics.setColor(fill);
				graphics.fill(box);
				graphics.setColor(color);
				graphics.draw(box);
			}
		}

		// needed ground items
		if (config.highlightGroundItems())
		{
			Color color = config.groundItemColor();
			for (GroundHighlight g : plugin.getGroundHighlights())
			{
				LocalPoint lp = g.getTile().getLocalLocation();
				if (lp == null)
				{
					continue;
				}
				Polygon poly = Perspective.getCanvasTilePoly(client, lp);
				if (poly != null)
				{
					OverlayUtil.renderPolygon(graphics, poly, color);
				}
				Point textLoc = Perspective.getCanvasTextLocation(client, graphics, lp, g.getName(), 0);
				if (textLoc != null)
				{
					OverlayUtil.renderTextLocation(graphics, textLoc, g.getName(), color);
				}
			}
		}

		// pinned target on top
		if (target != null)
		{
			Color color = config.highlightColor();
			outlineRenderer.drawOutline(target, 2, color, 2);
			drawNameAbove(graphics, target, color);
		}

		drawTargetArrow(graphics, target);
		return null;
	}

	private void drawTargetArrow(Graphics2D graphics, NPC npc)
	{
		if (!config.enableHintArrow())
		{
			return;
		}
		int centerX;
		int tipY;
		Shape hull = npc == null ? null : npc.getConvexHull();
		if (hull != null)
		{
			Rectangle bounds = hull.getBounds();
			centerX = bounds.x + bounds.width / 2;
			tipY = bounds.y - 4;
		}
		else
		{
			net.runelite.api.coords.WorldPoint point = plugin.getTargetArrowPoint();
			if (point == null)
			{
				return;
			}
			LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), point);
			if (local == null)
			{
				return;
			}
			Polygon tile = Perspective.getCanvasTilePoly(client, local);
			if (tile == null)
			{
				return;
			}
			Rectangle bounds = tile.getBounds();
			centerX = bounds.x + bounds.width / 2;
			tipY = bounds.y - 3;
		}

		int size = config.targetArrowSize();
		Polygon arrow = targetArrowPolygon(centerX, tipY, size);
		Graphics2D arrowGraphics = (Graphics2D) graphics.create();
		try
		{
			arrowGraphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				RenderingHints.VALUE_ANTIALIAS_ON);
			arrowGraphics.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			arrowGraphics.setColor(config.targetArrowColor());
			arrowGraphics.fillPolygon(arrow);
			arrowGraphics.setColor(new Color(0, 0, 0,
				Math.min(220, config.targetArrowColor().getAlpha())));
			arrowGraphics.drawPolygon(arrow);
		}
		finally
		{
			arrowGraphics.dispose();
		}
	}

	static Polygon targetArrowPolygon(int centerX, int tipY, int size)
	{
		int half = Math.max(3, size / 2);
		int top = tipY - Math.max(6, size);
		Polygon arrow = new Polygon();
		arrow.addPoint(centerX - half, top);
		arrow.addPoint(centerX + half, top);
		arrow.addPoint(centerX, tipY);
		return arrow;
	}

	private static void drawNameAbove(Graphics2D graphics, NPC npc, Color color)
	{
		String rawName = npc.getName();
		if (rawName == null)
		{
			return;
		}
		String name = Text.removeTags(rawName);
		Point textLoc = npc.getCanvasTextLocation(graphics, name, npc.getLogicalHeight() + 40);
		if (textLoc != null)
		{
			OverlayUtil.renderTextLocation(graphics, textLoc, name, color);
		}
	}
}

