package com.hcimguide;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * One teleport the route suggester can recommend: a destination plus the
 * items needed to use it. Coordinates are plain ints (not WorldPoint) so
 * this class - and everything that reasons about routes - stays pure Java
 * and unit-testable without a RuneLite client.
 */
public class TeleportOption
{
	/** Config-facing grouping; each category has its own enable toggle. */
	public enum Category
	{
		SPELL,
		TAB,
		JEWELRY,
		OTHER
	}

	/**
	 * One item requirement. {@code namePart} is a lowercase PREFIX of the
	 * in-game item name ("law rune", "ring of dueling"), so charge variants
	 * ("Ring of dueling(8)") match automatically. {@code chargedOnly}
	 * restricts matches to names carrying a "(...)" suffix - this is what
	 * separates a charged Amulet of glory from a dead one, whose name has
	 * no suffix at all.
	 */
	public static class ItemNeed
	{
		private final String namePart;
		private final int qty;
		private final boolean chargedOnly;

		ItemNeed(String namePart, int qty, boolean chargedOnly)
		{
			this.namePart = namePart;
			this.qty = qty;
			this.chargedOnly = chargedOnly;
		}

		public String getNamePart()
		{
			return namePart;
		}

		public int getQty()
		{
			return qty;
		}

		public boolean isChargedOnly()
		{
			return chargedOnly;
		}
	}

	private final String name;
	private final Category category;
	private final int x;
	private final int y;
	private final int plane;
	private final List<ItemNeed> needs;

	TeleportOption(String name, Category category, int x, int y, int plane, ItemNeed... needs)
	{
		this.name = name;
		this.category = category;
		this.x = x;
		this.y = y;
		this.plane = plane;
		this.needs = Collections.unmodifiableList(new ArrayList<>(Arrays.asList(needs)));
	}

	public String getName()
	{
		return name;
	}

	public Category getCategory()
	{
		return category;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	public int getPlane()
	{
		return plane;
	}

	/** Empty list = free (e.g. the home teleport). */
	public List<ItemNeed> getNeeds()
	{
		return needs;
	}

	// -------------------------------------------------------------- builders

	static ItemNeed rune(String runeName, int qty)
	{
		return new ItemNeed(runeName, qty, false);
	}

	/** Charged jewelry: only "(n)"-suffixed variants count. */
	static ItemNeed jewelry(String namePrefix)
	{
		return new ItemNeed(namePrefix, 1, true);
	}

	static ItemNeed item(String namePrefix)
	{
		return new ItemNeed(namePrefix, 1, false);
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

/**
 * Resolves transport shorthand independently from ordinary named places.
 *
 * <p>Transport aliases are deliberately contextual. A fairy-ring code is only
 * accepted next to an actual fairy-ring/access phrase, and item names such as
 * "Digsite pendant" only resolve when used as a travel instruction. This keeps
 * short codes and teleport items from becoming false location matches in bank
 * or equipment lists.</p>
 */
@Singleton
final class TransportResolver
{
	private static final String RESOURCE = "transport-destinations.json";
	private static final Pattern FAIRY_CODE = Pattern.compile("(?i)[a-d][i-l][p-s]");

	private static final Pattern TRANSPORT_INTENT = Pattern.compile(
		"(?i)\\b(?:tele(?:port)?(?:ed|ing|s)?|home tele(?:port)?|minigame tele(?:port)?|fairy ring|"
			+ "spirit tree|gnome glider|glider|minecart|quetzal|charter ship|charter|"
			+ "(?:take|enter|use|go through) (?:the |a |an |your )?"
			+ "(?:boat|ship|portal|minecart|quetzal|canoe|glider)|"
			+ "(?:boat|ship|canoe|minecart|quetzal|glider) to|sail|"
			+ "portal nexus|poh portal|house portal)\\b");
	private static final Pattern TRANSPORT_ITEM_ACTION = Pattern.compile(
		"(?i)(?:\\b(?:use|rub|activate|teleport with|travel with)\\s+"
			+ "(?:(?:the|a|an|your)\\s+)?"
			+ "(?:ardy cloak|ardougne cloak|ring of dueling|dueling ring|games necklace|"
			+ "amulet of glory|glory|skills necklace|combat bracelet|necklace of passage|"
			+ "digsite pendant|camulet|ectophial|chronicle|teleport crystal|giantsoul amulet|"
			+ "chasm teleport scroll|kharedst's memoirs|kharedsts memoirs|book of the dead)\\b"
			+ "|\\b(?:ardy cloak|ardougne cloak|ring of dueling|dueling ring|games necklace|"
			+ "amulet of glory|glory|skills necklace|combat bracelet|necklace of passage|"
			+ "digsite pendant|camulet|ectophial|chronicle|teleport crystal|giantsoul amulet|"
			+ "chasm teleport scroll|kharedst's memoirs|kharedsts memoirs|book of the dead)\\b"
			+ "[^.\\n]{0,60}?(?:->|→|\\bto\\b|\\btele(?:port)?\\b))");

	private static final Pattern FAIRY_CODE_AFTER_CONTEXT = Pattern.compile(
		"(?i)\\b(?:fairy ring|ardy cloak|ardougne cloak|poh|player owned house|"
			+ "house fairy ring|quest cape|slayer ring)\\b[^a-z0-9]{0,12}"
			+ "(?:to|code|then|use|via)?[^a-z0-9]{0,12}\\b([a-d][i-l][p-s])\\b");
	private static final Pattern FAIRY_CODE_BEFORE_CONTEXT = Pattern.compile(
		"(?i)\\b([a-d][i-l][p-s])\\b[^a-z0-9]{0,12}"
			+ "(?:fairy ring|fairy code)\\b");

	private final List<Destination> destinations;
	private final Map<String, Destination> fairyRings;

	@Inject
	TransportResolver(Gson gson)
	{
		List<Destination> loaded = new ArrayList<>();
		Map<String, Destination> rings = new HashMap<>();
		try (InputStream in = TransportResolver.class.getResourceAsStream(RESOURCE))
		{
			if (in != null)
			{
				Entry[] entries = gson.fromJson(
					new InputStreamReader(in, StandardCharsets.UTF_8), Entry[].class);
				if (entries != null)
				{
					for (Entry entry : entries)
					{
						Destination destination = Destination.from(entry);
						if (destination == null)
						{
							continue;
						}
						loaded.add(destination);
						if (destination.code != null)
						{
							rings.put(destination.code, destination);
						}
					}
				}
			}
		}
		catch (Exception ignored)
		{
			// Optional transport data must never prevent plugin startup.
		}
		destinations = Collections.unmodifiableList(loaded);
		fairyRings = Collections.unmodifiableMap(rings);
	}

	StepLocationHint find(String stepText)
	{
		if (stepText == null || stepText.trim().isEmpty())
		{
			return null;
		}

		Destination ring = findFairyRing(stepText);
		if (ring != null)
		{
			return ring.hint();
		}

		String normalized = PlaceDirectory.normalizeWords(stepText);
		if (normalized.isEmpty())
		{
			return null;
		}
		String haystack = " " + normalized + " ";
		Destination best = null;
		int bestEnd = -1;
		int bestLength = -1;
		for (Destination destination : destinations)
		{
			for (String phrase : destination.phrases)
			{
				String needle = " " + phrase + " ";
				int index = haystack.lastIndexOf(needle);
				if (index < 0)
				{
					continue;
				}
				int end = index + needle.length();
				if (end > bestEnd || (end == bestEnd && phrase.length() > bestLength))
				{
					best = destination;
					bestEnd = end;
					bestLength = phrase.length();
				}
			}
		}
		return best == null ? null : best.hint();
	}

	private Destination findFairyRing(String stepText)
	{
		Matcher after = FAIRY_CODE_AFTER_CONTEXT.matcher(stepText);
		Destination found = null;
		while (after.find())
		{
			Destination candidate = fairyRings.get(after.group(1).toUpperCase(Locale.ROOT));
			if (candidate != null)
			{
				found = candidate;
			}
		}
		if (found != null)
		{
			return found;
		}

		Matcher before = FAIRY_CODE_BEFORE_CONTEXT.matcher(stepText);
		while (before.find())
		{
			Destination candidate = fairyRings.get(before.group(1).toUpperCase(Locale.ROOT));
			if (candidate != null)
			{
				found = candidate;
			}
		}
		return found;
	}

	static boolean hasTransportIntent(String stepText)
	{
		if (stepText == null || stepText.isEmpty())
		{
			return false;
		}
		return TRANSPORT_INTENT.matcher(stepText).find()
			|| TRANSPORT_ITEM_ACTION.matcher(stepText).find()
			|| FAIRY_CODE_AFTER_CONTEXT.matcher(stepText).find()
			|| FAIRY_CODE_BEFORE_CONTEXT.matcher(stepText).find();
	}

	private static final class Destination
	{
		private final String name;
		private final String code;
		private final WorldPoint point;
		private final List<String> phrases;

		private Destination(String name, String code, WorldPoint point, List<String> phrases)
		{
			this.name = name;
			this.code = code;
			this.point = point;
			this.phrases = phrases;
		}

		private StepLocationHint hint()
		{
			String id = code != null ? "transport:fairy-ring:" + code.toLowerCase(Locale.ROOT)
				: "transport:" + PlaceDirectory.normalizeWords(name).replace(' ', '-');
			return new StepLocationHint(name, point, false, true, true, id,
				LocationSource.TRANSPORT, LocationConfidence.EXACT, 4, 2);
		}

		private static Destination from(Entry entry)
		{
			if (entry == null || entry.name == null || entry.name.trim().isEmpty()
				|| entry.x <= 0 || entry.y <= 0 || entry.plane < 0 || entry.plane > 3)
			{
				return null;
			}
			String code = null;
			if (entry.code != null && FAIRY_CODE.matcher(entry.code).matches())
			{
				code = entry.code.toUpperCase(Locale.ROOT);
			}
			List<String> phrases = new ArrayList<>();
			if (entry.phrases != null)
			{
				for (String value : entry.phrases)
				{
					String phrase = PlaceDirectory.normalizeWords(value);
					if (phrase.length() >= 5 && !phrases.contains(phrase))
					{
						phrases.add(phrase);
					}
				}
			}
			if (code == null && phrases.isEmpty())
			{
				return null;
			}
			return new Destination(entry.name.trim(), code,
				new WorldPoint(entry.x, entry.y, entry.plane),
				Collections.unmodifiableList(phrases));
		}
	}

	private static final class Entry
	{
		private String name;
		private String code;
		private List<String> phrases;
		private int x;
		private int y;
		private int plane;
	}
}

package com.hcimguide;

import java.util.Locale;

/**
 * Detection of video-guide links (YouTube/Streamable) in guide content, so
 * steps that reference a video can offer a "watch in browser" action.
 *
 * Guide text is REMOTE data, so only an exact host whitelist ever qualifies -
 * no other URLs are surfaced as clickable anywhere in the plugin. Opening is
 * always a deliberate user click routed through RuneLite's LinkBrowser; the
 * plugin itself never fetches these URLs.
 */
final class VideoLinks
{
	private static final String TRAILING_PUNCTUATION = ")].,;:!?'\"";
	/** Longest URL worth considering; also bounds all per-candidate work. */
	private static final int MAX_URL = 2000;

	private VideoLinks()
	{
	}

	/** True only for http(s) URLs whose exact host is a known video site. */
	static boolean isVideoUrl(String url)
	{
		if (url == null)
		{
			return false;
		}
		String u = url.trim();
		if (u.length() > MAX_URL)
		{
			return false;
		}
		// fail closed on anything that couldn't be a clean ASCII URL: spaces,
		// control chars and backslashes break LinkBrowser (or parse
		// differently across URL implementations), and non-ASCII rejects both
		// homoglyph hosts and our own "…" truncation marker
		for (int i = 0; i < u.length(); i++)
		{
			char c = u.charAt(i);
			if (c <= ' ' || c > '~' || c == '\\')
			{
				return false;
			}
		}
		u = u.toLowerCase(Locale.ROOT);
		String rest;
		if (u.startsWith("https://"))
		{
			rest = u.substring(8);
		}
		else if (u.startsWith("http://"))
		{
			rest = u.substring(7);
		}
		else
		{
			return false;
		}
		int end = rest.length();
		for (int i = 0; i < rest.length(); i++)
		{
			char c = rest.charAt(i);
			if (c == '/' || c == '?' || c == '#')
			{
				end = i;
				break;
			}
		}
		String host = rest.substring(0, end);
		// userinfo tricks ("https://youtube.com@evil.example/") never qualify
		if (host.contains("@"))
		{
			return false;
		}
		int colon = host.indexOf(':');
		if (colon >= 0)
		{
			host = host.substring(0, colon);
		}
		if (host.startsWith("www."))
		{
			host = host.substring(4);
		}
		else if (host.startsWith("m."))
		{
			host = host.substring(2);
		}
		// exact equality: "youtube.com.evil.example" must not pass
		return host.equals("youtube.com") || host.equals("youtu.be") || host.equals("streamable.com");
	}

	/**
	 * A whitelisted URL normalized for presentation, or null. Recognized
	 * hosts are always opened over HTTPS - an http:// link in remote guide
	 * text must not hand the user's browser a downgraded connection.
	 */
	static String accepted(String url)
	{
		if (!isVideoUrl(url))
		{
			return null;
		}
		String u = url.trim();
		if (u.regionMatches(true, 0, "http://", 0, 7))
		{
			return "https://" + u.substring(7);
		}
		return u;
	}

	/**
	 * First whitelisted video URL embedded in plain step text (the wikitext
	 * guide pastes bare URLs), with trailing prose punctuation stripped.
	 * Returns the URL in its ORIGINAL case except the scheme - video ids are
	 * case-sensitive; the scheme is normalized to https. Scanning looks for
	 * a lowercase "http" on purpose: guides paste plain lowercase URLs, and
	 * an exotic mixed-case scheme simply isn't discovered (fails closed).
	 */
	static String firstVideoUrl(String text)
	{
		if (text == null)
		{
			return null;
		}
		int idx = 0;
		while ((idx = text.indexOf("http", idx)) >= 0)
		{
			int end = idx;
			while (end < text.length() && !Character.isWhitespace(text.charAt(end)))
			{
				end++;
			}
			// strip trailing prose punctuation BY INDEX - one substring total,
			// so hostile ")))...)"-tails stay linear, not quadratic
			int trimEnd = end;
			while (trimEnd > idx && TRAILING_PUNCTUATION.indexOf(text.charAt(trimEnd - 1)) >= 0)
			{
				trimEnd--;
			}
			if (trimEnd - idx <= MAX_URL)
			{
				String ok = accepted(text.substring(idx, trimEnd));
				if (ok != null)
				{
					return ok;
				}
			}
			idx = end + 1;
		}
		return null;
	}
}

package com.hcimguide;

import net.runelite.api.coords.WorldPoint;

/** Debounces waypoint arrival so passing near a destination for one tick cannot skip it. */
final class WaypointArrivalTracker
{
	private int ticksInside;
	private String token;

	void reset()
	{
		ticksInside = 0;
		token = null;
	}

	boolean update(String stepKey, int index, StepLocationHint waypoint, WorldPoint player)
	{
		if (stepKey == null || waypoint == null || waypoint.getPoint() == null || player == null)
		{
			reset();
			return false;
		}
		String current = stepKey + "|" + index + "|" + waypoint.getIdentity();
		if (!current.equals(token))
		{
			token = current;
			ticksInside = 0;
		}
		WorldPoint target = waypoint.getPoint();
		if (player.getPlane() != target.getPlane() || tileDistance(player, target) > waypoint.getArrivalRadius())
		{
			ticksInside = 0;
			return false;
		}
		if (++ticksInside >= waypoint.getConfirmationTicks())
		{
			reset();
			return true;
		}
		return false;
	}

	private static int tileDistance(WorldPoint a, WorldPoint b)
	{
		return Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY()));
	}
}

package com.hcimguide;

import java.io.UnsupportedEncodingException;
import java.net.URLDecoder;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Turns a pasted OSRS-wiki link into a page title. Only the official wiki
 * host is accepted, so a guide can never be imported from an arbitrary
 * website. Pure Java - unit-testable anywhere.
 */
public final class WikiUrl
{
	private static final Pattern URL = Pattern.compile(
		"^https?://oldschool\\.runescape\\.wiki/(?:w|wiki)/([^?#]+).*$", Pattern.CASE_INSENSITIVE);

	private WikiUrl()
	{
	}

	/**
	 * @param input a wiki URL (https://oldschool.runescape.wiki/w/Page_Title)
	 *              or a bare page title
	 * @return the wiki page title, underscores preserved
	 * @throws IllegalArgumentException when the input is not an OSRS-wiki link or title
	 */
	public static String pageTitle(String input)
	{
		if (input == null || input.trim().isEmpty())
		{
			throw new IllegalArgumentException("No link given");
		}
		String s = input.trim();

		if (s.contains("://") || s.startsWith("www."))
		{
			Matcher m = URL.matcher(s.startsWith("www.") ? "https://" + s.substring(4) : s);
			if (!m.matches())
			{
				throw new IllegalArgumentException(
					"Only oldschool.runescape.wiki links are supported");
			}
			s = m.group(1);
		}
		try
		{
			// in a URL PATH a literal "+" means "+", but URLDecoder applies
			// query semantics ("+" -> space) - protect it first
			s = URLDecoder.decode(s.replace("+", "%2B"), "UTF-8");
		}
		catch (UnsupportedEncodingException e)
		{
			// UTF-8 is always present; fall through with the raw value
		}
		s = s.trim().replace(' ', '_');
		// MediaWiki forbids these in titles; for us they're also the Swing-HTML
		// injection characters - reject outright
		if (s.isEmpty() || s.length() > 255 || s.contains("<") || s.contains(">")
			|| s.contains("[") || s.contains("]") || s.contains("{") || s.contains("}") || s.contains("|"))
		{
			throw new IllegalArgumentException("Not a valid wiki page title");
		}
		return s;
	}

	/** Human-friendly display name for a page title ("Guide:Some_Guide" -> "Some Guide"). */
	public static String displayName(String pageTitle)
	{
		String s = pageTitle.replace('_', ' ');
		int colon = s.indexOf(':');
		if (colon > 0 && colon < s.length() - 1)
		{
			s = s.substring(colon + 1);
		}
		return s.trim();
	}
}

package com.hcimguide;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Tolerant parser that converts the guide's raw wikitext into the
 * Guide/Episode/Bank/Step model. It intentionally ignores anything it does
 * not understand (templates on their own lines, embedded videos, tables)
 * so that unrelated wiki edits do not break the plugin.
 */
public class WikitextParser
{
	private static final Pattern HEADING = Pattern.compile("^(={2,6})\\s*(.*?)\\s*\\1\\s*$");
	private static final Pattern BULLET = Pattern.compile("^([*#:]+)\\s*(.*)$");
	private static final Pattern EPISODE_TITLE = Pattern.compile("^Episode\\s+(\\d{1,3})\\b.*", Pattern.CASE_INSENSITIVE);
	private static final Pattern BANK_TITLE = Pattern.compile("^Bank\\s+([0-9]+[A-Za-z]?)\\b.*", Pattern.CASE_INSENSITIVE);
	/**
	 * Strict standalone bank label. Unlike BANK_TITLE this deliberately does
	 * not accept ordinary prose such as "Bank 9 duplicates Bank 8". Optional
	 * location/context text must be separated from the number by punctuation.
	 */
	private static final Pattern BANK_LABEL = Pattern.compile(
		"^Bank\\s*#?\\s*([0-9]+[A-Za-z]?)(?:\\s*(?:[-:–—]\\s*.+|\\([^)]*\\)|\\[[^]]*]))?\\s*[.:]?\\s*$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern BOLD_RUN = Pattern.compile("'''\\s*(.*?)\\s*'''");
	/**
	 * {{Youtube|id}} embed template. The id must be the FIRST argument and be
	 * terminated by '|' or '}' - so named parameters ({{Youtube|width=400|id}})
	 * and over-long ids yield no video at all rather than a wrong URL, in
	 * keeping with the tolerant-parser design. Both live capitalizations of
	 * the template name match.
	 */
	private static final Pattern YOUTUBE_TEMPLATE = Pattern.compile("\\{\\{\\s*[Yy]ou[Tt]ube\\s*\\|\\s*([A-Za-z0-9_-]{5,20})\\s*[|}]");
	// NOTE: HTML comments are stripped with the regex-free stripHtmlComments()
	// - a lazy <!--.*?--> pattern goes quadratic on unterminated prefixes

	/**
	 * The live guide's ONLY literal bank number: an HTML comment right before
	 * each {{Checklist}} block ("&lt;!-- Bank 12 --&gt;", "&lt;!-- Bank 105A --&gt;").
	 */
	private static final Pattern BANK_COMMENT = Pattern.compile(
		"^<!--\\s*Bank\\s*#?\\s*([0-9]+[A-Za-z]?)\\s*-->$", Pattern.CASE_INSENSITIVE);

	/**
	 * Video URL in a standalone marker line: a {{Youtube|id}} embed or a
	 * bare/labeled link. The wiki uses {{Youtube}} in two roles - section
	 * videos AND inline embeds of the video the PREVIOUS step already links
	 * (bullet with the URL, then the embed). An embed whose id appears in the
	 * previous line is the step's video, already surfaced on the step row, so
	 * it must not be promoted to "section video guide".
	 */
	private static String bankVideoIn(String line, String previousLine)
	{
		Matcher yt = YOUTUBE_TEMPLATE.matcher(line);
		if (yt.find())
		{
			String id = yt.group(1);
			if (previousLine != null && previousLine.contains(id))
			{
				return null;
			}
			return "https://youtu.be/" + id;
		}
		return VideoLinks.firstVideoUrl(line);
	}

	/** Extracts a {{Checklist}} block's title= argument (may be empty or computed). */
	private static String checklistTitle(String line)
	{
		int t = line.indexOf("title=");
		if (t < 0)
		{
			return "";
		}
		int start = t + "title=".length();
		int end = start;
		int brace = 0;
		while (end < line.length())
		{
			char c = line.charAt(end);
			if (c == '{')
			{
				brace++;
			}
			else if (c == '}')
			{
				brace--;
			}
			else if (c == '|' && brace == 0)
			{
				break;
			}
			end++;
		}
		String raw = line.substring(start, end);
		// computed titles ("Bank {{#expr:{{#var:bankNumber}}+1}}") carry no
		// usable number - treat as empty so the block continues the current
		// section (the preceding <!-- Bank N --> comment names real banks)
		if (raw.contains("{{"))
		{
			return "";
		}
		return cleanInline(raw).trim();
	}

	/**
	 * File/Image embeds, including piped captions and ONE level of nested
	 * links inside the caption. Removed entirely - before piped-link handling,
	 * which would otherwise keep the caption as text.
	 */
	private static final Pattern FILE_LINK = Pattern.compile(
		"(?i)\\[\\[(?:File|Image):[^\\[\\]]*(?:\\[\\[[^\\[\\]]*]][^\\[\\]]*)*]]");
	private static final Pattern WIKILINK_PIPED = Pattern.compile("\\[\\[[^\\[\\]|]*\\|([^\\[\\]]*)]]");
	private static final Pattern WIKILINK = Pattern.compile("\\[\\[([^\\[\\]|]*)]]");
	private static final Pattern EXTLINK_LABELED = Pattern.compile("\\[(?:https?|ftp)://\\S*\\s+([^\\]]*)]");
	private static final Pattern EXTLINK = Pattern.compile("\\[(?:https?|ftp)://[^\\]\\s]*]");
	private static final Pattern TEMPLATE = Pattern.compile("\\{\\{([^{}]*)}}");
	private static final Pattern HTML_TAG = Pattern.compile("<[^<>]+>");

	/**
	 * Parses in strict Episode/Bank mode first; when the page has no
	 * "Episode N" headings at all (an arbitrary wiki guide), falls back to a
	 * generic mode where every top-level heading becomes a chapter and every
	 * deeper heading becomes a section, so most bullet-list guide pages work.
	 */
	public Guide parse(String wikitext)
	{
		Guide strict = parseInternal(wikitext, false);
		if (!strict.isEmpty())
		{
			return strict;
		}
		return parseInternal(wikitext, true);
	}

	/** Hard cap on steps per guide - a runaway page can't OOM the client or freeze Swing. */
	private static final int MAX_STEPS = 25_000;
	/**
	 * Structural caps (the step cap alone doesn't bound the MODEL: a file of
	 * nothing but headings creates episodes/banks without ever adding a
	 * step). Real guides: 20 episodes, ~230 banks - these are pure safety
	 * margins, and hitting one marks the guide truncated.
	 */
	private static final int MAX_EPISODES = 500;
	private static final int MAX_BANKS_PER_EPISODE = 500;
	/**
	 * Longest bullet line accepted as a step. Real steps are under ~1k chars;
	 * a pathological megabyte line would otherwise flow through every
	 * cleanup regex and into item parsing. Oversized lines are SKIPPED (and
	 * the guide marked truncated), never shortened: a shortened text would
	 * mint a different step key and silently orphan saved progress if the
	 * source were ever fixed.
	 */
	private static final int MAX_STEP_SOURCE_CHARS = 4096;

	private Guide parseInternal(String wikitext, boolean generic)
	{
		Guide guide = new Guide();
		if (wikitext == null)
		{
			return guide;
		}
		int totalSteps = 0;
		int genericChapter = 0;
		int chapterLevel = -1; // in generic mode: the first heading level seen becomes chapter level

		GuideEpisode episode = null;
		GuideBank bank = null;
		// occurrence counter of identical step text within a bank, for stable keys
		Map<String, Integer> occurrence = new HashMap<>();
		Map<String, GuideBank> banksById = new HashMap<>();
		// literal bank number announced by a "<!-- Bank N -->" comment, waiting
		// for its {{Checklist}} block (an image line may sit between them)
		String pendingBank = null;
		// previous non-empty line, for telling a section {{Youtube}} embed
		// apart from an inline embed of the preceding step's own video
		String lastNonEmpty = null;

		for (String rawLine : wikitext.split("\r?\n"))
		{
			String line = rawLine.trim();
			if (line.isEmpty())
			{
				continue;
			}
			String previousLine = lastNonEmpty;
			lastNonEmpty = line;

			Matcher h = HEADING.matcher(line);
			if (h.matches())
			{
				// same source cap as step lines: cleanInline runs a dozen
				// linear passes, and headings were the one line kind fed to it
				// unbounded - a pathological multi-megabyte heading must not
				// buy CPU the step lines already refuse
				String headingSource = h.group(2);
				if (headingSource.length() > MAX_STEP_SOURCE_CHARS)
				{
					headingSource = headingSource.substring(0, MAX_STEP_SOURCE_CHARS);
				}
				String title = cleanInline(headingSource);
				int level = h.group(1).length();

				boolean isChapter;
				if (generic)
				{
					if (chapterLevel < 0)
					{
						chapterLevel = level;
					}
					isChapter = level <= chapterLevel;
				}
				else
				{
					isChapter = EPISODE_TITLE.matcher(title).matches();
				}

				if (isChapter)
				{
					int number;
					if (generic)
					{
						number = ++genericChapter;
					}
					else
					{
						Matcher ep = EPISODE_TITLE.matcher(title);
						//noinspection ResultOfMethodCallIgnored
						ep.matches();
						number = Integer.parseInt(ep.group(1));
					}
					if (guide.getEpisodes().size() >= MAX_EPISODES)
					{
						// heading spam: stop growing the model - later steps
						// keep pooling into the current episode
						guide.markTruncated();
						continue;
					}
					episode = new GuideEpisode(number, title);
					guide.getEpisodes().add(episode);
					bank = null;
					banksById.clear();
					pendingBank = null;
					continue;
				}

				if (episode != null)
				{
					Matcher bk = BANK_TITLE.matcher(title);
					String id;
					if (bk.matches())
					{
						// episode-namespaced so duplicate bank numbers across episodes can never collide
						id = "E" + episode.getNumber() + ".B" + bk.group(1).toUpperCase();
					}
					else
					{
						id = "E" + episode.getNumber() + "-" + slug(title);
					}
					bank = findOrCreateBank(guide, episode, banksById, id, title);
				}
				else
				{
					// heading before the first episode (intro/terminology) - skipped
					bank = null;
				}
				continue;
			}

			// THE LIVE GUIDE'S REAL FORMAT (verified against the actual stored
			// snapshot): each bank is a {{Checklist|title=Bank {{#expr:...}}|
			// template whose number is COMPUTED by wiki parser functions - the
			// only literal number lives in an HTML comment ("<!-- Bank 12 -->")
			// placed just before the block. So: remember the comment's number,
			// then open that bank when its {{Checklist}} arrives. Checklists
			// with a literal title ("Herblore") become named sections; ones
			// with an empty or computed-but-unannounced title CONTINUE the
			// current section (the wiki uses those as visual continuation
			// boxes around screenshots).
			boolean handledAsChecklist = false;
			if (episode != null)
			{
				Matcher bc = BANK_COMMENT.matcher(line);
				if (bc.matches())
				{
					pendingBank = bc.group(1).toUpperCase(Locale.ROOT);
					continue;
				}
				if (line.startsWith("{{Checklist"))
				{
					if (pendingBank != null)
					{
						bank = findOrCreateBank(guide, episode, banksById,
							"E" + episode.getNumber() + ".B" + pendingBank, "Bank " + pendingBank);
						pendingBank = null;
					}
					else
					{
						String title = checklistTitle(line);
						if (!title.isEmpty())
						{
							Matcher tb = BANK_LABEL.matcher(title);
							String id = tb.matches()
								? "E" + episode.getNumber() + ".B" + tb.group(1).toUpperCase(Locale.ROOT)
								: "E" + episode.getNumber() + "-" + slug(title);
							bank = findOrCreateBank(guide, episode, banksById, id, title);
						}
						// empty/computed title: continuation of the current section
					}
					// a checklist's FIRST item can sit on the opening line
					// ("{{Checklist|title=|* If you didn't get your spade...")
					int inline = line.indexOf("|*");
					if (inline < 0)
					{
						continue;
					}
					line = line.substring(inline + 1);
					handledAsChecklist = true; // fall through to the bullet code
				}
			}

			// Other guides mark banks as visible text: bold lines, list items,
			// table cells, captions. Extract the label from the whole raw line;
			// the anchored matcher keeps prose ("Bank 9 duplicates Bank 8") as
			// prose.
			if (episode != null && !handledAsChecklist)
			{
				String bankLabel = extractBankLabel(rawLine);
				if (bankLabel != null)
				{
					Matcher bk = BANK_LABEL.matcher(bankLabel);
					//noinspection ResultOfMethodCallIgnored
					bk.matches();
					String id = "E" + episode.getNumber() + ".B" + bk.group(1).toUpperCase(Locale.ROOT);
					bank = findOrCreateBank(guide, episode, banksById, id, bankLabel);
					continue;
				}
			}

			Matcher b = BULLET.matcher(line);
			if (b.matches() && episode != null)
			{
				if (totalSteps >= MAX_STEPS)
				{
					guide.markTruncated();
					continue;
				}
				if (line.length() > MAX_STEP_SOURCE_CHARS)
				{
					guide.markTruncated();
					continue;
				}
				String text = cleanInline(b.group(2));
				if (text.isEmpty())
				{
					continue;
				}
				totalSteps++;
				if (bank == null)
				{
					String id = "E" + episode.getNumber() + "-notes";
					bank = findOrCreateBank(guide, episode, banksById, id, "Notes");
				}
				int depth = Math.max(0, b.group(1).length() - 1);
				String occKey = bank.getId() + " " + text;
				int occ = occurrence.merge(occKey, 1, Integer::sum) - 1;
				// String.hashCode is stable across JVMs. Identical texts in a bank are
				// separated by the occurrence suffix; a 32-bit collision between two
				// DIFFERENT texts within one ~30-step bank is vanishingly unlikely.
				String key = bank.getId() + "#" + Integer.toHexString(text.hashCode()) + "#" + occ;
				GuideStep guideStep = new GuideStep(key, text, depth, bank.getId());
				// video URLs become a per-step "watch in browser" action; text
				// (and therefore keys) untouched. The RAW line is the fallback:
				// cleanInline strips labeled extlinks ("[url watch this]" ->
				// "watch this"), so their URL only survives pre-clean
				String videoUrl = VideoLinks.firstVideoUrl(text);
				if (videoUrl == null)
				{
					videoUrl = VideoLinks.firstVideoUrl(b.group(2));
				}
				guideStep.setVideoUrl(videoUrl);
				bank.getSteps().add(guideStep);
				continue;
			}

			// standalone video markers - "Video Guide: <url>" lines and
			// {{Youtube|id}} embed templates - attach to the bank they follow;
			// one placed right under an episode heading (before any bank) is
			// that EPISODE's video guide. First marker wins at each level. A
			// marker sitting between a "<!-- Bank N -->" comment and its
			// {{Checklist}} belongs to the ANNOUNCED bank, which doesn't exist
			// yet - never credit it to the previous bank.
			if (episode != null && !handledAsChecklist && pendingBank == null)
			{
				String video = bankVideoIn(line, previousLine);
				if (video != null)
				{
					if (bank != null)
					{
						if (bank.getVideoUrl() == null)
						{
							bank.setVideoUrl(video);
						}
					}
					else if (episode.getVideoUrl() == null)
					{
						episode.setVideoUrl(video);
					}
				}
			}
			// anything else (plain paragraphs, templates, iframes) is ignored
		}

		return guide;
	}

	private static GuideBank findOrCreateBank(Guide guide, GuideEpisode episode,
		Map<String, GuideBank> banksById, String id, String title)
	{
		GuideBank existing = banksById.get(id);
		if (existing != null)
		{
			return existing;
		}
		if (banksById.size() >= MAX_BANKS_PER_EPISODE && !episode.getBanks().isEmpty())
		{
			// bank-marker spam: stop growing the model - further steps pool
			// into the episode's last bank instead of new structures
			guide.markTruncated();
			return episode.getBanks().get(episode.getBanks().size() - 1);
		}
		GuideBank created = new GuideBank(id, title, episode.getNumber());
		banksById.put(id, created);
		episode.getBanks().add(created);
		return created;
	}

	/**
	 * Returns a normalized standalone bank label, or null when the line is
	 * ordinary guide prose. This intentionally tolerates wiki layout wrappers
	 * while keeping the semantic match strict.
	 */
	/**
	 * A real bank-label line (label + attached screenshot markup) is short.
	 * Lines beyond this can only be prose or hostile input, and the
	 * label-extraction work below must never run on megabyte lines - a
	 * crafted page could otherwise turn the per-candidate surrounding scan
	 * quadratic and hang guide parsing for hours.
	 */
	private static final int MAX_LABEL_LINE_CHARS = 4096;

	/** Bound the expensive surrounding-text checks per line (real lines have one). */
	private static final int MAX_LABEL_CANDIDATES = 4;

	static String extractBankLabel(String rawLine)
	{
		if (rawLine == null || rawLine.length() > MAX_LABEL_LINE_CHARS)
		{
			return null;
		}
		String raw = stripHtmlComments(rawLine).trim();
		if (raw.isEmpty())
		{
			return null;
		}

		// First prefer an explicitly bold bank label. Search the ORIGINAL line
		// so a caption such as [[File:bank.png|thumb|'''Bank 12''']] is not
		// discarded before we see it. For the surrounding-text check, remove
		// the complete image block with the balanced scanner; that still rejects
		// prose such as "Go to '''Bank 9''' after the quest".
		Matcher bold = BOLD_RUN.matcher(raw);
		int candidatesChecked = 0;
		while (bold.find() && candidatesChecked < MAX_LABEL_CANDIDATES)
		{
			String candidate = normalizeBankCandidate(cleanInline(bold.group(1)));
			if (!isBankLabel(candidate))
			{
				continue;
			}
			candidatesChecked++;
			String surrounding = raw.substring(0, bold.start()) + " " + raw.substring(bold.end());
			surrounding = stripFileLinks(surrounding);
			surrounding = normalizeLayoutJunk(cleanInline(surrounding));
			if (surrounding.isEmpty() || surrounding.matches("[-:–—].{0,60}"))
			{
				return candidate;
			}
		}

		String withoutFiles = stripFileLinks(raw);
		// Also support unbolded/table/list/HTML-wrapped standalone labels. The
		// exact anchored matcher is what prevents a normal instruction sentence
		// beginning with the word Bank from becoming a section accidentally.
		String remainder = normalizeBankCandidate(cleanInline(withoutFiles));
		if (isBankLabel(remainder))
		{
			return remainder;
		}

		// Caption-only bank label ([[File:bank.png|thumb|Bank 14]] alone on a
		// line): ONLY when nothing else remains on the line - a step that
		// merely carries a "Bank N"-captioned screenshot must stay a step,
		// not become a section marker that swallows the step and re-keys
		// everything after it.
		if (remainder.isEmpty())
		{
			return extractBankLabelFromFileCaptions(raw);
		}
		return null;
	}

	/**
	 * Regex-free HTML comment stripping: the naive {@code <!--.*?-->} pattern
	 * goes quadratic on a long line full of unterminated "<!--" prefixes.
	 * An unterminated comment discards the remainder of the line, matching
	 * MediaWiki's own behavior closely enough for label detection.
	 */
	static String stripHtmlComments(String s)
	{
		int start = s.indexOf("<!--");
		if (start < 0)
		{
			return s;
		}
		StringBuilder sb = new StringBuilder(s.length());
		int i = 0;
		while (start >= 0)
		{
			sb.append(s, i, start);
			int end = s.indexOf("-->", start + 4);
			if (end < 0)
			{
				return sb.toString(); // unterminated: drop the rest
			}
			sb.append(' ');
			i = end + 3;
			start = s.indexOf("<!--", i);
		}
		sb.append(s, i, s.length());
		return sb.toString();
	}

	/** Find an exact bank label in a top-level File/Image link caption field. */
	private static String extractBankLabelFromFileCaptions(String s)
	{
		int i = 0;
		while (i < s.length())
		{
			if (!startsFileLink(s, i))
			{
				i++;
				continue;
			}
			int end = endOfWikiLink(s, i);
			if (end < 0)
			{
				return null;
			}
			String body = s.substring(i + 2, end - 2);
			for (String field : splitTopLevelPipes(body))
			{
				String candidate = normalizeBankCandidate(cleanInline(field));
				if (isBankLabel(candidate))
				{
					return candidate;
				}
			}
			i = end;
		}
		return null;
	}

	/** Split File-link options without splitting pipes inside nested wiki links/templates. */
	private static java.util.List<String> splitTopLevelPipes(String s)
	{
		java.util.List<String> fields = new java.util.ArrayList<>();
		int squareDepth = 0;
		int braceDepth = 0;
		int start = 0;
		for (int i = 0; i < s.length(); i++)
		{
			if (i + 1 < s.length() && s.charAt(i) == '[' && s.charAt(i + 1) == '[')
			{
				squareDepth++;
				i++;
			}
			else if (i + 1 < s.length() && s.charAt(i) == ']' && s.charAt(i + 1) == ']')
			{
				squareDepth = Math.max(0, squareDepth - 1);
				i++;
			}
			else if (i + 1 < s.length() && s.charAt(i) == '{' && s.charAt(i + 1) == '{')
			{
				braceDepth++;
				i++;
			}
			else if (i + 1 < s.length() && s.charAt(i) == '}' && s.charAt(i + 1) == '}')
			{
				braceDepth = Math.max(0, braceDepth - 1);
				i++;
			}
			else if (s.charAt(i) == '|' && squareDepth == 0 && braceDepth == 0)
			{
				fields.add(s.substring(start, i));
				start = i + 1;
			}
		}
		fields.add(s.substring(start));
		return fields;
	}

	private static boolean isBankLabel(String candidate)
	{
		return candidate != null && candidate.length() <= 100 && BANK_LABEL.matcher(candidate).matches();
	}

	private static String normalizeBankCandidate(String s)
	{
		if (s == null)
		{
			return "";
		}
		return normalizeLayoutJunk(s)
			.replaceAll("\\s+", " ")
			.trim();
	}

	private static String normalizeLayoutJunk(String s)
	{
		String out = s == null ? "" : s.trim();
		// <gallery> entries use: File:name.png|caption
		out = out.replaceFirst("(?i)^(?:File|Image):[^|]+\\|\\s*", "");
		// MediaWiki table cell syntax: | style="..." | content
		out = out.replaceFirst("^[|!]\\s*[^|]*=\\s*[^|]*\\|\\s*", "");
		// table/list/definition prefixes and harmless trailing cell punctuation
		out = out.replaceFirst("^[|!;:*#\\s]+", "");
		out = out.replaceFirst("[|!;\\s]+$", "");
		return out.trim();
	}

	/** Remove complete [[File:...]] / [[Image:...]] blocks with nested links. */
	private static String stripFileLinks(String s)
	{
		StringBuilder out = new StringBuilder(s.length());
		int i = 0;
		while (i < s.length())
		{
			if (startsFileLink(s, i))
			{
				int end = endOfWikiLink(s, i);
				if (end < 0)
				{
					// malformed image markup: discard the remainder rather than
					// leaking an arbitrary caption into a section/step label
					break;
				}
				i = end;
				continue;
			}
			out.append(s.charAt(i++));
		}
		return out.toString();
	}

	private static boolean startsFileLink(String s, int at)
	{
		return regionMatchesIgnoreCase(s, at, "[[File:") || regionMatchesIgnoreCase(s, at, "[[Image:");
	}

	private static boolean regionMatchesIgnoreCase(String s, int at, String prefix)
	{
		return at >= 0 && at + prefix.length() <= s.length()
			&& s.regionMatches(true, at, prefix, 0, prefix.length());
	}

	/** Returns index immediately after the balanced closing brackets. */
	private static int endOfWikiLink(String s, int start)
	{
		int depth = 0;
		for (int i = start; i + 1 < s.length(); i++)
		{
			if (s.charAt(i) == '[' && s.charAt(i + 1) == '[')
			{
				depth++;
				i++;
			}
			else if (s.charAt(i) == ']' && s.charAt(i + 1) == ']')
			{
				depth--;
				i++;
				if (depth == 0)
				{
					return i + 1;
				}
			}
		}
		return -1;
	}

	/**
	 * Strips wiki markup from a single line, leaving readable text.
	 */
	static String cleanInline(String s)
	{
		if (s == null)
		{
			return "";
		}
		String out = stripFileLinks(s);

		// templates may be nested; peel from the inside out a few times
		for (int i = 0; i < 5 && out.contains("{{"); i++)
		{
			out = replaceTemplates(out);
		}

		// Regex fallback for malformed/simple image syntax not caught above.
		out = FILE_LINK.matcher(out).replaceAll("");

		out = WIKILINK_PIPED.matcher(out).replaceAll("$1");

		Matcher m = WIKILINK.matcher(out);
		StringBuffer sb = new StringBuffer();
		while (m.find())
		{
			String target = m.group(1).replace('_', ' ');
			// drop namespace prefixes like "File:.." entirely
			if (target.regionMatches(true, 0, "File:", 0, 5) || target.regionMatches(true, 0, "Image:", 0, 6))
			{
				m.appendReplacement(sb, "");
			}
			else
			{
				m.appendReplacement(sb, Matcher.quoteReplacement(target));
			}
		}
		m.appendTail(sb);
		out = sb.toString();

		out = EXTLINK_LABELED.matcher(out).replaceAll("$1");
		out = EXTLINK.matcher(out).replaceAll("");
		out = out.replace("'''", "").replace("''", "");
		// SECURITY: decode entities BEFORE stripping tags, so entity-escaped
		// markup ("&lt;html&gt;") becomes a real tag and is removed with the
		// rest. "&amp;" is decoded LAST to prevent double-decoding
		// ("&amp;lt;" must yield the literal text "&lt;", not "<").
		out = out.replace("&nbsp;", " ")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replace("&#39;", "'")
			.replace("&quot;", "\"")
			.replace("&amp;", "&");
		out = HTML_TAG.matcher(out).replaceAll("");
		// belt and braces: no angle bracket may survive into display strings -
		// Swing renders any label/tooltip text starting with "<html>" as HTML
		out = out.replace("<", "").replace(">", "");
		out = out.replaceAll("\\s+", " ").trim();
		return out;
	}

	/**
	 * HTML-safety for display strings from ANY source (used by the JSON guide
	 * parser too): strip tags and angle brackets so Swing can never render a
	 * label/tooltip as live HTML, and collapse whitespace. Does not touch wiki
	 * markup - JSON text has none.
	 */
	static String sanitizeDisplay(String s)
	{
		if (s == null)
		{
			return "";
		}
		String out = HTML_TAG.matcher(s).replaceAll("");
		out = out.replace("<", "").replace(">", "");
		return out.replaceAll("\\s+", " ").trim();
	}

	private static String replaceTemplates(String s)
	{
		Matcher m = TEMPLATE.matcher(s);
		StringBuffer sb = new StringBuffer();
		while (m.find())
		{
			String inner = m.group(1);
			String replacement = "";
			// {{plink|Item name|...}} or {{SCP|Skill|level}} -> first useful positional arg
			String[] parts = inner.split("\\|");
			for (int i = 1; i < parts.length; i++)
			{
				String p = parts[i].trim();
				if (!p.isEmpty() && !p.contains("="))
				{
					replacement = p;
					break;
				}
			}
			m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
		}
		m.appendTail(sb);
		return sb.toString();
	}

	private static String slug(String s)
	{
		return s.toLowerCase(java.util.Locale.ROOT)
			.replaceAll("[^a-z0-9]+", "-")
			.replaceAll("(^-|-$)", "");
	}
}

package com.hcimguide;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AlternativeItemRequirementTest
{
	@Test
	public void aggregatesInterchangeableInventoryItems()
	{
		ItemReq food = ItemReq.anyOf("Any cooked food", 21, "3×7",
			"Shark", "Lobster", "Swordfish");
		Map<String, Integer> exact = new HashMap<>();
		exact.put(Names.normalize("Shark"), 10);
		exact.put(Names.normalize("Lobster"), 6);
		exact.put(Names.normalize("Swordfish"), 5);
		InventorySnapshot snapshot = new InventorySnapshot(exact, new HashMap<>());

		assertEquals(21, snapshot.countOf(food));
		assertTrue(food.isAlternativeGroup());
		// an alternative GROUP shows its first option; only a CATEGORY uses the
		// declared lowest tier
		assertEquals("Shark", food.getIconName());
		assertEquals("3×7 Any cooked food (any of: Shark, Lobster, Swordfish)", food.toString());
	}

	/**
	 * "Random cooked food" is a RUNTIME CATEGORY, not a fixed alternatives
	 * list: membership is decided against live item definitions (anything
	 * edible and prepared), with the bank-tag examples only a representative
	 * subset. This pins the final category contract - an earlier design used
	 * a hardcoded anyOf list and was superseded.
	 */
	@Test
	public void randomFoodOverrideUsesTheCookedFoodCategory()
	{
		List<ItemReq> reqs = StepItemOverrides.forStep(
			"Withdraw: Bow of Faerdhinen & Crystal Armour, Seal of Passage, 3 lots of 7 random cooked food");
		ItemReq food = reqs.get(reqs.size() - 1);

		assertEquals("Any cooked food", food.getName());
		assertEquals(21, food.getQuantity());
		assertEquals("3×7", food.getQuantityLabel());
		assertTrue(food.isCategoryRequirement());
		assertEquals(ItemCategory.COOKED_FOOD, food.getCategory());
		// lowest tier represents the family, so the slot never implies gear
		// the step does not actually need
		assertEquals("Shrimps", food.getIconName());
		assertTrue(food.getMatchNames().contains("Cooked karambwan"));
	}

	@Test
	public void logOrAxeIsSatisfiedByEitherChoice()
	{
		List<ItemReq> reqs = StepItemOverrides.forStep(
			"Withdraw: Coins, Dueling Ring, a knife, log or axe, ardy cloak, dramen staff.");
		ItemReq choice = reqs.get(3);
		Map<String, Integer> exact = new HashMap<>();
		exact.put(Names.normalize("Rune axe"), 1);
		InventorySnapshot snapshot = new InventorySnapshot(exact, new HashMap<>());

		assertEquals("Log or axe", choice.getName());
		assertEquals(1, snapshot.countOf(choice));
	}
}

package com.hcimguide;

import java.util.Collections;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ArrivalCompletionPolicyTest
{
	private static final String BANK = "B1";

	@Test
	public void explicitTeleportCanCompleteAtFinalDestination()
	{
		GuideStep step = step("Teleport to Varrock");
		assertTrue(ArrivalCompletionPolicy.canComplete(step,
			plan(step, transport("Varrock", 3213, 3424)), false, false, false));
	}

	@Test
	public void explicitWalkingStepCanCompleteAtNamedPlace()
	{
		GuideStep step = step("Run to Canifis");
		assertTrue(ArrivalCompletionPolicy.canComplete(step,
			plan(step, place("Canifis", 3505, 3485)), false, false, false));
	}

	@Test
	public void commonMovementPhrasesRemainEligible()
	{
		GuideStep makeWay = step("Make your way to Canifis");
		assertTrue(ArrivalCompletionPolicy.canComplete(makeWay,
			plan(makeWay, place("Canifis", 3505, 3485)), false, false, false));
		GuideStep climb = step("Climb down to the marked cave entrance");
		assertTrue(ArrivalCompletionPolicy.canComplete(climb,
			plan(climb, place("Cave entrance", 3200, 3200)), false, false, false));
		GuideStep compoundMake = step("Go to Varrock and make a pie");
		assertFalse(ArrivalCompletionPolicy.canComplete(compoundMake,
			plan(compoundMake, place("Varrock", 3213, 3424)), false, false, false));
	}

	@Test
	public void compoundTeleportAndActionDoesNotCompleteFromArrival()
	{
		GuideStep step = step("Salve teleport, kill ghouls for the diary");
		assertFalse(ArrivalCompletionPolicy.canComplete(step,
			plan(step, transport("Salve Graveyard", 3432, 3460)), false, false, false));
	}

	@Test
	public void separateConditionEntityParentAndInheritedLocationsAreRejected()
	{
		GuideStep step = step("Run to Canifis");
		StepLocationPlan direct = plan(step, place("Canifis", 3505, 3485));
		assertFalse(ArrivalCompletionPolicy.canComplete(step, direct, true, false, false));
		assertFalse(ArrivalCompletionPolicy.canComplete(step, direct, false, true, false));
		assertFalse(ArrivalCompletionPolicy.canComplete(step, direct, false, false, true));

		StepLocationHint inherited = place("Canifis", 3505, 3485).inferredCopy();
		assertFalse(ArrivalCompletionPolicy.canComplete(step, plan(step, inherited),
			false, false, false));
	}

	@Test
	public void finalWaypointControlsCompletionForMultiStopTravel()
	{
		GuideStep step = step("Ring of dueling to Emir's Arena, then run to Mage Training Arena");
		StepLocationPlan plan = new StepLocationPlan(step.getKey(), java.util.Arrays.asList(
			transport("Emir's Arena", 3315, 3235), place("Mage Training Arena", 3363, 3317)));
		assertTrue(ArrivalCompletionPolicy.canComplete(step, plan, false, false, false));
	}

	@Test
	public void destinationNamedBankIsStillPureTravel()
	{
		GuideStep step = step("Teleport to Varrock East Bank");
		assertTrue(ArrivalCompletionPolicy.canComplete(step,
			plan(step, place("Varrock East Bank", 3253, 3420)), false, false, false));
	}

	@Test
	public void sequencedBankAndObjectActionsAreRejected()
	{
		GuideStep bank = step("Teleport to Varrock, then bank");
		assertFalse(ArrivalCompletionPolicy.canComplete(bank,
			plan(bank, transport("Varrock", 3213, 3424)), false, false, false));
		GuideStep open = step("Teleport to Lumbridge and open the chest");
		assertFalse(ArrivalCompletionPolicy.canComplete(open,
			plan(open, transport("Lumbridge", 3222, 3218)), false, false, false));
	}

	@Test
	public void unresolvedFinalTravelNeverCompletesAtIntermediateWaypoint()
	{
		GuideStep step = step("Teleport to Lumbridge, then run to an unknown cellar");
		StepLocationPlan incomplete = new StepLocationPlan(step.getKey(),
			Collections.singletonList(transport("Lumbridge", 3222, 3218)),
			LocationResolutionReason.UNKNOWN_NAMED_PLACE,
			Collections.singletonList("run to an unknown cellar"));
		assertFalse(ArrivalCompletionPolicy.canComplete(step, incomplete,
			false, false, false));
	}

	@Test
	public void transportShorthandCanCompleteWithoutGenericTravelVerb()
	{
		GuideStep step = step("Dueling ring to Castle Wars");
		assertTrue(ArrivalCompletionPolicy.canComplete(step,
			plan(step, transport("Castle Wars", 2440, 3089)), false, false, false));
	}

	@Test
	public void visitOnlyNamedPlaceCanCompleteButSequencedVisitCannot()
	{
		GuideStep direct = step("Visit Canifis");
		assertTrue(ArrivalCompletionPolicy.canComplete(direct,
			plan(direct, place("Canifis", 3505, 3485)), false, false, false));
		GuideStep compound = step("Teleport to Varrock and visit the museum");
		assertFalse(ArrivalCompletionPolicy.canComplete(compound,
			plan(compound, transport("Varrock", 3213, 3424)), false, false, false));
	}

	@Test
	public void rejectsAdditionalCompoundActions()
	{
		GuideStep read = step("Teleport to Varrock and read the noticeboard");
		assertFalse(ArrivalCompletionPolicy.canComplete(read,
			plan(read, transport("Varrock", 3213, 3424)), false, false, false));
		GuideStep pay = step("Run to Canifis and pay the boatman");
		assertFalse(ArrivalCompletionPolicy.canComplete(pay,
			plan(pay, place("Canifis", 3505, 3485)), false, false, false));
		GuideStep open = step("Open the gate at Canifis");
		assertFalse(ArrivalCompletionPolicy.canComplete(open,
			plan(open, place("Canifis", 3505, 3485)), false, false, false));
	}

	@Test
	public void manualPinDoesNotCreateTravelSemantics()
	{
		StepLocationHint manual = StepLocationHint.manual("manual:test", "Custom point",
			new WorldPoint(3200, 3200, 0), 5);
		GuideStep wait = step("Wait here for the next instruction");
		assertFalse(ArrivalCompletionPolicy.canComplete(wait,
			plan(wait, manual), false, false, false));
		GuideStep walk = step("Walk to the marked point");
		assertTrue(ArrivalCompletionPolicy.canComplete(walk,
			plan(walk, manual), false, false, false));
	}

	private static GuideStep step(String text)
	{
		return new GuideStep(BANK + "#step", text, 0, BANK);
	}

	private static StepLocationPlan plan(GuideStep step, StepLocationHint hint)
	{
		return new StepLocationPlan(step.getKey(), Collections.singletonList(hint));
	}

	private static StepLocationHint transport(String label, int x, int y)
	{
		return new StepLocationHint(label, new WorldPoint(x, y, 0), false, true, true,
			"transport:" + label.toLowerCase().replace(' ', '-'), LocationSource.TRANSPORT,
			LocationConfidence.EXACT, 5, 2);
	}

	private static StepLocationHint place(String label, int x, int y)
	{
		return new StepLocationHint(label, new WorldPoint(x, y, 0), false, true, false,
			"place:" + label.toLowerCase().replace(' ', '-'), LocationSource.NAMED_PLACE,
			LocationConfidence.EXACT, 5, 2);
	}
}

package com.hcimguide;

import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ConditionParserTest
{
	@Test
	public void detectsQuestStart()
	{
		StepCondition c = ConditionParser.parse("Talk to Morgan and start Vampyre Slayer (1)");
		assertEquals(StepCondition.Type.QUEST_STARTED, c.getType());
		assertEquals(Quest.VAMPYRE_SLAYER, c.getQuest());

		c = ConditionParser.parse("Head to King Roald and start Priest in Peril (1,1,3)");
		assertEquals(StepCondition.Type.QUEST_STARTED, c.getType());
		assertEquals(Quest.PRIEST_IN_PERIL, c.getQuest());

		c = ConditionParser.parse("Start A Porcine of Interest");
		assertEquals(StepCondition.Type.QUEST_STARTED, c.getType());
		assertEquals(Quest.A_PORCINE_OF_INTEREST, c.getQuest());
	}

	@Test
	public void detectsQuestCompletion()
	{
		StepCondition c = ConditionParser.parse("Head West to Port Sarim and talk to Veos to complete X Marks The Spot.");
		assertEquals(StepCondition.Type.QUEST_FINISHED, c.getType());
		assertEquals(Quest.X_MARKS_THE_SPOT, c.getQuest());
	}

	@Test
	public void ignoresPartialQuestSteps()
	{
		// "Complete 2nd Step of ..." must NOT auto-complete on quest finish
		assertNull(ConditionParser.parse("Complete 2nd Step of X Marks The Spot"));
		// not a quest at all
		assertNull(ConditionParser.parse("Complete 3 Floors of Stronghold of Security."));
	}

	@Test
	public void detectsSkillTargets()
	{
		StepCondition c = ConditionParser.parse("Train Draynor Agility to 5 Agility [Lumbridge Easy Diary]");
		assertEquals(StepCondition.Type.SKILL_LEVEL, c.getType());
		assertEquals(Skill.AGILITY, c.getSkill());
		assertEquals(5, c.getLevel());
	}

	@Test
	public void detectsItemSteps()
	{
		StepCondition c = ConditionParser.parse("Withdraw: Coins, Spade, Tinderbox (3 Inventory slots)");
		assertEquals(StepCondition.Type.ITEMS_IN_INVENTORY, c.getType());
		assertEquals(3, c.getItems().size());
	}

	@Test
	public void plainStepsHaveNoCondition()
	{
		assertNull(ConditionParser.parse("Head West towards Draynor hugging the fence to avoid the Jail Guards"));
		assertNull(ConditionParser.parse("Talk to Father Aereck (3,1) [Restless Ghost]"));
	}
}

