package com.hcimguide;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ItemListParserTest
{
	@Test
	public void parsesWithdrawLists()
	{
		List<ItemReq> w = ItemListParser.parse(
			"Withdraw: Coins, Air Runes, Mind Runes, Bread, Spade, Tinderbox, Air Talisman, Treasure Scroll (8 Inventory slots)");
		assertEquals(8, w.size());
		assertEquals("Coins", w.get(0).getName());
		assertEquals("Treasure Scroll", w.get(7).getName());
		assertEquals(1, w.get(0).getQuantity());

		List<ItemReq> w2 = ItemListParser.parse("Withdraw: Coins, Spade, Feather & Mysterious Orb (4 Inventory Slots)");
		assertEquals(4, w2.size());
		assertEquals("Mysterious Orb", w2.get(3).getName());
	}

	@Test
	public void parsesGatherSteps()
	{
		List<ItemReq> g = ItemListParser.parse("Collect 3x Logs [Tree Gnome Village]");
		assertEquals(3, g.get(0).getQuantity());
		assertEquals("Logs", g.get(0).getName());

		assertEquals("Beer", ItemListParser.parse("Take the Beer").get(0).getName());
		assertEquals("Leather Boots",
			ItemListParser.parse("Take Leather Boots off the table & wield").get(0).getName());
		assertEquals("Cheese",
			ItemListParser.parse("Collect Cheese from Aggie [Witch's House]").get(0).getName());
		assertEquals(5,
			ItemListParser.parse("Buy 5 Jugs of wine. Hop worlds and buy 10 in total.").get(0).getQuantity());
	}

	@Test
	public void ignoresNonItemSteps()
	{
		assertNull(ItemListParser.parse("Take Everything (Make sure you get a feather)"));
		assertNull(ItemListParser.parse("Talk to Father Aereck (3,1) [Restless Ghost]"));
		assertNull(ItemListParser.parse("Mine 10x Clay at varrock west mine"));
	}

	@Test
	public void nameEquivalenceHandlesPlurals()
	{
		assertTrue(ItemReq.namesEquivalent("Air Runes", "Air rune"));
		assertTrue(ItemReq.namesEquivalent("Coins", "Coins"));
		assertTrue(ItemReq.namesEquivalent("Jugs of wine", "Jug of wine"));
		assertFalse(ItemReq.namesEquivalent("Bread", "Bones"));
	}
	@Test
	public void bareTeleportRunesBecomeLawRuneBeforeInstructionFiltering()
	{
		List<ItemReq> bare = ItemListParser.parse("Withdraw: Teleport Runes");
		assertEquals(1, bare.size());
		assertEquals("Law rune", bare.get(0).getName());

		List<ItemReq> bank102 = ItemListParser.parse(
			"Withdraw: Teleport Runes, Tinderbox, Cat, 2 Waterskins");
		assertEquals("Law rune", bank102.get(0).getName());
		assertEquals("Tinderbox", bank102.get(1).getName());
		assertEquals(2, bank102.get(3).getQuantity());

		List<ItemReq> bank105 = ItemListParser.parse(
			"Withdraw: Coins, Teleport Runes, Hammer, 3 Planks, 90 Steel Nails, "
				+ "Rune Sword, 2 Compost, Maze Key, Ring of Charos");
		assertEquals("Coins", bank105.get(0).getName());
		assertEquals("Law rune", bank105.get(1).getName());

		List<ItemReq> bank111 = ItemListParser.parse(
			"Withdraw: Teleport Runes, Coins, Death Runes, Antipoison, "
				+ "Super Antipoison, Scrying Orb If 56/57/58 Magic; Wizard Mind Bomb, "
				+ "(9/10 Inventory Slots) + Food");
		assertEquals("Law rune", bank111.get(0).getName());
		assertEquals("Death rune", bank111.get(2).getName());

		assertNull(ItemListParser.parse("Teleport out"));
	}

	@Test
	public void inventoryFillDisplaysFullCountButUsesHalfThresholdWithOtherItems()
	{
		List<ItemReq> only = ItemListParser.parse("Withdraw: Inventory of Lobsters");
		assertEquals(1, only.size());
		assertTrue(only.get(0).isInventoryFill());
		assertEquals(28, only.get(0).getQuantity());
		assertEquals(28, only.get(0).getCompletionQuantity());

		List<ItemReq> mixed = ItemListParser.parse(
			"Withdraw: Inventory of Lobsters, Rope, Knife");
		assertEquals(3, mixed.size());
		assertEquals(28, mixed.get(0).getQuantity());
		assertEquals(14, mixed.get(0).getCompletionQuantity());
		assertEquals("28x Lobsters", mixed.get(0).toString());
		assertEquals(1, mixed.get(1).getCompletionQuantity());

		List<ItemReq> doubled = ItemListParser.parse(
			"Withdraw: 2x Inventory of Lobsters, Rope");
		assertEquals(56, doubled.get(0).getQuantity());
		assertEquals(28, doubled.get(0).getCompletionQuantity());
	}

}

package com.hcimguide;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class JsonGuideParserTest
{
	private static final String SAMPLE = "{"
		+ "\"title\": \"BRUHsailer Complete Guide\","
		+ "\"chapters\": ["
		+ "  {\"title\": \"Chapter 1: Get to da chopper\", \"sections\": ["
		+ "    {\"title\": \"1.1: Tutorial island\", \"steps\": ["
		+ "      {\"content\": [{\"text\": \"Choose a swag look\"}], \"metadata\": {\"items_needed\": \"none\"}},"
		+ "      {\"content\": [{\"text\": \"Complete tutorial\"}], \"nestedContent\": [{\"level\": 1, \"content\": [{\"text\": \"talk to the guide\"}]}], \"metadata\": {\"items_needed\": \"Bronze axe, Tinderbox\"}}"
		+ "    ]}"
		+ "  ]}"
		+ "]}";

	@Test
	public void detectsJsonGuideVsWikitext()
	{
		assertTrue(JsonGuideParser.looksLikeJsonGuide(SAMPLE));
		assertFalse(JsonGuideParser.looksLikeJsonGuide("== Episode 1 ==\n* step"));
		assertFalse(JsonGuideParser.looksLikeJsonGuide("{{template}} wiki text"));
		assertFalse(JsonGuideParser.looksLikeJsonGuide(null));
	}

	@Test
	public void mapsChaptersSectionsSteps()
	{
		Guide g = new JsonGuideParser().parse(SAMPLE);
		assertEquals(1, g.getEpisodes().size());
		GuideEpisode ch = g.getEpisodes().get(0);
		assertEquals("Chapter 1: Get to da chopper", ch.getTitle());
		assertEquals(1, ch.getBanks().size());
		GuideBank sec = ch.getBanks().get(0);
		assertEquals("C1.S1", sec.getId());
		// two steps + one nested
		assertEquals(3, sec.getSteps().size());
		assertEquals("Choose a swag look", sec.getSteps().get(0).getText());
		assertTrue(sec.getSteps().get(1).getText().contains("(Items: Bronze axe, Tinderbox)"));
		assertEquals(1, sec.getSteps().get(2).getDepth());
	}

	@Test
	public void stripsHtmlFromStepText()
	{
		Guide g = new JsonGuideParser().parse(
			"{\"chapters\":[{\"sections\":[{\"steps\":[{\"content\":[{\"text\":\"<html><img src=x>hi\"}]}]}]}]}");
		String t = g.getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getText();
		assertFalse(t.contains("<"));
		assertFalse(t.contains(">"));
	}

	@Test
	public void keysAreStableAcrossReparse()
	{
		String k1 = new JsonGuideParser().parse(SAMPLE).getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getKey();
		String k2 = new JsonGuideParser().parse(SAMPLE).getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getKey();
		assertEquals(k1, k2);
	}

	@Test
	public void splitsParagraphStepsIntoOneStepPerSentence()
	{
		Guide g = new JsonGuideParser().parse("{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":[{\"text\":\"First action here. Second action here.\"}],"
			+ "\"metadata\":{\"items_needed\":\"knife, logs\"}}"
			+ "]}]}]}");
		GuideBank sec = g.getEpisodes().get(0).getBanks().get(0);
		assertEquals(2, sec.getSteps().size());
		// the items suffix rides the FIRST fragment only
		assertEquals("First action here. (Items: knife, logs)", sec.getSteps().get(0).getText());
		assertEquals("Second action here.", sec.getSteps().get(1).getText());
	}

	@Test
	public void neverSplitsInsideParenthesesOrAfterAbbreviations()
	{
		assertEquals(2, JsonGuideParser.splitDigestible(
			"Pickpocket men (hop worlds. Really). Fletch the logs afterwards.").size());
		assertEquals(2, JsonGuideParser.splitDigestible(
			"Use 2t oaks, see e.g. Getting Rats for the method. Continue to 35.").size());
	}

	@Test
	public void videoLinkAttachesToTheFragmentContainingItsAnchor()
	{
		Guide g = new JsonGuideParser().parse("{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":["
			+ "{\"text\":\"Train woodcutting to 35 first. \"},"
			+ "{\"text\":\"Getting Rats for 2t Oaks\",\"url\":\"https://www.youtube.com/watch?v=3ysPgln5qZ4\",\"isLink\":true},"
			+ "{\"text\":\" shows the method. Then bank everything you have.\"}"
			+ "]}"
			+ "]}]}]}");
		GuideBank sec = g.getEpisodes().get(0).getBanks().get(0);
		int withVideo = 0;
		for (GuideStep s : sec.getSteps())
		{
			if (s.getVideoUrl() != null)
			{
				withVideo++;
				assertTrue(s.getText().contains("Getting Rats"));
				assertEquals("https://www.youtube.com/watch?v=3ysPgln5qZ4", s.getVideoUrl());
			}
		}
		assertEquals(1, withVideo);
	}

	@Test
	public void nonVideoUrlsNeverBecomeLinks()
	{
		Guide g = new JsonGuideParser().parse("{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":[{\"text\":\"Wiki map reference for the route.\","
			+ "\"formatting\":{\"url\":\"https://oldschool.runescape.wiki/w/Map\",\"isLink\":true}}]}"
			+ "]}]}]}");
		assertTrue(g.getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getVideoUrl() == null);
	}

	@Test
	public void oldParagraphKeyMapsToAllSplitChildren()
	{
		Guide g = new JsonGuideParser().parse("{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":[{\"text\":\"First action here. Second action here.\"}]}"
			+ "]}]}]}");
		String oldText = "First action here. Second action here.";
		String oldKey = "C1.S1#" + Integer.toHexString(oldText.hashCode()) + "#0";
		GuideBank sec = g.getEpisodes().get(0).getBanks().get(0);
		java.util.List<String> children = g.getLegacySplitKeys().get(oldKey);
		assertEquals(2, children.size());
		assertEquals(sec.getSteps().get(0).getKey(), children.get(0));
		assertEquals(sec.getSteps().get(1).getKey(), children.get(1));
	}
}

package com.hcimguide;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

/**
 * Regression coverage for the activation-generation rule.
 *
 * <p>RuneLite reuses the plugin instance across disable and re-enable, so a
 * plain active flag cannot tell a callback from a previous activation apart
 * from a live one. These tests pin that behaviour.</p>
 */
public class LifecycleGenerationTest
{
	@Test
	public void isNotActiveBeforeFirstBegin()
	{
		assertFalse(new LifecycleGeneration().isActive());
	}

	@Test
	public void ownTokenIsCurrentWhileActive()
	{
		LifecycleGeneration lifecycle = new LifecycleGeneration();
		long token = lifecycle.begin();
		assertTrue(lifecycle.isActive());
		assertTrue(lifecycle.isCurrent(token));
	}

	@Test
	public void tokenStopsBeingCurrentAfterEnd()
	{
		LifecycleGeneration lifecycle = new LifecycleGeneration();
		long token = lifecycle.begin();
		lifecycle.end();
		assertFalse(lifecycle.isActive());
		assertFalse(lifecycle.isCurrent(token));
	}

	/** The race this class exists for. */
	@Test
	public void previousActivationCannotAffectTheNextOne()
	{
		LifecycleGeneration lifecycle = new LifecycleGeneration();
		long first = lifecycle.begin();
		lifecycle.end();
		long second = lifecycle.begin();

		assertNotEquals(first, second);
		assertFalse("work from the old activation must be rejected",
			lifecycle.isCurrent(first));
		assertTrue(lifecycle.isCurrent(second));
	}

	/**
	 * Shutdown cleanup is queued AFTER end() and must still run while the
	 * plugin stays disabled - but if a re-enable outruns the queued cleanup,
	 * the cleanup must yield so it cannot wipe the new activation's state.
	 * The cleanup captures {@code current()} after end() and compares it
	 * against {@code current()} at execution time; this pins that pattern.
	 */
	@Test
	public void shutdownCleanupYieldsOnceANewActivationBegins()
	{
		LifecycleGeneration lifecycle = new LifecycleGeneration();
		lifecycle.begin();
		lifecycle.end();
		long closing = lifecycle.current();

		// plugin still disabled when the queued cleanup runs: it may proceed
		assertTrue("cleanup must run while no new activation exists",
			lifecycle.current() == closing);

		// stop -> start -> old callback: the re-enable wins the race
		lifecycle.begin();
		assertNotEquals("cleanup queued by the closing activation must yield "
			+ "to the newer activation", closing, lifecycle.current());
	}

	@Test
	public void repeatedCyclesNeverReuseAToken()
	{
		LifecycleGeneration lifecycle = new LifecycleGeneration();
		long previous = lifecycle.begin();
		for (int i = 0; i < 100; i++)
		{
			lifecycle.end();
			long token = lifecycle.begin();
			assertTrue("generation must advance", token > previous);
			assertFalse("older token must never match again",
				lifecycle.isCurrent(previous));
			previous = token;
		}
	}
}

