package com.hcimguide;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LocationSuppressionStateTest
{
	private static final String STEP_ONE = "E1.B1#1";
	private static final String STEP_TWO = "E1.B1#2";

	@Test
	public void hideAppliesToExactlyTheOriginStep()
	{
		LocationSuppressionState state = new LocationSuppressionState();
		state.hide(STEP_ONE);
		assertTrue(state.hides(STEP_ONE));
		// an equivalent follow-up destination is a DIFFERENT step and must
		// not inherit the hide - this pins the step-scoped contract
		assertFalse(state.hides(STEP_TWO));
	}

	@Test
	public void guidedStepMovingOnClearsTheSuppression()
	{
		LocationSuppressionState state = new LocationSuppressionState();
		state.hide(STEP_ONE);
		assertFalse("origin still guided: no change",
			state.clearWhenGuidedStepChanged(STEP_ONE));
		assertTrue(state.hides(STEP_ONE));
		assertTrue("guided step changed: suppression clears",
			state.clearWhenGuidedStepChanged(STEP_TWO));
		assertFalse("returning to the origin does not restore the old hide",
			state.hides(STEP_ONE));
		assertFalse(state.isActive());
	}

	@Test
	public void clearAndNullsAreSafe()
	{
		LocationSuppressionState state = new LocationSuppressionState();
		assertFalse(state.hides(null));
		assertFalse(state.clearWhenGuidedStepChanged(null));
		state.hide(null);
		assertFalse(state.isActive());
		state.hide(STEP_ONE);
		state.clear();
		assertFalse(state.isActive());
		assertFalse(state.hides(STEP_ONE));
	}

	@Test
	public void hideWithNoGuidedStepClearsWhenAnotherStepBecomesGuided()
	{
		LocationSuppressionState state = new LocationSuppressionState();
		state.hide(STEP_ONE);
		// guided step becomes null (e.g. bank completed) -> origin no longer
		// guided -> suppression clears rather than lingering for a return
		assertTrue(state.clearWhenGuidedStepChanged(null));
		assertFalse(state.isActive());
	}
}

package com.hcimguide;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Regression coverage for the parsing and requirement behaviour added in
 * 1.5.4 and 1.5.5. Each test names the bug it protects against.
 */
public class NewBehaviourTest
{
	private static String render(String step)
	{
		List<ItemReq> reqs = ItemListParser.parse(step);
		if (reqs == null)
		{
			return "(null)";
		}
		StringBuilder sb = new StringBuilder();
		for (ItemReq r : reqs)
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(r.toString());
		}
		return sb.toString();
	}

	@Test
	public void instructionAfterAndIsNotAnItem()
	{
		assertEquals("Rope", render("Withdraw: Rope and climb down"));
	}

	@Test
	public void quantityLabelsRenderWithoutAnExtraX()
	{
		assertEquals("100+ Cosmic Runes", render("Buy 100+ Cosmic Runes"));
		// "Food" is now the cooked-food category, so the display name changed.
		// The point of this check is that the vague quantity label survives.
		assertEquals("few Any cooked food", render("Withdraw: Few food"));
	}

	/** Spelled-out counts used to parse as 1, so steps completed after one item. */
	@Test
	public void spelledOutQuantitiesAreCounted()
	{
		assertEquals("2x cheese", render("Buy two cheese"));
		assertEquals("3x raw beef", render("Buy three raw beef"));
		assertEquals("8x redberries", render("Buy eight redberries"));
	}

	/** "and" separates list members but is part of some real item names. */
	@Test
	public void andSplitsProseButNotItemNames()
	{
		assertEquals("2x cheese, 3x raw beef", render("Buy two cheese and three raw beef"));
		assertEquals("Pestle and mortar, Vial of water",
			render("Withdraw: Pestle and mortar, Vial of water"));
		assertEquals("Bow and arrow, Coins", render("Withdraw: Bow and arrow, Coins"));
	}

	@Test
	public void thousandsSuffixExpands()
	{
		assertEquals("16000x feathers", render("Buy 16k feathers"));
	}

	/**
	 * "100+ Cosmic Runes" lost its item when it was not the first entry: the
	 * boundary split cut at the '+' before the segment's own count was read.
	 */
	@Test
	public void openQuantitySurvivesInAnyListPosition()
	{
		assertEquals("100+ Cosmic Runes", render("Buy 100+ Cosmic Runes"));
		assertEquals("500x Law Runes, 100+ Cosmic Runes",
			render("Buy 500 Law Runes, 100+ Cosmic Runes"));
	}

	@Test
	public void hedgesBeforeACountAreStripped()
	{
		assertEquals("4x Jute seeds", render("Buy at least 4x Jute seeds"));
		assertEquals("100x Soda Ash", render("Buy your 100 Soda Ash"));
	}

	/** A shared trailing noun distributes, but only over bare modifiers. */
	@Test
	public void sharedTrailingNounDistributes()
	{
		assertEquals("Bronze Knives, Iron Knives, Steel Knives",
			render("Buy Bronze, Iron, and Steel Knives"));
	}

	@Test
	public void sharedTrailingNounDoesNotTouchOrdinaryLists()
	{
		assertEquals("Coins, Spade, Dramen Staff",
			render("Withdraw: Coins, Spade, Dramen Staff"));
	}

	/** Dose plurals resolve through the alias layer, not a per-step override. */
	@Test
	public void dosePluralsResolve()
	{
		assertEquals("56x Waterskins(4)", render("Buy 2x Inventory of Waterskins(4)"));
		assertEquals("Waterskin(4)", ItemAliases.canonical(ItemReq.normalize("Waterskins(4)")));
	}

	@Test
	public void namedTeleportExpandsToItsRunes()
	{
		assertEquals("2x Fire rune, 2x Law rune",
			render("Withdraw: trollheim teleport runes"));
	}

	/** A vague count keeps the guide's own wording as the slot label. */
	@Test
	public void vagueQuantityKeepsTheGuideWording()
	{
		List<ItemReq> reqs = ItemListParser.parse("Withdraw: Few food");
		assertEquals("few", reqs.get(0).getQuantityLabel());
		// bare "food" stays free text on purpose: any cooked food satisfies it,
		// and a specific alias would show a missing border to a player carrying
		// a different food
		assertNull(ItemAliases.canonical(ItemReq.normalize("food")));
	}

	/**
	 * Concept phrases name no item, so they must be recognised as concepts:
	 * they render a sprite, skip inventory checks, and never block trip ready.
	 */
	@Test
	public void conceptPhrasesAreRecognised()
	{
		assertTrue(ConceptItems.isConcept("Combat Gear"));
		assertTrue(ConceptItems.isConcept("Range Gear"));
		assertFalse(ConceptItems.isConcept("combat stats"));
		assertFalse(ConceptItems.isConcept("Shark"));
	}

	/**
	 * An override replaces the whole parsed list for its step, so it must list
	 * everything the step needs. These three previously dropped items.
	 */
	@Test
	public void overridesKeepEveryItemTheStepNeeds()
	{
		String gauntlet = render("Withdraw: Bow of Faerdhinen & Crystal Armour, "
			+ "Seal of Passage, 3 lots of 7 random cooked food");
		assertTrue(gauntlet.contains("Bow of Faerdhinen"));
		assertTrue(gauntlet.contains("Seal of Passage"));
		// the food requirement renders as its category display name; the
		// representative Shark icon is a display concern (getIconName)
		assertTrue(gauntlet.contains("Any cooked food"));

		String seeds = render("Buy at least 4x Jute seeds, 1x Marigold seeds, "
			+ "6x Onion seeds, 6x Cabbage seeds for "
			+ "[Kandarin Easy Diary and Garden of Tranquility]");
		assertTrue(seeds.contains("Jute seed"));
		assertTrue(seeds.contains("Marigold seed"));
		assertTrue(seeds.contains("Onion seed"));
		assertTrue(seeds.contains("Cabbage seed"));

		String withdraw = render("Withdraw: Coins, Dueling Ring, a knife, "
			+ "log or axe, ardy cloak, dramen staff.");
		assertTrue(withdraw.contains("Coins"));
		assertTrue(withdraw.contains("Knife"));
		assertTrue(withdraw.contains("Dramen staff"));
	}
}

package com.hcimguide;

import java.awt.Font;
import org.junit.After;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class OverlayFontsTest
{
	@After
	public void clearCache()
	{
		OverlayFonts.clear();
	}

	@Test
	public void familyWeightAndSizeAreIndependent()
	{
		Font font = OverlayFonts.resolve(new Font(Font.SANS_SERIF, Font.PLAIN, 12),
			HcimGuideConfig.OverlayFontFamily.MONOSPACED, "",
			HcimGuideConfig.OverlayFontWeight.BOLD_ITALIC, 23);

		assertEquals(Font.MONOSPACED, font.getFamily());
		assertEquals(Font.BOLD | Font.ITALIC, font.getStyle());
		assertEquals(23, font.getSize());
	}

	@Test
	public void unavailableCustomFamilyFallsBackSafely()
	{
		Font font = OverlayFonts.resolve(new Font(Font.SERIF, Font.PLAIN, 12),
			HcimGuideConfig.OverlayFontFamily.CUSTOM,
			"Guide Overlay Definitely Missing Font 8f0c7b", HcimGuideConfig.OverlayFontWeight.PLAIN, 17);

		assertEquals(Font.SANS_SERIF, font.getFamily());
		assertEquals(17, font.getSize());
	}

	@Test
	public void legacySansChoiceUsesNewIndependentSize()
	{
		Font font = OverlayFonts.resolve(null,
			HcimGuideConfig.OverlayFontFamily.SANS_SMALL, "",
			HcimGuideConfig.OverlayFontWeight.FAMILY_DEFAULT, 31);

		assertEquals(Font.SANS_SERIF, font.getFamily());
		assertEquals(31, font.getSize());
	}

	@Test
	public void requestedSizeIsClampedToConfigBounds()
	{
		Font tiny = OverlayFonts.resolve(null,
			HcimGuideConfig.OverlayFontFamily.SANS_SERIF, "",
			HcimGuideConfig.OverlayFontWeight.PLAIN, 1);
		Font huge = OverlayFonts.resolve(null,
			HcimGuideConfig.OverlayFontFamily.SANS_SERIF, "",
			HcimGuideConfig.OverlayFontWeight.PLAIN, 999);

		assertEquals(8, tiny.getSize());
		assertEquals(40, huge.getSize());
	}

	@Test
	public void cacheIsBoundedAndClearable()
	{
		for (int size = 8; size <= 40; size++)
		{
			for (HcimGuideConfig.OverlayFontWeight weight : HcimGuideConfig.OverlayFontWeight.values())
			{
				OverlayFonts.resolve(null, HcimGuideConfig.OverlayFontFamily.CUSTOM,
					"Missing font " + size + '-' + weight.name(), weight, size);
			}
		}

		assertTrue(OverlayFonts.cacheSizeForTesting() <= 128);
		OverlayFonts.clear();
		assertEquals(0, OverlayFonts.cacheSizeForTesting());
	}
	@Test
	public void clientDefaultPreservesFallbackStyleUnlessOverridden()
	{
		Font fallback = new Font(Font.SERIF, Font.ITALIC, 14);
		Font inherited = OverlayFonts.resolve(fallback,
			HcimGuideConfig.OverlayFontFamily.CLIENT_DEFAULT, "",
			HcimGuideConfig.OverlayFontWeight.FAMILY_DEFAULT, 20);
		Font overridden = OverlayFonts.resolve(fallback,
			HcimGuideConfig.OverlayFontFamily.CLIENT_DEFAULT, "",
			HcimGuideConfig.OverlayFontWeight.BOLD, 20);

		assertEquals(Font.ITALIC, inherited.getStyle());
		assertEquals(Font.BOLD, overridden.getStyle());
	}

}

package com.hcimguide;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class PathfinderIntegrationTest
{
	@Test
	public void activeTargetTracksTheLastSuccessfulHandoff()
	{
		List<PluginMessage> messages = new ArrayList<>();
		PathfinderIntegration integration = new PathfinderIntegration(messages::add);
		WorldPoint target = new WorldPoint(3200, 3200, 0);

		integration.setTarget(target);

		assertEquals(1, messages.size());
		assertEquals(target, integration.getActiveTarget());
	}

	@Test
	public void forceResendDoesNotBlankTheCompassSnapshot()
	{
		List<PluginMessage> messages = new ArrayList<>();
		PathfinderIntegration integration = new PathfinderIntegration(messages::add);
		WorldPoint target = new WorldPoint(3200, 3200, 0);
		integration.setTarget(target);

		integration.forceResend();

		assertEquals(target, integration.getActiveTarget());
		integration.setTarget(target);
		assertEquals(2, messages.size());
		assertEquals(target, integration.getActiveTarget());
	}

	@Test
	public void movingNpcDeadbandKeepsCompassOnTheDrawnPathTarget()
	{
		List<PluginMessage> messages = new ArrayList<>();
		PathfinderIntegration integration = new PathfinderIntegration(messages::add);
		WorldPoint drawnTarget = new WorldPoint(3200, 3200, 0);
		integration.setTarget(drawnTarget, true);

		integration.setTarget(new WorldPoint(3201, 3200, 0), true);

		assertEquals(1, messages.size());
		assertEquals(drawnTarget, integration.getActiveTarget());
	}

	@Test
	public void clearAfterForceResendStillClearsTheSnapshot()
	{
		List<PluginMessage> messages = new ArrayList<>();
		PathfinderIntegration integration = new PathfinderIntegration(messages::add);
		integration.setTarget(new WorldPoint(3200, 3200, 0));
		integration.forceResend();

		integration.clear();

		assertEquals(2, messages.size());
		assertNull(integration.getActiveTarget());
	}

	@Test
	public void failedRetargetKeepsTheLastPathAndCompassAligned()
	{
		List<PluginMessage> messages = new ArrayList<>();
		PathfinderIntegration integration = new PathfinderIntegration(message ->
		{
			if (!messages.isEmpty())
			{
				throw new IllegalStateException("simulated hand-off failure");
			}
			messages.add(message);
		});
		WorldPoint accepted = new WorldPoint(3200, 3200, 0);
		integration.setTarget(accepted);

		integration.setTarget(new WorldPoint(3300, 3300, 0));

		assertEquals(accepted, integration.getActiveTarget());
	}
}

