package com.hcimguide;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class ProgressCodecTest
{
	@Test
	public void roundTripsProgress() throws Exception
	{
		Set<String> keys = new HashSet<>();
		for (int i = 0; i < 500; i++)
		{
			keys.add("E1.B" + (i / 20) + "#" + Integer.toHexString(i * 31) + "#" + (i % 3));
		}
		String code = ProgressCodec.encode(keys, "b0aty-hcim-v3");
		assertTrue(code.startsWith("HCIMGUIDE1:"));
		ProgressCodec.Decoded decoded = ProgressCodec.decode(code);
		assertEquals(keys, decoded.keys);
		assertEquals("b0aty-hcim-v3", decoded.guideId);
	}

	@Test
	public void identicalProgressYieldsIdenticalCode() throws Exception
	{
		Set<String> a = new HashSet<>();
		a.add("k1");
		a.add("k2");
		Set<String> b = new HashSet<>();
		b.add("k2");
		b.add("k1");
		assertEquals(ProgressCodec.encode(a, "g"), ProgressCodec.encode(b, "g"));
	}

	@Test
	public void emptyProgressAndNullGuideIdRoundTrip() throws Exception
	{
		ProgressCodec.Decoded decoded = ProgressCodec.decode(ProgressCodec.encode(new HashSet<>(), null));
		assertTrue(decoded.keys.isEmpty());
		assertNull(decoded.guideId);
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsMissingPrefix()
	{
		ProgressCodec.decode("not a code");
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsCorruptPayload()
	{
		ProgressCodec.decode("HCIMGUIDE1:%%%not-base64%%%");
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsNull()
	{
		ProgressCodec.decode(null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsOversizedEncodedInput()
	{
		ProgressCodec.decode("HCIMGUIDE1:" + new String(new char[8 * 1024 * 1024 + 1]).replace('\0', 'A'));
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsNewlinesInKeys() throws Exception
	{
		Set<String> keys = new HashSet<>();
		keys.add("valid\nforged");
		ProgressCodec.encode(keys, "guide");
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsMetadataLookingKeys() throws Exception
	{
		Set<String> keys = new HashSet<>();
		keys.add("#guide:forged");
		ProgressCodec.encode(keys, "guide");
	}

	@Test(expected = IllegalArgumentException.class)
	public void rejectsInvalidGuideId() throws Exception
	{
		ProgressCodec.encode(new HashSet<>(), "../../outside");
	}
}

package com.hcimguide;

import java.util.HashSet;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ProgressKeyMigrationTest
{
	@Test
	public void migratesEpisodeWideNotesKeysToBankKeysInGuideOrder()
	{
		Guide guide = new WikitextParser().parse("== Episode 1 - x ==\n"
			+ "'''Bank 1'''\n* same step\n* unique\n"
			+ "'''Bank 2'''\n* same step\n");
		Set<String> completed = new HashSet<>();
		completed.add(legacy("E1-notes", "same step", 0));
		completed.add(legacy("E1-notes", "same step", 1));

		assertTrue(ProgressKeyMigration.migrateLegacyNotes(guide, completed));
		assertTrue(completed.contains(guide.getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getKey()));
		assertTrue(completed.contains(guide.getEpisodes().get(0).getBanks().get(1).getSteps().get(0).getKey()));
		assertFalse(completed.contains(legacy("E1-notes", "same step", 0)));
		assertFalse(completed.contains(legacy("E1-notes", "same step", 1)));
	}

	@Test
	public void leavesCorrectBankKeysAndUnrelatedKeysUntouched()
	{
		Guide guide = new WikitextParser().parse("== Episode 1 - x ==\n'''Bank 1'''\n* step\n");
		String current = guide.getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getKey();
		Set<String> completed = new HashSet<>();
		completed.add(current);
		completed.add("unrelated");

		assertFalse(ProgressKeyMigration.migrateLegacyNotes(guide, completed));
		assertTrue(completed.contains(current));
		assertTrue(completed.contains("unrelated"));
	}

	@Test
	public void completedParagraphMarksEverySplitChildComplete()
	{
		Guide g = new JsonGuideParser().parse("{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":[{\"text\":\"First action here. Second action here.\"}]}"
			+ "]}]}]}");
		String oldText = "First action here. Second action here.";
		String oldKey = "C1.S1#" + Integer.toHexString(oldText.hashCode()) + "#0";
		Set<String> completed = new HashSet<>();
		completed.add(oldKey);

		assertTrue(ProgressKeyMigration.migrateSplitKeys(g, completed));
		GuideBank sec = g.getEpisodes().get(0).getBanks().get(0);
		assertTrue(completed.contains(sec.getSteps().get(0).getKey()));
		assertTrue(completed.contains(sec.getSteps().get(1).getKey()));
		assertFalse(completed.contains(oldKey));
	}

	@Test
	public void splitMigrationNeverStealsALiveKey()
	{
		Guide g = new JsonGuideParser().parse("{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":[{\"text\":\"Just one action, nothing to split.\"}]}"
			+ "]}]}]}");
		String live = g.getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getKey();
		g.getLegacySplitKeys().put(live, java.util.Arrays.asList("C1.S1#dead#0"));
		Set<String> completed = new HashSet<>();
		completed.add(live);

		assertFalse(ProgressKeyMigration.migrateSplitKeys(g, completed));
		assertTrue(completed.contains(live));
	}

	@Test
	public void duplicateSentenceCollisionResolvesWhenParentParagraphIsInStore()
	{
		// paragraph B equals paragraph A's leading sentence: B's old key is
		// owned by A's first split child. With both old paragraph keys saved,
		// B's child must still be ticked; a lone new-format tick on the live
		// child must never be reinterpreted.
		String json = "{\"chapters\":[{\"sections\":[{\"steps\":["
			+ "{\"content\":[{\"text\":\"Alpha beta gamma delta. Second sentence here.\"}]},"
			+ "{\"content\":[{\"text\":\"Alpha beta gamma delta.\"}]}"
			+ "]}]}]}";
		Guide g = new JsonGuideParser().parse(json);
		String oldA = "C1.S1#" + Integer.toHexString("Alpha beta gamma delta. Second sentence here.".hashCode()) + "#0";
		String oldB = "C1.S1#" + Integer.toHexString("Alpha beta gamma delta.".hashCode()) + "#0";
		Set<String> completed = new HashSet<>();
		completed.add(oldA);
		completed.add(oldB);

		assertTrue(ProgressKeyMigration.migrateSplitKeys(g, completed));
		for (GuideStep s : g.getEpisodes().get(0).getBanks().get(0).getSteps())
		{
			assertTrue(completed.contains(s.getKey()));
		}

		Guide g2 = new JsonGuideParser().parse(json);
		Set<String> newTick = new HashSet<>();
		newTick.add(g2.getEpisodes().get(0).getBanks().get(0).getSteps().get(0).getKey());
		assertFalse(ProgressKeyMigration.migrateSplitKeys(g2, newTick));
		assertTrue(newTick.size() == 1);
	}

	private static String legacy(String notesId, String text, int occurrence)
	{
		return notesId + "#" + Integer.toHexString(text.hashCode()) + "#" + occurrence;
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;

public class StepExecutionPlannerTest
{
	@Test
	public void repeatedSemanticLegsReceiveStableDistinctIds()
	{
		String key = "bank#repeated-route";
		GuideStep step = new GuideStep(key,
			"Teleport to Varrock, then teleport to Falador, then teleport to Varrock",
			0, "bank");
		Gson gson = new Gson();
		StepExecutionPlan plan = StepExecutionPlanner.build(step,
			new PlaceDirectory(gson), new TransportResolver(gson), ignored -> null);

		assertNotNull(plan);
		assertEquals(3, plan.size());
		assertNotEquals(plan.get(0).getId(), plan.get(2).getId());
		assertEquals(0, plan.indexOfId(plan.get(0).getId()));
		assertEquals(2, plan.indexOfId(plan.get(2).getId()));
	}
	@Test
	public void oneBareTravelPhaseMayBorrowAProvenParentDestination()
	{
		String key = "bank#parent-fallback";
		GuideStep step = new GuideStep(key, "Teleport and bank at Camelot", 0, "bank");
		StepLocationHint camelot = new StepLocationHint("Camelot",
			new net.runelite.api.coords.WorldPoint(2757, 3479, 0), false);
		StepLocationPlan parent = new StepLocationPlan(key,
			java.util.Collections.singletonList(camelot));
		Gson gson = new Gson();
		StepExecutionPlan plan = StepExecutionPlanner.build(step,
			new PlaceDirectory(gson), new TransportResolver(gson), ignored -> null, parent);

		assertNotNull(plan);
		assertEquals(2, plan.size());
		assertEquals(StepPhaseParser.Kind.TRAVEL, plan.get(0).getKind());
		assertEquals(StepPhaseParser.Kind.TASK, plan.get(1).getKind());
	}

}

package com.hcimguide;

import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class StepItemRequirementsTest
{
	@Test
	public void jsonItemsSuffixUsesTheSameDisplayProjection()
	{
		GuideStep step = new GuideStep("suffix", "Talk to Bob. (Items: knife, 2 ropes)", 0, null);
		List<ItemReq> reqs = StepItemRequirements.displayFor(step);
		assertNotNull(reqs);
		assertEquals(2, reqs.size());
		assertEquals("knife", ItemReq.normalize(reqs.get(0).getName()));
		assertEquals(2, reqs.get(1).getQuantity());
		// the projection preserves the guide's own wording ("2 ropes"), and
		// normalize() only lowercases - it does not singularise. The contract
		// worth pinning is that the requirement is equivalent to Rope.
		assertEquals("ropes", ItemReq.normalize(reqs.get(1).getName()));
		assertTrue(ItemReq.namesEquivalent(reqs.get(1).getName(), "Rope"));
	}

	@Test
	public void conditionItemsTakePriorityOverDisplaySuffix()
	{
		String text = "Withdraw: Coins, Rope (Items: knife)";
		StepCondition condition = ConditionParser.parse(text);
		List<ItemReq> reqs = StepItemRequirements.displayFor(text, condition);
		assertNotNull(reqs);
		assertEquals("coins", ItemReq.normalize(reqs.get(0).getName()));
		assertEquals("rope", ItemReq.normalize(reqs.get(1).getName()));
	}
}

package com.hcimguide;

import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class StepLocationPlannerTest
{
	private final PlaceDirectory places = new PlaceDirectory(new Gson());
	private final TransportResolver transports = new TransportResolver(new Gson());

	@Test
	public void directPlaceAndLocalActionsShareAnArea()
	{
		GuideBank bank = bank("B1",
			step("a", "Do Tithe Farm until 62 Farming", "B1"),
			step("b", "Buy the seed box and refill your watering cans", "B1"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		assertEquals("Tithe Farm", hints.get("a").getLabel());
		assertFalse(hints.get("a").isInferred());
		assertEquals("Tithe Farm", hints.get("b").getLabel());
		assertTrue(hints.get("b").isInferred());
	}

	@Test
	public void contextNeverCrossesABankBoundary()
	{
		GuideBank first = bank("B1", step("a", "Do Tithe Farm", "B1"));
		GuideBank second = bank("B2", step("b", "Withdraw coins and a hammer", "B2"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(first, second), Collections.emptyMap(), places, transports, name -> null);

		assertTrue(hints.containsKey("a"));
		assertFalse(hints.containsKey("b"));
	}

	@Test
	public void unresolvedMovementBreaksInheritedContext()
	{
		GuideBank bank = bank("B1",
			step("a", "Do Tithe Farm", "B1"),
			step("b", "Walk to the unknown shrine", "B1"),
			step("c", "Buy three ropes", "B1"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		assertTrue(hints.containsKey("a"));
		assertFalse(hints.containsKey("b"));
		assertFalse(hints.containsKey("c"));
	}

	@Test
	public void movementPlaceOverridesEntityMentionedEnRoute()
	{
		GuideBank bank = bank("B1", step("a", "Go to Tithe Farm and talk to the farmer", "B1"));
		Map<String, String> targets = new HashMap<>();
		targets.put("a", "Farmer");
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), targets, places, transports, name -> new WorldPoint(3222, 3218, 0));

		assertEquals("Tithe Farm", hints.get("a").getLabel());
		assertTrue(hints.get("a").isPreferredOverEntity());
	}

	@Test
	public void ordinaryInteractionPrefersPreciseEntityLocation()
	{
		GuideBank bank = bank("B1", step("a", "Talk to the farmer at Tithe Farm", "B1"));
		Map<String, String> targets = new HashMap<>();
		targets.put("a", "Farmer");
		WorldPoint npcPoint = new WorldPoint(1805, 3502, 0);
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), targets, places, transports, name -> npcPoint);

		assertEquals("Farmer", hints.get("a").getLabel());
		assertEquals(npcPoint, hints.get("a").getPoint());
		assertFalse(hints.get("a").isPreferredOverEntity());
	}

	@Test
	public void fairyRingCodeResolvesBeforeOrdinaryPlaceMatching()
	{
		GuideBank bank = bank("B1", step("a", "Ardy cloak -> CIS, then run north", "B1"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		assertEquals("Fairy ring CIS", hints.get("a").getLabel());
		assertEquals(new WorldPoint(1636, 3869, 0), hints.get("a").getPoint());
		assertTrue(hints.get("a").isTransport());
	}

	@Test
	public void genericTransportToKnownPlaceIsMarkedAsTransport()
	{
		GuideBank bank = bank("B1", step("a", "Take the minecart to Lovakengj", "B1"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		assertEquals("Lovakengj", hints.get("a").getLabel());
		assertTrue(hints.get("a").isTransport());
		assertTrue(hints.get("a").isPreferredOverEntity());
	}

	@Test
	public void laterNamedEndpointBeatsIntermediateTeleportArrival()
	{
		GuideBank bank = bank("B1", step("a",
			"Ring of dueling to Emir's Arena, then run to Mage Training Arena", "B1"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		assertEquals("Mage Training Arena", hints.get("a").getLabel());
		assertEquals(new WorldPoint(3363, 3317, 0), hints.get("a").getPoint());
		// The route starts with a teleport, but the final waypoint is reached by running.
		assertFalse(hints.get("a").isTransport());
	}

	@Test
	public void multiStopInstructionBuildsOrderedWaypoints()
	{
		GuideBank bank = bank("B1", step("a",
			"Use a ring of dueling to Emir's Arena, then run to Mage Training Arena", "B1"));
		Map<String, StepLocationPlan> plans = StepLocationPlanner.buildPlans(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		StepLocationPlan plan = plans.get("a");
		assertEquals(2, plan.size());
		assertEquals("Emir's Arena", plan.get(0).getLabel());
		assertEquals("Mage Training Arena", plan.get(1).getLabel());
	}

	@Test
	public void legacySingleHintViewStillUsesFinalEndpoint()
	{
		GuideBank bank = bank("B1", step("a",
			"Use a ring of dueling to Emir's Arena, then run to Mage Training Arena", "B1"));
		Map<String, StepLocationHint> hints = StepLocationPlanner.build(
			guide(bank), Collections.emptyMap(), places, transports, name -> null);

		assertEquals("Mage Training Arena", hints.get("a").getLabel());
	}

	private static Guide guide(GuideBank... banks)
	{
		Guide guide = new Guide();
		GuideEpisode episode = new GuideEpisode(1, "Episode 1");
		Collections.addAll(episode.getBanks(), banks);
		guide.getEpisodes().add(episode);
		return guide;
	}

	private static GuideBank bank(String id, GuideStep... steps)
	{
		GuideBank bank = new GuideBank(id, id, 1);
		Collections.addAll(bank.getSteps(), steps);
		return bank;
	}

	private static GuideStep step(String key, String text, String bankId)
	{
		return new GuideStep(key, text, 0, bankId);
	}
	@Test
	public void doesNotSplitNextToPhrase()
	{
		GuideBank bank = bank("B1", step("a", "Go next to Tithe Farm and begin the activity", "B1"));
		Map<String, StepLocationPlan> plans = StepLocationPlanner.buildPlans(guide(bank),
			Collections.emptyMap(), places, transports, ignored -> null);

		StepLocationPlan plan = plans.values().iterator().next();
		assertEquals(1, plan.size());
		assertEquals("Tithe Farm", plan.get(0).getLabel());
	}

	@Test
	public void optionalCanifisNoteDoesNotOverrideFairyRingArrival()
	{
		GuideBank bank = bank("B103", step("a",
			"Use the fairy ring to the Old Crone (rebank in Canifis if needed)", "B103"),
			step("b", "Continue the quest until you need supplies", "B103"),
			step("c", "Rebank in Canifis before starting In Aid of the Myreque", "B103"));
		Map<String, StepLocationPlan> plans = StepLocationPlanner.buildPlans(
			guide(bank), Collections.emptyMap(), places, transports, ignored -> null);

		StepLocationPlan first = plans.get("a");
		assertTrue(first == null || first.getWaypoints().stream()
			.noneMatch(h -> "Canifis".equals(h.getLabel())));
		assertEquals("Canifis", plans.get("c").get(0).getLabel());
	}

	@Test
	public void orderedRouteMayRevisitAnEarlierDestination()
	{
		GuideBank bank = bank("B1", step("a",
			"Travel to Varrock, then Falador, then Varrock", "B1"));
		Map<String, StepLocationPlan> plans = StepLocationPlanner.buildPlans(
			guide(bank), Collections.emptyMap(), places, transports, ignored -> null);

		StepLocationPlan plan = plans.get("a");
		assertEquals(3, plan.size());
		assertEquals("Varrock", plan.get(0).getLabel());
		assertEquals("Falador", plan.get(1).getLabel());
		assertEquals("Varrock", plan.get(2).getLabel());
	}

}

