package com.hcimguide;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Corpus-level invariants for {@link StepPhaseParser}.
 *
 * <p>These exist because the classifier decides, for every row in the bundled
 * guides, whether reaching a destination is allowed to tick a checklist row.
 * A single misclassification is a premature completion, which is the worst
 * failure this plugin has: it tells a player a step is done when it is not.
 * Per-row tests cannot catch a rule that quietly widens; a whole-corpus check
 * can.</p>
 *
 * <p>Deliberately depends on {@code StepPhaseParser} alone. Every other class in
 * the phase system reaches the RuneLite API, so a test touching them cannot run
 * outside a full client build. Keeping this file dependency-free means the
 * invariants are checked on every ordinary {@code gradlew test}.</p>
 */
public class StepPhaseCorpusTest
{
	/**
	 * Rows that must stay non-completable. Each was reviewed by hand: reaching
	 * the destination proves nothing about the action the row also requires.
	 */
	private static final String[] MUST_NOT_COMPLETE_ON_ARRIVAL = {
		"Teleport to Varrock and talk to Aubury",
		"Take the boat to Brimhaven, then buy a swamp paste",
		"Head North and take Jug of Water [Monk's Friend]",
		"Break another POH tab and return to Thurgo.",
		"Right click House Teleport, choose Outside House, then head east",
		"Use Star on Experiment Entrance (Don't enter)",
		"Run South and kill 5 Rats",
		"Teleport to Camelot and complete the Seers diary",
	};

	/**
	 * Rows the CLASSIFIER calls travel-only but which are protected at runtime by
	 * a different gate. "Go back to Draynor bank. (Items: ...)" reads as pure
	 * travel because going to the bank IS the instruction; the items suffix is a
	 * parsed item condition, and ArrivalCompletionPolicy.canComplete rejects any
	 * row carrying one. Recorded here so the distinction is deliberate rather
	 * than discovered later: the mode alone is not the safety boundary.
	 */
	private static final String[] TRAVEL_BUT_GATED_BY_ITEM_CONDITION = {
		"Go back to Draynor bank. (Items: 3445 gp, fishing net, bucket)",
		"Go to the Varrock East bank. (Items: 3650 gp, Chronicle, bucket of milk)",
	};

	@Test
	public void itemSuffixRowsRelyOnTheConditionGateNotTheMode()
	{
		for (String row : TRAVEL_BUT_GATED_BY_ITEM_CONDITION)
		{
			// documents current behaviour: the parser sees travel, and the
			// runtime item-condition gate is what prevents completion
			assertEquals(row, StepPhaseParser.Mode.PURE_TRAVEL,
				StepPhaseParser.parse(row).getMode());
		}
	}

	/** Rows where arrival genuinely is the whole instruction. */
	private static final String[] MAY_COMPLETE_ON_ARRIVAL = {
		"Head North",
		"Home teleport to Lumbridge",
		"Head West to the Hunter's Guild",
		"Take the boat to Rimmington",
		"Run to Draynor Village",
	};

	@Test
	public void compoundRowsAreNeverPureTravel()
	{
		for (String row : MUST_NOT_COMPLETE_ON_ARRIVAL)
		{
			assertFalse("must not be arrival-completable: " + row,
				StepPhaseParser.parse(row).getMode() == StepPhaseParser.Mode.PURE_TRAVEL);
		}
	}

	@Test
	public void travelOnlyRowsRemainPureTravel()
	{
		for (String row : MAY_COMPLETE_ON_ARRIVAL)
		{
			assertEquals("should stay arrival-completable: " + row,
				StepPhaseParser.Mode.PURE_TRAVEL, StepPhaseParser.parse(row).getMode());
		}
	}

	/**
	 * The property that made GUIDANCE_ONLY safe to introduce. These rows produce
	 * phases so the plugin can target the right clause, but the mode itself must
	 * keep them out of the arrival-completion path.
	 */
	@Test
	public void guidanceOnlyIsNeverPureTravel()
	{
		String[] guidanceRows = {
			"Right click House Teleport, choose Outside House, then head east",
			"Break another POH tab and return to Thurgo.",
			"Use Star on Experiment Entrance (Don't enter)",
		};
		for (String row : guidanceRows)
		{
			StepPhaseParser.Mode mode = StepPhaseParser.parse(row).getMode();
			assertTrue("expected GUIDANCE_ONLY or MANUAL for: " + row,
				mode == StepPhaseParser.Mode.GUIDANCE_ONLY
					|| mode == StepPhaseParser.Mode.MANUAL);
			assertFalse("guidance rows must not be arrival-completable: " + row,
				mode == StepPhaseParser.Mode.PURE_TRAVEL);
		}
	}

	/** Every parsed row must keep at least one clause; silent loss hides text. */
	@Test
	public void everyRowRetainsAtLeastOneClause()
	{
		List<String> all = new ArrayList<>();
		for (String row : MUST_NOT_COMPLETE_ON_ARRIVAL)
		{
			all.add(row);
		}
		for (String row : MAY_COMPLETE_ON_ARRIVAL)
		{
			all.add(row);
		}
		for (String row : all)
		{
			assertFalse("no clause retained for: " + row,
				StepPhaseParser.parse(row).getClauses().isEmpty());
		}
	}

	/**
	 * A task may only ever be the final actionable clause. Anything else means a
	 * later travel leg is stranded behind an action with no automatic signal.
	 */
	@Test
	public void travelThenTaskEndsWithTheTask()
	{
		String[] rows = {
			"Teleport to Varrock and talk to Aubury",
			"Take the boat to Brimhaven, then buy a swamp paste",
			"Run south and meet the scout outside the gate",
		};
		for (String row : rows)
		{
			StepPhaseParser.Parsed parsed = StepPhaseParser.parse(row);
			if (parsed.getMode() != StepPhaseParser.Mode.TRAVEL_THEN_TASK)
			{
				continue;
			}
			List<StepPhaseParser.Clause> actionable = new ArrayList<>();
			for (StepPhaseParser.Clause clause : parsed.getClauses())
			{
				if (clause.getKind() != StepPhaseParser.Kind.NOTE)
				{
					actionable.add(clause);
				}
			}
			assertFalse("no actionable clause: " + row, actionable.isEmpty());
			assertEquals("task must be last for: " + row,
				StepPhaseParser.Kind.TASK,
				actionable.get(actionable.size() - 1).getKind());
			for (int i = 0; i + 1 < actionable.size(); i++)
			{
				assertFalse("task before the final clause in: " + row,
					actionable.get(i).getKind() == StepPhaseParser.Kind.TASK);
			}
		}
	}

	/** Parsing must be deterministic; a mode that varies per call is unusable. */
	@Test
	public void classificationIsStableAcrossRepeatedParses()
	{
		Map<StepPhaseParser.Mode, Integer> first = new EnumMap<>(StepPhaseParser.Mode.class);
		for (String row : MUST_NOT_COMPLETE_ON_ARRIVAL)
		{
			first.merge(StepPhaseParser.parse(row).getMode(), 1, Integer::sum);
		}
		Map<StepPhaseParser.Mode, Integer> second = new EnumMap<>(StepPhaseParser.Mode.class);
		for (String row : MUST_NOT_COMPLETE_ON_ARRIVAL)
		{
			second.merge(StepPhaseParser.parse(row).getMode(), 1, Integer::sum);
		}
		assertEquals(first, second);
	}
}

package com.hcimguide;

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class StepPhaseParserTest
{
	@Test
	public void separatesTravelFromARealFollowUpTask()
	{
		assertPlan("Teleport to Varrock and talk to Aubury",
			StepPhaseParser.Mode.TRAVEL_THEN_TASK,
			StepPhaseParser.Kind.TRAVEL, StepPhaseParser.Kind.TASK);
		assertPlan("Head North and take Jug of Water",
			StepPhaseParser.Mode.TRAVEL_THEN_TASK,
			StepPhaseParser.Kind.TRAVEL, StepPhaseParser.Kind.TASK);
		assertPlan("Head to Ice Mountain. There use Secateurs on White Tree",
			StepPhaseParser.Mode.TRAVEL_THEN_TASK,
			StepPhaseParser.Kind.TRAVEL, StepPhaseParser.Kind.TASK);
	}

	@Test
	public void recognizesConveyancesWithoutTreatingThemAsItems()
	{
		assertMode("Take the Arceuus Minecart to Lovakenj",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Head West and take the Lady of the Waves to Port Khazard",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Dueling ring to Al Kharid, take the gnome glider to Feldip Hills",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Return to Minecart and take to Shayzien East",
			StepPhaseParser.Mode.PURE_TRAVEL);
	}

	@Test
	public void preservesFairyRingAccessAndCodeAsOneExecutableRoute()
	{
		StepPhaseParser.Parsed parsed = StepPhaseParser.parse("Ardy Cloak -> AIS");
		assertEquals(StepPhaseParser.Mode.PURE_TRAVEL, parsed.getMode());
		assertEquals(1, parsed.getClauses().size());
		assertEquals("Ardy Cloak -> AIS", parsed.getClauses().get(0).getText());
	}

	@Test
	public void arrowToNonTravelTaskBecomesASeparatePhase()
	{
		assertPlan("Teleport to POH -> Lunar Spellbook",
			StepPhaseParser.Mode.TRAVEL_THEN_TASK,
			StepPhaseParser.Kind.TRAVEL, StepPhaseParser.Kind.TASK);
	}

	@Test
	public void destinationNamedBankIsNotAVisitToThenUseTheBank()
	{
		assertMode("Head to Edgeville Bank", StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Run to Falador east bank", StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Teleport to Ardougne and bank at South Bank",
			StepPhaseParser.Mode.TRAVEL_THEN_TASK);
		assertMode("Teleport to a bank to prepare Barrows",
			StepPhaseParser.Mode.MANUAL);
	}

	@Test
	public void itemSuffixCreatesPreparationWithoutChangingTravelClassification()
	{
		StepPhaseParser.Parsed parsed = StepPhaseParser.parse(
			"Dueling ring to Ferox, take the portal to Soul Wars, then to Edgeville. "
				+ "(Items: 1600 soda ash, chisel)");
		assertTrue(parsed.hasItemPreparation());
		assertEquals(StepPhaseParser.Mode.PURE_TRAVEL, parsed.getMode());
	}

	@Test
	public void optionalAndAlternativeRoutesFailClosed()
	{
		assertMode("Use a games necklace to Games Room or Minigame Teleport",
			StepPhaseParser.Mode.MANUAL);
		assertMode("Teleport to Trollheim if you can, else Ardy Cloak -> AJR",
			StepPhaseParser.Mode.MANUAL);
		assertMode("Whenever convenient, teleport to Canifis",
			StepPhaseParser.Mode.MANUAL);
	}

	@Test
	public void leadingTaskOrTaskBetweenTravelLegsBecomesGuidanceOnly()
	{
		// These rows produce phases for TARGETING only. Arrival completion is
		// gated separately on the mode, so they still cannot auto-complete -
		// guidanceOnlyRowsCannotComplete() below pins that property.
		assertMode("Right click House Teleport, choose Outside House, then head east",
			StepPhaseParser.Mode.GUIDANCE_ONLY);
		assertMode("Teleport to POH, send the butler, then teleport to Digsite",
			StepPhaseParser.Mode.GUIDANCE_ONLY);
		assertMode("Dump all your herblore experience, then return to this step",
			StepPhaseParser.Mode.GUIDANCE_ONLY);
	}

	@Test
	public void parentheticalRequiredActionPreventsArrivalCompletion()
	{
		StepPhaseParser.Parsed parsed = StepPhaseParser.parse(
			"Go to Edgeville, take the lever to the Wilderness, then Ardougne "
				+ "(use the lever 4 times)");
		assertTrue(parsed.hasRequiredParentheticalAction());
		assertEquals(StepPhaseParser.Mode.MANUAL, parsed.getMode());
	}

	@Test
	public void optionalParentheticalDoesNotCreateAFalseTask()
	{
		StepPhaseParser.Parsed parsed = StepPhaseParser.parse(
			"Use your chronicle to teleport to Varrock "
				+ "(optional: restore run energy at Clan Wars first). (Items: bucket)");
		assertFalse(parsed.hasRequiredParentheticalAction());
		assertEquals(StepPhaseParser.Mode.PURE_TRAVEL, parsed.getMode());
	}

	@Test
	public void unknownRouteFragmentIsNotSilentlyDiscarded()
	{
		assertMode("Falador Teleport -> 10 Grain south of Doric -> Tegid",
			StepPhaseParser.Mode.MANUAL);
		assertMode("Teleport to Falador -> somewhere mysterious", StepPhaseParser.Mode.MANUAL);
	}

	@Test
	public void commonDirectionAndAcronymTextRemainIntact()
	{
		assertMode("Head North then East", StepPhaseParser.Mode.PURE_TRAVEL);
		StepPhaseParser.Parsed acronym = StepPhaseParser.parse("Head south to H.A.M. Hideout");
		assertEquals(1, acronym.getClauses().size());
		assertEquals("Head south to H.A.M. Hideout", acronym.getClauses().get(0).getText());
	}

	@Test
	public void conditionalStartingLocationRemainsManual()
	{
		assertMode("If you were at Land's End, now charter a ship to Catherby",
			StepPhaseParser.Mode.MANUAL);
		assertMode("If you were at Port Sarim, charter to the Pandemonium",
			StepPhaseParser.Mode.MANUAL);
	}

	@Test
	public void fairyRingAccessDoesNotReplaceAnExplicitFinalDestination()
	{
		assertPlan("Ardy Cloak -> CLS Fairy Ring to get to Hazelmere",
			StepPhaseParser.Mode.PURE_TRAVEL,
			StepPhaseParser.Kind.TRAVEL, StepPhaseParser.Kind.TRAVEL);
	}

	@Test
	public void recognizesUseBasedTransportAndTemporalContext()
	{
		assertMode("Use your freshly charged Glory to teleport to Edgeville",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Use 2 ectotokens to enter Port Phasmatys",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("After Finding Percival use Fairy Ring BJR to return",
			StepPhaseParser.Mode.PURE_TRAVEL);
	}

	@Test
	public void placeNamesAndLocationExitDoNotBecomeTasks()
	{
		assertMode("Return to Eagles Peak and use Rope on Eagle to Snowy Hunter Area",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Leave the Tzhaar cave", StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Leave one redberry in the bank", StepPhaseParser.Mode.MANUAL);
	}

	@Test
	public void arrowConveyancesRetainAllTravelLegs()
	{
		assertMode("Minecart -> Shayzien East", StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Glider -> Feldip Hills -> Back to Al Kharid",
			StepPhaseParser.Mode.PURE_TRAVEL);
		assertMode("Ardy Cloak -> CLS Fairy Ring to get to Hazelmere",
			StepPhaseParser.Mode.PURE_TRAVEL);
	}

	private static void assertMode(String text, StepPhaseParser.Mode expected)
	{
		assertEquals(text, expected, StepPhaseParser.parse(text).getMode());
	}

	private static void assertPlan(String text, StepPhaseParser.Mode mode,
		StepPhaseParser.Kind... kinds)
	{
		StepPhaseParser.Parsed parsed = StepPhaseParser.parse(text);
		assertEquals(text, mode, parsed.getMode());
		List<StepPhaseParser.Kind> actual = parsed.getClauses().stream()
			.filter(c -> c.getKind() != StepPhaseParser.Kind.NOTE)
			.map(StepPhaseParser.Clause::getKind)
			.collect(Collectors.toList());
		assertEquals(text, Arrays.asList(kinds), actual);
	}

	/** The safety property: guidance-only rows may target but never complete. */
	@Test
	public void guidanceOnlyRowsCannotComplete()
	{
		String[] rows = {
			"Right click House Teleport, choose Outside House, then head east",
			"Teleport to POH, send the butler, then teleport to Digsite",
			"Dump all your herblore experience, then return to this step",
		};
		for (String row : rows)
		{
			assertEquals(row, StepPhaseParser.Mode.GUIDANCE_ONLY,
				StepPhaseParser.parse(row).getMode());
			assertFalse(row, ArrivalCompletionPolicy.isPureTravelText(row));
		}
	}
}

package com.hcimguide;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class StepTextSemanticTest
{
	@Test
	public void classifiesActualTransportAsCyanCategory()
	{
		assertEquals(StepTextSemantic.Kind.TRANSPORT,
			StepTextSemantic.classify("Use your games necklace to teleport to Wintertodt"));
		assertEquals(StepTextSemantic.Kind.TRANSPORT,
			StepTextSemantic.classify("Fairy ring -> BKR, then run east"));
		assertEquals(StepTextSemantic.Kind.TRANSPORT,
			StepTextSemantic.classify("Take the Quetzal to Tal Teklan"));
	}

	@Test
	public void classifiesPreparationWithoutMistakingTeleportItemsForTravel()
	{
		assertEquals(StepTextSemantic.Kind.PREPARATION,
			StepTextSemantic.classify("Withdraw a games necklace, food, and stamina potion"));
		assertEquals(StepTextSemantic.Kind.PREPARATION,
			StepTextSemantic.classify("Equip your Ardougne cloak before leaving"));
		assertEquals(StepTextSemantic.Kind.PREPARATION,
			StepTextSemantic.classify("Requires at least level 62 Farming"));
	}

	@Test
	public void preparationLeadWinsOverLaterTransportMention()
	{
		assertEquals(StepTextSemantic.Kind.PREPARATION,
			StepTextSemantic.classify("Withdraw food before teleporting to the Digsite"));
	}

	@Test
	public void explicitRequirementWinsOverLaterTransportMention()
	{
		assertEquals(StepTextSemantic.Kind.PREPARATION,
			StepTextSemantic.classify("Make sure you have food before teleporting to Varrock"));
		assertEquals(StepTextSemantic.Kind.TRANSPORT,
			StepTextSemantic.classify("Teleport to Varrock with 3 charges remaining"));
	}

	@Test
	public void dangerWinsOverTransportAndPreparation()
	{
		assertEquals(StepTextSemantic.Kind.DANGER,
			StepTextSemantic.classify("Teleport to the Wilderness and do not die"));
		assertEquals(StepTextSemantic.Kind.DANGER,
			StepTextSemantic.classify("Bring only items you are willing to lose on death"));
		assertEquals(StepTextSemantic.Kind.DANGER,
			StepTextSemantic.classify("Suicide to return faster"));
	}

	@Test
	public void avoidsCommonFalsePositives()
	{
		assertEquals(StepTextSemantic.Kind.PREPARATION,
			StepTextSemantic.classify("Buy death runes from the shop"));
		assertEquals(StepTextSemantic.Kind.NORMAL,
			StepTextSemantic.classify("Complete Death Plateau"));
		assertEquals(StepTextSemantic.Kind.NORMAL,
			StepTextSemantic.classify("Train Farming to level 62"));
		assertEquals(StepTextSemantic.Kind.NORMAL,
			StepTextSemantic.classify("Kill the boss and loot the chest"));
	}
}

